/* Conteúdo dos módulos da documentação admin — um arquivo só */
window.ADMIN_DOCS_MODULES = {"hub": "{% comment %} Conteúdo inicial: hub. JS troca pelo fragmento do módulo. {% endcomment %}\n<div class=\"cover\" id=\"visao-geral\">\n      <div class=\"kicker\"><span class=\"t-en\">Internal admin documentation</span><span class=\"t-pt\">Documentação interna do admin</span><span class=\"t-es\">Documentación interna del admin</span></div>\n      <h1><span class=\"t-en\">Admin Panel &mdash; Reference Guide</span><span class=\"t-pt\">Painel Administrativo &mdash; Guia de Referência</span><span class=\"t-es\">Panel Administrativo &mdash; Guía de Referencia</span></h1>\n      <p>\n        <span class=\"t-en\">Reference guide to the main screens, fields and actions in the admin panel: Orders, Products, Prices, Stock, Categories, Customers and users, Marketing (Promotions, Coupons, Newsletter, Reviews) and Management (Wallet, Movimentations, Reports). Includes screenshots and the function of each field, filter and button, in three languages.</span><span class=\"t-pt\">Guia de referência das principais telas, campos e ações do painel administrativo: Pedidos, Produtos, Preços, Estoques, Categorias, Clientes e usuários, Marketing (Promoções, Cupons, Newsletter, Avaliações) e Gestão (Carteira, Movimentações, Relatórios). Inclui capturas de tela e a função de cada campo, filtro e botão, em três idiomas.</span><span class=\"t-es\">Guía de referencia de las principales pantallas, campos y acciones del panel administrativo: Pedidos, Productos, Precios, Existencias, Categorías, Clientes y usuarios, Marketing (Promociones, Cupones, Boletín, Reseñas) y Gestión (Cartera, Movimientos, Informes). Incluye capturas de pantalla y la función de cada campo, filtro y botón, en tres idiomas.</span>\n      </p>\n      <div class=\"meta\">\n        <span><span class=\"t-en\">Modules</span><span class=\"t-pt\">Módulos</span><span class=\"t-es\">Módulos</span>: <span class=\"t-en\">Orders, Products, Prices, Stock, Categories, Customers and users, Marketing, Management</span><span class=\"t-pt\">Pedidos, Produtos, Preços, Estoques, Categorias, Clientes e usuários, Marketing, Gestão</span><span class=\"t-es\">Pedidos, Productos, Precios, Existencias, Categorías, Clientes y usuarios, Marketing, Gestión</span></span>\n        <span id=\"gen-date\"></span>\n      </div>\n    </div>\n\n    \n    <div class=\"docs-hub\">\n      <h2 class=\"docs-hub__title\"><span class=\"t-en\">Browse by module</span><span class=\"t-pt\">Navegar por módulo</span><span class=\"t-es\">Navegar por módulo</span></h2>\n      <p class=\"docs-hub__lead\"><span class=\"t-en\">Pick a module below. Only that topic is loaded — you do not download the whole documentation at once.</span><span class=\"t-pt\">Escolha um módulo abaixo. Só o conteúdo daquele tópico é carregado — a documentação inteira não precisa baixar de uma vez.</span><span class=\"t-es\">Elige un módulo abajo. Solo se carga ese tema — no hace falta descargar toda la documentación de una vez.</span></p>\n      <div class=\"docs-hub__grid\">\n\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=minhas-lojas\">\n        <strong><span class=\"t-en\">My stores</span><span class=\"t-pt\">Minhas lojas</span><span class=\"t-es\">Mis tiendas</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=pedidos\">\n        <strong><span class=\"t-en\">Orders</span><span class=\"t-pt\">Pedidos</span><span class=\"t-es\">Pedidos</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=produtos\">\n        <strong><span class=\"t-en\">Products</span><span class=\"t-pt\">Produtos</span><span class=\"t-es\">Productos</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=precos\">\n        <strong><span class=\"t-en\">Price tables</span><span class=\"t-pt\">Tabelas de preço</span><span class=\"t-es\">Tablas de precios</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=estoques\">\n        <strong><span class=\"t-en\">Stocks</span><span class=\"t-pt\">Estoques</span><span class=\"t-es\">Inventarios</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=categorias\">\n        <strong><span class=\"t-en\">Categories</span><span class=\"t-pt\">Categorias</span><span class=\"t-es\">Categorías</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=clientes\">\n        <strong><span class=\"t-en\">Customers and users</span><span class=\"t-pt\">Clientes e usuários</span><span class=\"t-es\">Clientes y usuarios</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=marketing\">\n        <strong><span class=\"t-en\">Marketing</span><span class=\"t-pt\">Marketing</span><span class=\"t-es\">Marketing</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=gestao\">\n        <strong><span class=\"t-en\">Management</span><span class=\"t-pt\">Gestão</span><span class=\"t-es\">Gestión</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=personalizar\">\n        <strong><span class=\"t-en\">Customize</span><span class=\"t-pt\">Personalizar</span><span class=\"t-es\">Personalizar</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=canais\">\n        <strong><span class=\"t-en\">Channels</span><span class=\"t-pt\">Canais</span><span class=\"t-es\">Canales</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=integracoes\">\n        <strong><span class=\"t-en\">Integrations</span><span class=\"t-pt\">Integrações</span><span class=\"t-es\">Integraciones</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      <a class=\"docs-hub__card\" href=\"/pagina/documentacao-da-admin?modulo=configuracoes\">\n        <strong><span class=\"t-en\">Settings</span><span class=\"t-pt\">Configurações</span><span class=\"t-es\">Configuraciones</span></strong>\n        <span class=\"docs-hub__go\" aria-hidden=\"true\">→</span>\n      </a>\n      </div>\n    </div>\n", "minhas-lojas": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">My stores</span><span class=\"t-pt\">Minhas lojas</span><span class=\"t-es\">Mis tiendas</span></p>\n<section class=\"doc-section\" id=\"minhas-lojas\">\n      <h2><span class=\"t-en\">1. My stores</span><span class=\"t-pt\">1. Minhas lojas</span><span class=\"t-es\">1. Mis tiendas</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">The \"My stores\" shortcut in the left menu opens the storefront (the public, customer-facing site) associated with the admin.</span><span class=\"t-pt\">O atalho \"Minhas lojas\" no menu esquerdo abre a loja virtual (o site público, voltado ao cliente) associada ao admin.</span><span class=\"t-es\">El atajo \"Mis tiendas\" en el menú izquierdo abre la tienda virtual (el sitio público, orientado al cliente) asociada al admin.</span>\n      </p>\n      <div class=\"subsection\" id=\"minhas-lojas-detalhe\">\n        <h3><span class=\"badge\"><span class=\"t-en\">My stores &gt; Sidebar</span><span class=\"t-pt\">Minhas lojas &gt; Menu lateral</span><span class=\"t-es\">Mis tiendas &gt; Menú lateral</span></span></h3>\n        <h3><span class=\"t-en\">Storefront access link</span><span class=\"t-pt\">Link de acesso à loja virtual</span><span class=\"t-es\">Enlace de acceso a la tienda virtual</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Behavior depends on how many active stores the account has under <b>Channels</b>:</p></span><span class=\"t-pt\"><p>O comportamento depende de quantas lojas ativas a conta tem em <b>Canais</b>:</p></span><span class=\"t-es\"><p>El comportamiento depende de cuántas tiendas activas tiene la cuenta en <b>Canales</b>:</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/001-minhas-lojas-en-my-stores-expanded-as-a-dropdown-with-two-active.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"my stores expanded as a dropdown with two active stores (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/002-minhas-lojas-pt-my-stores-expanded-as-a-dropdown-with-two-active.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"my stores expanded as a dropdown with two active stores (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/003-minhas-lojas-es-my-stores-expanded-as-a-dropdown-with-two-active.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"my stores expanded as a dropdown with two active stores (es)\">\n          <figcaption><span class=\"t-en\">Example with multi-store enabled: \"My stores\" expands into a dropdown listing each active store</span><span class=\"t-pt\">Exemplo com multilojas ativado: \"Minhas lojas\" se expande em um dropdown listando cada loja ativa</span><span class=\"t-es\">Ejemplo con multitienda activado: \"Mis tiendas\" se expande en un menú desplegable con cada tienda activa</span></figcaption>\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Single active store</span><span class=\"t-pt\">Apenas uma loja ativa</span><span class=\"t-es\">Solo una tienda activa</span></b> &mdash; <span class=\"t-en\">clicking \"My stores\" opens that store's public site directly in a new tab.</span><span class=\"t-pt\">clicar em \"Minhas lojas\" abre diretamente o site público dessa loja em uma nova aba.</span><span class=\"t-es\">hacer clic en \"Mis tiendas\" abre directamente el sitio público de esa tienda en una pestaña nueva.</span></li>\n          <li><b><span class=\"t-en\">Multiple active stores (multi-store)</span><span class=\"t-pt\">Mais de uma loja ativa (multilojas)</span><span class=\"t-es\">Más de una tienda activa (multitienda)</span></b> &mdash; <span class=\"t-en\">when more than one sales channel is active under Channels, \"My stores\" becomes a dropdown/submenu listing the name of each active store; clicking a store name opens that specific store's public site in a new tab.</span><span class=\"t-pt\">quando mais de um canal de venda está ativo em Canais, \"Minhas lojas\" vira um dropdown/submenu com o nome de cada loja ativa; clicar no nome de uma loja abre o site público daquela loja específica em uma nova aba.</span><span class=\"t-es\">cuando hay más de un canal de venta activo en Canales, \"Mis tiendas\" se convierte en un menú desplegable con el nombre de cada tienda activa; hacer clic en el nombre de una tienda abre el sitio público de esa tienda específica en una pestaña nueva.</span></li>\n        </ul>\n        <div class=\"note\"><span class=\"t-en\">&#128161; In the example captured above, the account has two active stores (Papelaria and Farmácia), each with its own storefront domain.</span><span class=\"t-pt\">&#128161; No exemplo capturado acima, a conta tem duas lojas ativas (Papelaria e Farmácia), cada uma com seu próprio domínio de loja virtual.</span><span class=\"t-es\">&#128161; En el ejemplo capturado arriba, la cuenta tiene dos tiendas activas (Papelaria y Farmácia), cada una con su propio dominio de tienda virtual.</span></div>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Overview</span><span class=\"t-pt\">Visão geral</span><span class=\"t-es\">Visión general</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=pedidos\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Orders</span><span class=\"t-pt\">Pedidos</span><span class=\"t-es\">Pedidos</span></strong></a>\n</nav>\n", "pedidos": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Orders</span><span class=\"t-pt\">Pedidos</span><span class=\"t-es\">Pedidos</span></p>\n<section class=\"doc-section\" id=\"pedidos\">\n      <h2><span class=\"t-en\">2. Orders</span><span class=\"t-pt\">2. Pedidos</span><span class=\"t-es\">2. Pedidos</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">The Orders module concentrates all store sales: order list and search, invoice issuance, manual order/quotation creation, and the order edit screen (products, shipping, payment, address and customer data).</span><span class=\"t-pt\">O módulo Pedidos concentra todas as vendas da loja: lista e busca de pedidos, emissão de notas fiscais, criação manual de pedidos/orçamentos e a tela de edição de cada pedido (produtos, frete, pagamento, endereço e dados do cliente).</span><span class=\"t-es\">El módulo Pedidos concentra todas las ventas de la tienda: lista y búsqueda de pedidos, emisión de notas fiscales, creación manual de pedidos/presupuestos y la pantalla de edición de cada pedido (productos, envío, pago, dirección y datos del cliente).</span>\n      </p>\n      <div class=\"subsection\" id=\"lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Orders &gt; List</span><span class=\"t-pt\">Pedidos &gt; Lista</span><span class=\"t-es\">Pedidos &gt; Lista</span></span></h3>\n        <h3><span class=\"t-en\">Order list</span><span class=\"t-pt\">Lista de pedidos</span><span class=\"t-es\">Lista de pedidos</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Initial screen of the section. Shows a summary by status, quick search/filters and the table with all orders.</p></span><span class=\"t-pt\"><p>Tela inicial da seção. Mostra um resumo por status, a busca/filtros rápidos e a tabela com todos os pedidos.</p></span><span class=\"t-es\"><p>Pantalla inicial de la sección. Muestra un resumen por estado, la búsqueda/filtros rápidos y la tabla con todos los pedidos.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/004-pedidos-en-order-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/005-pedidos-pt-order-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/006-pedidos-es-order-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order list (es)\">\n          <figcaption><span class=\"t-en\">Orders &gt; List screen, showing the status summary and the order table</span><span class=\"t-pt\">Tela Pedidos &gt; Lista, com o resumo de status e a tabela de pedidos</span><span class=\"t-es\">Pantalla Pedidos &gt; Lista, con el resumen de estados y la tabla de pedidos</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Status cards</span><span class=\"t-pt\">Cards de status</span><span class=\"t-es\">Tarjetas de estado</span></td><td class=\"field-type\"><span class=\"t-en\">Indicator / shortcut</span><span class=\"t-pt\">Indicador / atalho</span><span class=\"t-es\">Indicador / atajo</span></td><td class=\"field-desc\"><span class=\"t-en\">Pending, Approved, In Preparation, Shipped, Completed, Cancelled &mdash; show the number of orders in each status; clickable to filter the table.</span><span class=\"t-pt\">Pendente, Aprovado, Processando, Enviado, Finalizado, Cancelado &mdash; mostram a quantidade de pedidos em cada status; clicáveis para filtrar a tabela.</span><span class=\"t-es\">Pendiente, Aprobado, Procesando, Enviado, Finalizado, Cancelado &mdash; muestran la cantidad de pedidos en cada estado; se puede hacer clic para filtrar la tabla.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search</span><span class=\"t-pt\">Busca</span><span class=\"t-es\">Búsqueda</span></td><td class=\"field-type\">Text</td><td class=\"field-desc\"><span class=\"t-en\">\"Order #ID, product ##SKU/title, customer name/email/phone\" field &mdash; free search by order number, product SKU/title or customer name, e-mail or phone.</span><span class=\"t-pt\">\"#ID do pedido, ##SKU/título do produto, nome/e-mail/telefone do cliente\" &mdash; busca livre por número do pedido, SKU/título do produto ou nome, e-mail ou telefone do cliente.</span><span class=\"t-es\">\"#ID del pedido, ##SKU/título del producto, nombre/correo/teléfono del cliente\" &mdash; búsqueda libre por número de pedido, SKU/título del producto o nombre, correo o teléfono del cliente.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Date / Status / Payment status / Channel</span><span class=\"t-pt\">Data / Status / Status de pagamento / Canal</span><span class=\"t-es\">Fecha / Estado / Estado de pago / Canal</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Standard filters by issue date range, order stage, Paid/Not Paid and sales channel.</span><span class=\"t-pt\">Filtros padrão por intervalo de data, etapa do pedido, Pago/Não pago e canal de venda.</span><span class=\"t-es\">Filtros estándar por rango de fecha, etapa del pedido, Pagado/No pagado y canal de venta.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">More filters</span><span class=\"t-pt\">Mais filtros</span><span class=\"t-es\">Más filtros</span></td><td class=\"field-type\"><span class=\"t-en\">Side panel</span><span class=\"t-pt\">Painel lateral</span><span class=\"t-es\">Panel lateral</span></td><td class=\"field-desc\"><span class=\"t-en\">Opens a side panel with additional criteria: district, city, coupon, state, shipping type, payment method, seller, invoice status, order value range and sort order.</span><span class=\"t-pt\">Abre um painel lateral com critérios adicionais: bairro, cidade, cupom, UF, tipo de frete, forma de pagamento, vendedor, status de nota fiscal, intervalo de valor do pedido e ordenação.</span><span class=\"t-es\">Abre un panel lateral con criterios adicionales: barrio, ciudad, cupón, estado, tipo de envío, forma de pago, vendedor, estado de la factura, rango de valor del pedido y orden.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Table</span><span class=\"t-pt\">Tabela</span><span class=\"t-es\">Tabla</span></td><td class=\"field-type\"><span class=\"t-en\">List</span><span class=\"t-pt\">Lista</span><span class=\"t-es\">Lista</span></td><td class=\"field-desc\"><span class=\"t-en\">Columns: Order (#ID, link), Status (interactive dropdown &mdash; lets you change the order's status and sub-status directly from the list, e.g. Shipped &rarr; In transport / Exchange in progress / Return in progress / Cancellation requested, without opening the order), Date, Customers (name + email), Payment (Paid/Not Paid), Total, Method (icon with payment detail), Actions (&#8942; menu).</span><span class=\"t-pt\">Colunas: Pedido (#ID, link), Status (dropdown interativo &mdash; permite mudar o status e o substatus do pedido direto da lista, ex.: Enviado &rarr; Em transporte / Em processo de troca / Em processo de devolução / Solicitação de cancelamento, sem abrir o pedido), Data, Clientes (nome + e-mail), Pagamento (Pago/Não pago), Total, Método (ícone com detalhe do meio de pagamento), Ações (menu &#8942;).</span><span class=\"t-es\">Columnas: Pedido (#ID, enlace), Estado (menú desplegable interactivo &mdash; permite cambiar el estado y el subestado del pedido directamente desde la lista, ej.: Enviado &rarr; En transporte / En proceso de cambio / En proceso de devolución / Solicitud de cancelación, sin abrir el pedido), Fecha, Clientes (nombre + correo), Pago (Pagado/No pagado), Total, Método (ícono con detalle del medio de pago), Acciones (menú &#8942;).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">+ Create Order/quotation</span><span class=\"t-pt\">+ Criar Pedido/Orçamento</span><span class=\"t-es\">+ Crear Pedido/Presupuesto</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Opens the screen for manually creating a new order or quotation (see section 1.6).</span><span class=\"t-pt\">Abre a tela de criação manual de um novo pedido ou orçamento (ver seção 1.6).</span><span class=\"t-es\">Abre la pantalla de creación manual de un nuevo pedido o presupuesto (ver sección 1.6).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">More options</span><span class=\"t-pt\">Mais opções</span><span class=\"t-es\">Más opciones</span></td><td class=\"field-type\"><span class=\"t-en\">Menu</span><span class=\"t-pt\">Menu</span><span class=\"t-es\">Menú</span></td><td class=\"field-desc\"><span class=\"t-en\">Active when selecting 1+ orders via the checkbox; bulk actions (see section 1.7).</span><span class=\"t-pt\">Ativo ao selecionar 1+ pedidos pela caixinha; ações em massa (ver seção 1.7).</span><span class=\"t-es\">Activo al seleccionar 1 o más pedidos con la casilla; acciones masivas (ver sección 1.7).</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"filtros\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Orders &gt; List &gt; More filters</span><span class=\"t-pt\">Pedidos &gt; Lista &gt; Mais filtros</span><span class=\"t-es\">Pedidos &gt; Lista &gt; Más filtros</span></span></h3>\n        <h3><span class=\"t-en\">Advanced filters</span><span class=\"t-pt\">Filtros avançados</span><span class=\"t-es\">Filtros avanzados</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Side panel triggered by the \"More filters\" button, with additional search criteria.</p></span><span class=\"t-pt\"><p>Painel lateral acionado pelo botão \"Mais filtros\", com critérios adicionais de busca.</p></span><span class=\"t-es\"><p>Panel lateral activado por el botón \"Más filtros\", con criterios adicionales de búsqueda.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/007-pedidos-en-more-filters-panel-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"more filters panel (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/008-pedidos-pt-more-filters-panel-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"more filters panel (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/009-pedidos-es-more-filters-panel-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"more filters panel (es)\">\n          <figcaption><span class=\"t-en\">\"More filters\" side panel with additional search criteria</span><span class=\"t-pt\">Painel lateral \"Mais filtros\" com critérios adicionais de busca</span><span class=\"t-es\">Panel lateral \"Más filtros\" con criterios adicionales de búsqueda</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">District / City / State</span><span class=\"t-pt\">Bairro / Cidade / UF</span><span class=\"t-es\">Barrio / Ciudad / Estado</span></td><td class=\"field-type\"><span class=\"t-en\">Text (multiple)</span><span class=\"t-pt\">Texto (múltiplos)</span><span class=\"t-es\">Texto (múltiples)</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters by the shipping address location.</span><span class=\"t-pt\">Filtra pela localização do endereço de entrega.</span><span class=\"t-es\">Filtra por la ubicación de la dirección de entrega.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Coupon</span><span class=\"t-pt\">Cupom</span><span class=\"t-es\">Cupón</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters orders that used a specific discount coupon.</span><span class=\"t-pt\">Filtra pedidos que usaram um cupom de desconto específico.</span><span class=\"t-es\">Filtra pedidos que usaron un cupón de descuento específico.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Shipping</span><span class=\"t-pt\">Frete</span><span class=\"t-es\">Envío</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters by shipping type/carrier used.</span><span class=\"t-pt\">Filtra pelo tipo/transportadora de frete usado.</span><span class=\"t-es\">Filtra por el tipo/transportista de envío usado.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Sub-order payout status</span><span class=\"t-pt\">Status de repasse do subpedido</span><span class=\"t-es\">Estado de repasse del subpedido</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters by the payout (settlement) status of the sub-order to the seller.</span><span class=\"t-pt\">Filtra pelo status de repasse (acerto financeiro) do subpedido ao vendedor.</span><span class=\"t-es\">Filtra por el estado de repasse (liquidación) del subpedido al vendedor.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Payment / Substatus</span><span class=\"t-pt\">Pagamento / Substatus</span><span class=\"t-es\">Pago / Subestado</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters by payment method used or by a secondary status within the main stage.</span><span class=\"t-pt\">Filtra pelo método de pagamento usado ou por uma etapa secundária dentro do status principal.</span><span class=\"t-es\">Filtra por el método de pago usado o por una etapa secundaria dentro del estado principal.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Seller</span><span class=\"t-pt\">Vendedor</span><span class=\"t-es\">Vendedor</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters orders from a specific seller.</span><span class=\"t-pt\">Filtra pedidos de um vendedor específico.</span><span class=\"t-es\">Filtra pedidos de un vendedor específico.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Has invoice</span><span class=\"t-pt\">Com nota fiscal</span><span class=\"t-es\">Con factura</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters orders that already have (or not) an invoice issued.</span><span class=\"t-pt\">Filtra pedidos que já têm (ou não) nota fiscal emitida.</span><span class=\"t-es\">Filtra pedidos que ya tienen (o no) factura emitida.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Shipping label</span><span class=\"t-pt\">Etiqueta</span><span class=\"t-es\">Etiqueta</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters by the shipping label's status (e.g. issued, printed).</span><span class=\"t-pt\">Filtra pelo status da etiqueta de envio (ex.: emitida, impressa).</span><span class=\"t-es\">Filtra por el estado de la etiqueta de envío (ej.: emitida, impresa).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Order value</span><span class=\"t-pt\">Valor do pedido</span><span class=\"t-es\">Valor del pedido</span></td><td class=\"field-type\"><span class=\"t-en\">Range (min/max)</span><span class=\"t-pt\">Intervalo (mín/máx)</span><span class=\"t-es\">Rango (mín/máx)</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters orders within a minimum and maximum total value.</span><span class=\"t-pt\">Filtra pedidos dentro de um valor total mínimo e máximo.</span><span class=\"t-es\">Filtra pedidos dentro de un valor total mínimo y máximo.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">With unlinked product</span><span class=\"t-pt\">Com produto não vinculado</span><span class=\"t-es\">Con producto no vinculado</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters orders that contain a product not linked/mapped in the catalog (info tooltip explains the criteria).</span><span class=\"t-pt\">Filtra pedidos que contêm um produto não vinculado/mapeado no catálogo (tem um tooltip de informação explicando o critério).</span><span class=\"t-es\">Filtra pedidos que contienen un producto no vinculado/mapeado en el catálogo (tiene un tooltip informativo que explica el criterio).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Sort by</span><span class=\"t-pt\">Ordenar por</span><span class=\"t-es\">Ordenar por</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Defines the table sort order (default: Most recent).</span><span class=\"t-pt\">Define a ordem de exibição da tabela (padrão: Mais recente).</span><span class=\"t-es\">Define el orden de la tabla (predeterminado: Más reciente).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Cancel / Search</span><span class=\"t-pt\">Cancelar / Buscar</span><span class=\"t-es\">Cancelar / Buscar</span></td><td class=\"field-type\"><span class=\"t-en\">Buttons</span><span class=\"t-pt\">Botões</span><span class=\"t-es\">Botones</span></td><td class=\"field-desc\"><span class=\"t-en\">Cancel closes the panel without applying; Search applies the selected filters.</span><span class=\"t-pt\">Cancelar fecha o painel sem aplicar; Buscar aplica os filtros selecionados.</span><span class=\"t-es\">Cancelar cierra el panel sin aplicar; Buscar aplica los filtros seleccionados.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"detalhe\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Orders &gt; #ID &gt; Edit</span><span class=\"t-pt\">Pedidos &gt; #ID &gt; Editar</span><span class=\"t-es\">Pedidos &gt; #ID &gt; Editar</span></span></h3>\n        <h3><span class=\"t-en\">Order detail / edit</span><span class=\"t-pt\">Detalhe / edição do pedido</span><span class=\"t-es\">Detalle / edición del pedido</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Screen opened when clicking an order in the list. Gathers all order data: products, shipping, discounts, taxes, payment, financial movements, shipping address, customer data and notes. It is the same structure used to manually create an order (section 1.6).</p></span><span class=\"t-pt\"><p>Tela aberta ao clicar em um pedido na lista. Reúne todos os dados do pedido: produtos, frete, descontos, taxas, pagamento, movimentações financeiras, endereço de entrega, dados do cliente e observações. É a mesma estrutura usada para criar um pedido manualmente (seção 1.6).</p></span><span class=\"t-es\"><p>Pantalla que se abre al hacer clic en un pedido de la lista. Reúne todos los datos del pedido: productos, envío, descuentos, tasas, pago, movimientos financieros, dirección de entrega, datos del cliente y observaciones. Es la misma estructura usada para crear un pedido manualmente (sección 1.6).</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/010-pedidos-en-order-detail-top-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order detail top (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/011-pedidos-pt-order-detail-top-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order detail top (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/012-pedidos-es-order-detail-top-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order detail top (es)\">\n</div>\n        <table class=\"fields\">\n          <thead><tr><th style=\"width:22%\"><span class=\"t-en\">Block / field</span><span class=\"t-pt\">Bloco / campo</span><span class=\"t-es\">Bloque / campo</span></th><th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th><th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th></tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Price table</span><span class=\"t-pt\">Tabela de preço</span><span class=\"t-es\">Tabla de precio</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Defines the price table applied to the order.</span><span class=\"t-pt\">Define a tabela de preços aplicada ao pedido.</span><span class=\"t-es\">Define la tabla de precios aplicada al pedido.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Sales channel</span><span class=\"t-pt\">Canal de venda</span><span class=\"t-es\">Canal de venta</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Channel through which the order came in.</span><span class=\"t-pt\">Canal pelo qual o pedido entrou.</span><span class=\"t-es\">Canal por el cual entró el pedido.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Status / Additional status / Payment status</span><span class=\"t-pt\">Status / Status adicional / Status de pagamento</span><span class=\"t-es\">Estado / Estado adicional / Estado de pago</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Current stage of the order, a complementary status detail, and the payment situation (Paid/Not Paid).</span><span class=\"t-pt\">Etapa atual do pedido, um detalhe complementar de status e a situação do pagamento (Pago/Não pago).</span><span class=\"t-es\">Etapa actual del pedido, un detalle complementario de estado y la situación del pago (Pagado/No pagado).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Products</span><span class=\"t-pt\">Produtos</span><span class=\"t-es\">Productos</span></td><td class=\"field-type\"><span class=\"t-en\">Search + table</span><span class=\"t-pt\">Busca + tabela</span><span class=\"t-es\">Búsqueda + tabla</span></td><td class=\"field-desc\"><span class=\"t-en\">Search field to add items; table with Product (name, ID, SKU), Price, Quantity and Total per item; shows the Products subtotal.</span><span class=\"t-pt\">Campo de busca para adicionar itens; tabela com Produto (nome, ID, SKU), Preço, Quantidade e Total por item; exibe o Subtotal dos produtos.</span><span class=\"t-es\">Campo de búsqueda para agregar artículos; tabla con Producto (nombre, ID, SKU), Precio, Cantidad y Total por artículo; muestra el Subtotal de los productos.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Shipping</span><span class=\"t-pt\">Frete</span><span class=\"t-es\">Envío</span></td><td class=\"field-type\"><span class=\"t-en\">Block</span><span class=\"t-pt\">Bloco</span><span class=\"t-es\">Bloque</span></td><td class=\"field-desc\"><span class=\"t-en\">Shipping method, value and expected delivery date. The two icons next to the value open the tracking/invoice details and let you link specific products to that shipment.</span><span class=\"t-pt\">Método de frete, valor e data prevista de entrega. Os dois ícones ao lado do valor abrem os detalhes de rastreio/nota e permitem associar produtos específicos a esse frete.</span><span class=\"t-es\">Método de envío, valor y fecha prevista de entrega. Los dos íconos junto al valor abren los detalles de seguimiento/factura y permiten asociar productos específicos a ese envío.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Shipping address</span><span class=\"t-pt\">Endereço de entrega</span><span class=\"t-es\">Dirección de envío</span></td><td class=\"field-type\"><span class=\"t-en\">Side panel</span><span class=\"t-pt\">Painel lateral</span><span class=\"t-es\">Panel lateral</span></td><td class=\"field-desc\"><span class=\"t-en\">Country, Receiver, Zip code, Street, Number, Complement, District, City and State.</span><span class=\"t-pt\">País, Recebedor, CEP, Rua, Número, Complemento, Bairro, Cidade e Estado.</span><span class=\"t-es\">País, Destinatario, Código postal, Calle, Número, Complemento, Barrio, Ciudad y Estado.</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"shot\" style=\"margin-top:22px;\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/013-pedidos-en-order-detail-middle-discount-tax-customer-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order detail middle - discount, tax, customer (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/014-pedidos-pt-order-detail-middle-discount-tax-customer-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order detail middle - discount, tax, customer (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/015-pedidos-es-order-detail-middle-discount-tax-customer-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order detail middle - discount, tax, customer (es)\">\n</div>\n        <table class=\"fields\">\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Discount / Tax</span><span class=\"t-pt\">Desconto / Taxa</span><span class=\"t-es\">Descuento / Impuesto</span></td><td class=\"field-type\"><span class=\"t-en\">Blocks</span><span class=\"t-pt\">Blocos</span><span class=\"t-es\">Bloques</span></td><td class=\"field-desc\"><span class=\"t-en\">Note, percentage and value for a discount or an additional tax applied to the order.</span><span class=\"t-pt\">Observação, percentual e valor de um desconto ou de uma taxa adicional aplicada ao pedido.</span><span class=\"t-es\">Observación, porcentaje y valor de un descuento o de un impuesto adicional aplicado al pedido.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Customer details</span><span class=\"t-pt\">Detalhes do cliente</span><span class=\"t-es\">Detalles del cliente</span></td><td class=\"field-type\"><span class=\"t-en\">Side panel</span><span class=\"t-pt\">Painel lateral</span><span class=\"t-es\">Panel lateral</span></td><td class=\"field-desc\"><span class=\"t-en\">Customer (selection + link to record), Name, Email, Phone (country code + number), Document and Secondary document.</span><span class=\"t-pt\">Cliente (seleção + link para o cadastro), Nome, E-mail, Telefone (DDI + número), Documento e Documento secundário (RG, IE ou Isento).</span><span class=\"t-es\">Cliente (selección + enlace al registro), Nombre, Correo electrónico, Teléfono (código de país + número), Documento y Documento secundario.</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"shot\" style=\"margin-top:22px;\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/016-pedidos-en-order-detail-bottom-payment-additional-info-move.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order detail bottom - payment, additional info, movements (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/017-pedidos-pt-order-detail-bottom-payment-additional-info-move.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order detail bottom - payment, additional info, movements (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/018-pedidos-es-order-detail-bottom-payment-additional-info-move.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order detail bottom - payment, additional info, movements (es)\">\n</div>\n        <table class=\"fields\">\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Payment</span><span class=\"t-pt\">Pagamento</span><span class=\"t-es\">Pago</span></td><td class=\"field-type\"><span class=\"t-en\">Block</span><span class=\"t-pt\">Bloco</span><span class=\"t-es\">Bloque</span></td><td class=\"field-desc\"><span class=\"t-en\">Payment method used, value, Refund button and a small icon that shows the raw notification history sent by the payment gateway. Shows Payment discount, Total paid and Order total.</span><span class=\"t-pt\">Método de pagamento usado, valor, botão Reembolsar e um ícone pequeno que exibe o histórico de notificações enviado pela integradora de pagamento. Exibe Desconto de pagamento, Total pago e Total do pedido.</span><span class=\"t-es\">Método de pago usado, valor, botón Reembolsar y un ícono pequeño que muestra el historial de notificaciones enviado por el integrador de pago. Muestra Descuento de pago, Total pagado y Total del pedido.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Additional information</span><span class=\"t-pt\">Informações adicionais</span><span class=\"t-es\">Información adicional</span></td><td class=\"field-type\"><span class=\"t-en\">Side panel</span><span class=\"t-pt\">Painel lateral</span><span class=\"t-es\">Panel lateral</span></td><td class=\"field-desc\"><span class=\"t-en\">Free-text order notes.</span><span class=\"t-pt\">Observações livres do pedido.</span><span class=\"t-es\">Notas libres del pedido.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Movements</span><span class=\"t-pt\">Movimentações</span><span class=\"t-es\">Movimientos</span></td><td class=\"field-type\"><span class=\"t-en\">Expandable block</span><span class=\"t-pt\">Bloco expansível</span><span class=\"t-es\">Bloque expandible</span></td><td class=\"field-desc\"><span class=\"t-en\">Financial entries of the order (e.g. shipping cost, order total); each row can be expanded to edit its Category, Value and Description. Shows the final Net total.</span><span class=\"t-pt\">Lançamentos financeiros do pedido (ex.: custo com frete, total do pedido); cada linha pode ser expandida para editar Categoria, Valor e Descrição. Exibe o Total líquido final.</span><span class=\"t-es\">Asientos financieros del pedido (ej.: costo de envío, total del pedido); cada fila se puede expandir para editar Categoría, Valor y Descripción. Muestra el Total líquido final.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Save order</span><span class=\"t-pt\">Salvar pedido</span><span class=\"t-es\">Guardar pedido</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Saves the changes made to the order.</span><span class=\"t-pt\">Grava as alterações feitas no pedido.</span><span class=\"t-es\">Guarda los cambios realizados en el pedido.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"acoes\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Orders &gt; #ID &gt; Actions</span><span class=\"t-pt\">Pedidos &gt; #ID &gt; Ações</span><span class=\"t-es\">Pedidos &gt; #ID &gt; Acciones</span></span></h3>\n        <h3><span class=\"t-en\">Order actions menu</span><span class=\"t-pt\">Menu de ações do pedido</span><span class=\"t-es\">Menú de acciones del pedido</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>\"Actions\" button at the top of the order detail screen.</p></span><span class=\"t-pt\"><p>Botão \"Ações\" no topo da tela de detalhe do pedido.</p></span><span class=\"t-es\"><p>Botón \"Acciones\" en la parte superior de la pantalla de detalle del pedido.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/019-pedidos-en-order-actions-dropdown-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order actions dropdown (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/020-pedidos-pt-order-actions-dropdown-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order actions dropdown (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/021-pedidos-es-order-actions-dropdown-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"order actions dropdown (es)\">\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">permanently deletes the order.</span><span class=\"t-pt\">exclui o pedido permanentemente.</span><span class=\"t-es\">elimina el pedido de forma permanente.</span></li>\n          <li><b><span class=\"t-en\">Print label</span><span class=\"t-pt\">Imprimir etiqueta</span><span class=\"t-es\">Imprimir etiqueta</span></b> &mdash; <span class=\"t-en\">generates the shipping label.</span><span class=\"t-pt\">gera a etiqueta de envio.</span><span class=\"t-es\">genera la etiqueta de envío.</span></li>\n          <li><b><span class=\"t-en\">Print order</span><span class=\"t-pt\">Imprimir pedido</span><span class=\"t-es\">Imprimir pedido</span></b> &mdash; <span class=\"t-en\">generates a printable order receipt/summary.</span><span class=\"t-pt\">gera um comprovante/resumo do pedido para impressão.</span><span class=\"t-es\">genera un comprobante/resumen del pedido para imprimir.</span></li>\n          <li><b><span class=\"t-en\">Print coupon</span><span class=\"t-pt\">Imprimir cupom</span><span class=\"t-es\">Imprimir cupón</span></b> &mdash; <span class=\"t-en\">generates the fiscal receipt/sales voucher.</span><span class=\"t-pt\">gera o cupom fiscal/comprovante de venda.</span><span class=\"t-es\">genera el cupón fiscal/comprobante de venta.</span></li>\n          <li><b><span class=\"t-en\">Select seller</span><span class=\"t-pt\">Selecionar vendedor</span><span class=\"t-es\">Seleccionar vendedor</span></b> &mdash; <span class=\"t-en\">assigns the order to a seller.</span><span class=\"t-pt\">atribui o pedido a um vendedor.</span><span class=\"t-es\">asigna el pedido a un vendedor.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"nf\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Orders &gt; Invoice</span><span class=\"t-pt\">Pedidos &gt; NF</span><span class=\"t-es\">Pedidos &gt; NF</span></span></h3>\n        <h3><span class=\"t-en\">Invoices (NF tab)</span><span class=\"t-pt\">Notas fiscais (aba NF)</span><span class=\"t-es\">Notas fiscales (pestaña NF)</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Second tab of the Orders screen, dedicated to invoice issuance control.</p></span><span class=\"t-pt\"><p>Segunda aba da tela de Pedidos, dedicada ao controle de emissão de notas fiscais.</p></span><span class=\"t-es\"><p>Segunda pestaña de la pantalla de Pedidos, dedicada al control de emisión de notas fiscales.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/022-pedidos-en-invoice-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"invoice tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/023-pedidos-pt-invoice-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"invoice tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/024-pedidos-es-invoice-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"invoice tab (es)\">\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Instructions</span><span class=\"t-pt\">Instruções</span><span class=\"t-es\">Instrucciones</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Explains how automatic and manual invoice issuance works: it uses the order's shipping and the products linked to it; automatic issuance requires enabling it per channel and an order status of In preparation or higher.</span><span class=\"t-pt\">Explica como funciona a emissão automática e manual da nota: ela usa o frete do pedido e os produtos vinculados a ele; a emissão automática exige ativação por canal e status do pedido Em preparação ou superior.</span><span class=\"t-es\">Explica cómo funciona la emisión automática y manual de la factura: usa el envío del pedido y los productos vinculados a él; la emisión automática requiere activarla por canal y un estado del pedido En preparación o superior.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search / Status</span><span class=\"t-pt\">Busca / Status</span><span class=\"t-es\">Búsqueda / Estado</span></td><td class=\"field-type\"><span class=\"t-en\">Text / Select</span><span class=\"t-pt\">Texto / Select</span><span class=\"t-es\">Texto / Select</span></td><td class=\"field-desc\"><span class=\"t-en\">Search by order or invoice number, and filter by invoice issuance status.</span><span class=\"t-pt\">Busca por pedido ou número da nota, e filtro pela situação de emissão da nota.</span><span class=\"t-es\">Búsqueda por pedido o número de la factura, y filtro por la situación de emisión de la factura.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Table</span><span class=\"t-pt\">Tabela</span><span class=\"t-es\">Tabla</span></td><td class=\"field-type\"><span class=\"t-en\">List</span><span class=\"t-pt\">Lista</span><span class=\"t-es\">Lista</span></td><td class=\"field-desc\"><span class=\"t-en\">Columns: #ID / Order status, Shipping name, Order date, Invoice number, Invoice icon, Invoice status (badge), Actions.</span><span class=\"t-pt\">Colunas: #ID / Status do pedido, Nome do frete, Emissão do pedido, Número da nota fiscal, Nota (ícone de documento), Status da nota (badge), Ações.</span><span class=\"t-es\">Columnas: #ID / Estado del pedido, Nombre del envío, Emisión del pedido, Número de la factura, Nota (ícono de documento), Estado de la nota (etiqueta), Acciones.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Actions icon</span><span class=\"t-pt\">Ícone de ações</span><span class=\"t-es\">Ícono de acciones</span></td><td class=\"field-type\"><span class=\"t-en\">Modal</span><span class=\"t-pt\">Modal</span><span class=\"t-es\">Modal</span></td><td class=\"field-desc\"><span class=\"t-en\">Opens the form to generate the electronic invoice (NFe) for that order &mdash; carrier, volumes and additional tax data, all optional.</span><span class=\"t-pt\">Abre o formulário para gerar a nota fiscal eletrônica (NFe) daquele pedido &mdash; dados de transportador, volumes e informações fiscais adicionais, todos opcionais.</span><span class=\"t-es\">Abre el formulario para generar la factura electrónica (NFe) de ese pedido &mdash; datos de transportista, volúmenes e información fiscal adicional, todos opcionales.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"criar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Orders &gt; Add</span><span class=\"t-pt\">Pedidos &gt; Adicionar</span><span class=\"t-es\">Pedidos &gt; Agregar</span></span></h3>\n        <h3><span class=\"t-en\">Create order/quotation</span><span class=\"t-pt\">Criar pedido/orçamento</span><span class=\"t-es\">Crear pedido/presupuesto</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via the \"+ Create Order/quotation\" button in the list. Uses exactly the same blocks as the detail screen (section 1.3), blank, to manually assemble an order or quotation.</p></span><span class=\"t-pt\"><p>Aberta pelo botão \"+ Criar Pedido/Orçamento\" na lista. Usa exatamente os mesmos blocos da tela de detalhe (seção 1.3), em branco, para montagem manual de um pedido ou orçamento.</p></span><span class=\"t-es\"><p>Se abre con el botón \"+ Crear Pedido/Presupuesto\" en la lista. Usa exactamente los mismos bloques de la pantalla de detalle (sección 1.3), en blanco, para armar manualmente un pedido o presupuesto.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/025-pedidos-en-create-order-quotation-screen-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"create order/quotation screen (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/026-pedidos-pt-create-order-quotation-screen-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"create order/quotation screen (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/027-pedidos-es-create-order-quotation-screen-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"create order/quotation screen (es)\">\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Save quotation</span><span class=\"t-pt\">Salvar orçamento</span><span class=\"t-es\">Guardar presupuesto</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Saves as a quotation (proposal not yet confirmed as a sale).</span><span class=\"t-pt\">Salva como orçamento (proposta ainda não confirmada como venda).</span><span class=\"t-es\">Guarda como presupuesto (propuesta aún no confirmada como venta).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Save order</span><span class=\"t-pt\">Salvar pedido</span><span class=\"t-es\">Guardar pedido</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Confirms and saves as a sales order.</span><span class=\"t-pt\">Confirma e grava como pedido de venda.</span><span class=\"t-es\">Confirma y guarda como pedido de venta.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"massa\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Orders &gt; List</span><span class=\"t-pt\">Pedidos &gt; Lista</span><span class=\"t-es\">Pedidos &gt; Lista</span></span></h3>\n        <h3><span class=\"t-en\">Bulk actions and row actions</span><span class=\"t-pt\">Ações em massa e ações por linha</span><span class=\"t-es\">Acciones masivas y acciones por fila</span></h3>\n        <div class=\"desc\"><p><span class=\"t-en\">Two ways to run quick actions directly from the list, without opening the order.</span><span class=\"t-pt\">Duas formas de executar ações rápidas direto na lista, sem abrir o pedido.</span><span class=\"t-es\">Dos formas de ejecutar acciones rápidas directamente en la lista, sin abrir el pedido.</span></p></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/028-pedidos-en-bulk-actions-menu-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk actions menu (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/029-pedidos-pt-bulk-actions-menu-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk actions menu (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/030-pedidos-es-bulk-actions-menu-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk actions menu (es)\">\n          <figcaption><span class=\"t-en\">Select 1+ orders via the checkbox and click \"More options\"</span><span class=\"t-pt\">Selecione 1+ pedidos pela caixinha e clique em \"Mais opções\"</span><span class=\"t-es\">Seleccione 1 o más pedidos con la casilla y haga clic en \"Más opciones\"</span></figcaption>\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Print order</span><span class=\"t-pt\">Imprimir pedido</span><span class=\"t-es\">Imprimir pedido</span></b></li>\n          <li><b><span class=\"t-en\">Print coupon</span><span class=\"t-pt\">Imprimir cupom</span><span class=\"t-es\">Imprimir cupón</span></b></li>\n          <li><b><span class=\"t-en\">Print label</span><span class=\"t-pt\">Imprimir etiqueta</span><span class=\"t-es\">Imprimir etiqueta</span></b></li>\n          <li><b><span class=\"t-en\">Generate shipping tag</span><span class=\"t-pt\">Gerar etiqueta</span><span class=\"t-es\">Generar etiqueta</span></b></li>\n          <li><b><span class=\"t-en\">Cancel shipping tag</span><span class=\"t-pt\">Cancelar etiqueta</span><span class=\"t-es\">Cancelar etiqueta</span></b></li>\n          <li><b><span class=\"t-en\">Bulk change status</span><span class=\"t-pt\">Alteração de status em massa</span><span class=\"t-es\">Cambio de estado masivo</span></b> &mdash; <span class=\"t-en\">changes the status of all selected orders at once.</span><span class=\"t-pt\">altera o status de todos os pedidos selecionados de uma vez.</span><span class=\"t-es\">cambia el estado de todos los pedidos seleccionados a la vez.</span></li>\n        </ul>\n        <div class=\"shot\" style=\"margin-top:22px;\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/031-pedidos-en-row-actions-menu-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"row actions menu (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/032-pedidos-pt-row-actions-menu-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"row actions menu (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/033-pedidos-es-row-actions-menu-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"row actions menu (es)\">\n          <figcaption><span class=\"t-en\">Click the 3 dots (&#8942;) in the \"Actions\" column of a row</span><span class=\"t-pt\">Clique nos 3 pontinhos (&#8942;) na coluna \"Ações\" de uma linha</span><span class=\"t-es\">Haga clic en los 3 puntos (&#8942;) en la columna \"Acciones\" de una fila</span></figcaption>\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the order for editing.</span><span class=\"t-pt\">abre o pedido para edição.</span><span class=\"t-es\">abre el pedido para edición.</span></li>\n          <li><b><span class=\"t-en\">Print order</span><span class=\"t-pt\">Imprimir pedido</span><span class=\"t-es\">Imprimir pedido</span></b></li>\n          <li><b><span class=\"t-en\">Print label</span><span class=\"t-pt\">Imprimir etiqueta</span><span class=\"t-es\">Imprimir etiqueta</span></b></li>\n          <li><b><span class=\"t-en\">Invoice/Tracking</span><span class=\"t-pt\">NF/Rastreio</span><span class=\"t-es\">Factura/Rastreo</span></b> &mdash; <span class=\"t-en\">quick access to the invoice and shipment tracking.</span><span class=\"t-pt\">acesso rápido à nota fiscal e rastreio do envio.</span><span class=\"t-es\">acceso rápido a la factura y seguimiento del envío.</span></li>\n          <li><b><span class=\"t-en\">Generate shipping tag</span><span class=\"t-pt\">Gerar etiqueta</span><span class=\"t-es\">Generar etiqueta</span></b></li>\n          <li><b><span class=\"t-en\">Cancel shipping tag</span><span class=\"t-pt\">Cancelar etiqueta</span><span class=\"t-es\">Cancelar etiqueta</span></b></li>\n        </ul>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=minhas-lojas\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">My stores</span><span class=\"t-pt\">Minhas lojas</span><span class=\"t-es\">Mis tiendas</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=produtos\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Products</span><span class=\"t-pt\">Produtos</span><span class=\"t-es\">Productos</span></strong></a>\n</nav>\n", "produtos": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Products</span><span class=\"t-pt\">Produtos</span><span class=\"t-es\">Productos</span></p>\n<section class=\"doc-section\" id=\"produtos\">\n      <h2><span class=\"t-en\">3. Products &gt; Products</span><span class=\"t-pt\">3. Produtos &gt; Produtos</span><span class=\"t-es\">3. Productos &gt; Productos</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">The Products module manages the store catalog: product list and search, general data / price / stock / images of each product, and manual product creation. This covers the \"Products\" submenu; Price tables, Stocks and Categories are documented separately.</span><span class=\"t-pt\">O módulo Produtos gerencia o catálogo da loja: lista e busca de produtos, dados gerais / preço / estoque / imagens de cada produto e a criação manual de produtos. Esta seção cobre o submenu \"Produtos\"; Tabelas de preço, Estoques e Categorias são documentados à parte.</span><span class=\"t-es\">El módulo Productos gestiona el catálogo de la tienda: lista y búsqueda de productos, datos generales / precio / stock / imágenes de cada producto y la creación manual de productos. Esta sección cubre el submenú \"Productos\"; Tablas de precios, Inventarios y Categorías se documentan por separado.</span>\n      </p>\n      <div class=\"subsection\" id=\"produtos-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; List</span><span class=\"t-pt\">Produtos &gt; Lista</span><span class=\"t-es\">Productos &gt; Lista</span></span></h3>\n        <h3><span class=\"t-en\">Product list</span><span class=\"t-pt\">Lista de produtos</span><span class=\"t-es\">Lista de productos</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Initial screen of the section. Shows the search box, quick filters and the table with all products in the catalog.</p></span><span class=\"t-pt\"><p>Tela inicial da seção. Mostra a caixa de busca, os filtros rápidos e a tabela com todos os produtos do catálogo.</p></span><span class=\"t-es\"><p>Pantalla inicial de la sección. Muestra el cuadro de búsqueda, los filtros rápidos y la tabla con todos los productos del catálogo.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/034-produtos-en-product-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/035-produtos-pt-product-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/036-produtos-es-product-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product list (es)\">\n          <figcaption><span class=\"t-en\">Products &gt; List screen, with the search box, filters and the product table</span><span class=\"t-pt\">Tela Produtos &gt; Lista, com a caixa de busca, filtros e a tabela de produtos</span><span class=\"t-es\">Pantalla Productos &gt; Lista, con el cuadro de búsqueda, filtros y la tabla de productos</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search</span><span class=\"t-pt\">Busca</span><span class=\"t-es\">Búsqueda</span></td><td class=\"field-type\">Text</td><td class=\"field-desc\"><span class=\"t-en\">\"#ID, ##SKU, GTIN or title\" field &mdash; free search by product ID, SKU, barcode or title.</span><span class=\"t-pt\">\"#ID, ##SKU, GTIN ou título\" &mdash; busca livre por ID, SKU, código de barras ou título do produto.</span><span class=\"t-es\">\"#ID, ##SKU, GTIN o título\" &mdash; búsqueda libre por ID, SKU, código de barras o título del producto.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Category / Brand / Status / Stock</span><span class=\"t-pt\">Categoria / Marca / Status / Estoque</span><span class=\"t-es\">Categoría / Marca / Estado / Inventario</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Standard filters by product category, brand, active/inactive status and stock situation.</span><span class=\"t-pt\">Filtros padrão por categoria do produto, marca, status ativo/inativo e situação de estoque.</span><span class=\"t-es\">Filtros estándar por categoría del producto, marca, estado activo/inactivo y situación de inventario.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">More filters</span><span class=\"t-pt\">Mais filtros</span><span class=\"t-es\">Más filtros</span></td><td class=\"field-type\"><span class=\"t-en\">Side panel</span><span class=\"t-pt\">Painel lateral</span><span class=\"t-es\">Panel lateral</span></td><td class=\"field-desc\"><span class=\"t-en\">Opens a side panel with additional criteria (see next subsection).</span><span class=\"t-pt\">Abre um painel lateral com critérios adicionais (ver próxima subseção).</span><span class=\"t-es\">Abre un panel lateral con criterios adicionales (ver próxima subsección).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Table</span><span class=\"t-pt\">Tabela</span><span class=\"t-es\">Tabla</span></td><td class=\"field-type\"><span class=\"t-en\">List</span><span class=\"t-pt\">Lista</span><span class=\"t-es\">Lista</span></td><td class=\"field-desc\"><span class=\"t-en\">Columns: Product (image, title, ID, SKU, multiple and total stock), Category / Brand, Type (Standard / Kit / Build your own), Price / Promotion, Actions (&#8942; menu).</span><span class=\"t-pt\">Colunas: Produto (imagem, título, ID, SKU, múltiplo e estoque total), Categoria / Marca, Tipo (Padrão / Kit / Monte o seu), Preço / Promoção, Ações (menu &#8942;).</span><span class=\"t-es\">Columnas: Producto (imagen, título, ID, SKU, múltiplo y stock total), Categoría / Marca, Tipo (Estándar / Kit / Arma tu propio), Precio / Promoción, Acciones (menú &#8942;).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">+ Add product</span><span class=\"t-pt\">+ Adicionar produto</span><span class=\"t-es\">+ Añadir producto</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Opens the screen for manually creating a new product (see the \"Create product\" subsection).</span><span class=\"t-pt\">Abre a tela de criação manual de um novo produto (ver subseção \"Criar produto\").</span><span class=\"t-es\">Abre la pantalla de creación manual de un nuevo producto (ver subsección \"Crear producto\").</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">More options</span><span class=\"t-pt\">Mais opções</span><span class=\"t-es\">Más opciones</span></td><td class=\"field-type\"><span class=\"t-en\">Menu</span><span class=\"t-pt\">Menu</span><span class=\"t-es\">Menú</span></td><td class=\"field-desc\"><span class=\"t-en\">Active when selecting 1+ products via the checkbox; bulk actions (see \"Bulk / row actions\").</span><span class=\"t-pt\">Ativo ao selecionar 1+ produtos pela caixinha; ações em massa (ver \"Ações em massa e por linha\").</span><span class=\"t-es\">Activo al seleccionar 1 o más productos con la casilla; acciones masivas (ver \"Acciones masivas y por fila\").</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"produtos-filtros\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; List &gt; More filters</span><span class=\"t-pt\">Produtos &gt; Lista &gt; Mais filtros</span><span class=\"t-es\">Productos &gt; Lista &gt; Más filtros</span></span></h3>\n        <h3><span class=\"t-en\">Advanced filters</span><span class=\"t-pt\">Filtros avançados</span><span class=\"t-es\">Filtros avanzados</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Side panel triggered by the \"More filters\" button, with additional search criteria for the catalog.</p></span><span class=\"t-pt\"><p>Painel lateral acionado pelo botão \"Mais filtros\", com critérios adicionais de busca no catálogo.</p></span><span class=\"t-es\"><p>Panel lateral activado por el botón \"Más filtros\", con criterios adicionales de búsqueda en el catálogo.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/037-produtos-en-more-filters-panel-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"more filters panel (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/038-produtos-pt-more-filters-panel-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"more filters panel (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/039-produtos-es-more-filters-panel-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"more filters panel (es)\">\n          <figcaption><span class=\"t-en\">\"More filters\" side panel, with product type, condition, storage and category/brand criteria</span><span class=\"t-pt\">Painel lateral \"Mais filtros\", com critérios de tipo de produto, condição, armazenagem e categoria/marca</span><span class=\"t-es\">Panel lateral \"Más filtros\", con criterios de tipo de producto, condición, almacenamiento y categoría/marca</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Date</span><span class=\"t-pt\">Data</span><span class=\"t-es\">Fecha</span></td><td class=\"field-type\"><span class=\"t-en\">Date range</span><span class=\"t-pt\">Intervalo de data</span><span class=\"t-es\">Rango de fecha</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters by product registration date.</span><span class=\"t-pt\">Filtra pela data de cadastro do produto.</span><span class=\"t-es\">Filtra por la fecha de registro del producto.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Product type / Composition type</span><span class=\"t-pt\">Tipo do produto / Produto composição do tipo</span><span class=\"t-es\">Tipo de producto / Tipo de composición</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters by Standard, Kit or Build your own, and by the composition type used.</span><span class=\"t-pt\">Filtra por Padrão, Kit ou Monte o seu, e pelo tipo de composição usado.</span><span class=\"t-es\">Filtra por Estándar, Kit o Arma tu propio, y por el tipo de composición usado.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Condition</span><span class=\"t-pt\">Condição</span><span class=\"t-es\">Condición</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters by product condition (e.g. New).</span><span class=\"t-pt\">Filtra pela condição do produto (ex.: Novo).</span><span class=\"t-es\">Filtra por la condición del producto (ej.: Nuevo).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Distribution center</span><span class=\"t-pt\">Centro de distribuição</span><span class=\"t-es\">Centro de distribución</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters products linked to a specific distribution center.</span><span class=\"t-pt\">Filtra produtos vinculados a um centro de distribuição específico.</span><span class=\"t-es\">Filtra productos vinculados a un centro de distribución específico.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Multiple storage</span><span class=\"t-pt\">Armazenagem múltipla</span><span class=\"t-es\">Almacenamiento múltiple</span></td><td class=\"field-type\"><span class=\"t-en\">Text (multiple)</span><span class=\"t-pt\">Texto (múltiplos)</span><span class=\"t-es\">Texto (múltiples)</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters by one or more storage/warehouse codes, separated by commas.</span><span class=\"t-pt\">Filtra por um ou mais códigos de armazenagem, separados por vírgula.</span><span class=\"t-es\">Filtra por uno o más códigos de almacenamiento, separados por coma.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Has category / Has brand</span><span class=\"t-pt\">Contém categoria / Contém marca</span><span class=\"t-es\">Contiene categoría / Contiene marca</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Filters products that do (or don't) have a category or brand assigned.</span><span class=\"t-pt\">Filtra produtos que têm (ou não) categoria ou marca definida.</span><span class=\"t-es\">Filtra productos que tienen (o no) categoría o marca definida.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Cancel / Search</span><span class=\"t-pt\">Cancelar / Buscar</span><span class=\"t-es\">Cancelar / Buscar</span></td><td class=\"field-type\"><span class=\"t-en\">Buttons</span><span class=\"t-pt\">Botões</span><span class=\"t-es\">Botones</span></td><td class=\"field-desc\"><span class=\"t-en\">Cancel closes the panel without applying; Search applies the selected filters.</span><span class=\"t-pt\">Cancelar fecha o painel sem aplicar; Buscar aplica os filtros selecionados.</span><span class=\"t-es\">Cancelar cierra el panel sin aplicar; Buscar aplica los filtros seleccionados.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"produtos-dados-gerais\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Edit &gt; General data</span><span class=\"t-pt\">Produtos &gt; Editar &gt; Dados gerais</span><span class=\"t-es\">Productos &gt; Editar &gt; Datos generales</span></span></h3>\n        <h3><span class=\"t-en\">General data tab</span><span class=\"t-pt\">Aba Dados gerais</span><span class=\"t-es\">Pestaña Datos generales</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened by clicking a product name in the list, or via \"Edit\" in the row actions menu. The edit screen has tabs for General data, SEO, Variants, Kit, Build your own, Related and Attributes; this subsection covers the main \"General data\" tab, which holds the product's core information. The other tabs are covered next.</p></span><span class=\"t-pt\"><p>Aberta ao clicar no nome de um produto na lista, ou pelo \"Editar\" no menu de ações da linha. A tela de edição tem abas para Dados gerais, SEO, Variações, Kit, Monte o seu, Relacionados e Atributos; esta subseção cobre a aba principal \"Dados gerais\", que reúne as informações centrais do produto. As demais abas são cobertas a seguir.</p></span><span class=\"t-es\"><p>Se abre al hacer clic en el nombre de un producto en la lista, o mediante \"Editar\" en el menú de acciones de la fila. La pantalla de edición tiene pestañas para Datos generales, SEO, Variantes, Kit, Arma tu propio, Relacionados y Atributos; esta subsección cubre la pestaña principal \"Datos generales\", que reúne la información central del producto. Las demás pestañas se cubren a continuación.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/040-produtos-en-product-edit-top-information-and-additional-data.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product edit top - information and additional data (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/041-produtos-pt-product-edit-top-information-and-additional-data.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product edit top - information and additional data (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/042-produtos-es-product-edit-top-information-and-additional-data.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product edit top - information and additional data (es)\">\n</div>\n        <table class=\"fields\">\n          <thead><tr><th style=\"width:22%\"><span class=\"t-en\">Block / field</span><span class=\"t-pt\">Bloco / campo</span><span class=\"t-es\">Bloque / campo</span></th><th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th><th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th></tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Title</span><span class=\"t-pt\">Título</span><span class=\"t-es\">Título</span></td><td class=\"field-type\">Text</td><td class=\"field-desc\"><span class=\"t-en\">Product name, shown in the catalog and storefront.</span><span class=\"t-pt\">Nome do produto, exibido no catálogo e na loja virtual.</span><span class=\"t-es\">Nombre del producto, mostrado en el catálogo y en la tienda virtual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">SKU / Barcode (GTIN/EAN)</span><span class=\"t-pt\">SKU / Código de barras (GTIN/EAN)</span><span class=\"t-es\">SKU / Código de barras (GTIN/EAN)</span></td><td class=\"field-type\">Text</td><td class=\"field-desc\"><span class=\"t-en\">Internal reference code and the product's barcode.</span><span class=\"t-pt\">Código de referência interno e o código de barras do produto.</span><span class=\"t-es\">Código de referencia interno y el código de barras del producto.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Cost price / Margin / Price</span><span class=\"t-pt\">Preço de custo / Margem / Preço</span><span class=\"t-es\">Precio de costo / Margen / Precio</span></td><td class=\"field-type\">Currency / %</td><td class=\"field-desc\"><span class=\"t-en\">Cost price, markup percentage and the resulting sale price (calculated together).</span><span class=\"t-pt\">Preço de custo, percentual de margem e o preço de venda resultante (calculados em conjunto).</span><span class=\"t-es\">Precio de costo, porcentaje de margen y el precio de venta resultante (calculados en conjunto).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Promotion price / Stock quantity</span><span class=\"t-pt\">Preço promoção / Quantidade em estoque</span><span class=\"t-es\">Precio promoción / Cantidad en stock</span></td><td class=\"field-type\">Currency / Number</td><td class=\"field-desc\"><span class=\"t-en\">Optional promotional price, and the available stock quantity (or unlimited, when stock is not managed).</span><span class=\"t-pt\">Preço promocional opcional, e a quantidade de estoque disponível (ou ilimitado, quando o produto não controla estoque).</span><span class=\"t-es\">Precio promocional opcional, y la cantidad de stock disponible (o ilimitado, cuando el producto no controla stock).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Category</span><span class=\"t-pt\">Categoria</span><span class=\"t-es\">Categoría</span></td><td class=\"field-type\"><span class=\"t-en\">List</span><span class=\"t-pt\">Lista</span><span class=\"t-es\">Lista</span></td><td class=\"field-desc\"><span class=\"t-en\">One or more categories linked to the product; one of them can be marked as Main.</span><span class=\"t-pt\">Uma ou mais categorias vinculadas ao produto; uma delas pode ser marcada como Principal.</span><span class=\"t-es\">Una o más categorías vinculadas al producto; una de ellas puede marcarse como Principal.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Brand / Model</span><span class=\"t-pt\">Marca / Modelo</span><span class=\"t-es\">Marca / Modelo</span></td><td class=\"field-type\">Text</td><td class=\"field-desc\"><span class=\"t-en\">Product brand and model, used for search and filters.</span><span class=\"t-pt\">Marca e modelo do produto, usados para busca e filtros.</span><span class=\"t-es\">Marca y modelo del producto, usados para búsqueda y filtros.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Visible in search</span><span class=\"t-pt\">Visível em buscas</span><span class=\"t-es\">Visible en la búsqueda</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Whether the product appears in the storefront's internal search.</span><span class=\"t-pt\">Se o produto aparece na busca interna da loja virtual.</span><span class=\"t-es\">Si el producto aparece en la búsqueda interna de la tienda virtual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">NCM / MPN / Tax classification / Condition / Supplier</span><span class=\"t-pt\">NCM / MPN / Classificação tributária / Condição / Fornecedor</span><span class=\"t-es\">NCM / MPN / Clasificación tributaria / Condición / Proveedor</span></td><td class=\"field-type\"><span class=\"t-en\">Text / Select</span><span class=\"t-pt\">Texto / Select</span><span class=\"t-es\">Texto / Select</span></td><td class=\"field-desc\"><span class=\"t-en\">Tax and supplier data used for invoicing and internal management.</span><span class=\"t-pt\">Dados fiscais e de fornecedor usados para emissão de nota e gestão interna.</span><span class=\"t-es\">Datos fiscales y de proveedor usados para emisión de factura y gestión interna.</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"shot\" style=\"margin-top:22px;\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/043-produtos-en-product-edit-middle-description-and-storage-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product edit middle - description and storage (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/044-produtos-pt-product-edit-middle-description-and-storage-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product edit middle - description and storage (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/045-produtos-es-product-edit-middle-description-and-storage-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product edit middle - description and storage (es)\">\n</div>\n        <table class=\"fields\">\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Description</span><span class=\"t-pt\">Descrição</span><span class=\"t-es\">Descripción</span></td><td class=\"field-type\"><span class=\"t-en\">Rich text</span><span class=\"t-pt\">Texto rico</span><span class=\"t-es\">Texto enriquecido</span></td><td class=\"field-desc\"><span class=\"t-en\">Full product description, with a rich-text editor (formatting, lists, tables).</span><span class=\"t-pt\">Descrição completa do produto, com editor de texto rico (formatação, listas, tabelas).</span><span class=\"t-es\">Descripción completa del producto, con editor de texto enriquecido (formato, listas, tablas).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Storage: Unit / Multiple</span><span class=\"t-pt\">Armazenamento: Unidade / Múltiplo</span><span class=\"t-es\">Almacenamiento: Unidad / Múltiplo</span></td><td class=\"field-type\"><span class=\"t-en\">Select / Number</span><span class=\"t-pt\">Select / Número</span><span class=\"t-es\">Select / Número</span></td><td class=\"field-desc\"><span class=\"t-en\">Sale unit (e.g. UN) and the multiple quantity sold per unit.</span><span class=\"t-pt\">Unidade de venda (ex.: UN) e o múltiplo vendido por unidade.</span><span class=\"t-es\">Unidad de venta (ej.: UN) y el múltiplo vendido por unidad.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Product type</span><span class=\"t-pt\">Tipo do produto</span><span class=\"t-es\">Tipo de producto</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Physical or Digital &mdash; defines whether shipping dimensions apply.</span><span class=\"t-pt\">Físico ou Digital &mdash; define se as dimensões de frete se aplicam.</span><span class=\"t-es\">Físico o Digital &mdash; define si se aplican las dimensiones de envío.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Weight / Width / Length / Height</span><span class=\"t-pt\">Peso / Largura / Comprimento / Altura</span><span class=\"t-es\">Peso / Ancho / Largo / Alto</span></td><td class=\"field-type\">Number</td><td class=\"field-desc\"><span class=\"t-en\">Physical dimensions used to calculate shipping cost.</span><span class=\"t-pt\">Dimensões físicas usadas para calcular o custo de frete.</span><span class=\"t-es\">Dimensiones físicas usadas para calcular el costo de envío.</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"shot\" style=\"margin-top:22px;\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/046-produtos-en-product-edit-bottom-image-upload-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product edit bottom - image upload (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/047-produtos-pt-product-edit-bottom-image-upload-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product edit bottom - image upload (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/048-produtos-es-product-edit-bottom-image-upload-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"product edit bottom - image upload (es)\">\n</div>\n        <table class=\"fields\">\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Image</span><span class=\"t-pt\">Imagem</span><span class=\"t-es\">Imagen</span></td><td class=\"field-type\"><span class=\"t-en\">Upload</span><span class=\"t-pt\">Upload</span><span class=\"t-es\">Carga de archivo</span></td><td class=\"field-desc\"><span class=\"t-en\">Drag-and-drop or \"Browse images\" to add product photos; the first/marked image is the Main one shown in the catalog.</span><span class=\"t-pt\">Arraste e solte ou \"Buscar imagens\" para adicionar fotos do produto; a primeira imagem/marcada é a Principal, exibida no catálogo.</span><span class=\"t-es\">Arrastrar y soltar o \"Buscar imágenes\" para agregar fotos del producto; la primera imagen/marcada es la Principal, mostrada en el catálogo.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"produtos-seo\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Edit &gt; SEO</span><span class=\"t-pt\">Produtos &gt; Editar &gt; SEO</span><span class=\"t-es\">Productos &gt; Editar &gt; SEO</span></span></h3>\n        <h3><span class=\"t-en\">SEO tab</span><span class=\"t-pt\">Aba SEO</span><span class=\"t-es\">Pestaña SEO</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Search-engine-optimization fields for the product's public page on the storefront.</p></span><span class=\"t-pt\"><p>Campos de otimização para buscadores da página pública do produto na loja virtual.</p></span><span class=\"t-es\"><p>Campos de optimización para buscadores de la página pública del producto en la tienda virtual.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/049-produtos-en-seo-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"SEO tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/050-produtos-pt-seo-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"SEO tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/051-produtos-es-seo-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"SEO tab (es)\">\n          <figcaption><span class=\"t-en\">SEO tab: tags, title, URL and meta description</span><span class=\"t-pt\">Aba SEO: tags, título, URL e meta descrição</span><span class=\"t-es\">Pestaña SEO: etiquetas, título, URL y meta descripción</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">SEO tags</span><span class=\"t-pt\">Tags SEO</span><span class=\"t-es\">Etiquetas SEO</span></td><td class=\"field-type\"><span class=\"t-en\">Text (multiple)</span><span class=\"t-pt\">Texto (múltiplos)</span><span class=\"t-es\">Texto (múltiples)</span></td><td class=\"field-desc\"><span class=\"t-en\">Free keywords for the product, added one at a time by pressing Enter.</span><span class=\"t-pt\">Palavras-chave livres do produto, adicionadas uma a uma ao pressionar Enter.</span><span class=\"t-es\">Palabras clave libres del producto, agregadas una a una al presionar Enter.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">SEO title</span><span class=\"t-pt\">Título SEO</span><span class=\"t-es\">Título SEO</span></td><td class=\"field-type\">Text</td><td class=\"field-desc\"><span class=\"t-en\">Overrides the page title used by search engines; falls back to the product title when empty.</span><span class=\"t-pt\">Substitui o título de página usado pelos buscadores; usa o título do produto quando vazio.</span><span class=\"t-es\">Sustituye el título de página usado por los buscadores; usa el título del producto cuando está vacío.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">SEO URL</span><span class=\"t-pt\">URL SEO</span><span class=\"t-es\">URL SEO</span></td><td class=\"field-type\">Text</td><td class=\"field-desc\"><span class=\"t-en\">The product's public URL slug on the storefront domain.</span><span class=\"t-pt\">O slug da URL pública do produto no domínio da loja virtual.</span><span class=\"t-es\">El slug de la URL pública del producto en el dominio de la tienda virtual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Meta tag description</span><span class=\"t-pt\">Meta tag description</span><span class=\"t-es\">Meta tag description</span></td><td class=\"field-type\">Text</td><td class=\"field-desc\"><span class=\"t-en\">Short description shown by search engines below the page title in results.</span><span class=\"t-pt\">Descrição curta exibida pelos buscadores abaixo do título da página nos resultados.</span><span class=\"t-es\">Descripción corta mostrada por los buscadores debajo del título de la página en los resultados.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"produtos-variacoes\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Edit &gt; Variants</span><span class=\"t-pt\">Produtos &gt; Editar &gt; Variações</span><span class=\"t-es\">Productos &gt; Editar &gt; Variantes</span></span></h3>\n        <h3><span class=\"t-en\">Variants tab</span><span class=\"t-pt\">Aba Variações</span><span class=\"t-es\">Pestaña Variantes</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Used only for \"Standard\" type products, to register variations of the same product (e.g. different colors or sizes) as a grid. Not used for \"Kit\" or \"Build your own\" types. This catalog currently has no product with variants configured, so the screen below shows its default/empty state.</p></span><span class=\"t-pt\"><p>Usada apenas em produtos do tipo \"Padrão\", para cadastrar variações do mesmo produto (ex.: cores ou tamanhos diferentes) em forma de grade. Não é usada nos tipos \"Kit\" ou \"Monte o seu\". Este catálogo não tem, no momento, nenhum produto com variações configuradas, então a tela abaixo mostra seu estado padrão/vazio.</p></span><span class=\"t-es\"><p>Se usa solo en productos de tipo \"Estándar\", para registrar variantes del mismo producto (ej.: colores o tallas diferentes) en forma de cuadrícula. No se usa en los tipos \"Kit\" o \"Arma tu propio\". Este catálogo no tiene, por el momento, ningún producto con variantes configuradas, así que la pantalla de abajo muestra su estado predeterminado/vacío.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/052-produtos-en-variants-tab-default-state-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"variants tab default state (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/053-produtos-pt-variants-tab-default-state-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"variants tab default state (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/054-produtos-es-variants-tab-default-state-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"variants tab default state (es)\">\n          <figcaption><span class=\"t-en\">Variants tab in its default state: grid composition and \"Add grid\"</span><span class=\"t-pt\">Aba Variações em seu estado padrão: composição das grades e \"Adicionar grade\"</span><span class=\"t-es\">Pestaña Variantes en su estado predeterminado: composición de la grilla y \"Agregar grid\"</span></figcaption>\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Composition of grid</span><span class=\"t-pt\">Composição das grades</span><span class=\"t-es\">Composición de grid</span></b> &mdash; <span class=\"t-en\">expandable panel showing the variation attributes (e.g. Color, Size) once created.</span><span class=\"t-pt\">painel expansível que mostra os atributos de variação (ex.: Cor, Tamanho) depois de criados.</span><span class=\"t-es\">panel expandible que muestra los atributos de variación (ej.: Color, Talla) una vez creados.</span></li>\n          <li><b><span class=\"t-en\">Add grid</span><span class=\"t-pt\">Adicionar grade</span><span class=\"t-es\">Agregar grid</span></b> &mdash; <span class=\"t-en\">creates a new variation attribute and its possible values, generating one product line per combination.</span><span class=\"t-pt\">cria um novo atributo de variação e seus valores possíveis, gerando uma linha de produto por combinação.</span><span class=\"t-es\">crea un nuevo atributo de variación y sus valores posibles, generando una línea de producto por combinación.</span></li>\n          <li><b><span class=\"t-en\">Change SKU pattern</span><span class=\"t-pt\">Mudar padrão de sku</span><span class=\"t-es\">Cambiar patrón de SKU</span></b> &mdash; <span class=\"t-en\">lets each generated variant use a custom SKU pattern instead of the default one.</span><span class=\"t-pt\">permite que cada variação gerada use um padrão de SKU customizado em vez do padrão.</span><span class=\"t-es\">permite que cada variante generada use un patrón de SKU personalizado en lugar del predeterminado.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"produtos-kit\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Edit &gt; Kit</span><span class=\"t-pt\">Produtos &gt; Editar &gt; Kit</span><span class=\"t-es\">Productos &gt; Editar &gt; Kit</span></span></h3>\n        <h3><span class=\"t-en\">Kit tab</span><span class=\"t-pt\">Aba Kit</span><span class=\"t-es\">Pestaña Kit</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Used only for \"Kit\" type products, to bundle several existing products sold together under one price. Not used for \"Standard\" or \"Build your own\" types. This catalog currently has no Kit-type product, so the screen below shows its default/empty state.</p></span><span class=\"t-pt\"><p>Usada apenas em produtos do tipo \"Kit\", para reunir vários produtos já existentes vendidos juntos por um preço único. Não é usada nos tipos \"Padrão\" ou \"Monte o seu\". Este catálogo não tem, no momento, nenhum produto do tipo Kit, então a tela abaixo mostra seu estado padrão/vazio.</p></span><span class=\"t-es\"><p>Se usa solo en productos de tipo \"Kit\", para reunir varios productos ya existentes vendidos juntos por un precio único. No se usa en los tipos \"Estándar\" o \"Arma tu propio\". Este catálogo no tiene, por el momento, ningún producto de tipo Kit, así que la pantalla de abajo muestra su estado predeterminado/vacío.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/055-produtos-en-kit-tab-default-state-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"kit tab default state (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/056-produtos-pt-kit-tab-default-state-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"kit tab default state (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/057-produtos-es-kit-tab-default-state-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"kit tab default state (es)\">\n          <figcaption><span class=\"t-en\">Kit tab in its default state: pricing fields and the empty component list</span><span class=\"t-pt\">Aba Kit em seu estado padrão: campos de preço e a lista de componentes vazia</span><span class=\"t-es\">Pestaña Kit en su estado predeterminado: campos de precio y la lista de componentes vacía</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Cost price / Standard price</span><span class=\"t-pt\">Preço de custo / Preço padrão</span><span class=\"t-es\">Precio de costo / Precio estándar</span></td><td class=\"field-type\">Currency</td><td class=\"field-desc\"><span class=\"t-en\">Cost and sale price of the kit as a whole.</span><span class=\"t-pt\">Custo e preço de venda do kit como um todo.</span><span class=\"t-es\">Costo y precio de venta del kit en su conjunto.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Promotional discount / Price promotion</span><span class=\"t-pt\">Desconto promocional / Preço promoção</span><span class=\"t-es\">Descuento promocional / Precio promoción</span></td><td class=\"field-type\">% / Currency</td><td class=\"field-desc\"><span class=\"t-en\">Optional discount applied to the kit price.</span><span class=\"t-pt\">Desconto opcional aplicado ao preço do kit.</span><span class=\"t-es\">Descuento opcional aplicado al precio del kit.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Select a product / Include in bulk</span><span class=\"t-pt\">Selecione um produto / Incluir em massa</span><span class=\"t-es\">Seleccione un producto / Incluir en lote</span></td><td class=\"field-type\"><span class=\"t-en\">Search / Button</span><span class=\"t-pt\">Busca / Botão</span><span class=\"t-es\">Búsqueda / Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Adds the existing products that make up the kit, one by one or in bulk.</span><span class=\"t-pt\">Adiciona os produtos já existentes que compõem o kit, um a um ou em massa.</span><span class=\"t-es\">Agrega los productos ya existentes que componen el kit, uno a uno o en lote.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Table: Product / Quantity / Price / Info</span><span class=\"t-pt\">Tabela: Produto / Quantidade / Preço / Info</span><span class=\"t-es\">Tabla: Producto / Cantidad / Precio / Info</span></td><td class=\"field-type\"><span class=\"t-en\">List</span><span class=\"t-pt\">Lista</span><span class=\"t-es\">Lista</span></td><td class=\"field-desc\"><span class=\"t-en\">Each component product added to the kit, with the quantity included and its individual price.</span><span class=\"t-pt\">Cada produto componente adicionado ao kit, com a quantidade incluída e seu preço individual.</span><span class=\"t-es\">Cada producto componente agregado al kit, con la cantidad incluida y su precio individual.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"produtos-monteoseu\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Edit &gt; Build your own</span><span class=\"t-pt\">Produtos &gt; Editar &gt; Monte o seu</span><span class=\"t-es\">Productos &gt; Editar &gt; Arma tu propio</span></span></h3>\n        <h3><span class=\"t-en\">Build your own tab</span><span class=\"t-pt\">Aba Monte o seu</span><span class=\"t-es\">Pestaña Arma tu propio</span></h3>\n        <div class=\"desc\"><p><span class=\"t-en\">Used only for \"Build your own\" type products, to configure the sections and options the customer picks from to assemble the product on the storefront (e.g. a school-supplies kit where the customer chooses the notebook, pencils, eraser, etc.). This is the most complex tab, since each configurable section behaves as its own small product list with its own rules.</span><span class=\"t-pt\">Usada apenas em produtos do tipo \"Monte o seu\", para configurar as seções e opções que o cliente escolhe para montar o produto na loja virtual (ex.: um kit escolar em que o cliente escolhe o caderno, os lápis, a borracha etc.). É a aba mais complexa, já que cada seção configurável funciona como uma pequena lista de produtos com regras próprias.</span><span class=\"t-es\">Se usa solo en productos de tipo \"Arma tu propio\", para configurar las secciones y opciones que el cliente elige para armar el producto en la tienda virtual (ej.: un kit escolar en el que el cliente elige el cuaderno, los lápices, la goma, etc.). Es la pestaña más compleja, ya que cada sección configurable funciona como una pequeña lista de productos con sus propias reglas.</span></p></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/058-produtos-en-build-your-own-tab-pricing-and-first-configurabl.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"build your own tab - pricing and first configurable section (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/059-produtos-pt-build-your-own-tab-pricing-and-first-configurabl.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"build your own tab - pricing and first configurable section (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/060-produtos-es-build-your-own-tab-pricing-and-first-configurabl.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"build your own tab - pricing and first configurable section (es)\">\n</div>\n        <table class=\"fields\">\n          <thead><tr><th style=\"width:22%\"><span class=\"t-en\">Block / field</span><span class=\"t-pt\">Bloco / campo</span><span class=\"t-es\">Bloque / campo</span></th><th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th><th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th></tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Standard price / Cost price</span><span class=\"t-pt\">Preço padrão / Preço de custo</span><span class=\"t-es\">Precio estándar / Precio de costo</span></td><td class=\"field-type\">Currency</td><td class=\"field-desc\"><span class=\"t-en\">Base price of the assembled product and its cost.</span><span class=\"t-pt\">Preço base do produto montado e seu custo.</span><span class=\"t-es\">Precio base del producto armado y su costo.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Promotional discount / Price promotion</span><span class=\"t-pt\">Desconto promocional / Preço promoção</span><span class=\"t-es\">Descuento promocional / Precio promoción</span></td><td class=\"field-type\">% / Currency</td><td class=\"field-desc\"><span class=\"t-en\">Optional discount applied to the whole assembled product.</span><span class=\"t-pt\">Desconto opcional aplicado ao produto montado como um todo.</span><span class=\"t-es\">Descuento opcional aplicado al producto armado en su conjunto.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Components promotion</span><span class=\"t-pt\">Promoção componentes</span><span class=\"t-es\">Promoción componentes</span></td><td class=\"field-type\">Toggle</td><td class=\"field-desc\"><span class=\"t-en\">When enabled, promotional prices set on the individual component products are also applied here.</span><span class=\"t-pt\">Quando ativado, os preços promocionais definidos nos produtos componentes individuais também são aplicados aqui.</span><span class=\"t-es\">Cuando está activado, los precios promocionales definidos en los productos componentes individuales también se aplican aquí.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Hide initial price</span><span class=\"t-pt\">Ocultar preço inicial</span><span class=\"t-es\">Ocultar precio inicial</span></td><td class=\"field-type\">Toggle</td><td class=\"field-desc\"><span class=\"t-en\">Hides the \"starting from\" base price on the storefront, showing only the final calculated price.</span><span class=\"t-pt\">Oculta o preço inicial \"a partir de\" na loja virtual, mostrando apenas o preço final calculado.</span><span class=\"t-es\">Oculta el precio inicial \"desde\" en la tienda virtual, mostrando solo el precio final calculado.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Add section</span><span class=\"t-pt\">Adicionar seção</span><span class=\"t-es\">Agregar sección</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Creates a new configurable section (e.g. \"Notebook\", \"Pencils\") that the customer will choose products from.</span><span class=\"t-pt\">Cria uma nova seção configurável (ex.: \"Caderno\", \"Lápis\") da qual o cliente escolherá produtos.</span><span class=\"t-es\">Crea una nueva sección configurable (ej.: \"Cuaderno\", \"Lápices\") de la cual el cliente elegirá productos.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Distinct products / Min qty / Max qty</span><span class=\"t-pt\">Produtos distintos / Qtd. mínima / Qtd. máxima</span><span class=\"t-es\">Productos distintos / Cant. mínima / Cant. máxima</span></td><td class=\"field-type\">Number</td><td class=\"field-desc\"><span class=\"t-en\">How many different products the customer may pick in this section, and the minimum/maximum total quantity.</span><span class=\"t-pt\">Quantos produtos diferentes o cliente pode escolher nesta seção, e a quantidade total mínima/máxima.</span><span class=\"t-es\">Cuántos productos diferentes puede elegir el cliente en esta sección, y la cantidad total mínima/máxima.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Selection type / Visualization</span><span class=\"t-pt\">Tipo de seleção / Visualização</span><span class=\"t-es\">Tipo de selección / Visualización</span></td><td class=\"field-type\">Select / Toggle</td><td class=\"field-desc\"><span class=\"t-en\">How options are presented to the customer, and whether the section starts expanded on the storefront.</span><span class=\"t-pt\">Como as opções são apresentadas ao cliente, e se a seção inicia expandida na loja virtual.</span><span class=\"t-es\">Cómo se presentan las opciones al cliente, y si la sección inicia expandida en la tienda virtual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Select a product / Include in bulk</span><span class=\"t-pt\">Selecione um produto / Incluir em massa</span><span class=\"t-es\">Seleccione un producto / Incluir en lote</span></td><td class=\"field-type\"><span class=\"t-en\">Search / Button</span><span class=\"t-pt\">Busca / Botão</span><span class=\"t-es\">Búsqueda / Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Adds the products available as options in this section, one by one or in bulk.</span><span class=\"t-pt\">Adiciona os produtos disponíveis como opções nesta seção, um a um ou em massa.</span><span class=\"t-es\">Agrega los productos disponibles como opciones en esta sección, uno a uno o en lote.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Table: Product / Initial / Min / Max / Price / Link</span><span class=\"t-pt\">Tabela: Produto / Inicial / Min / Max / Preço / Link</span><span class=\"t-es\">Tabla: Producto / Inicial / Min / Max / Precio / Link</span></td><td class=\"field-type\"><span class=\"t-en\">List</span><span class=\"t-pt\">Lista</span><span class=\"t-es\">Lista</span></td><td class=\"field-desc\"><span class=\"t-en\">Each option product in the section, its default/min/max selectable quantity, its price impact and whether it's active (Link).</span><span class=\"t-pt\">Cada produto opção da seção, sua quantidade padrão/mín/máx selecionável, seu impacto no preço e se está ativo (Link).</span><span class=\"t-es\">Cada producto opción de la sección, su cantidad predeterminada/mín/máx seleccionable, su impacto en el precio y si está activo (Link).</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"shot\" style=\"margin-top:22px;\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/061-produtos-en-build-your-own-tab-list-of-collapsed-configurabl.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"build your own tab - list of collapsed configurable sections (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/062-produtos-pt-build-your-own-tab-list-of-collapsed-configurabl.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"build your own tab - list of collapsed configurable sections (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/063-produtos-es-build-your-own-tab-list-of-collapsed-configurabl.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"build your own tab - list of collapsed configurable sections (es)\">\n</div>\n        <div class=\"note\"><span class=\"t-en\">&#128161; Each configurable section can be dragged to reorder, renamed via the pencil icon, expanded/collapsed via the arrow, and removed via the trash icon &mdash; in the example captured, the product has 9 sections (Book, Eraser, Backpack, Glue, Pens, Notebooks, Colored pencils, Pencil case, Paper), each with its own list of option products configured as shown above.</span><span class=\"t-pt\">&#128161; Cada seção configurável pode ser arrastada para reordenar, renomeada pelo ícone de lápis, expandida/recolhida pela seta, e removida pelo ícone de lixeira &mdash; no exemplo capturado, o produto tem 9 seções (Livro, Borracha, Mochila, Cola, Canetas, Cadernos, Lápis de cor, Estojo, Sulfite), cada uma com sua própria lista de produtos opção configurada como mostrado acima.</span><span class=\"t-es\">&#128161; Cada sección configurable se puede arrastrar para reordenar, renombrar con el ícono de lápiz, expandir/contraer con la flecha, y eliminar con el ícono de papelera &mdash; en el ejemplo capturado, el producto tiene 9 secciones (Libro, Goma, Mochila, Pegamento, Bolígrafos, Cuadernos, Lápices de color, Estuche, Papel), cada una con su propia lista de productos opción configurada como se muestra arriba.</span></div>\n      </div>\n      <div class=\"subsection\" id=\"produtos-relacionados\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Edit &gt; Related</span><span class=\"t-pt\">Produtos &gt; Editar &gt; Relacionados</span><span class=\"t-es\">Productos &gt; Editar &gt; Relacionados</span></span></h3>\n        <h3><span class=\"t-en\">Related tab</span><span class=\"t-pt\">Aba Relacionados</span><span class=\"t-es\">Pestaña Relacionados</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Links other existing products as related items, shown together with this product on the storefront (cross-sell). Available for any product type.</p></span><span class=\"t-pt\"><p>Vincula outros produtos já existentes como itens relacionados, exibidos junto com este produto na loja virtual (cross-sell). Disponível para qualquer tipo de produto.</p></span><span class=\"t-es\"><p>Vincula otros productos ya existentes como artículos relacionados, mostrados junto con este producto en la tienda virtual (venta cruzada). Disponible para cualquier tipo de producto.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/064-produtos-en-related-tab-default-state-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"related tab default state (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/065-produtos-pt-related-tab-default-state-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"related tab default state (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/066-produtos-es-related-tab-default-state-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"related tab default state (es)\">\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Select a product / Include in bulk</span><span class=\"t-pt\">Selecione um produto / Incluir em massa</span><span class=\"t-es\">Seleccione un producto / Incluir en lote</span></td><td class=\"field-type\"><span class=\"t-en\">Search / Button</span><span class=\"t-pt\">Busca / Botão</span><span class=\"t-es\">Búsqueda / Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Adds related products, one by one or in bulk.</span><span class=\"t-pt\">Adiciona produtos relacionados, um a um ou em massa.</span><span class=\"t-es\">Agrega productos relacionados, uno a uno o en lote.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Table: Product</span><span class=\"t-pt\">Tabela: Produto</span><span class=\"t-es\">Tabla: Producto</span></td><td class=\"field-type\"><span class=\"t-en\">List</span><span class=\"t-pt\">Lista</span><span class=\"t-es\">Lista</span></td><td class=\"field-desc\"><span class=\"t-en\">Each related product linked so far; empty (\"Select a product\") until at least one is added.</span><span class=\"t-pt\">Cada produto relacionado já vinculado; vazia (\"Selecione um produto\") até que ao menos um seja adicionado.</span><span class=\"t-es\">Cada producto relacionado ya vinculado; vacía (\"Seleccione un producto\") hasta que se agregue al menos uno.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"produtos-atributos\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Edit &gt; Attributes</span><span class=\"t-pt\">Produtos &gt; Editar &gt; Atributos</span><span class=\"t-es\">Productos &gt; Editar &gt; Atributos</span></span></h3>\n        <h3><span class=\"t-en\">Attributes tab</span><span class=\"t-pt\">Aba Atributos</span><span class=\"t-es\">Pestaña Atributos</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Extra key/value data attached to the product, split into platform-defined default attributes and free-form additional attributes.</p></span><span class=\"t-pt\"><p>Dados extras de chave/valor anexados ao produto, divididos em atributos padrão definidos pela plataforma e atributos adicionais de formato livre.</p></span><span class=\"t-es\"><p>Datos extra de clave/valor anexados al producto, divididos en atributos predeterminados definidos por la plataforma y atributos adicionales de formato libre.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/067-produtos-en-attributes-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"attributes tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/068-produtos-pt-attributes-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"attributes tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/069-produtos-es-attributes-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"attributes tab (es)\">\n          <figcaption><span class=\"t-en\">Attributes tab: default attributes table and additional attributes search</span><span class=\"t-pt\">Aba Atributos: tabela de atributos predeterminados e busca de atributos adicionais</span><span class=\"t-es\">Pestaña Atributos: tabla de atributos predeterminados y búsqueda de atributos adicionales</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Default attributes</span><span class=\"t-pt\">Atributos predeterminados</span><span class=\"t-es\">Atributos predeterminados</span></td><td class=\"field-type\"><span class=\"t-en\">List (Name / Value / Description / Actions)</span><span class=\"t-pt\">Lista (Nome / Valor / Descrição / Ações)</span><span class=\"t-es\">Lista (Nombre / Valor / Descripción / Acciones)</span></td><td class=\"field-desc\"><span class=\"t-en\">Fixed, platform-defined attributes (e.g. buy-button behavior, maximum discount per payment method, checkout file upload) that can be individually edited via the pencil icon.</span><span class=\"t-pt\">Atributos fixos definidos pela plataforma (ex.: comportamento do botão comprar, desconto máximo por forma de pagamento, upload de arquivo no checkout) que podem ser editados individualmente pelo ícone de lápis.</span><span class=\"t-es\">Atributos fijos definidos por la plataforma (ej.: comportamiento del botón comprar, descuento máximo por forma de pago, carga de archivo en el checkout) que se pueden editar individualmente con el ícono de lápiz.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Additional attributes</span><span class=\"t-pt\">Atributos adicionais</span><span class=\"t-es\">Atributos adicionales</span></td><td class=\"field-type\"><span class=\"t-en\">Search + list (Name / Value / Actions)</span><span class=\"t-pt\">Busca + lista (Nome / Valor / Ações)</span><span class=\"t-es\">Búsqueda + lista (Nombre / Valor / Acciones)</span></td><td class=\"field-desc\"><span class=\"t-en\">Free-form custom attributes searched and added by name, each with its own value and add/edit/remove actions.</span><span class=\"t-pt\">Atributos personalizados de formato livre, buscados e adicionados pelo nome, cada um com seu próprio valor e ações de adicionar/editar/remover.</span><span class=\"t-es\">Atributos personalizados de formato libre, buscados y agregados por nombre, cada uno con su propio valor y acciones de agregar/editar/eliminar.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"produtos-criar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Add</span><span class=\"t-pt\">Produtos &gt; Adicionar</span><span class=\"t-es\">Productos &gt; Agregar</span></span></h3>\n        <h3><span class=\"t-en\">Create product</span><span class=\"t-pt\">Criar produto</span><span class=\"t-es\">Crear producto</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via the \"+ Add product\" button in the list. Uses the same blocks as the detail screen (previous subsection), blank, to manually register a new product.</p></span><span class=\"t-pt\"><p>Aberta pelo botão \"+ Adicionar produto\" na lista. Usa os mesmos blocos da tela de detalhe (subseção anterior), em branco, para o cadastro manual de um novo produto.</p></span><span class=\"t-es\"><p>Se abre con el botón \"+ Añadir producto\" en la lista. Usa los mismos bloques de la pantalla de detalle (subsección anterior), en blanco, para el registro manual de un nuevo producto.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/070-produtos-en-add-product-screen-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add product screen (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/071-produtos-pt-add-product-screen-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add product screen (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/072-produtos-es-add-product-screen-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add product screen (es)\">\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Status</span><span class=\"t-pt\">Status</span><span class=\"t-es\">Estado</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle</span><span class=\"t-pt\">Toggle</span><span class=\"t-es\">Interruptor</span></td><td class=\"field-desc\"><span class=\"t-en\">Activates or keeps the product inactive (hidden from the storefront) right from creation.</span><span class=\"t-pt\">Ativa ou mantém o produto inativo (oculto na loja virtual) já na criação.</span><span class=\"t-es\">Activa o mantiene el producto inactivo (oculto en la tienda virtual) desde la creación.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Save</span><span class=\"t-pt\">Salvar</span><span class=\"t-es\">Guardar</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Creates the product with the data filled in on the General data tab (and any other tabs used).</span><span class=\"t-pt\">Cria o produto com os dados preenchidos na aba Dados gerais (e nas demais abas usadas).</span><span class=\"t-es\">Crea el producto con los datos completados en la pestaña Datos generales (y en las demás pestañas usadas).</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"produtos-massa\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; List</span><span class=\"t-pt\">Produtos &gt; Lista</span><span class=\"t-es\">Productos &gt; Lista</span></span></h3>\n        <h3><span class=\"t-en\">Bulk actions and row actions</span><span class=\"t-pt\">Ações em massa e ações por linha</span><span class=\"t-es\">Acciones masivas y acciones por fila</span></h3>\n        <div class=\"desc\"><p><span class=\"t-en\">Two ways to run quick actions directly from the list, without opening the product.</span><span class=\"t-pt\">Duas formas de executar ações rápidas direto na lista, sem abrir o produto.</span><span class=\"t-es\">Dos formas de ejecutar acciones rápidas directamente en la lista, sin abrir el producto.</span></p></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/073-produtos-en-bulk-actions-menu-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk actions menu (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/074-produtos-pt-bulk-actions-menu-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk actions menu (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/075-produtos-es-bulk-actions-menu-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk actions menu (es)\">\n          <figcaption><span class=\"t-en\">Select 1+ products via the checkbox and click \"More options\"</span><span class=\"t-pt\">Selecione 1+ produtos pela caixinha e clique em \"Mais opções\"</span><span class=\"t-es\">Seleccione 1 o más productos con la casilla y haga clic en \"Más opciones\"</span></figcaption>\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Bulk remove</span><span class=\"t-pt\">Remover em massa</span><span class=\"t-es\">Eliminar en masa</span></b> &mdash; <span class=\"t-en\">permanently removes all selected products.</span><span class=\"t-pt\">remove permanentemente todos os produtos selecionados.</span><span class=\"t-es\">elimina permanentemente todos los productos seleccionados.</span></li>\n          <li><b><span class=\"t-en\">Bulk add category</span><span class=\"t-pt\">Adicionar categoria em massa</span><span class=\"t-es\">Agregar categoría en masa</span></b> &mdash; <span class=\"t-en\">assigns a category to all selected products at once.</span><span class=\"t-pt\">atribui uma categoria a todos os produtos selecionados de uma vez.</span><span class=\"t-es\">asigna una categoría a todos los productos seleccionados a la vez.</span></li>\n          <li><b><span class=\"t-en\">Bulk add brand</span><span class=\"t-pt\">Adicionar marca em massa</span><span class=\"t-es\">Agregar marca en masa</span></b> &mdash; <span class=\"t-en\">assigns a brand to all selected products at once.</span><span class=\"t-pt\">atribui uma marca a todos os produtos selecionados de uma vez.</span><span class=\"t-es\">asigna una marca a todos los productos seleccionados a la vez.</span></li>\n        </ul>\n        <div class=\"shot\" style=\"margin-top:22px;\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/076-produtos-en-row-actions-menu-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"row actions menu (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/077-produtos-pt-row-actions-menu-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"row actions menu (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/078-produtos-es-row-actions-menu-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"row actions menu (es)\">\n          <figcaption><span class=\"t-en\">Click the 3 dots (&#8942;) in the \"Actions\" column of a row</span><span class=\"t-pt\">Clique nos 3 pontinhos (&#8942;) na coluna \"Ações\" de uma linha</span><span class=\"t-es\">Haga clic en los 3 puntos (&#8942;) en la columna \"Acciones\" de una fila</span></figcaption>\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the product for editing.</span><span class=\"t-pt\">abre o produto para edição.</span><span class=\"t-es\">abre el producto para edición.</span></li>\n          <li><b><span class=\"t-en\">Deactivate</span><span class=\"t-pt\">Desativar</span><span class=\"t-es\">Desactivar</span></b> &mdash; <span class=\"t-en\">hides the product from the storefront without deleting it.</span><span class=\"t-pt\">oculta o produto da loja virtual sem excluí-lo.</span><span class=\"t-es\">oculta el producto de la tienda virtual sin eliminarlo.</span></li>\n          <li><b><span class=\"t-en\">Go to product</span><span class=\"t-pt\">Ir ao produto</span><span class=\"t-es\">Ir al producto</span></b> &mdash; <span class=\"t-en\">opens the product's public page on the storefront in a new tab.</span><span class=\"t-pt\">abre a página pública do produto na loja virtual em uma nova aba.</span><span class=\"t-es\">abre la página pública del producto en la tienda virtual en una pestaña nueva.</span></li>\n          <li><b><span class=\"t-en\">Remove</span><span class=\"t-pt\">Remover</span><span class=\"t-es\">Eliminar</span></b> &mdash; <span class=\"t-en\">permanently deletes the product.</span><span class=\"t-pt\">exclui o produto permanentemente.</span><span class=\"t-es\">elimina el producto de forma permanente.</span></li>\n        </ul>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=pedidos\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Orders</span><span class=\"t-pt\">Pedidos</span><span class=\"t-es\">Pedidos</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=precos\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Price tables</span><span class=\"t-pt\">Tabelas de preço</span><span class=\"t-es\">Tablas de precios</span></strong></a>\n</nav>\n", "precos": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Price tables</span><span class=\"t-pt\">Tabelas de preço</span><span class=\"t-es\">Tablas de precios</span></p>\n<section class=\"doc-section\" id=\"precos\">\n      <h2><span class=\"t-en\">4. Products &gt; Price tables</span><span class=\"t-pt\">4. Produtos &gt; Tabelas de preço</span><span class=\"t-es\">4. Productos &gt; Tablas de precios</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Price tables let the same catalog be sold at different prices, margins and conditions &mdash; for example one table per sales channel, or a special table restricted to customers with a given document type (CPF/CNPJ). Each product can have its cost, margin, price and promotional price set independently on every table.</span><span class=\"t-pt\">As tabelas de preço permitem vender o mesmo catálogo com preços, margens e condições diferentes &mdash; por exemplo, uma tabela por canal de venda, ou uma tabela especial restrita a clientes com determinado tipo de documento (CPF/CNPJ). Cada produto pode ter custo, margem, preço e preço promocional definidos de forma independente em cada tabela.</span><span class=\"t-es\">Las tablas de precios permiten vender el mismo catálogo con precios, márgenes y condiciones diferentes &mdash; por ejemplo, una tabla por canal de venta, o una tabla especial restringida a clientes con determinado tipo de documento (CPF/CNPJ). Cada producto puede tener costo, margen, precio y precio promocional definidos de forma independiente en cada tabla.</span>\n      </p>\n      <div class=\"subsection\" id=\"precos-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Price tables</span><span class=\"t-pt\">Produtos &gt; Tabelas de preço</span><span class=\"t-es\">Productos &gt; Tablas de precios</span></span></h3>\n        <h3><span class=\"t-en\">Price table list</span><span class=\"t-pt\">Lista de tabelas de preço</span><span class=\"t-es\">Lista de tablas de precios</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Initial screen of the section. Shows every price table registered in the store, one row per table. Each table works like a separate price list that can later be applied to a sales channel or to a group of customers &mdash; this screen only manages the tables themselves, not the individual product prices (see the next subsections).</p></span><span class=\"t-pt\"><p>Tela inicial da seção. Mostra todas as tabelas de preço cadastradas na loja, uma linha por tabela. Cada tabela funciona como uma lista de preços separada, que depois pode ser aplicada a um canal de venda ou a um grupo de clientes &mdash; esta tela só gerencia as tabelas em si, não os preços individuais dos produtos (ver próximas subseções).</p></span><span class=\"t-es\"><p>Pantalla inicial de la sección. Muestra todas las tablas de precios registradas en la tienda, una fila por tabla. Cada tabla funciona como una lista de precios independiente, que luego puede aplicarse a un canal de venta o a un grupo de clientes &mdash; esta pantalla solo gestiona las tablas en sí, no los precios individuales de los productos (ver próximas subsecciones).</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/079-precos-en-price-table-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"price table list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/080-precos-pt-price-table-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"price table list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/081-precos-es-price-table-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"price table list (es)\">\n          <figcaption><span class=\"t-en\">Products &gt; Price tables screen, listing every price table</span><span class=\"t-pt\">Tela Produtos &gt; Tabelas de preço, listando todas as tabelas de preço</span><span class=\"t-es\">Pantalla Productos &gt; Tablas de precios, con la lista de todas las tablas de precios</span></figcaption>\n        </div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/082-precos-en-price-table-row-actions-menu-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"price table row actions menu (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/083-precos-pt-price-table-row-actions-menu-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"price table row actions menu (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/084-precos-es-price-table-row-actions-menu-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"price table row actions menu (es)\">\n          <figcaption><span class=\"t-en\">Row actions menu, opened via the 3 dots (&#8942;) in the \"Actions\" column</span><span class=\"t-pt\">Menu de ações da linha, aberto pelos 3 pontinhos (&#8942;) na coluna \"Ações\"</span><span class=\"t-es\">Menú de acciones de la fila, abierto con los 3 puntos (&#8942;) en la columna \"Acciones\"</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">ID / Name</span><span class=\"t-pt\">ID / Nome</span><span class=\"t-es\">ID / Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Table identifier and name; clicking the name also opens editing.</span><span class=\"t-pt\">Identificador e nome da tabela; clicar no nome também abre a edição.</span><span class=\"t-es\">Identificador y nombre de la tabla; hacer clic en el nombre también abre la edición.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Documents</span><span class=\"t-pt\">Documentos</span><span class=\"t-es\">Documentos</span></td><td class=\"field-type\"><span class=\"t-en\">Tag</span><span class=\"t-pt\">Tag</span><span class=\"t-es\">Etiqueta</span></td><td class=\"field-desc\"><span class=\"t-en\">Which customer document types (CPF, CNPJ, CNPJ with state registration, foreign) this table applies to; \"Channel default\" means no restriction.</span><span class=\"t-pt\">Para quais tipos de documento de cliente (CPF, CNPJ, CNPJ com IE, estrangeiro) esta tabela vale; \"Padrão do canal\" significa sem restrição.</span><span class=\"t-es\">Para qué tipos de documento de cliente (CPF, CNPJ, CNPJ con IE, extranjero) aplica esta tabla; \"Predeterminado del canal\" significa sin restricción.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Cost</span><span class=\"t-pt\">Custo</span><span class=\"t-es\">Costo</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Base used to calculate the price: the product's own cost price, or another price table's price.</span><span class=\"t-pt\">Base usada para calcular o preço: o preço de custo do próprio produto, ou o preço de outra tabela.</span><span class=\"t-es\">Base usada para calcular el precio: el precio de costo del propio producto, o el precio de otra tabla.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Margin / Minimum value</span><span class=\"t-pt\">Margem / Valor mínimo</span><span class=\"t-es\">Margen / Valor mínimo</span></td><td class=\"field-type\"><span class=\"t-en\">Number</span><span class=\"t-pt\">Número</span><span class=\"t-es\">Número</span></td><td class=\"field-desc\"><span class=\"t-en\">Default markup percentage applied over the cost, and an optional floor price for the table.</span><span class=\"t-pt\">Percentual de markup padrão aplicado sobre o custo, e um preço mínimo opcional para a tabela.</span><span class=\"t-es\">Porcentaje de margen predeterminado aplicado sobre el costo, y un precio mínimo opcional para la tabla.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Default</span><span class=\"t-pt\">Padrão</span><span class=\"t-es\">Predeterminado</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle button</span><span class=\"t-pt\">Botão de alternância</span><span class=\"t-es\">Botón de alternancia</span></td><td class=\"field-desc\"><span class=\"t-en\">Marks the table used whenever no other table applies; only one table can be Default, and it cannot be deleted.</span><span class=\"t-pt\">Marca a tabela usada quando nenhuma outra se aplica; apenas uma tabela pode ser Padrão, e ela não pode ser excluída.</span><span class=\"t-es\">Marca la tabla usada cuando ninguna otra aplica; solo una tabla puede ser Predeterminada, y no se puede eliminar.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">+ Add price table</span><span class=\"t-pt\">+ Adicionar tabela</span><span class=\"t-es\">+ Agregar tabla</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Opens the form to create a new price table (see \"Create / edit table\").</span><span class=\"t-pt\">Abre o formulário para criar uma nova tabela de preço (ver \"Criar/editar tabela\").</span><span class=\"t-es\">Abre el formulario para crear una nueva tabla de precios (ver \"Crear/editar tabla\").</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">List products</span><span class=\"t-pt\">Listar produtos</span><span class=\"t-es\">Listar productos</span></b> &mdash; <span class=\"t-en\">opens this table's product list, where each product's cost/margin/price can be set (see next subsection).</span><span class=\"t-pt\">abre a lista de produtos desta tabela, onde custo/margem/preço de cada produto pode ser definido (ver próxima subseção).</span><span class=\"t-es\">abre la lista de productos de esta tabla, donde se puede definir costo/margen/precio de cada producto (ver próxima subsección).</span></li>\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the same form used to create a table, with its current settings.</span><span class=\"t-pt\">abre o mesmo formulário usado para criar uma tabela, com as configurações atuais.</span><span class=\"t-es\">abre el mismo formulario usado para crear una tabla, con la configuración actual.</span></li>\n          <li><b><span class=\"t-en\">Clone</span><span class=\"t-pt\">Clonar</span><span class=\"t-es\">Clonar</span></b> &mdash; <span class=\"t-en\">creates a copy of the table, including the prices already set for each product.</span><span class=\"t-pt\">cria uma cópia da tabela, incluindo os preços já definidos para cada produto.</span><span class=\"t-es\">crea una copia de la tabla, incluyendo los precios ya definidos para cada producto.</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">permanently removes the table; disabled for the Default table.</span><span class=\"t-pt\">remove a tabela permanentemente; desabilitado para a tabela Padrão.</span><span class=\"t-es\">elimina la tabla de forma permanente; deshabilitado para la tabla Predeterminada.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"precos-criar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Price tables &gt; Add/Edit</span><span class=\"t-pt\">Produtos &gt; Tabelas de preço &gt; Adicionar/Editar</span><span class=\"t-es\">Productos &gt; Tablas de precios &gt; Agregar/Editar</span></span></h3>\n        <h3><span class=\"t-en\">Create / edit price table</span><span class=\"t-pt\">Criar/editar tabela</span><span class=\"t-es\">Crear/editar tabla</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via \"Add price table\" or via \"Edit\" in a row's actions menu. Both use the same form.</p></span><span class=\"t-pt\"><p>Aberta pelo botão \"Adicionar tabela\" ou pelo \"Editar\" no menu de ações da linha. Ambos usam o mesmo formulário.</p></span><span class=\"t-es\"><p>Se abre con el botón \"Agregar tabla\" o con \"Editar\" en el menú de acciones de la fila. Ambos usan el mismo formulario.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/085-precos-en-add-edit-price-table-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add/edit price table modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/086-precos-pt-add-edit-price-table-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add/edit price table modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/087-precos-es-add-edit-price-table-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add/edit price table modal (es)\">\n          <figcaption><span class=\"t-en\">\"Add price table\" form, with name, documents, cost basis, default margin and minimum value</span><span class=\"t-pt\">Formulário \"Adicionar tabela\", com nome, documentos, base de custo, margem padrão e valor mínimo</span><span class=\"t-es\">Formulario \"Agregar tabla\", con nombre, documentos, base de costo, margen predeterminado y valor mínimo</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Internal name used to identify the table in the list and in the tabs of the product list screen.</span><span class=\"t-pt\">Nome interno usado para identificar a tabela na lista e nas abas da tela de produtos.</span><span class=\"t-es\">Nombre interno usado para identificar la tabla en la lista y en las pestañas de la pantalla de productos.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Documents</span><span class=\"t-pt\">Documentos</span><span class=\"t-es\">Documentos</span></td><td class=\"field-type\"><span class=\"t-en\">Multi-select</span><span class=\"t-pt\">Multisseleção</span><span class=\"t-es\">Multiselección</span></td><td class=\"field-desc\"><span class=\"t-en\">Restricts the table to customers with CPF, CNPJ, CNPJ with state registration and/or foreign documents; leave empty for the channel default.</span><span class=\"t-pt\">Restringe a tabela a clientes com CPF, CNPJ, CNPJ com IE e/ou documentos estrangeiros; deixe vazio para o padrão do canal.</span><span class=\"t-es\">Restringe la tabla a clientes con CPF, CNPJ, CNPJ con IE y/o documentos extranjeros; deje vacío para el predeterminado del canal.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Cost</span><span class=\"t-pt\">Custo</span><span class=\"t-es\">Costo</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">\"Product\" calculates from the product's own cost price; \"Price table\" calculates from another table's resulting price instead.</span><span class=\"t-pt\">\"Produto\" calcula a partir do preço de custo do próprio produto; \"Tabela de preço\" calcula a partir do preço resultante de outra tabela.</span><span class=\"t-es\">\"Producto\" calcula a partir del precio de costo del propio producto; \"Tabla de precios\" calcula a partir del precio resultante de otra tabla.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Default margin</span><span class=\"t-pt\">Margem padrão</span><span class=\"t-es\">Margen predeterminado</span></td><td class=\"field-type\"><span class=\"t-en\">Number (%)</span><span class=\"t-pt\">Número (%)</span><span class=\"t-es\">Número (%)</span></td><td class=\"field-desc\"><span class=\"t-en\">Markup percentage applied over the cost to suggest each product's price on this table.</span><span class=\"t-pt\">Percentual de markup aplicado sobre o custo para sugerir o preço de cada produto nesta tabela.</span><span class=\"t-es\">Porcentaje de margen aplicado sobre el costo para sugerir el precio de cada producto en esta tabla.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Minimum value</span><span class=\"t-pt\">Valor mínimo</span><span class=\"t-es\">Valor mínimo</span></td><td class=\"field-type\"><span class=\"t-en\">Currency</span><span class=\"t-pt\">Moeda</span><span class=\"t-es\">Moneda</span></td><td class=\"field-desc\"><span class=\"t-en\">Optional floor price for products on this table.</span><span class=\"t-pt\">Preço mínimo opcional para os produtos desta tabela.</span><span class=\"t-es\">Precio mínimo opcional para los productos de esta tabla.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Active</span><span class=\"t-pt\">Ativo</span><span class=\"t-es\">Activo</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle</span><span class=\"t-pt\">Alternância</span><span class=\"t-es\">Alternancia</span></td><td class=\"field-desc\"><span class=\"t-en\">Enables or disables the table without deleting it; only shown when editing an existing table.</span><span class=\"t-pt\">Ativa ou desativa a tabela sem excluí-la; só aparece ao editar uma tabela existente.</span><span class=\"t-es\">Activa o desactiva la tabla sin eliminarla; solo aparece al editar una tabla existente.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"precos-produtos\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Price tables &gt; List products</span><span class=\"t-pt\">Produtos &gt; Tabelas de preço &gt; Listar produtos</span><span class=\"t-es\">Productos &gt; Tablas de precios &gt; Listar productos</span></span></h3>\n        <h3><span class=\"t-en\">Table products &amp; bulk pricing</span><span class=\"t-pt\">Produtos da tabela e reajuste em massa</span><span class=\"t-es\">Productos de la tabla y reajuste masivo</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via \"List products\" in a table's actions menu. Shows every product in the catalog with its cost, margin, price and promotional price on that specific table, all editable inline. The tabs at the top (one per price table) are simply a quick way to switch which table is being edited &mdash; they are not different screens, just the different price tables described in the previous subsections.</p></span><span class=\"t-pt\"><p>Aberta pelo \"Listar produtos\" no menu de ações de uma tabela. Mostra todos os produtos do catálogo com custo, margem, preço e preço promocional naquela tabela específica, tudo editável direto na linha. As abas no topo (uma por tabela de preço) são apenas um atalho para trocar qual tabela está sendo editada &mdash; não são telas diferentes, apenas as mesmas tabelas de preço descritas nas subseções anteriores.</p></span><span class=\"t-es\"><p>Se abre con \"Listar productos\" en el menú de acciones de una tabla. Muestra todos los productos del catálogo con costo, margen, precio y precio promocional en esa tabla específica, todo editable directamente en la fila. Las pestañas en la parte superior (una por tabla de precios) son solo un atajo para cambiar qué tabla se está editando &mdash; no son pantallas diferentes, sino las mismas tablas de precios descritas en las subsecciones anteriores.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/088-precos-en-price-table-product-list-with-editable-pricing-c.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"price table product list with editable pricing columns (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/089-precos-pt-price-table-product-list-with-editable-pricing-c.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"price table product list with editable pricing columns (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/090-precos-es-price-table-product-list-with-editable-pricing-c.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"price table product list with editable pricing columns (es)\">\n</div>\n        <table class=\"fields\">\n          <thead><tr><th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th><th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th><th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th></tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Table tabs</span><span class=\"t-pt\">Abas de tabelas</span><span class=\"t-es\">Pestañas de tablas</span></td><td class=\"field-type\"><span class=\"t-en\">Tabs</span><span class=\"t-pt\">Abas</span><span class=\"t-es\">Pestañas</span></td><td class=\"field-desc\"><span class=\"t-en\">One tab per price table registered in the store; switching tabs loads that table's prices for the same product list.</span><span class=\"t-pt\">Uma aba por tabela de preço cadastrada na loja; trocar de aba carrega os preços daquela tabela para a mesma lista de produtos.</span><span class=\"t-es\">Una pestaña por tabla de precios registrada en la tienda; cambiar de pestaña carga los precios de esa tabla para la misma lista de productos.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search / filters</span><span class=\"t-pt\">Busca / filtros</span><span class=\"t-es\">Búsqueda / filtros</span></td><td class=\"field-type\"><span class=\"t-en\">Text / Select</span><span class=\"t-pt\">Texto / Seleção</span><span class=\"t-es\">Texto / Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Search by ID, SKU, GTIN or title, plus filters by category, brand and the product's status on this table; \"More filters\" opens a side panel with further criteria (distribution center, condition, storage, stock, images, etc.), mirroring the product list's own filters.</span><span class=\"t-pt\">Busca por ID, SKU, GTIN ou título, além de filtros por categoria, marca e status do produto nesta tabela; \"Mais filtros\" abre um painel lateral com critérios adicionais (centro de distribuição, condição, armazenagem, estoque, imagens, etc.), semelhante aos filtros da própria lista de produtos.</span><span class=\"t-es\">Búsqueda por ID, SKU, GTIN o título, además de filtros por categoría, marca y estado del producto en esta tabla; \"Más filtros\" abre un panel lateral con criterios adicionales (centro de distribución, condición, almacenamiento, stock, imágenes, etc.), similar a los filtros de la propia lista de productos.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Cost / Margin / Price</span><span class=\"t-pt\">Custo / Margem / Preço</span><span class=\"t-es\">Costo / Margen / Precio</span></td><td class=\"field-type\"><span class=\"t-en\">Editable fields</span><span class=\"t-pt\">Campos editáveis</span><span class=\"t-es\">Campos editables</span></td><td class=\"field-desc\"><span class=\"t-en\">Per-product values for this table; changing the cost or margin recalculates the price (and vice-versa).</span><span class=\"t-pt\">Valores por produto nesta tabela; alterar o custo ou a margem recalcula o preço (e vice-versa).</span><span class=\"t-es\">Valores por producto en esta tabla; cambiar el costo o el margen recalcula el precio (y viceversa).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Promo desc. / Promotion price</span><span class=\"t-pt\">Desc. promo / Preço promoção</span><span class=\"t-es\">Desc. promo / Precio promoción</span></td><td class=\"field-type\"><span class=\"t-en\">Editable fields</span><span class=\"t-pt\">Campos editáveis</span><span class=\"t-es\">Campos editables</span></td><td class=\"field-desc\"><span class=\"t-en\">Optional promotional discount (%) and the resulting promotional price shown to customers on this table.</span><span class=\"t-pt\">Desconto promocional (%) opcional e o preço promocional resultante, mostrado ao cliente nesta tabela.</span><span class=\"t-es\">Descuento promocional (%) opcional y el precio promocional resultante, mostrado al cliente en esta tabla.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Activate / Deactivate / Save all</span><span class=\"t-pt\">Ativar / Desativar / Salvar tudo</span><span class=\"t-es\">Activar / Desactivar / Guardar todo</span></td><td class=\"field-type\"><span class=\"t-en\">Buttons</span><span class=\"t-pt\">Botões</span><span class=\"t-es\">Botones</span></td><td class=\"field-desc\"><span class=\"t-en\">Activate/Deactivate apply to the selected products on this table; Save all persists every price edited on the page.</span><span class=\"t-pt\">Ativar/Desativar valem para os produtos selecionados nesta tabela; Salvar tudo grava todos os preços editados na página.</span><span class=\"t-es\">Activar/Desactivar aplican a los productos seleccionados en esta tabla; Guardar todo graba todos los precios editados en la página.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Price adjustment</span><span class=\"t-pt\">Reajuste</span><span class=\"t-es\">Reajuste</span></td><td class=\"field-type\"><span class=\"t-en\">Bulk action</span><span class=\"t-pt\">Ação em massa</span><span class=\"t-es\">Acción masiva</span></td><td class=\"field-desc\"><span class=\"t-en\">Bulk-changes cost, margin, price or promotional price/discount for every product matching the current search/filters at once (see below).</span><span class=\"t-pt\">Altera em massa custo, margem, preço ou desconto/preço promocional de todos os produtos do filtro/busca atual de uma vez (ver abaixo).</span><span class=\"t-es\">Cambia en masa el costo, margen, precio o descuento/precio promocional de todos los productos del filtro/búsqueda actual a la vez (ver abajo).</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"desc\" style=\"margin-top:18px;\"><span class=\"t-en\"><p>The \"Price adjustment\" button opens a bulk-edit dialog that applies a single change to every product matching the current search/filters on this table (all 10,000+ products by default, if none are set) &mdash; useful to adjust an entire table at once instead of product by product.</p></span><span class=\"t-pt\"><p>O botão \"Reajuste\" abre uma janela de edição em massa, que aplica uma única alteração a todos os produtos do filtro/busca atual nesta tabela (todos os mais de 10 mil produtos por padrão, se nenhum filtro estiver ativo) &mdash; útil para ajustar uma tabela inteira de uma vez, em vez de produto por produto.</p></span><span class=\"t-es\"><p>El botón \"Reajuste\" abre una ventana de edición masiva, que aplica un único cambio a todos los productos del filtro/búsqueda actual en esta tabla (los más de 10 mil productos por defecto, si no hay ningún filtro activo) &mdash; útil para ajustar toda una tabla de una vez, en lugar de producto por producto.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/091-precos-en-bulk-price-adjustment-dialog-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk price adjustment dialog (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/092-precos-pt-bulk-price-adjustment-dialog-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk price adjustment dialog (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/093-precos-es-bulk-price-adjustment-dialog-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk price adjustment dialog (es)\">\n</div>\n        <table class=\"fields\">\n          <thead><tr><th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th><th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th><th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th></tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Action</span><span class=\"t-pt\">Ação</span><span class=\"t-es\">Acción</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">What to change: e.g. increase/decrease the price or margin by a fixed amount, set the price or margin to a fixed value, or change the promotional discount.</span><span class=\"t-pt\">O que alterar: ex. acrescentar/descontar um valor fixo no preço ou na margem, definir o preço ou a margem para um valor fixo, ou alterar o % de desconto promocional.</span><span class=\"t-es\">Qué cambiar: ej. sumar/restar un valor fijo al precio o al margen, fijar el precio o el margen a un valor fijo, o cambiar el % de descuento promocional.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Value</span><span class=\"t-pt\">Valor</span><span class=\"t-es\">Valor</span></td><td class=\"field-type\"><span class=\"t-en\">Number</span><span class=\"t-pt\">Número</span><span class=\"t-es\">Número</span></td><td class=\"field-desc\"><span class=\"t-en\">Amount or percentage used by the selected action.</span><span class=\"t-pt\">Valor ou percentual usado pela ação selecionada.</span><span class=\"t-es\">Valor o porcentaje usado por la acción seleccionada.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Apply</span><span class=\"t-pt\">Aplicar</span><span class=\"t-es\">Aplicar</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Runs the adjustment; the dialog states in advance how many products will be affected, and warns that products beyond the first page are processed in a background queue.</span><span class=\"t-pt\">Executa o ajuste; a janela informa antecipadamente quantos produtos serão afetados, e avisa que os produtos além da primeira página são processados em uma fila em segundo plano.</span><span class=\"t-es\">Ejecuta el ajuste; la ventana informa por adelantado cuántos productos se verán afectados, y avisa que los productos más allá de la primera página se procesan en una cola en segundo plano.</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"note\"><span class=\"t-en\">&#128161; The 5 icons in the row 's \"Actions\" column: a power icon to activate/deactivate the product on this specific table; a clock icon for scheduling a promotion (shows \"No promotion\" and stays disabled while no promotional price is set); a star for the highlight/featured deadline; an eye for \"price on request\" (hides the price and asks the customer to contact the store); and a layers icon for wholesale pricing tiers.</span><span class=\"t-pt\">&#128161; Os 5 ícones na coluna \"Ações\" da linha: um ícone de energia para ativar/desativar o produto naquela tabela específica; um ícone de relógio para agendar uma promoção (mostra \"Sem promoção\" e fica desabilitado enquanto não há preço promocional definido); uma estrela para o prazo do destaque; um olho para \"sob consulta\" (oculta o preço e pede que o cliente entre em contato com a loja); e um ícone de camadas para a venda por atacado.</span><span class=\"t-es\">&#128161; Los 5 íconos en la columna \"Acciones\" de la fila: un ícono de encendido para activar/desactivar el producto en esa tabla específica; un ícono de reloj para programar una promoción (muestra \"Sin promoción\" y permanece deshabilitado mientras no haya un precio promocional definido); una estrella para el plazo del destacado; un ojo para \"sobre consulta\" (oculta el precio y pide que el cliente contacte a la tienda); y un ícono de capas para la venta al por mayor.</span></div>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=produtos\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Products</span><span class=\"t-pt\">Produtos</span><span class=\"t-es\">Productos</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=estoques\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Stocks</span><span class=\"t-pt\">Estoques</span><span class=\"t-es\">Inventarios</span></strong></a>\n</nav>\n", "estoques": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Stocks</span><span class=\"t-pt\">Estoques</span><span class=\"t-es\">Inventarios</span></p>\n<section class=\"doc-section\" id=\"estoques\">\n      <h2><span class=\"t-en\">5. Products &gt; Stocks</span><span class=\"t-pt\">5. Produtos &gt; Estoques</span><span class=\"t-es\">5. Productos &gt; Inventarios</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Stocks represent the store's distribution centers / warehouses (own or third-party) &mdash; each with its own delivery lead time, and each product can have a different quantity available on every stock. This is where physical availability is managed; the \"Products\" list only shows the combined total.</span><span class=\"t-pt\">Estoques representam os centros de distribuição / depósitos da loja (próprios ou de terceiros) &mdash; cada um com seu próprio prazo de entrega, e cada produto pode ter uma quantidade diferente disponível em cada estoque. É aqui que a disponibilidade física é gerenciada; a lista de \"Produtos\" só mostra o total combinado.</span><span class=\"t-es\">Los inventarios representan los centros de distribución / depósitos de la tienda (propios o de terceros) &mdash; cada uno con su propio plazo de entrega, y cada producto puede tener una cantidad diferente disponible en cada inventario. Aquí es donde se gestiona la disponibilidad física; la lista de \"Productos\" solo muestra el total combinado.</span>\n      </p>\n      <div class=\"subsection\" id=\"estoques-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Stocks</span><span class=\"t-pt\">Produtos &gt; Estoques</span><span class=\"t-es\">Productos &gt; Inventarios</span></span></h3>\n        <h3><span class=\"t-en\">Stock list</span><span class=\"t-pt\">Lista de estoques</span><span class=\"t-es\">Lista de inventarios</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Initial screen of the section. Shows every distribution center/warehouse registered in the store, one row per stock. Like price tables, this screen only manages the stocks themselves; per-product quantities are set on the next subsections.</p></span><span class=\"t-pt\"><p>Tela inicial da seção. Mostra todos os centros de distribuição/depósitos cadastrados na loja, uma linha por estoque. Assim como nas tabelas de preço, esta tela só gerencia os estoques em si; as quantidades por produto são definidas nas próximas subseções.</p></span><span class=\"t-es\"><p>Pantalla inicial de la sección. Muestra todos los centros de distribución/depósitos registrados en la tienda, una fila por inventario. Al igual que en las tablas de precios, esta pantalla solo gestiona los inventarios en sí; las cantidades por producto se definen en las próximas subsecciones.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/094-estoques-en-stock-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stock list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/095-estoques-pt-stock-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stock list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/096-estoques-es-stock-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stock list (es)\">\n          <figcaption><span class=\"t-en\">Products &gt; Stocks screen, listing every distribution center/warehouse</span><span class=\"t-pt\">Tela Produtos &gt; Estoques, listando todos os centros de distribuição/depósitos</span><span class=\"t-es\">Pantalla Productos &gt; Inventarios, con la lista de todos los centros de distribución/depósitos</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">ID / Name</span><span class=\"t-pt\">ID / Nome</span><span class=\"t-es\">ID / Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Stock identifier and name.</span><span class=\"t-pt\">Identificador e nome do estoque.</span><span class=\"t-es\">Identificador y nombre del inventario.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Min/Max deadline</span><span class=\"t-pt\">Prazo mínimo/máximo</span><span class=\"t-es\">Plazo mínimo/máximo</span></td><td class=\"field-type\"><span class=\"t-en\">Number + unit</span><span class=\"t-pt\">Número + unidade</span><span class=\"t-es\">Número + unidad</span></td><td class=\"field-desc\"><span class=\"t-en\">Estimated lead time for this stock to prepare an order, in minutes/hours/days; \"Immediate delivery\" when left empty.</span><span class=\"t-pt\">Prazo estimado para este estoque preparar um pedido, em minutos/horas/dias; \"Entrega imediata\" quando deixado em branco.</span><span class=\"t-es\">Plazo estimado para que este inventario prepare un pedido, en minutos/horas/días; \"Entrega inmediata\" cuando se deja en blanco.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></td><td class=\"field-type\"><span class=\"t-en\">Tag</span><span class=\"t-pt\">Tag</span><span class=\"t-es\">Etiqueta</span></td><td class=\"field-desc\"><span class=\"t-en\">\"Physical\" for a warehouse the store operates directly, \"Third party\" for an outsourced/partner stock (e.g. a fulfillment provider).</span><span class=\"t-pt\">\"Físico\" para um depósito operado diretamente pela loja, \"Terceiros\" para um estoque terceirizado/parceiro (ex.: um provedor de fulfillment).</span><span class=\"t-es\">\"Físico\" para un depósito operado directamente por la tienda, \"Terceros\" para un inventario tercerizado/socio (ej.: un proveedor de fulfillment).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Zip code</span><span class=\"t-pt\">CEP</span><span class=\"t-es\">Código postal</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Postal code of the stock's origin address, used to calculate shipping; set via \"Set origin address\" in the row's actions.</span><span class=\"t-pt\">CEP do endereço de origem do estoque, usado para calcular o frete; definido pelo \"Definir endereço de origem\" nas ações da linha.</span><span class=\"t-es\">Código postal de la dirección de origen del inventario, usado para calcular el envío; se define con \"Definir dirección de origen\" en las acciones de la fila.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Default</span><span class=\"t-pt\">Padrão</span><span class=\"t-es\">Predeterminado</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle button</span><span class=\"t-pt\">Botão de alternância</span><span class=\"t-es\">Botón de alternancia</span></td><td class=\"field-desc\"><span class=\"t-en\">Marks the stock used whenever no other applies; only one stock can be Default.</span><span class=\"t-pt\">Marca o estoque usado quando nenhum outro se aplica; apenas um estoque pode ser Padrão.</span><span class=\"t-es\">Marca el inventario usado cuando ninguno otro aplica; solo un inventario puede ser Predeterminado.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">+ Add stock</span><span class=\"t-pt\">+ Adicionar estoque</span><span class=\"t-es\">+ Agregar stock</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Opens the form to create a new stock (see \"Create / edit stock\").</span><span class=\"t-pt\">Abre o formulário para criar um novo estoque (ver \"Criar/editar estoque\").</span><span class=\"t-es\">Abre el formulario para crear un nuevo inventario (ver \"Crear/editar inventario\").</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">List products</span><span class=\"t-pt\">Listar produtos</span><span class=\"t-es\">Listar productos</span></b> &mdash; <span class=\"t-en\">opens this stock's product list, where the available quantity of each product is set (see next subsection).</span><span class=\"t-pt\">abre a lista de produtos deste estoque, onde a quantidade disponível de cada produto é definida (ver próxima subseção).</span><span class=\"t-es\">abre la lista de productos de este inventario, donde se define la cantidad disponible de cada producto (ver próxima subsección).</span></li>\n          <li><b><span class=\"t-en\">Set origin address</span><span class=\"t-pt\">Definir endereço de origem</span><span class=\"t-es\">Definir dirección de origen</span></b> &mdash; <span class=\"t-en\">registers the postal address this stock ships from, used for shipping calculations.</span><span class=\"t-pt\">cadastra o endereço postal de onde este estoque despacha, usado para o cálculo do frete.</span><span class=\"t-es\">registra la dirección postal desde donde despacha este inventario, usada para el cálculo del envío.</span></li>\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the same form used to create a stock, with its current settings.</span><span class=\"t-pt\">abre o mesmo formulário usado para criar um estoque, com as configurações atuais.</span><span class=\"t-es\">abre el mismo formulario usado para crear un inventario, con la configuración actual.</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">permanently removes the stock.</span><span class=\"t-pt\">remove o estoque permanentemente.</span><span class=\"t-es\">elimina el inventario de forma permanente.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"estoques-criar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Stocks &gt; Add/Edit</span><span class=\"t-pt\">Produtos &gt; Estoques &gt; Adicionar/Editar</span><span class=\"t-es\">Productos &gt; Inventarios &gt; Agregar/Editar</span></span></h3>\n        <h3><span class=\"t-en\">Create / edit stock</span><span class=\"t-pt\">Criar/editar estoque</span><span class=\"t-es\">Crear/editar inventario</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via \"Add stock\" or via \"Edit\" in a row's actions menu. Both use the same form.</p></span><span class=\"t-pt\"><p>Aberta pelo botão \"Adicionar estoque\" ou pelo \"Editar\" no menu de ações da linha. Ambos usam o mesmo formulário.</p></span><span class=\"t-es\"><p>Se abre con el botón \"Agregar stock\" o con \"Editar\" en el menú de acciones de la fila. Ambos usan el mismo formulario.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/097-estoques-en-add-edit-stock-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add/edit stock modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/098-estoques-pt-add-edit-stock-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add/edit stock modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/099-estoques-es-add-edit-stock-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add/edit stock modal (es)\">\n          <figcaption><span class=\"t-en\">\"Add stock\" form, with name, type, min/max deadline, unit and the Active toggle</span><span class=\"t-pt\">Formulário \"Adicionar estoque\", com nome, tipo, prazo mínimo/máximo, unidade e o toggle Ativo</span><span class=\"t-es\">Formulario \"Agregar stock\", con nombre, tipo, plazo mínimo/máximo, unidad y el interruptor Activo</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Internal name used to identify the stock in the list and in the tabs of the product quantity screen.</span><span class=\"t-pt\">Nome interno usado para identificar o estoque na lista e nas abas da tela de quantidades por produto.</span><span class=\"t-es\">Nombre interno usado para identificar el inventario en la lista y en las pestañas de la pantalla de cantidades por producto.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Physical (store-operated warehouse) or Third party (outsourced stock).</span><span class=\"t-pt\">Físico (depósito operado pela loja) ou Terceiros (estoque terceirizado).</span><span class=\"t-es\">Físico (depósito operado por la tienda) o Terceros (inventario tercerizado).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Min/Max deadline + Unit</span><span class=\"t-pt\">Prazo mínimo/máximo + Unidade</span><span class=\"t-es\">Plazo mínimo/máximo + Unidad</span></td><td class=\"field-type\"><span class=\"t-en\">Number + Select</span><span class=\"t-pt\">Número + Seleção</span><span class=\"t-es\">Número + Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Estimated lead time range to prepare an order from this stock, in minutes, hours or days.</span><span class=\"t-pt\">Faixa de prazo estimada para preparar um pedido a partir deste estoque, em minutos, horas ou dias.</span><span class=\"t-es\">Rango de plazo estimado para preparar un pedido desde este inventario, en minutos, horas o días.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Active</span><span class=\"t-pt\">Ativo</span><span class=\"t-es\">Activo</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle</span><span class=\"t-pt\">Alternância</span><span class=\"t-es\">Alternancia</span></td><td class=\"field-desc\"><span class=\"t-en\">Enables or disables the stock without deleting it.</span><span class=\"t-pt\">Ativa ou desativa o estoque sem excluí-lo.</span><span class=\"t-es\">Activa o desactiva el inventario sin eliminarlo.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"estoques-produtos\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Stocks &gt; List products</span><span class=\"t-pt\">Produtos &gt; Estoques &gt; Listar produtos</span><span class=\"t-es\">Productos &gt; Inventarios &gt; Listar productos</span></span></h3>\n        <h3><span class=\"t-en\">Stock quantities &amp; bulk adjust</span><span class=\"t-pt\">Quantidades do estoque e reajuste em massa</span><span class=\"t-es\">Cantidades del inventario y reajuste masivo</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via \"List products\" in a stock's actions menu. Shows every product in the catalog with its total, available and reserved quantity on that specific stock. As with price tables, the tabs at the top simply switch which stock is being edited &mdash; they are the same stocks listed in the previous subsection.</p></span><span class=\"t-pt\"><p>Aberta pelo \"Listar produtos\" no menu de ações de um estoque. Mostra todos os produtos do catálogo com a quantidade total, disponível e reservada naquele estoque específico. Assim como nas tabelas de preço, as abas no topo apenas trocam qual estoque está sendo editado &mdash; são os mesmos estoques listados na subseção anterior.</p></span><span class=\"t-es\"><p>Se abre con \"Listar productos\" en el menú de acciones de un inventario. Muestra todos los productos del catálogo con la cantidad total, disponible y reservada en ese inventario específico. Al igual que con las tablas de precios, las pestañas en la parte superior solo cambian qué inventario se está editando &mdash; son los mismos inventarios listados en la subsección anterior.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/100-estoques-en-stock-product-list-with-editable-quantity-column.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stock product list with editable quantity column (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/101-estoques-pt-stock-product-list-with-editable-quantity-column.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stock product list with editable quantity column (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/102-estoques-es-stock-product-list-with-editable-quantity-column.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stock product list with editable quantity column (es)\">\n</div>\n        <table class=\"fields\">\n          <thead><tr><th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th><th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th><th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th></tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Stock tabs</span><span class=\"t-pt\">Abas de estoques</span><span class=\"t-es\">Pestañas de inventarios</span></td><td class=\"field-type\"><span class=\"t-en\">Tabs</span><span class=\"t-pt\">Abas</span><span class=\"t-es\">Pestañas</span></td><td class=\"field-desc\"><span class=\"t-en\">One tab per stock registered in the store; switching tabs loads that stock's quantities for the same product list.</span><span class=\"t-pt\">Uma aba por estoque cadastrado na loja; trocar de aba carrega as quantidades daquele estoque para a mesma lista de produtos.</span><span class=\"t-es\">Una pestaña por inventario registrado en la tienda; cambiar de pestaña carga las cantidades de ese inventario para la misma lista de productos.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search / filters</span><span class=\"t-pt\">Busca / filtros</span><span class=\"t-es\">Búsqueda / filtros</span></td><td class=\"field-type\"><span class=\"t-en\">Text / Select / Number</span><span class=\"t-pt\">Texto / Seleção / Número</span><span class=\"t-es\">Texto / Selección / Número</span></td><td class=\"field-desc\"><span class=\"t-en\">Search by ID, SKU, GTIN or title, filters by category and brand, plus a Minimum/Maximum quantity range; \"More filters\" opens the same side panel used elsewhere in Products.</span><span class=\"t-pt\">Busca por ID, SKU, GTIN ou título, filtros por categoria e marca, além de uma faixa de quantidade Mínimo/Máximo; \"Mais filtros\" abre o mesmo painel lateral usado em outras telas de Produtos.</span><span class=\"t-es\">Búsqueda por ID, SKU, GTIN o título, filtros por categoría y marca, además de un rango de cantidad Mínimo/Máximo; \"Más filtros\" abre el mismo panel lateral usado en otras pantallas de Productos.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Stock total / Available / Reserved</span><span class=\"t-pt\">Estoque total / Disponível / Reservado</span><span class=\"t-es\">Total de stock / Disponible / Reservado</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">Total registered quantity, quantity free to sell, and quantity already committed to unfinished orders on this stock; &#8734; marks unlimited stock.</span><span class=\"t-pt\">Quantidade total cadastrada, quantidade livre para venda e quantidade já comprometida com pedidos em aberto neste estoque; &#8734; indica estoque ilimitado.</span><span class=\"t-es\">Cantidad total registrada, cantidad libre para vender y cantidad ya comprometida con pedidos abiertos en este inventario; &#8734; indica inventario ilimitado.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Quantity field</span><span class=\"t-pt\">Campo de quantidade</span><span class=\"t-es\">Campo de cantidad</span></td><td class=\"field-type\"><span class=\"t-en\">Editable field</span><span class=\"t-pt\">Campo editável</span><span class=\"t-es\">Campo editable</span></td><td class=\"field-desc\"><span class=\"t-en\">Sets the available quantity for that product directly; the \"+\" icon adds to the current quantity instead of replacing it, and the refresh icon resets the total stock.</span><span class=\"t-pt\">Define diretamente a quantidade disponível daquele produto; o ícone \"+\" soma à quantidade atual em vez de substituí-la, e o ícone de atualizar redefine o estoque total.</span><span class=\"t-es\">Define directamente la cantidad disponible de ese producto; el ícono \"+\" suma a la cantidad actual en lugar de reemplazarla, y el ícono de actualizar restablece el stock total.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Stock bulk adjust</span><span class=\"t-pt\">Reajuste de estoque</span><span class=\"t-es\">Ajuste masivo de stock</span></td><td class=\"field-type\"><span class=\"t-en\">Bulk action</span><span class=\"t-pt\">Ação em massa</span><span class=\"t-es\">Acción masiva</span></td><td class=\"field-desc\"><span class=\"t-en\">Bulk-changes the quantity for every product matching the current search/filters at once (see below).</span><span class=\"t-pt\">Altera em massa a quantidade de todos os produtos do filtro/busca atual de uma vez (ver abaixo).</span><span class=\"t-es\">Cambia en masa la cantidad de todos los productos del filtro/búsqueda actual a la vez (ver abajo).</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"desc\" style=\"margin-top:18px;\"><span class=\"t-en\"><p>The \"Stock bulk adjust\" button opens a dialog that applies a single quantity change to every product matching the current search/filters on this stock (all 10,000+ products by default, if none are set).</p></span><span class=\"t-pt\"><p>O botão \"Reajuste de estoque\" abre uma janela que aplica uma única alteração de quantidade a todos os produtos do filtro/busca atual neste estoque (todos os mais de 10 mil produtos por padrão, se nenhum filtro estiver ativo).</p></span><span class=\"t-es\"><p>El botón \"Ajuste masivo de stock\" abre una ventana que aplica un único cambio de cantidad a todos los productos del filtro/búsqueda actual en este inventario (los más de 10 mil productos por defecto, si no hay ningún filtro activo).</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/103-estoques-en-bulk-stock-adjustment-dialog-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk stock adjustment dialog (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/104-estoques-pt-bulk-stock-adjustment-dialog-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk stock adjustment dialog (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/105-estoques-es-bulk-stock-adjustment-dialog-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"bulk stock adjustment dialog (es)\">\n</div>\n        <table class=\"fields\">\n          <thead><tr><th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th><th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th><th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th></tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Action</span><span class=\"t-pt\">Ação</span><span class=\"t-es\">Acción</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">\"Add quantity\" increases the available quantity by the given value; \"Reset total stock\" sets it to a fixed value.</span><span class=\"t-pt\">\"Adicionar quantidade\" aumenta a quantidade disponível pelo valor informado; \"Redefinir estoque total\" fixa em um valor.</span><span class=\"t-es\">\"Agregar cantidad\" aumenta la cantidad disponible según el valor indicado; \"Restablecer stock total\" la fija en un valor.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Available</span><span class=\"t-pt\">Disponível</span><span class=\"t-es\">Disponible</span></td><td class=\"field-type\"><span class=\"t-en\">Number</span><span class=\"t-pt\">Número</span><span class=\"t-es\">Número</span></td><td class=\"field-desc\"><span class=\"t-en\">Quantity used by the selected action.</span><span class=\"t-pt\">Quantidade usada pela ação selecionada.</span><span class=\"t-es\">Cantidad usada por la acción seleccionada.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Save</span><span class=\"t-pt\">Salvar</span><span class=\"t-es\">Guardar</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Runs the adjustment; the dialog states in advance how many products will be affected.</span><span class=\"t-pt\">Executa o ajuste; a janela informa antecipadamente quantos produtos serão afetados.</span><span class=\"t-es\">Ejecuta el ajuste; la ventana informa por adelantado cuántos productos se verán afectados.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=precos\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Price tables</span><span class=\"t-pt\">Tabelas de preço</span><span class=\"t-es\">Tablas de precios</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=categorias\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Categories</span><span class=\"t-pt\">Categorias</span><span class=\"t-es\">Categorías</span></strong></a>\n</nav>\n", "categorias": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Categories</span><span class=\"t-pt\">Categorias</span><span class=\"t-es\">Categorías</span></p>\n<section class=\"doc-section\" id=\"categorias\">\n      <h2><span class=\"t-en\">6. Products &gt; Categories</span><span class=\"t-pt\">6. Produtos &gt; Categorias</span><span class=\"t-es\">6. Productos &gt; Categorías</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Categories organize the product catalog into a tree (subcategories are nested with the same tools used for import). Beyond organizing navigation, each category also controls which standard product fields and custom attributes are available for the products assigned to it.</span><span class=\"t-pt\">Categorias organizam o catálogo de produtos em uma árvore (subcategorias são aninhadas com as mesmas ferramentas usadas na importação). Além de organizar a navegação, cada categoria também controla quais campos padrão e atributos personalizados ficam disponíveis para os produtos atribuídos a ela.</span><span class=\"t-es\">Las categorías organizan el catálogo de productos en un árbol (las subcategorías se anidan con las mismas herramientas usadas en la importación). Además de organizar la navegación, cada categoría también controla qué campos estándar y atributos personalizados quedan disponibles para los productos asignados a ella.</span>\n      </p>\n      <div class=\"subsection\" id=\"categorias-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Categories</span><span class=\"t-pt\">Produtos &gt; Categorias</span><span class=\"t-es\">Productos &gt; Categorías</span></span></h3>\n        <h3><span class=\"t-en\">Category list</span><span class=\"t-pt\">Lista de categorias</span><span class=\"t-es\">Lista de categorías</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Initial screen of the section. Shows every category registered in the store. There is no manual \"add category\" button &mdash; new categories are always created through the \"Import categories\" dialog (see next subsection).</p></span><span class=\"t-pt\"><p>Tela inicial da seção. Mostra todas as categorias cadastradas na loja. Não existe um botão manual de \"adicionar categoria\" &mdash; novas categorias são sempre criadas pela janela \"Importar categorias\" (ver próxima subseção).</p></span><span class=\"t-es\"><p>Pantalla inicial de la sección. Muestra todas las categorías registradas en la tienda. No existe un botón manual de \"agregar categoría\" &mdash; las categorías nuevas siempre se crean con la ventana \"Importar categorías\" (ver próxima subsección).</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/106-categorias-en-category-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"category list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/107-categorias-pt-category-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"category list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/108-categorias-es-category-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"category list (es)\">\n          <figcaption><span class=\"t-en\">Products &gt; Categories screen, listing every registered category</span><span class=\"t-pt\">Tela Produtos &gt; Categorias, listando todas as categorias cadastradas</span><span class=\"t-es\">Pantalla Productos &gt; Categorías, con la lista de todas las categorías registradas</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search</span><span class=\"t-pt\">Buscar</span><span class=\"t-es\">Buscar</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Searches by category name; typing \"##\" between names filters by nesting level, the same syntax used to build subcategories on import.</span><span class=\"t-pt\">Busca pelo nome da categoria; digitar \"##\" entre nomes filtra por nível de aninhamento, a mesma sintaxe usada para montar subcategorias na importação.</span><span class=\"t-es\">Busca por el nombre de la categoría; escribir \"##\" entre nombres filtra por nivel de anidación, la misma sintaxis usada para armar subcategorías en la importación.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Is catalog</span><span class=\"t-pt\">É catálogo</span><span class=\"t-es\">Es catálogo</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters categories marked as \"Is catalog\" in their attributes (see \"Category attributes\").</span><span class=\"t-pt\">Filtra categorias marcadas como \"É catálogo\" em seus atributos (ver \"Atributos da categoria\").</span><span class=\"t-es\">Filtra categorías marcadas como \"Es catálogo\" en sus atributos (ver \"Atributos de la categoría\").</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Show in menu</span><span class=\"t-pt\">Exibir em menus</span><span class=\"t-es\">Mostrar en el menú</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters by whether the category is shown in the storefront's navigation menu.</span><span class=\"t-pt\">Filtra pela categoria ser exibida ou não no menu de navegação da loja virtual.</span><span class=\"t-es\">Filtra según si la categoría se muestra o no en el menú de navegación de la tienda virtual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Category / Title / Description</span><span class=\"t-pt\">Categoria / Título / Descrição</span><span class=\"t-es\">Categoría / Título / Descripción</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">Internal name, plus the storefront-facing title and description set in the edit form (both optional).</span><span class=\"t-pt\">Nome interno, além do título e descrição voltados à loja virtual, definidos no formulário de edição (ambos opcionais).</span><span class=\"t-es\">Nombre interno, además del título y la descripción orientados a la tienda virtual, definidos en el formulario de edición (ambos opcionales).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Show in menu</span><span class=\"t-pt\">Exibir em menus</span><span class=\"t-es\">Mostrar en el menú</span></td><td class=\"field-type\"><span class=\"t-en\">Yes/No column</span><span class=\"t-pt\">Coluna Sim/Não</span><span class=\"t-es\">Columna Sí/No</span></td><td class=\"field-desc\"><span class=\"t-en\">Whether this category currently appears in the storefront's navigation menu.</span><span class=\"t-pt\">Se esta categoria aparece atualmente no menu de navegação da loja virtual.</span><span class=\"t-es\">Si esta categoría aparece actualmente en el menú de navegación de la tienda virtual.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">List products</span><span class=\"t-pt\">Listar produtos</span><span class=\"t-es\">Listar productos</span></b> &mdash; <span class=\"t-en\">opens the product list filtered to this category.</span><span class=\"t-pt\">abre a lista de produtos filtrada por esta categoria.</span><span class=\"t-es\">abre la lista de productos filtrada por esta categoría.</span></li>\n          <li><b><span class=\"t-en\">Category attributes</span><span class=\"t-pt\">Atributos da categoria</span><span class=\"t-es\">Atributos de la categoría</span></b> &mdash; <span class=\"t-en\">opens the panel that controls which product fields apply to this category (see \"Category attributes\").</span><span class=\"t-pt\">abre o painel que controla quais campos de produto se aplicam a esta categoria (ver \"Atributos da categoria\").</span><span class=\"t-es\">abre el panel que controla qué campos de producto se aplican a esta categoría (ver \"Atributos de la categoría\").</span></li>\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the name/title/description/SEO form (see \"Edit category\").</span><span class=\"t-pt\">abre o formulário de nome/título/descrição/SEO (ver \"Editar categoria\").</span><span class=\"t-es\">abre el formulario de nombre/título/descripción/SEO (ver \"Editar categoría\").</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">permanently removes the category.</span><span class=\"t-pt\">remove a categoria permanentemente.</span><span class=\"t-es\">elimina la categoría de forma permanente.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"categorias-importar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Categories &gt; Import</span><span class=\"t-pt\">Produtos &gt; Categorias &gt; Importar</span><span class=\"t-es\">Productos &gt; Categorías &gt; Importar</span></span></h3>\n        <h3><span class=\"t-en\">Import categories</span><span class=\"t-pt\">Importar categorias</span><span class=\"t-es\">Importar categorías</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via the \"Import\" button on the category list. This is the only way to create categories &mdash; one name per line, with \"##\" between names to nest a subcategory under a parent (which is created automatically if it does not exist yet).</p></span><span class=\"t-pt\"><p>Aberta pelo botão \"Importar\" na lista de categorias. É a única forma de criar categorias &mdash; um nome por linha, com \"##\" entre nomes para aninhar uma subcategoria sob uma categoria pai (que é criada automaticamente caso ainda não exista).</p></span><span class=\"t-es\"><p>Se abre con el botón \"Importar\" en la lista de categorías. Es la única forma de crear categorías &mdash; un nombre por línea, con \"##\" entre nombres para anidar una subcategoría bajo una categoría padre (que se crea automáticamente si todavía no existe).</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/109-categorias-en-import-categories-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"import categories modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/110-categorias-pt-import-categories-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"import categories modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/111-categorias-es-import-categories-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"import categories modal (es)\">\n          <figcaption><span class=\"t-en\">\"Import categories\" dialog, with the example text explaining the ## nesting syntax</span><span class=\"t-pt\">Janela \"Importar categorias\", com o texto de exemplo explicando a sintaxe de aninhamento com ##</span><span class=\"t-es\">Ventana \"Importar categorías\", con el texto de ejemplo que explica la sintaxis de anidación con ##</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Text area</span><span class=\"t-pt\">Área de texto</span><span class=\"t-es\">Área de texto</span></td><td class=\"field-type\"><span class=\"t-en\">Multi-line text</span><span class=\"t-pt\">Texto de múltiplas linhas</span><span class=\"t-es\">Texto de varias líneas</span></td><td class=\"field-desc\"><span class=\"t-en\">One category per line; a plain name creates a top-level category, e.g. \"Computers\". Use \"##\" to nest, e.g. \"Appliances##Kitchen##Refrigerator\" creates (or reuses) \"Appliances\", then \"Kitchen\" under it, then \"Refrigerator\" under that.</span><span class=\"t-pt\">Uma categoria por linha; um nome simples cria uma categoria de nível principal, ex. \"Eletro\". Use \"##\" para aninhar, ex. \"Eletro##Cozinha##Geladeira\" cria (ou reaproveita) \"Eletro\", depois \"Cozinha\" dentro dela, depois \"Geladeira\" dentro dessa.</span><span class=\"t-es\">Una categoría por línea; un nombre simple crea una categoría de nivel principal, ej. \"Electro\". Use \"##\" para anidar, ej. \"Electro##Cocina##Nevera\" crea (o reutiliza) \"Electro\", luego \"Cocina\" dentro de ella, luego \"Nevera\" dentro de esa.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Import</span><span class=\"t-pt\">Importar</span><span class=\"t-es\">Importar</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Creates every category/subcategory listed; existing categories with the same name/path are reused, not duplicated.</span><span class=\"t-pt\">Cria todas as categorias/subcategorias listadas; categorias já existentes com o mesmo nome/caminho são reaproveitadas, não duplicadas.</span><span class=\"t-es\">Crea todas las categorías/subcategorías listadas; las categorías ya existentes con el mismo nombre/ruta se reutilizan, no se duplican.</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"note\"><span class=\"t-en\">&#128161; Newly imported categories start with no title, description or attributes set &mdash; edit each one afterward (see next subsections) to configure those.</span><span class=\"t-pt\">&#128161; Categorias recém-importadas começam sem título, descrição ou atributos definidos &mdash; edite cada uma depois (ver próximas subseções) para configurar isso.</span><span class=\"t-es\">&#128161; Las categorías recién importadas empiezan sin título, descripción ni atributos definidos &mdash; edite cada una después (ver próximas subsecciones) para configurar eso.</span></div>\n      </div>\n      <div class=\"subsection\" id=\"categorias-editar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Categories &gt; Edit</span><span class=\"t-pt\">Produtos &gt; Categorias &gt; Editar</span><span class=\"t-es\">Productos &gt; Categorías &gt; Editar</span></span></h3>\n        <h3><span class=\"t-en\">Edit category</span><span class=\"t-pt\">Editar categoria</span><span class=\"t-es\">Editar categoría</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via \"Edit\" in a category row's actions menu.</p></span><span class=\"t-pt\"><p>Aberta pelo \"Editar\" no menu de ações de uma linha de categoria.</p></span><span class=\"t-es\"><p>Se abre con \"Editar\" en el menú de acciones de una fila de categoría.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/112-categorias-en-edit-category-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"edit category modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/113-categorias-pt-edit-category-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"edit category modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/114-categorias-es-edit-category-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"edit category modal (es)\">\n          <figcaption><span class=\"t-en\">\"Edit category\" form, with name, title, description, SEO tags and the Show in menu toggle</span><span class=\"t-pt\">Formulário \"Editar categoria\", com nome, título, descrição, tags SEO e o toggle Exibir em menus</span><span class=\"t-es\">Formulario \"Editar categoría\", con nombre, título, descripción, etiquetas SEO y el interruptor Mostrar en el menú</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Internal name, also used to rebuild the ## path when re-importing.</span><span class=\"t-pt\">Nome interno, também usado para reconstruir o caminho ## ao reimportar.</span><span class=\"t-es\">Nombre interno, también usado para reconstruir la ruta ## al reimportar.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Title</span><span class=\"t-pt\">Título</span><span class=\"t-es\">Título</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Storefront-facing title shown to customers; falls back to Name when left empty.</span><span class=\"t-pt\">Título voltado à loja virtual, exibido aos clientes; usa o Nome quando deixado em branco.</span><span class=\"t-es\">Título orientado a la tienda virtual, mostrado a los clientes; usa el Nombre cuando se deja en blanco.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Description</span><span class=\"t-pt\">Descrição</span><span class=\"t-es\">Descripción</span></td><td class=\"field-type\"><span class=\"t-en\">Text area</span><span class=\"t-pt\">Área de texto</span><span class=\"t-es\">Área de texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Optional storefront-facing description for the category page.</span><span class=\"t-pt\">Descrição opcional voltada à loja virtual, para a página da categoria.</span><span class=\"t-es\">Descripción opcional orientada a la tienda virtual, para la página de la categoría.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">SEO tags</span><span class=\"t-pt\">Tags SEO</span><span class=\"t-es\">Etiquetas SEO</span></td><td class=\"field-type\"><span class=\"t-en\">Tag input</span><span class=\"t-pt\">Campo de tags</span><span class=\"t-es\">Campo de etiquetas</span></td><td class=\"field-desc\"><span class=\"t-en\">Free-form keywords added by typing and pressing Enter, used for search engine optimization.</span><span class=\"t-pt\">Palavras-chave livres, adicionadas digitando e pressionando Enter, usadas para otimização em mecanismos de busca.</span><span class=\"t-es\">Palabras clave libres, agregadas escribiendo y presionando Enter, usadas para optimización en motores de búsqueda.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Show in menu</span><span class=\"t-pt\">Exibir em menus</span><span class=\"t-es\">Mostrar en el menú</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle</span><span class=\"t-pt\">Alternância</span><span class=\"t-es\">Alternancia</span></td><td class=\"field-desc\"><span class=\"t-en\">Shows or hides the category from the storefront's navigation menu without deleting it.</span><span class=\"t-pt\">Exibe ou oculta a categoria do menu de navegação da loja virtual sem excluí-la.</span><span class=\"t-es\">Muestra u oculta la categoría del menú de navegación de la tienda virtual sin eliminarla.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"categorias-atributos\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Products &gt; Categories &gt; Category attributes</span><span class=\"t-pt\">Produtos &gt; Categorias &gt; Atributos da categoria</span><span class=\"t-es\">Productos &gt; Categorías &gt; Atributos de la categoría</span></span></h3>\n        <h3><span class=\"t-en\">Category attributes</span><span class=\"t-pt\">Atributos da categoria</span><span class=\"t-es\">Atributos de la categoría</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via \"Category attributes\" in a category row's actions menu. Controls which standard product fields are enabled for products assigned to this category, plus any custom attributes specific to it.</p></span><span class=\"t-pt\"><p>Aberta pelo \"Atributos da categoria\" no menu de ações de uma linha de categoria. Controla quais campos padrão de produto ficam habilitados para os produtos atribuídos a essa categoria, além de eventuais atributos personalizados específicos dela.</p></span><span class=\"t-es\"><p>Se abre con \"Atributos de la categoría\" en el menú de acciones de una fila de categoría. Controla qué campos estándar de producto quedan habilitados para los productos asignados a esa categoría, además de posibles atributos personalizados específicos de ella.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/115-categorias-en-category-attributes-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"category attributes modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/116-categorias-pt-category-attributes-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"category attributes modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/117-categorias-es-category-attributes-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"category attributes modal (es)\">\n          <figcaption><span class=\"t-en\">\"Category attributes\" panel, with the Is catalog checkbox and the expanded Platform default fields list</span><span class=\"t-pt\">Painel \"Atributos da categoria\", com o checkbox É catálogo e a lista expandida de Campos padrões da plataforma</span><span class=\"t-es\">Panel \"Atributos de la categoría\", con la casilla Es catálogo y la lista expandida de Campos predeterminados de la plataforma</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Is catalog</span><span class=\"t-pt\">É catálogo</span><span class=\"t-es\">Es catálogo</span></td><td class=\"field-type\"><span class=\"t-en\">Checkbox</span><span class=\"t-pt\">Checkbox</span><span class=\"t-es\">Casilla</span></td><td class=\"field-desc\"><span class=\"t-en\">Marks this category as a sellable catalog category (as opposed to a purely organizational/menu category).</span><span class=\"t-pt\">Marca esta categoria como uma categoria de catálogo vendável (em vez de puramente organizacional/de menu).</span><span class=\"t-es\">Marca esta categoría como una categoría de catálogo vendible (en lugar de puramente organizacional/de menú).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Platform default fields</span><span class=\"t-pt\">Campos padrões da plataforma</span><span class=\"t-es\">Campos predeterminados de la plataforma</span></td><td class=\"field-type\"><span class=\"t-en\">Checkbox group</span><span class=\"t-pt\">Grupo de checkboxes</span><span class=\"t-es\">Grupo de casillas</span></td><td class=\"field-desc\"><span class=\"t-en\">SKU, Barcode, Promotion, Stock, Brand, Model, Kit, Variation, Physical product, Storage, Delivery and Product preferences &mdash; each toggles whether that standard field is available on products in this category; \"Mark as main catalog category\" sets this as a product's primary category by default.</span><span class=\"t-pt\">SKU, Código de barras, Promoção, Estoque, Marca, Modelo, Kit, Variação, Produto físico, Armazenamento, Entrega e Preferências do produto &mdash; cada um alterna se aquele campo padrão fica disponível nos produtos desta categoria; \"Marcar como categoria principal\" define esta como a categoria principal do produto por padrão.</span><span class=\"t-es\">SKU, Código de barras, Promoción, Stock, Marca, Modelo, Kit, Variación, Producto físico, Almacenamiento, Entrega y Preferencias del producto &mdash; cada uno alterna si ese campo estándar está disponible en los productos de esta categoría; \"Marcar como categoría principal de catálogo\" define esta como la categoría principal del producto por defecto.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Custom attributes</span><span class=\"t-pt\">Atributos personalizados</span><span class=\"t-es\">Atributos personalizados</span></td><td class=\"field-type\"><span class=\"t-en\">List + button</span><span class=\"t-pt\">Lista + botão</span><span class=\"t-es\">Lista + botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Attributes specific to this category (e.g. \"Screen size\" for a Monitors category); \"Add new attribute\" opens the form to create one.</span><span class=\"t-pt\">Atributos específicos desta categoria (ex.: \"Tamanho da tela\" para uma categoria de Monitores); \"Incluir novo atributo\" abre o formulário para criar um.</span><span class=\"t-es\">Atributos específicos de esta categoría (ej.: \"Tamaño de pantalla\" para una categoría de Monitores); \"Agregar nuevo atributo\" abre el formulario para crear uno.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=estoques\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Stocks</span><span class=\"t-pt\">Estoques</span><span class=\"t-es\">Inventarios</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=clientes\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Customers and users</span><span class=\"t-pt\">Clientes e usuários</span><span class=\"t-es\">Clientes y usuarios</span></strong></a>\n</nav>\n", "clientes": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Customers and users</span><span class=\"t-pt\">Clientes e usuários</span><span class=\"t-es\">Clientes y usuarios</span></p>\n<section class=\"doc-section\" id=\"clientes\">\n      <h2><span class=\"t-en\">7. Customers and users</span><span class=\"t-pt\">7. Clientes e usuários</span><span class=\"t-es\">7. Clientes y usuarios</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">This section lists every registered customer and admin/staff user in one place &mdash; both share the same record type and list, distinguished by their \"User group\" (e.g. \"Customers\" vs. an internal staff group). Each record centralizes contact info, addresses, price table/channel assignment, security and a per-user wallet.</span><span class=\"t-pt\">Esta seção lista, em um só lugar, todos os clientes e usuários administrativos/da equipe cadastrados &mdash; ambos compartilham o mesmo tipo de registro e a mesma lista, distinguidos pelo \"Grupo de usuários\" (ex.: \"Clientes\" x um grupo interno da equipe). Cada registro centraliza dados de contato, endereços, tabela de preço/canal atribuídos, segurança e uma carteira por usuário.</span><span class=\"t-es\">Esta sección lista, en un solo lugar, todos los clientes y usuarios administrativos/del equipo registrados &mdash; ambos comparten el mismo tipo de registro y la misma lista, distinguidos por el \"Grupo de usuarios\" (ej.: \"Clientes\" frente a un grupo interno del equipo). Cada registro centraliza datos de contacto, direcciones, tabla de precios/canal asignados, seguridad y una cartera por usuario.</span>\n      </p>\n      <div class=\"subsection\" id=\"clientes-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customers and users</span><span class=\"t-pt\">Clientes e usuários</span><span class=\"t-es\">Clientes y usuarios</span></span></h3>\n        <h3><span class=\"t-en\">Customer list</span><span class=\"t-pt\">Lista de clientes</span><span class=\"t-es\">Lista de clientes</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Initial screen of the section. Shows every customer/user with their order history summary.</p></span><span class=\"t-pt\"><p>Tela inicial da seção. Mostra todos os clientes/usuários com um resumo do histórico de pedidos.</p></span><span class=\"t-es\"><p>Pantalla inicial de la sección. Muestra todos los clientes/usuarios con un resumen del historial de pedidos.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/118-clientes-en-customer-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/119-clientes-pt-customer-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/120-clientes-es-customer-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer list (es)\">\n          <figcaption><span class=\"t-en\">Customers and users screen, listing every registered customer/user</span><span class=\"t-pt\">Tela Clientes e usuários, listando todos os clientes/usuários cadastrados</span><span class=\"t-es\">Pantalla Clientes y usuarios, con la lista de todos los clientes/usuarios registrados</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search</span><span class=\"t-pt\">Buscar</span><span class=\"t-es\">Buscar</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Searches by ID, name, document, phone or email.</span><span class=\"t-pt\">Busca por ID, nome, documento, telefone ou e-mail.</span><span class=\"t-es\">Busca por ID, nombre, documento, teléfono o correo electrónico.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Status / Type</span><span class=\"t-pt\">Status / Tipo</span><span class=\"t-es\">Estado / Tipo</span></td><td class=\"field-type\"><span class=\"t-en\">Selects</span><span class=\"t-pt\">Seleções</span><span class=\"t-es\">Selecciones</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters by active/inactive and by person type: Individual, Company or Foreign person.</span><span class=\"t-pt\">Filtra por ativo/inativo e por tipo de pessoa: Pessoa física, Pessoa jurídica ou Pessoa estrangeira.</span><span class=\"t-es\">Filtra por activo/inactivo y por tipo de persona: Persona física, Persona jurídica o Persona extranjera.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">More filters</span><span class=\"t-pt\">Mais filtros</span><span class=\"t-es\">Más filtros</span></td><td class=\"field-type\"><span class=\"t-en\">Side panel</span><span class=\"t-pt\">Painel lateral</span><span class=\"t-es\">Panel lateral</span></td><td class=\"field-desc\"><span class=\"t-en\">Neighborhood, city, state, registration/last order date, gender, user group, minimum order count, price table, salesperson and minimum amount spent, plus a sort order.</span><span class=\"t-pt\">Bairro, cidade, UF, data de cadastro/último pedido, gênero, grupo de usuários, quantidade mínima de pedidos, tabela de preço, vendedor e valor gasto mínimo, além da ordenação.</span><span class=\"t-es\">Barrio, ciudad, provincia, fecha de registro/último pedido, género, grupo de usuarios, cantidad mínima de pedidos, tabla de precios, vendedor y monto gastado mínimo, además del orden.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Last order / Orders / Total</span><span class=\"t-pt\">Último pedido / Pedidos / Total</span><span class=\"t-es\">Último pedido / Pedidos / Total</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">How long ago the last order was placed, how many orders in total, and the combined amount spent.</span><span class=\"t-pt\">Há quanto tempo foi o último pedido, quantos pedidos ao todo, e o valor total gasto.</span><span class=\"t-es\">Hace cuánto fue el último pedido, cuántos pedidos en total, y el monto total gastado.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the customer's full record (see \"Create / edit customer\" and the detail tabs below).</span><span class=\"t-pt\">abre o registro completo do cliente (ver \"Criar/editar cliente\" e as abas de detalhe abaixo).</span><span class=\"t-es\">abre el registro completo del cliente (ver \"Crear/editar cliente\" y las pestañas de detalle abajo).</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">permanently removes the customer/user.</span><span class=\"t-pt\">remove o cliente/usuário permanentemente.</span><span class=\"t-es\">elimina el cliente/usuario de forma permanente.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"clientes-criar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customers and users &gt; Add</span><span class=\"t-pt\">Clientes e usuários &gt; Adicionar</span><span class=\"t-es\">Clientes y usuarios &gt; Agregar</span></span></h3>\n        <h3><span class=\"t-en\">Create / edit customer</span><span class=\"t-pt\">Criar/editar cliente</span><span class=\"t-es\">Crear/editar cliente</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via \"Create customer/user\" on the list. The left panel holds the core profile; the right panel has tabs for contacts, address, sales configuration and security. Clicking an existing customer's name on the list instead opens a different, richer layout &mdash; covered in \"Customer detail\" below, starting with the Overview subsection.</p></span><span class=\"t-pt\"><p>Aberta pelo \"Criar cliente/usuário\" na lista. O painel esquerdo traz o perfil principal; o painel direito tem abas de contatos, endereço, configuração de vendas e segurança. Clicar no nome de um cliente já existente na lista, por outro lado, abre um layout diferente e mais completo &mdash; coberto em \"Detalhe do cliente\" abaixo, a partir da subseção Visão geral.</p></span><span class=\"t-es\"><p>Se abre con \"Crear cliente/usuario\" en la lista. El panel izquierdo trae el perfil principal; el panel derecho tiene pestañas de contactos, dirección, configuración de ventas y seguridad. Al hacer clic en el nombre de un cliente ya existente en la lista, en cambio, se abre un diseño diferente y más completo &mdash; cubierto en \"Detalle del cliente\" abajo, a partir de la subsección Visión general.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/121-clientes-en-add-edit-customer-form-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add/edit customer form (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/122-clientes-pt-add-edit-customer-form-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add/edit customer form (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/123-clientes-es-add-edit-customer-form-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add/edit customer form (es)\">\n          <figcaption><span class=\"t-en\">\"Add customers and users\" form, with the profile panel and the Contacts/Login tab</span><span class=\"t-pt\">Formulário \"Adicionar clientes e usuários\", com o painel de perfil e a aba Contatos/Login</span><span class=\"t-es\">Formulario \"Agregar clientes y usuarios\", con el panel de perfil y la pestaña Contactos/Login</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Status</span><span class=\"t-pt\">Status</span><span class=\"t-es\">Estado</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle</span><span class=\"t-pt\">Alternância</span><span class=\"t-es\">Alternancia</span></td><td class=\"field-desc\"><span class=\"t-en\">Enables or disables the account without deleting it.</span><span class=\"t-pt\">Ativa ou desativa a conta sem excluí-la.</span><span class=\"t-es\">Activa o desactiva la cuenta sin eliminarla.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name / Nickname</span><span class=\"t-pt\">Nome / Apelido</span><span class=\"t-es\">Nombre / Apodo</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Full name, plus an optional internal nickname/handle.</span><span class=\"t-pt\">Nome completo, além de um apelido/identificador interno opcional.</span><span class=\"t-es\">Nombre completo, además de un apodo/identificador interno opcional.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Person type + Document</span><span class=\"t-pt\">Tipo de pessoa + Documento</span><span class=\"t-es\">Tipo de persona + Documento</span></td><td class=\"field-type\"><span class=\"t-en\">Select + Text</span><span class=\"t-pt\">Seleção + Texto</span><span class=\"t-es\">Selección + Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Individual (CPF), Company (CNPJ) or Foreign person, plus a secondary document field (RG, tax-exempt, etc.).</span><span class=\"t-pt\">Pessoa física (CPF), Pessoa jurídica (CNPJ) ou Pessoa estrangeira, além de um campo de documento secundário (RG, isento, etc.).</span><span class=\"t-es\">Persona física (CPF), Persona jurídica (CNPJ) o Persona extranjera, además de un campo de documento secundario (RG, exento, etc.).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Gender / Birth date</span><span class=\"t-pt\">Gênero / Data de nascimento</span><span class=\"t-es\">Género / Fecha de nacimiento</span></td><td class=\"field-type\"><span class=\"t-en\">Select / Date</span><span class=\"t-pt\">Seleção / Data</span><span class=\"t-es\">Selección / Fecha</span></td><td class=\"field-desc\"><span class=\"t-en\">Optional demographic fields.</span><span class=\"t-pt\">Campos demográficos opcionais.</span><span class=\"t-es\">Campos demográficos opcionales.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Observations</span><span class=\"t-pt\">Observações</span><span class=\"t-es\">Observaciones</span></td><td class=\"field-type\"><span class=\"t-en\">Text area</span><span class=\"t-pt\">Área de texto</span><span class=\"t-es\">Área de texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Free-form internal notes about the customer.</span><span class=\"t-pt\">Anotações internas livres sobre o cliente.</span><span class=\"t-es\">Notas internas libres sobre el cliente.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Contacts / Login tab</span><span class=\"t-pt\">Aba Contatos / Login</span><span class=\"t-es\">Pestaña Contactos / Login</span></td><td class=\"field-type\"><span class=\"t-en\">Tab</span><span class=\"t-pt\">Aba</span><span class=\"t-es\">Pestaña</span></td><td class=\"field-desc\"><span class=\"t-en\">Add phone/email contacts, each optionally tied to a specific sales channel; used for login and notifications.</span><span class=\"t-pt\">Adiciona contatos de telefone/e-mail, cada um opcionalmente vinculado a um canal de venda específico; usados para login e notificações.</span><span class=\"t-es\">Agrega contactos de teléfono/correo, cada uno opcionalmente vinculado a un canal de venta específico; usados para el login y las notificaciones.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Address tab</span><span class=\"t-pt\">Aba Endereço</span><span class=\"t-es\">Pestaña Dirección</span></td><td class=\"field-type\"><span class=\"t-en\">Tab</span><span class=\"t-pt\">Aba</span><span class=\"t-es\">Pestaña</span></td><td class=\"field-desc\"><span class=\"t-en\">Registers one or more delivery addresses; one can be marked Default.</span><span class=\"t-pt\">Cadastra um ou mais endereços de entrega; um pode ser marcado como Padrão.</span><span class=\"t-es\">Registra una o más direcciones de entrega; una puede marcarse como Predeterminada.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">General settings tab</span><span class=\"t-pt\">Aba Configuração geral</span><span class=\"t-es\">Pestaña Configuración general</span></td><td class=\"field-type\"><span class=\"t-en\">Tab</span><span class=\"t-pt\">Aba</span><span class=\"t-es\">Pestaña</span></td><td class=\"field-desc\"><span class=\"t-en\">User group, price table, salesperson, sales channels and additional price tables, plus an email marketing opt-in.</span><span class=\"t-pt\">Grupo de usuários, tabela de preço, vendedor, canais de venda e tabelas de preço adicionais, além do opt-in de e-mail marketing.</span><span class=\"t-es\">Grupo de usuarios, tabla de precios, vendedor, canales de venta y tablas de precios adicionales, además del opt-in de email marketing.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Security tab</span><span class=\"t-pt\">Aba Segurança</span><span class=\"t-es\">Pestaña Seguridad</span></td><td class=\"field-type\"><span class=\"t-en\">Tab</span><span class=\"t-pt\">Aba</span><span class=\"t-es\">Pestaña</span></td><td class=\"field-desc\"><span class=\"t-en\">Password change, two-factor authentication and API keys scoped to this user's permissions.</span><span class=\"t-pt\">Alteração de senha, autenticação de dois fatores e API keys com permissões deste usuário.</span><span class=\"t-es\">Cambio de contraseña, autenticación de dos factores y API keys con los permisos de este usuario.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"clientes-perfil\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customers and users &gt; Edit</span><span class=\"t-pt\">Clientes e usuários &gt; Editar</span><span class=\"t-es\">Clientes y usuarios &gt; Editar</span></span></h3>\n        <h3><span class=\"t-en\">Customer detail &mdash; Overview</span><span class=\"t-pt\">Detalhe do cliente &mdash; Visão geral</span><span class=\"t-es\">Detalle del cliente &mdash; Visión general</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Clicking a customer's name on the list opens a different layout from the create form: the left panel becomes a read-only summary card (name, document, gender, birth date) with an \"Edit\" button, and the right panel gains two extra tabs &mdash; \"Orders placed\" and \"Wallet\" &mdash; besides the four covered below. \"Edit\" opens the same core-profile fields (name, document, gender, birth date, observations) in a dialog, plus a Status toggle and a \"Delete\" button not available on the create form.</p></span><span class=\"t-pt\"><p>Clicar no nome de um cliente na lista abre um layout diferente do formulário de criação: o painel esquerdo vira um card de resumo somente leitura (nome, documento, gênero, data de nascimento) com um botão \"Editar\", e o painel direito ganha duas abas a mais &mdash; \"Pedidos efetuados\" e \"Carteira\" &mdash; além das quatro cobertas abaixo. \"Editar\" abre os mesmos campos do perfil principal (nome, documento, gênero, data de nascimento, observações) em uma janela, além de um interruptor de Status e um botão \"Deletar\" que não existem no formulário de criação.</p></span><span class=\"t-es\"><p>Al hacer clic en el nombre de un cliente en la lista se abre un diseño diferente al del formulario de creación: el panel izquierdo se convierte en una tarjeta de resumen de solo lectura (nombre, documento, género, fecha de nacimiento) con un botón \"Editar\", y el panel derecho gana dos pestañas más &mdash; \"Pedidos realizados\" y \"Cartera\" &mdash; además de las cuatro cubiertas abajo. \"Editar\" abre los mismos campos del perfil principal (nombre, documento, género, fecha de nacimiento, observaciones) en una ventana, además de un interruptor de Estado y un botón \"Borrar\" que no existen en el formulario de creación.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/124-clientes-en-edit-user-dialog-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"edit user dialog (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/125-clientes-pt-edit-user-dialog-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"edit user dialog (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/126-clientes-es-edit-user-dialog-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"edit user dialog (es)\">\n          <figcaption><span class=\"t-en\">\"Edit user\" dialog, opened from the summary card: profile image, Status, Delete and the same core fields as the create form</span><span class=\"t-pt\">Janela \"Editar usuário\", aberta pelo card de resumo: imagem de perfil, Status, Deletar e os mesmos campos principais do formulário de criação</span><span class=\"t-es\">Ventana \"Editar usuario\", abierta desde la tarjeta de resumen: imagen de perfil, Estado, Borrar y los mismos campos principales del formulario de creación</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Status</span><span class=\"t-pt\">Status</span><span class=\"t-es\">Estado</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle</span><span class=\"t-pt\">Alternância</span><span class=\"t-es\">Alternancia</span></td><td class=\"field-desc\"><span class=\"t-en\">Enables or disables the account without deleting it.</span><span class=\"t-pt\">Ativa ou desativa a conta sem excluí-la.</span><span class=\"t-es\">Activa o desactiva la cuenta sin eliminarla.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Permanently removes the customer/user; only available once the customer already exists.</span><span class=\"t-pt\">Remove o cliente/usuário permanentemente; disponível apenas quando o cliente já existe.</span><span class=\"t-es\">Elimina el cliente/usuario de forma permanente; disponible solo cuando el cliente ya existe.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name, Document, Gender, Birth date, Observations</span><span class=\"t-pt\">Nome, Documento, Gênero, Data de nascimento, Observações</span><span class=\"t-es\">Nombre, Documento, Género, Fecha de nacimiento, Observaciones</span></td><td class=\"field-type\"><span class=\"t-en\">Same as create</span><span class=\"t-pt\">Igual à criação</span><span class=\"t-es\">Igual a la creación</span></td><td class=\"field-desc\"><span class=\"t-en\">Same fields documented in \"Create / edit customer\" above, pre-filled with the existing values.</span><span class=\"t-pt\">Mesmos campos documentados em \"Criar/editar cliente\" acima, já preenchidos com os valores existentes.</span><span class=\"t-es\">Mismos campos documentados en \"Crear/editar cliente\" arriba, ya rellenados con los valores existentes.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"clientes-contatos\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customers and users &gt; Edit &gt; Contacts/Login</span><span class=\"t-pt\">Clientes e usuários &gt; Editar &gt; Contatos/Login</span><span class=\"t-es\">Clientes y usuarios &gt; Editar &gt; Contactos/Login</span></span></h3>\n        <h3><span class=\"t-en\">Customer detail &mdash; Contacts/Login</span><span class=\"t-pt\">Detalhe do cliente &mdash; Contatos/Login</span><span class=\"t-es\">Detalle del cliente &mdash; Contactos/Login</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Default tab when opening an existing customer. Lists every phone/e-mail contact used for login and notifications, each optionally tied to a sales channel.</p></span><span class=\"t-pt\"><p>Aba padrão ao abrir um cliente já existente. Lista todos os contatos de telefone/e-mail usados para login e notificações, cada um opcionalmente vinculado a um canal de venda.</p></span><span class=\"t-es\"><p>Pestaña predeterminada al abrir un cliente ya existente. Lista todos los contactos de teléfono/correo usados para el login y las notificaciones, cada uno opcionalmente vinculado a un canal de venta.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/127-clientes-en-customer-contacts-login-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer contacts/login tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/128-clientes-pt-customer-contacts-login-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer contacts/login tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/129-clientes-es-customer-contacts-login-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer contacts/login tab (es)\">\n          <figcaption><span class=\"t-en\">Contacts/Login tab, expanded, with the \"Tip\" panel and the customer's registered contacts</span><span class=\"t-pt\">Aba Contatos/Login, expandida, com o painel \"Dica\" e os contatos cadastrados do cliente</span><span class=\"t-es\">Pestaña Contactos/Login, expandida, con el panel \"Consejo\" y los contactos registrados del cliente</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Tip</span><span class=\"t-pt\">Dica</span><span class=\"t-es\">Consejo</span></td><td class=\"field-type\"><span class=\"t-en\">Info panel</span><span class=\"t-pt\">Painel de informação</span><span class=\"t-es\">Panel de información</span></td><td class=\"field-desc\"><span class=\"t-en\">Explains the sign-in rule: only contacts linked to the channel (or with no channel link at all) can be used to log in on that channel.</span><span class=\"t-pt\">Explica a regra de login: só contatos vinculados ao canal (ou sem nenhum vínculo de canal) podem ser usados para entrar naquele canal.</span><span class=\"t-es\">Explica la regla de inicio de sesión: solo los contactos vinculados al canal (o sin ningún vínculo de canal) pueden usarse para iniciar sesión en ese canal.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">+ Add contact</span><span class=\"t-pt\">+ Adicionar contato</span><span class=\"t-es\">+ Agregar contacto</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Adds a new contact row (type, value and channel).</span><span class=\"t-pt\">Adiciona uma nova linha de contato (tipo, valor e canal).</span><span class=\"t-es\">Agrega una nueva fila de contacto (tipo, valor y canal).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Type / Value / Channel</span><span class=\"t-pt\">Tipo / Valor / Canal</span><span class=\"t-es\">Tipo / Valor / Canal</span></td><td class=\"field-type\"><span class=\"t-en\">Select / Text / Select</span><span class=\"t-pt\">Seleção / Texto / Seleção</span><span class=\"t-es\">Selección / Texto / Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Email or phone, the contact's value, and which sales channel it's linked to (or none, to allow login on every channel).</span><span class=\"t-pt\">E-mail ou telefone, o valor do contato, e a qual canal de venda ele está vinculado (ou nenhum, para permitir login em todos os canais).</span><span class=\"t-es\">Correo o teléfono, el valor del contacto, y a qué canal de venta está vinculado (o ninguno, para permitir el login en todos los canales).</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"clientes-endereco\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customers and users &gt; Edit &gt; Address</span><span class=\"t-pt\">Clientes e usuários &gt; Editar &gt; Endereço</span><span class=\"t-es\">Clientes y usuarios &gt; Editar &gt; Dirección</span></span></h3>\n        <h3><span class=\"t-en\">Customer detail &mdash; Address</span><span class=\"t-pt\">Detalhe do cliente &mdash; Endereço</span><span class=\"t-es\">Detalle del cliente &mdash; Dirección</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists every address registered for the customer, collapsed by default; one is marked Default. Expanding a row shows its full form for editing.</p></span><span class=\"t-pt\"><p>Lista todos os endereços cadastrados para o cliente, recolhidos por padrão; um deles é marcado como Padrão. Expandir uma linha mostra o formulário completo para edição.</p></span><span class=\"t-es\"><p>Lista todas las direcciones registradas para el cliente, colapsadas de forma predeterminada; una se marca como Predeterminada. Al expandir una fila se muestra el formulario completo para editarla.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/130-clientes-en-customer-address-tab-expanded-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer address tab expanded (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/131-clientes-pt-customer-address-tab-expanded-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer address tab expanded (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/132-clientes-es-customer-address-tab-expanded-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer address tab expanded (es)\">\n          <figcaption><span class=\"t-en\">Address tab, one address expanded: Type, Country, Receiver, Zipcode, Street, Number, Complement, District, City, State, Latitude/Longitude and \"Use as default\"</span><span class=\"t-pt\">Aba Endereço, um endereço expandido: Tipo, País, Recebedor, CEP, Rua, Número, Complemento, Bairro, Cidade, UF, Latitude/Longitude e \"Usar como padrão\"</span><span class=\"t-es\">Pestaña Dirección, una dirección expandida: Tipo, País, Receptor, Código postal, Calle, Número, Complemento, Barrio, Ciudad, Estado, Latitud/Longitud y \"Usar como predeterminado\"</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">+ Add new address</span><span class=\"t-pt\">+ Adicionar novo endereço</span><span class=\"t-es\">+ Agregar nueva dirección</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Adds a new, empty address form to fill in and save.</span><span class=\"t-pt\">Adiciona um novo formulário de endereço vazio para preencher e salvar.</span><span class=\"t-es\">Agrega un nuevo formulario de dirección vacío para completar y guardar.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Type / Country</span><span class=\"t-pt\">Tipo / País</span><span class=\"t-es\">Tipo / País</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Delivery or Billing, and the country the address is in.</span><span class=\"t-pt\">Entrega ou Cobrança, e o país do endereço.</span><span class=\"t-es\">Entrega o Facturación, y el país de la dirección.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Receiver / Zipcode / Street / Number / Complement / District / City / State</span><span class=\"t-pt\">Recebedor / CEP / Rua / Número / Complemento / Bairro / Cidade / UF</span><span class=\"t-es\">Receptor / Código postal / Calle / Número / Complemento / Barrio / Ciudad / Estado</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Standard address fields; Zipcode auto-fills most of the others when recognized.</span><span class=\"t-pt\">Campos padrão de endereço; o CEP preenche automaticamente a maior parte dos outros quando reconhecido.</span><span class=\"t-es\">Campos estándar de dirección; el código postal completa automáticamente la mayoría de los demás cuando se reconoce.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Latitude / Longitude</span><span class=\"t-pt\">Latitude / Longitude</span><span class=\"t-es\">Latitud / Longitud</span></td><td class=\"field-type\"><span class=\"t-en\">Number (auto)</span><span class=\"t-pt\">Número (automático)</span><span class=\"t-es\">Número (automático)</span></td><td class=\"field-desc\"><span class=\"t-en\">Geocoded automatically from the address; used for delivery-radius and map features.</span><span class=\"t-pt\">Geocodificadas automaticamente a partir do endereço; usadas em recursos de raio de entrega e mapa.</span><span class=\"t-es\">Geocodificadas automáticamente a partir de la dirección; usadas en funciones de radio de entrega y mapa.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Use as default / Delete / Save</span><span class=\"t-pt\">Usar como padrão / Deletar / Salvar</span><span class=\"t-es\">Usar como predeterminado / Borrar / Guardar</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle + Buttons</span><span class=\"t-pt\">Alternância + Botões</span><span class=\"t-es\">Alternancia + Botones</span></td><td class=\"field-desc\"><span class=\"t-en\">Marks this as the customer's default address, permanently removes it, or saves changes to it.</span><span class=\"t-pt\">Marca este como o endereço padrão do cliente, remove-o permanentemente, ou salva as alterações nele.</span><span class=\"t-es\">Marca esta como la dirección predeterminada del cliente, la elimina permanentemente, o guarda los cambios en ella.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"clientes-config\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customers and users &gt; Edit &gt; General settings</span><span class=\"t-pt\">Clientes e usuários &gt; Editar &gt; Configuração geral</span><span class=\"t-es\">Clientes y usuarios &gt; Editar &gt; Configuración general</span></span></h3>\n        <h3><span class=\"t-en\">Customer detail &mdash; General settings</span><span class=\"t-pt\">Detalhe do cliente &mdash; Configuração geral</span><span class=\"t-es\">Detalle del cliente &mdash; Configuración general</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Sales-related settings that determine which prices, stock and salesperson apply to this customer's orders.</p></span><span class=\"t-pt\"><p>Configurações relacionadas a vendas que determinam quais preços, estoque e vendedor se aplicam aos pedidos deste cliente.</p></span><span class=\"t-es\"><p>Configuraciones relacionadas con las ventas que determinan qué precios, stock y vendedor se aplican a los pedidos de este cliente.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/133-clientes-en-customer-general-settings-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer general settings tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/134-clientes-pt-customer-general-settings-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer general settings tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/135-clientes-es-customer-general-settings-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer general settings tab (es)\">\n          <figcaption><span class=\"t-en\">General settings tab: user group, price table, salesperson, sales channels, additional price tables and e-mail marketing</span><span class=\"t-pt\">Aba Configuração geral: grupo de usuários, tabela de preço, vendedor, canais de venda, tabelas de preço adicionais e e-mail marketing</span><span class=\"t-es\">Pestaña Configuración general: grupo de usuarios, tabla de precios, vendedor, canales de venta, tablas de precios adicionales y correo de marketing</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">User group</span><span class=\"t-pt\">Grupo de usuários</span><span class=\"t-es\">Grupos de usuarios</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">Which customer group this account belongs to (affects visibility/pricing rules tied to groups).</span><span class=\"t-pt\">A qual grupo de clientes esta conta pertence (afeta regras de visibilidade/preço vinculadas a grupos).</span><span class=\"t-es\">A qué grupo de clientes pertenece esta cuenta (afecta reglas de visibilidad/precio vinculadas a grupos).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Price table</span><span class=\"t-pt\">Tabela de preço</span><span class=\"t-es\">Tabla de precios</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">The main price table applied to this customer's orders.</span><span class=\"t-pt\">A tabela de preço principal aplicada aos pedidos deste cliente.</span><span class=\"t-es\">La tabla de precios principal aplicada a los pedidos de este cliente.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Seller</span><span class=\"t-pt\">Vendedor</span><span class=\"t-es\">Vendedor</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">The salesperson associated with this customer, if any.</span><span class=\"t-pt\">O vendedor associado a este cliente, se houver.</span><span class=\"t-es\">El vendedor asociado a este cliente, si lo hay.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Sales channels</span><span class=\"t-pt\">Canais de venda</span><span class=\"t-es\">Canales de venta</span></td><td class=\"field-type\"><span class=\"t-en\">Select (multiple)</span><span class=\"t-pt\">Seleção (múltipla)</span><span class=\"t-es\">Selección (múltiple)</span></td><td class=\"field-desc\"><span class=\"t-en\">Which channels this customer is associated with.</span><span class=\"t-pt\">A quais canais este cliente está associado.</span><span class=\"t-es\">A qué canales está asociado este cliente.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Additional price tables</span><span class=\"t-pt\">Tabelas de preço adicionais</span><span class=\"t-es\">Tablas de precios adicionales</span></td><td class=\"field-type\"><span class=\"t-en\">Select (multiple)</span><span class=\"t-pt\">Seleção (múltipla)</span><span class=\"t-es\">Selección (múltiple)</span></td><td class=\"field-desc\"><span class=\"t-en\">Extra price tables this customer can also see/use besides the main one.</span><span class=\"t-pt\">Tabelas de preço extras que este cliente também pode ver/usar além da principal.</span><span class=\"t-es\">Tablas de precios adicionales que este cliente también puede ver/usar además de la principal.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">E-mail marketing</span><span class=\"t-pt\">E-mail marketing</span><span class=\"t-es\">Correo de marketing</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle</span><span class=\"t-pt\">Alternância</span><span class=\"t-es\">Alternancia</span></td><td class=\"field-desc\"><span class=\"t-en\">Whether this customer opted in to receive marketing e-mails.</span><span class=\"t-pt\">Se este cliente optou por receber e-mails de marketing.</span><span class=\"t-es\">Si este cliente optó por recibir correos de marketing.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"clientes-seguranca\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customers and users &gt; Edit &gt; Security</span><span class=\"t-pt\">Clientes e usuários &gt; Editar &gt; Segurança</span><span class=\"t-es\">Clientes y usuarios &gt; Editar &gt; Seguridad</span></span></h3>\n        <h3><span class=\"t-en\">Customer detail &mdash; Security</span><span class=\"t-pt\">Detalhe do cliente &mdash; Segurança</span><span class=\"t-es\">Detalle del cliente &mdash; Seguridad</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Login and access-credential settings for this customer/user: password, two-factor authentication and personal API keys.</p></span><span class=\"t-pt\"><p>Configurações de login e credenciais de acesso deste cliente/usuário: senha, autenticação de dois fatores e API keys pessoais.</p></span><span class=\"t-es\"><p>Configuraciones de inicio de sesión y credenciales de acceso de este cliente/usuario: contraseña, autenticación de dos factores y API keys personales.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/136-clientes-en-customer-security-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer security tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/137-clientes-pt-customer-security-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer security tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/138-clientes-es-customer-security-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer security tab (es)\">\n          <figcaption><span class=\"t-en\">Security tab: change password, two-factor authentication and the user's API keys table</span><span class=\"t-pt\">Aba Segurança: alterar senha, autenticação de dois fatores e a tabela de API keys do usuário</span><span class=\"t-es\">Pestaña Seguridad: cambiar contraseña, autenticación de dos factores y la tabla de API keys del usuario</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">New password</span><span class=\"t-pt\">Nova senha</span><span class=\"t-es\">Nueva contraseña</span></td><td class=\"field-type\"><span class=\"t-en\">Password field</span><span class=\"t-pt\">Campo de senha</span><span class=\"t-es\">Campo de contraseña</span></td><td class=\"field-desc\"><span class=\"t-en\">Sets a new password for this customer/user's login.</span><span class=\"t-pt\">Define uma nova senha para o login deste cliente/usuário.</span><span class=\"t-es\">Define una nueva contraseña para el login de este cliente/usuario.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Enable authentication</span><span class=\"t-pt\">Ativar autenticação</span><span class=\"t-es\">Activar autenticación</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Starts two-factor authentication setup for this account.</span><span class=\"t-pt\">Inicia a configuração de autenticação de dois fatores para esta conta.</span><span class=\"t-es\">Inicia la configuración de autenticación de dos factores para esta cuenta.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">+ New API key</span><span class=\"t-pt\">+ Nova API key</span><span class=\"t-es\">+ Nueva API key</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Creates an API key scoped to this user's own permissions, for personal integrations.</span><span class=\"t-pt\">Cria uma API key com as permissões deste próprio usuário, para integrações pessoais.</span><span class=\"t-es\">Crea una API key con los permisos de este propio usuario, para integraciones personales.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">API keys table</span><span class=\"t-pt\">Tabela de API keys</span><span class=\"t-es\">Tabla de API keys</span></td><td class=\"field-type\"><span class=\"t-en\">Name / Last used / Created at / Actions</span><span class=\"t-pt\">Nome / Último uso / Criado em / Ações</span><span class=\"t-es\">Nombre / Último uso / Creado en / Acciones</span></td><td class=\"field-desc\"><span class=\"t-en\">Lists this user's own API keys, each revocable individually.</span><span class=\"t-pt\">Lista as API keys deste usuário, cada uma revogável individualmente.</span><span class=\"t-es\">Lista las API keys de este usuario, cada una revocable individualmente.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"clientes-pedidos\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customers and users &gt; Edit &gt; Orders placed</span><span class=\"t-pt\">Clientes e usuários &gt; Editar &gt; Pedidos efetuados</span><span class=\"t-es\">Clientes y usuarios &gt; Editar &gt; Pedidos realizados</span></span></h3>\n        <h3><span class=\"t-en\">Customer detail &mdash; Orders placed</span><span class=\"t-pt\">Detalhe do cliente &mdash; Pedidos efetuados</span><span class=\"t-es\">Detalle del cliente &mdash; Pedidos realizados</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Only available once a customer already exists (not on the create form). Summarizes and lists every order this customer has placed, across all sales channels.</p></span><span class=\"t-pt\"><p>Disponível apenas quando o cliente já existe (não aparece no formulário de criação). Resume e lista todos os pedidos feitos por este cliente, em todos os canais de venda.</p></span><span class=\"t-es\"><p>Disponible solo cuando el cliente ya existe (no aparece en el formulario de creación). Resume y lista todos los pedidos realizados por este cliente, en todos los canales de venta.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/139-clientes-en-customer-order-history-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer order history (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/140-clientes-pt-customer-order-history-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer order history (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/141-clientes-es-customer-order-history-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"customer order history (es)\">\n          <figcaption><span class=\"t-en\">\"Orders placed\" tab, with the summary stats and the order history table</span><span class=\"t-pt\">Aba \"Pedidos efetuados\", com as estatísticas de resumo e a tabela de histórico de pedidos</span><span class=\"t-es\">Pestaña \"Pedidos realizados\", con las estadísticas resumen y la tabla de historial de pedidos</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Orders / Total / Average ticket / Last order</span><span class=\"t-pt\">Pedidos / Total / Ticket médio / Último pedido</span><span class=\"t-es\">Pedidos / Total / Ticket promedio / Último pedido</span></td><td class=\"field-type\"><span class=\"t-en\">Summary cards</span><span class=\"t-pt\">Cards de resumo</span><span class=\"t-es\">Tarjetas de resumen</span></td><td class=\"field-desc\"><span class=\"t-en\">Order count, combined amount spent, average order value, and how long ago the last order was placed.</span><span class=\"t-pt\">Quantidade de pedidos, valor total gasto, valor médio por pedido, e há quanto tempo foi o último pedido.</span><span class=\"t-es\">Cantidad de pedidos, monto total gastado, valor promedio por pedido, y hace cuánto fue el último pedido.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Order / Date / Channel / Status / Total</span><span class=\"t-pt\">Pedido / Data / Canal / Status / Total</span><span class=\"t-es\">Pedido / Fecha / Canal / Estado / Total</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">Each row links directly to that order's detail screen in the Orders section.</span><span class=\"t-pt\">Cada linha leva diretamente à tela de detalhe daquele pedido, na seção Pedidos.</span><span class=\"t-es\">Cada fila lleva directamente a la pantalla de detalle de ese pedido, en la sección Pedidos.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"clientes-carteira\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customers and users &gt; Edit &gt; Wallet</span><span class=\"t-pt\">Clientes e usuários &gt; Editar &gt; Carteira</span><span class=\"t-es\">Clientes y usuarios &gt; Editar &gt; Cartera</span></span></h3>\n        <h3><span class=\"t-en\">Customer detail &mdash; Wallet</span><span class=\"t-pt\">Detalhe do cliente &mdash; Carteira</span><span class=\"t-es\">Detalle del cliente &mdash; Cartera</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Only available once a customer already exists. Shows this customer's individual store-credit ledger (e.g. refunds issued as credit, manual adjustments) and lets staff add manual entries via \"Manage wallet\".</p></span><span class=\"t-pt\"><p>Disponível apenas quando o cliente já existe. Mostra o extrato individual de crédito de loja deste cliente (ex.: reembolsos emitidos como crédito, ajustes manuais) e permite à equipe adicionar lançamentos manuais pelo \"Gerenciar carteira\".</p></span><span class=\"t-es\"><p>Disponible solo cuando el cliente ya existe. Muestra el extracto individual de crédito de tienda de este cliente (ej.: reembolsos emitidos como crédito, ajustes manuales) y permite al equipo agregar movimientos manuales con \"Administrar cartera\".</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/142-clientes-en-manage-wallet-dialog-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manage wallet dialog (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/143-clientes-pt-manage-wallet-dialog-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manage wallet dialog (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/144-clientes-es-manage-wallet-dialog-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manage wallet dialog (es)\">\n          <figcaption><span class=\"t-en\">\"Manage wallet\" dialog, for adding a manual credit or debit entry to this customer</span><span class=\"t-pt\">Janela \"Gerenciar carteira\", para adicionar um lançamento manual de crédito ou débito a este cliente</span><span class=\"t-es\">Ventana \"Administrar cartera\", para agregar un movimiento manual de crédito o débito a este cliente</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Credit (adds to the customer's balance) or Debit (subtracts from it).</span><span class=\"t-pt\">Crédito (soma ao saldo do cliente) ou Débito (subtrai do saldo).</span><span class=\"t-es\">Crédito (suma al saldo del cliente) o Débito (resta del saldo).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Currency / Value</span><span class=\"t-pt\">Moeda / Valor</span><span class=\"t-es\">Moneda / Valor</span></td><td class=\"field-type\"><span class=\"t-en\">Select / Number</span><span class=\"t-pt\">Seleção / Número</span><span class=\"t-es\">Selección / Número</span></td><td class=\"field-desc\"><span class=\"t-en\">Currency and amount of the entry.</span><span class=\"t-pt\">Moeda e valor do lançamento.</span><span class=\"t-es\">Moneda y monto del movimiento.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Description</span><span class=\"t-pt\">Descrição</span><span class=\"t-es\">Descripción</span></td><td class=\"field-type\"><span class=\"t-en\">Text area</span><span class=\"t-pt\">Área de texto</span><span class=\"t-es\">Área de texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Internal note explaining the reason for the manual entry.</span><span class=\"t-pt\">Anotação interna explicando o motivo do lançamento manual.</span><span class=\"t-es\">Nota interna que explica el motivo del movimiento manual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Add</span><span class=\"t-pt\">Adicionar</span><span class=\"t-es\">Añadir</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Creates the entry; it applies only to this customer and the recipient cannot be changed afterward.</span><span class=\"t-pt\">Cria o lançamento; ele se aplica somente a este cliente e o destinatário não pode ser alterado depois.</span><span class=\"t-es\">Crea el movimiento; se aplica solo a este cliente y el destinatario no se puede cambiar después.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=categorias\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Categories</span><span class=\"t-pt\">Categorias</span><span class=\"t-es\">Categorías</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=marketing\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Marketing</span><span class=\"t-pt\">Marketing</span><span class=\"t-es\">Marketing</span></strong></a>\n</nav>\n", "marketing": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Marketing</span><span class=\"t-pt\">Marketing</span><span class=\"t-es\">Marketing</span></p>\n<section class=\"doc-section\" id=\"promocoes\">\n      <h2><span class=\"t-en\">8. Marketing &gt; Promotions</span><span class=\"t-pt\">8. Marketing &gt; Promoções</span><span class=\"t-es\">8. Marketing &gt; Promociones</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Promotions apply automatic discount rules to products at checkout, without requiring a code &mdash; unlike Coupons (next), which need the customer to enter one.</span><span class=\"t-pt\">Promoções aplicam regras de desconto automáticas a produtos no checkout, sem exigir um código &mdash; ao contrário de Cupons (a seguir), que exigem que o cliente informe um código.</span><span class=\"t-es\">Las promociones aplican reglas de descuento automáticas a productos en el checkout, sin exigir un código &mdash; a diferencia de Cupones (a continuación), que exigen que el cliente ingrese un código.</span>\n      </p>\n      <div class=\"subsection\" id=\"promocoes-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Marketing &gt; Promotions</span><span class=\"t-pt\">Marketing &gt; Promoções</span><span class=\"t-es\">Marketing &gt; Promociones</span></span></h3>\n        <h3><span class=\"t-en\">Promotion list</span><span class=\"t-pt\">Lista de promoções</span><span class=\"t-es\">Lista de promociones</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Initial screen of the section. Shows every promotion registered in the store.</p></span><span class=\"t-pt\"><p>Tela inicial da seção. Mostra todas as promoções cadastradas na loja.</p></span><span class=\"t-es\"><p>Pantalla inicial de la sección. Muestra todas las promociones registradas en la tienda.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/145-promocoes-en-promotion-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"promotion list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/146-promocoes-pt-promotion-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"promotion list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/147-promocoes-es-promotion-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"promotion list (es)\">\n          <figcaption><span class=\"t-en\">Marketing &gt; Promotions screen, with the search/status/date filters and the (empty) promotion table</span><span class=\"t-pt\">Tela Marketing &gt; Promoções, com os filtros de busca/status/data e a tabela de promoções (vazia)</span><span class=\"t-es\">Pantalla Marketing &gt; Promociones, con los filtros de búsqueda/estado/fecha y la tabla de promociones (vacía)</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search</span><span class=\"t-pt\">Buscar</span><span class=\"t-es\">Buscar</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Searches by ID or promotion name.</span><span class=\"t-pt\">Busca por ID ou nome da promoção.</span><span class=\"t-es\">Busca por ID o nombre de la promoción.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Status / Start / End</span><span class=\"t-pt\">Status / Início / Fim</span><span class=\"t-es\">Estado / Inicio / Fin</span></td><td class=\"field-type\"><span class=\"t-en\">Select / Dates</span><span class=\"t-pt\">Seleção / Datas</span><span class=\"t-es\">Selección / Fechas</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters by active/inactive and by validity date range.</span><span class=\"t-pt\">Filtra por ativo/inativo e por intervalo de datas de validade.</span><span class=\"t-es\">Filtra por activo/inactivo y por rango de fechas de validez.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name / Validity</span><span class=\"t-pt\">Nome / Validade</span><span class=\"t-es\">Nombre / Validez</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">Promotion name and its configured start/end dates (or unlimited, if left blank).</span><span class=\"t-pt\">Nome da promoção e suas datas de início/fim configuradas (ou sem limite, se deixadas em branco).</span><span class=\"t-es\">Nombre de la promoción y sus fechas de inicio/fin configuradas (o sin límite, si se dejan en blanco).</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the same form used to create a promotion, with its current settings.</span><span class=\"t-pt\">abre o mesmo formulário usado para criar uma promoção, com as configurações atuais.</span><span class=\"t-es\">abre el mismo formulario usado para crear una promoción, con la configuración actual.</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">permanently removes the promotion.</span><span class=\"t-pt\">remove a promoção permanentemente.</span><span class=\"t-es\">elimina la promoción de forma permanente.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"promocoes-criar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Marketing &gt; Promotions &gt; Add</span><span class=\"t-pt\">Marketing &gt; Promoções &gt; Adicionar</span><span class=\"t-es\">Marketing &gt; Promociones &gt; Agregar</span></span></h3>\n        <h3><span class=\"t-en\">Create promotion</span><span class=\"t-pt\">Criar promoção</span><span class=\"t-es\">Crear promoción</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via \"Add promotion\" on the list, or \"Edit\" on a row. The same form is used to create and edit.</p></span><span class=\"t-pt\"><p>Aberta pelo \"Adicionar promoção\" na lista, ou pelo \"Editar\" de uma linha. O mesmo formulário é usado para criar e editar.</p></span><span class=\"t-es\"><p>Se abre con \"Agregar promoción\" en la lista, o con \"Editar\" en una fila. Se usa el mismo formulario para crear y editar.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/148-promocoes-en-add-promotion-form-with-progressive-discount-sel.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add promotion form with Progressive discount selected (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/149-promocoes-pt-add-promotion-form-with-progressive-discount-sel.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add promotion form with Progressive discount selected (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/150-promocoes-es-add-promotion-form-with-progressive-discount-sel.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add promotion form with Progressive discount selected (es)\">\n          <figcaption><span class=\"t-en\">\"Add promotion\" form with \"Progressive discount\" selected, showing the discount-rules table and the Apply to / ZIP code sections</span><span class=\"t-pt\">Formulário \"Adicionar promoção\" com \"Desconto progressivo\" selecionado, mostrando a tabela de regras de desconto e as seções Aplicar para / CEP</span><span class=\"t-es\">Formulario \"Agregar promoción\" con \"Descuento progresivo\" seleccionado, mostrando la tabla de reglas de descuento y las secciones Aplicar a / Código postal</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Active</span><span class=\"t-pt\">Ativo</span><span class=\"t-es\">Activo</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle</span><span class=\"t-pt\">Alternância</span><span class=\"t-es\">Alternancia</span></td><td class=\"field-desc\"><span class=\"t-en\">Enables or disables the promotion without deleting it.</span><span class=\"t-pt\">Ativa ou desativa a promoção sem excluí-la.</span><span class=\"t-es\">Activa o desactiva la promoción sin eliminarla.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Internal name used to identify the promotion in the list.</span><span class=\"t-pt\">Nome interno usado para identificar a promoção na lista.</span><span class=\"t-es\">Nombre interno usado para identificar la promoción en la lista.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Discount</span><span class=\"t-pt\">Desconto</span><span class=\"t-es\">Descuento</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">\"Buy 2 pay 1\" and \"Buy 3 pay 2\" are fixed bundle discounts; \"Progressive discount\" reveals a \"Discount rules\" table instead (see below).</span><span class=\"t-pt\">\"Leve 2 pague 1\" e \"Leve 3 pague 2\" são descontos fixos por combo; \"Desconto progressivo\" revela uma tabela de \"Regras de desconto\" no lugar (ver abaixo).</span><span class=\"t-es\">\"Lleva 2 paga 1\" y \"Lleva 3 paga 2\" son descuentos fijos por combo; \"Descuento progresivo\" revela una tabla de \"Reglas de descuento\" en su lugar (ver abajo).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Start / End / Channels</span><span class=\"t-pt\">Início / Fim / Canais</span><span class=\"t-es\">Inicio / Fin / Canales</span></td><td class=\"field-type\"><span class=\"t-en\">Dates / Select</span><span class=\"t-pt\">Datas / Seleção</span><span class=\"t-es\">Fechas / Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Validity period (unlimited if left blank) and which sales channels the promotion applies to (all, if left blank).</span><span class=\"t-pt\">Período de validade (sem limite se deixado em branco) e a quais canais de venda a promoção se aplica (todos, se deixado em branco).</span><span class=\"t-es\">Período de validez (sin límite si se deja en blanco) y a qué canales de venta se aplica la promoción (todos, si se deja en blanco).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Discount rules</span><span class=\"t-pt\">Regras de desconto</span><span class=\"t-es\">Reglas de descuento</span></td><td class=\"field-type\"><span class=\"t-en\">Table (Progressive discount only)</span><span class=\"t-pt\">Tabela (só em Desconto progressivo)</span><span class=\"t-es\">Tabla (solo en Descuento progresivo)</span></td><td class=\"field-desc\"><span class=\"t-en\">Only shown for \"Progressive discount\". Toggles between \"By order amount\" and \"By quantity\"; each row sets a minimum (amount or item count) and the discount percentage applied once that minimum is reached, letting several tiers stack.</span><span class=\"t-pt\">Só aparece em \"Desconto progressivo\". Alterna entre \"Por valor do pedido\" e \"Por quantidade\"; cada linha define um mínimo (valor ou quantidade de itens) e o percentual de desconto aplicado ao atingir aquele mínimo, permitindo empilhar várias faixas.</span><span class=\"t-es\">Solo aparece en \"Descuento progresivo\". Alterna entre \"Por valor del pedido\" y \"Por cantidad\"; cada fila define un mínimo (valor o cantidad de artículos) y el porcentaje de descuento aplicado al alcanzar ese mínimo, permitiendo apilar varios niveles.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Apply to</span><span class=\"t-pt\">Aplicar para</span><span class=\"t-es\">Aplicar a</span></td><td class=\"field-type\"><span class=\"t-en\">Select + Include/All/Exclude</span><span class=\"t-pt\">Seleção + Incluir/Todos/Excluir</span><span class=\"t-es\">Selección + Incluir/Todos/Excluir</span></td><td class=\"field-desc\"><span class=\"t-en\">Scopes the promotion to Products or Categories, then narrows it to specific items to include, all of them, or specific items to exclude.</span><span class=\"t-pt\">Restringe a promoção a Produtos ou Categorias, e então a refina para itens específicos a incluir, todos eles, ou itens específicos a excluir.</span><span class=\"t-es\">Limita la promoción a Productos o Categorías, y luego la ajusta a artículos específicos para incluir, todos ellos, o artículos específicos para excluir.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">ZIP code</span><span class=\"t-pt\">CEP</span><span class=\"t-es\">Código postal</span></td><td class=\"field-type\"><span class=\"t-en\">Ranges list</span><span class=\"t-pt\">Lista de faixas</span><span class=\"t-es\">Lista de rangos</span></td><td class=\"field-desc\"><span class=\"t-en\">Optionally restricts the promotion to one or more postal code ranges; \"Add\" appends another range.</span><span class=\"t-pt\">Restringe opcionalmente a promoção a uma ou mais faixas de CEP; \"Adicionar\" inclui outra faixa.</span><span class=\"t-es\">Restringe opcionalmente la promoción a uno o más rangos de código postal; \"Agregar\" incluye otro rango.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n\n    </section>\n\n<section class=\"doc-section\" id=\"cupons\">\n      <h2><span class=\"t-en\">9. Marketing &gt; Coupons</span><span class=\"t-pt\">9. Marketing &gt; Cupons</span><span class=\"t-es\">9. Marketing &gt; Cupones</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Coupons apply a discount when the customer enters a code at checkout &mdash; unlike Promotions (previous), which apply automatically.</span><span class=\"t-pt\">Cupons aplicam um desconto quando o cliente informa um código no checkout &mdash; ao contrário de Promoções (anterior), que se aplicam automaticamente.</span><span class=\"t-es\">Los cupones aplican un descuento cuando el cliente ingresa un código en el checkout &mdash; a diferencia de Promociones (anterior), que se aplican automáticamente.</span>\n      </p>\n      <div class=\"subsection\" id=\"cupons-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Marketing &gt; Coupons</span><span class=\"t-pt\">Marketing &gt; Cupons</span><span class=\"t-es\">Marketing &gt; Cupones</span></span></h3>\n        <h3><span class=\"t-en\">Coupon list</span><span class=\"t-pt\">Lista de cupons</span><span class=\"t-es\">Lista de cupones</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Initial screen of the section. Shows every coupon registered in the store.</p></span><span class=\"t-pt\"><p>Tela inicial da seção. Mostra todos os cupons cadastrados na loja.</p></span><span class=\"t-es\"><p>Pantalla inicial de la sección. Muestra todos los cupones registrados en la tienda.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/151-cupons-en-coupon-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"coupon list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/152-cupons-pt-coupon-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"coupon list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/153-cupons-es-coupon-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"coupon list (es)\">\n          <figcaption><span class=\"t-en\">Marketing &gt; Coupons screen, with the search/status/date filters and the (empty) coupon table</span><span class=\"t-pt\">Tela Marketing &gt; Cupons, com os filtros de busca/status/data e a tabela de cupons (vazia)</span><span class=\"t-es\">Pantalla Marketing &gt; Cupones, con los filtros de búsqueda/estado/fecha y la tabla de cupones (vacía)</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search</span><span class=\"t-pt\">Buscar</span><span class=\"t-es\">Buscar</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Searches by ID, name or #code#.</span><span class=\"t-pt\">Busca por ID, nome ou #código#.</span><span class=\"t-es\">Busca por ID, nombre o #código#.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Status / Start / End</span><span class=\"t-pt\">Status / Início / Fim</span><span class=\"t-es\">Estado / Inicio / Fin</span></td><td class=\"field-type\"><span class=\"t-en\">Select / Dates</span><span class=\"t-pt\">Seleção / Datas</span><span class=\"t-es\">Selección / Fechas</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters by active/inactive and by validity date range.</span><span class=\"t-pt\">Filtra por ativo/inativo e por intervalo de datas de validade.</span><span class=\"t-es\">Filtra por activo/inactivo y por rango de fechas de validez.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name / Code / Discount / Validity</span><span class=\"t-pt\">Nome / Código / Desconto / Validade</span><span class=\"t-es\">Nombre / Código / Descuento / Validez</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">The coupon's internal name, the code customers must enter, the discount it grants, and its configured validity period.</span><span class=\"t-pt\">O nome interno do cupom, o código que os clientes devem informar, o desconto que ele concede, e o período de validade configurado.</span><span class=\"t-es\">El nombre interno del cupón, el código que los clientes deben ingresar, el descuento que otorga, y el período de validez configurado.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the same form used to create a coupon, with its current settings.</span><span class=\"t-pt\">abre o mesmo formulário usado para criar um cupom, com as configurações atuais.</span><span class=\"t-es\">abre el mismo formulario usado para crear un cupón, con la configuración actual.</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">permanently removes the coupon.</span><span class=\"t-pt\">remove o cupom permanentemente.</span><span class=\"t-es\">elimina el cupón de forma permanente.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"cupons-criar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Marketing &gt; Coupons &gt; Add</span><span class=\"t-pt\">Marketing &gt; Cupons &gt; Adicionar</span><span class=\"t-es\">Marketing &gt; Cupones &gt; Agregar</span></span></h3>\n        <h3><span class=\"t-en\">Create coupon</span><span class=\"t-pt\">Criar cupom</span><span class=\"t-es\">Crear cupón</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Opened via \"Add coupon\" on the list, or \"Edit\" on a row. The same form is used to create and edit. The collapsible \"Observations\" panel at the top explains how each discount type is calculated: percentage and fixed-value discounts are based on the products' total value, while free shipping is based on the shipping cost.</p></span><span class=\"t-pt\"><p>Aberta pelo \"Adicionar cupom\" na lista, ou pelo \"Editar\" de uma linha. O mesmo formulário é usado para criar e editar. O painel retrátil \"Observações\" no topo explica como cada tipo de desconto é calculado: os descontos percentual e valor fixo têm como base o valor total dos produtos, enquanto o frete grátis tem como base o valor do frete.</p></span><span class=\"t-es\"><p>Se abre con \"Agregar cupón\" en la lista, o con \"Editar\" en una fila. Se usa el mismo formulario para crear y editar. El panel plegable \"Observaciones\" en la parte superior explica cómo se calcula cada tipo de descuento: los descuentos porcentual y de valor fijo se basan en el valor total de los productos, mientras que el envío gratis se basa en el costo del envío.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/154-cupons-en-add-coupon-form-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add coupon form (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/155-cupons-pt-add-coupon-form-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add coupon form (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/156-cupons-es-add-coupon-form-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add coupon form (es)\">\n          <figcaption><span class=\"t-en\">\"Add coupon\" form, with the expanded Observations panel, Name/Code fields and the discount rules</span><span class=\"t-pt\">Formulário \"Adicionar cupom\", com o painel Observações expandido, os campos Nome/Código e as regras de desconto</span><span class=\"t-es\">Formulario \"Agregar cupón\", con el panel Observaciones expandido, los campos Nombre/Código y las reglas de descuento</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name / Code</span><span class=\"t-pt\">Nome / Código</span><span class=\"t-es\">Nombre / Código</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Internal name, and the code the customer types in at checkout to apply the discount.</span><span class=\"t-pt\">Nome interno, e o código que o cliente digita no checkout para aplicar o desconto.</span><span class=\"t-es\">Nombre interno, y el código que el cliente escribe en el checkout para aplicar el descuento.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Discount</span><span class=\"t-pt\">Desconto</span><span class=\"t-es\">Descuento</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Percentage, Fixed value, or Free shipping.</span><span class=\"t-pt\">Percentual, Valor fixo, ou Frete grátis.</span><span class=\"t-es\">Porcentual, Valor fijo, o Envío gratis.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Show on product page</span><span class=\"t-pt\">Exibir na página do produto</span><span class=\"t-es\">Mostrar en la página del producto</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Whether the coupon's discount is advertised directly on the product page.</span><span class=\"t-pt\">Se o desconto do cupom é anunciado diretamente na página do produto.</span><span class=\"t-es\">Si el descuento del cupón se anuncia directamente en la página del producto.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Minimum order value</span><span class=\"t-pt\">Valor mínimo do pedido</span><span class=\"t-es\">Valor mínimo del pedido</span></td><td class=\"field-type\"><span class=\"t-en\">Number</span><span class=\"t-pt\">Número</span><span class=\"t-es\">Número</span></td><td class=\"field-desc\"><span class=\"t-en\">Order subtotal required for the coupon to be accepted.</span><span class=\"t-pt\">Subtotal do pedido necessário para o cupom ser aceito.</span><span class=\"t-es\">Subtotal del pedido necesario para que se acepte el cupón.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Usage limit / Limit per customer</span><span class=\"t-pt\">Limite de uso / Limite por cliente</span><span class=\"t-es\">Límite de uso / Límite por cliente</span></td><td class=\"field-type\"><span class=\"t-en\">Number</span><span class=\"t-pt\">Número</span><span class=\"t-es\">Número</span></td><td class=\"field-desc\"><span class=\"t-en\">Maximum total redemptions, and maximum redemptions per individual customer; both unlimited if left blank.</span><span class=\"t-pt\">Máximo de usos no total, e máximo de usos por cliente individual; ambos ilimitados se deixados em branco.</span><span class=\"t-es\">Máximo de usos en total, y máximo de usos por cliente individual; ambos ilimitados si se dejan en blanco.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Start / End / Channels</span><span class=\"t-pt\">Início / Fim / Canais</span><span class=\"t-es\">Inicio / Fin / Canales</span></td><td class=\"field-type\"><span class=\"t-en\">Dates / Select</span><span class=\"t-pt\">Datas / Seleção</span><span class=\"t-es\">Fechas / Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Validity period and which sales channels accept the coupon (unlimited/all if left blank).</span><span class=\"t-pt\">Período de validade e em quais canais de venda o cupom é aceito (sem limite/todos se deixado em branco).</span><span class=\"t-es\">Período de validez y en qué canales de venta se acepta el cupón (sin límite/todos si se deja en blanco).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Payment restrictions</span><span class=\"t-pt\">Restrições de pagamentos</span><span class=\"t-es\">Restricciones de pago</span></td><td class=\"field-type\"><span class=\"t-en\">Multi-select</span><span class=\"t-pt\">Seleção múltipla</span><span class=\"t-es\">Selección múltiple</span></td><td class=\"field-desc\"><span class=\"t-en\">Limits the coupon to specific payment methods configured in the store (e.g. a gateway's Pix, credit card or boleto); all methods accepted if left blank.</span><span class=\"t-pt\">Restringe o cupom a formas de pagamento específicas configuradas na loja (ex.: Pix, cartão ou boleto de um gateway); todas as formas são aceitas se deixado em branco.</span><span class=\"t-es\">Restringe el cupón a métodos de pago específicos configurados en la tienda (ej.: Pix, tarjeta o boleto de una pasarela); se aceptan todos los métodos si se deja en blanco.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Apply to</span><span class=\"t-pt\">Aplicar para</span><span class=\"t-es\">Aplicar a</span></td><td class=\"field-type\"><span class=\"t-en\">Select + Include/All/Exclude</span><span class=\"t-pt\">Seleção + Incluir/Todos/Excluir</span><span class=\"t-es\">Selección + Incluir/Todos/Excluir</span></td><td class=\"field-desc\"><span class=\"t-en\">Scopes the coupon to Products or Categories, then narrows it to specific items to include, all of them, or specific items to exclude.</span><span class=\"t-pt\">Restringe o cupom a Produtos ou Categorias, e então o refina para itens específicos a incluir, todos eles, ou itens específicos a excluir.</span><span class=\"t-es\">Limita el cupón a Productos o Categorías, y luego lo ajusta a artículos específicos para incluir, todos ellos, o artículos específicos para excluir.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">ZIP code</span><span class=\"t-pt\">CEP</span><span class=\"t-es\">Código postal</span></td><td class=\"field-type\"><span class=\"t-en\">Ranges list</span><span class=\"t-pt\">Lista de faixas</span><span class=\"t-es\">Lista de rangos</span></td><td class=\"field-desc\"><span class=\"t-en\">Optionally restricts the coupon to one or more postal code ranges.</span><span class=\"t-pt\">Restringe opcionalmente o cupom a uma ou mais faixas de CEP.</span><span class=\"t-es\">Restringe opcionalmente el cupón a uno o más rangos de código postal.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n\n    </section>\n\n<section class=\"doc-section\" id=\"newsletter\">\n      <h2><span class=\"t-en\">10. Marketing &gt; Newsletter</span><span class=\"t-pt\">10. Marketing &gt; Newsletter</span><span class=\"t-es\">10. Marketing &gt; Boletín</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Lists everyone who subscribed to the store's newsletter (e.g. via a signup form on the storefront). This section is read-only for subscriber data &mdash; there is no manual \"add subscriber\" action; entries appear automatically as customers opt in.</span><span class=\"t-pt\">Lista todos que assinaram a newsletter da loja (ex.: por um formulário de cadastro na loja virtual). Esta seção é somente leitura quanto aos dados dos assinantes &mdash; não há uma ação manual de \"adicionar assinante\"; os registros aparecem automaticamente conforme os clientes aceitam.</span><span class=\"t-es\">Lista a todos los que se suscribieron al boletín de la tienda (ej.: mediante un formulario de registro en la tienda virtual). Esta sección es de solo lectura respecto a los datos de los suscriptores &mdash; no hay una acción manual de \"agregar suscriptor\"; los registros aparecen automáticamente a medida que los clientes aceptan.</span>\n      </p>\n      <div class=\"subsection\" id=\"newsletter-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Marketing &gt; Newsletter</span><span class=\"t-pt\">Marketing &gt; Newsletter</span><span class=\"t-es\">Marketing &gt; Boletín</span></span></h3>\n        <h3><span class=\"t-en\">Subscriber list</span><span class=\"t-pt\">Lista de assinantes</span><span class=\"t-es\">Lista de suscriptores</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Only screen of the section. Lists every newsletter subscriber, with an option to export the list.</p></span><span class=\"t-pt\"><p>Única tela da seção. Lista todos os assinantes da newsletter, com a opção de exportar a lista.</p></span><span class=\"t-es\"><p>Única pantalla de la sección. Lista todos los suscriptores del boletín, con la opción de exportar la lista.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/157-newsletter-en-newsletter-subscriber-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"newsletter subscriber list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/158-newsletter-pt-newsletter-subscriber-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"newsletter subscriber list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/159-newsletter-es-newsletter-subscriber-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"newsletter subscriber list (es)\">\n          <figcaption><span class=\"t-en\">Marketing &gt; Newsletter screen, with the search/channel filters and the (empty) subscriber table</span><span class=\"t-pt\">Tela Marketing &gt; Newsletter, com os filtros de busca/canal e a tabela de assinantes (vazia)</span><span class=\"t-es\">Pantalla Marketing &gt; Boletín, con los filtros de búsqueda/canal y la tabla de suscriptores (vacía)</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search by name or email</span><span class=\"t-pt\">Buscar por nome ou e-mail</span><span class=\"t-es\">Buscar por nombre o correo</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters the subscriber list.</span><span class=\"t-pt\">Filtra a lista de assinantes.</span><span class=\"t-es\">Filtra la lista de suscriptores.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Channel</span><span class=\"t-pt\">Canal</span><span class=\"t-es\">Canal</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters by which sales channel the subscriber signed up through.</span><span class=\"t-pt\">Filtra pelo canal de venda pelo qual o assinante se cadastrou.</span><span class=\"t-es\">Filtra por el canal de venta a través del cual se registró el suscriptor.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name / Email / Phone / Birth date / Channel</span><span class=\"t-pt\">Nome / E-mail / Telefone / Nascimento / Canal</span><span class=\"t-es\">Nombre / Correo / Teléfono / Nacimiento / Canal</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">Contact and demographic data collected at signup, plus the originating channel.</span><span class=\"t-pt\">Dados de contato e demográficos coletados no cadastro, além do canal de origem.</span><span class=\"t-es\">Datos de contacto y demográficos recopilados en el registro, además del canal de origen.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Export</span><span class=\"t-pt\">Exportar</span><span class=\"t-es\">Exportar</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Downloads the current (filtered) subscriber list as a file, for use in an external email marketing tool.</span><span class=\"t-pt\">Baixa a lista de assinantes atual (filtrada) como um arquivo, para uso em uma ferramenta externa de e-mail marketing.</span><span class=\"t-es\">Descarga la lista de suscriptores actual (filtrada) como un archivo, para usar en una herramienta externa de email marketing.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">removes a subscriber from the list.</span><span class=\"t-pt\">remove um assinante da lista.</span><span class=\"t-es\">elimina un suscriptor de la lista.</span></li>\n        </ul>\n      </div>\n\n    </section>\n\n<section class=\"doc-section\" id=\"avaliacoes\">\n      <h2><span class=\"t-en\">11. Marketing &gt; Reviews</span><span class=\"t-pt\">11. Marketing &gt; Avaliações</span><span class=\"t-es\">11. Marketing &gt; Reseñas</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Manages product reviews. Reviews can arrive automatically from storefront customers, or be added manually by an admin user &mdash; useful to seed a new product with initial social proof.</span><span class=\"t-pt\">Gerencia as avaliações de produtos. As avaliações podem chegar automaticamente de clientes da loja virtual, ou ser adicionadas manualmente por um usuário admin &mdash; útil para dar a um produto novo uma prova social inicial.</span><span class=\"t-es\">Gestiona las reseñas de productos. Las reseñas pueden llegar automáticamente de clientes de la tienda virtual, o ser agregadas manualmente por un usuario admin &mdash; útil para dar a un producto nuevo una prueba social inicial.</span>\n      </p>\n      <div class=\"subsection\" id=\"avaliacoes-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Marketing &gt; Reviews</span><span class=\"t-pt\">Marketing &gt; Avaliações</span><span class=\"t-es\">Marketing &gt; Reseñas</span></span></h3>\n        <h3><span class=\"t-en\">Review list</span><span class=\"t-pt\">Lista de avaliações</span><span class=\"t-es\">Lista de reseñas</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists every product review. Filters cover ID/title/SKU/customer name, period, rating, approval status and channel; an additional \"More filters\" panel offers only a sort order (Most recent). Each row shows the reviewed product, star rating, reviewer information, comment and approval status.</p></span><span class=\"t-pt\"><p>Lista todas as avaliações de produtos. Os filtros cobrem ID/título/SKU/nome do cliente, período, avaliação (estrelas), status de aprovação e canal; um painel adicional \"Mais filtros\" oferece apenas uma ordenação (Mais recente). Cada linha mostra o produto avaliado, a nota em estrelas, as informações do avaliador, o comentário e o status de aprovação.</p></span><span class=\"t-es\"><p>Lista todas las reseñas de productos. Los filtros cubren ID/título/SKU/nombre del cliente, período, calificación (estrellas), estado de aprobación y canal; un panel adicional \"Más filtros\" ofrece solo un orden (Más reciente). Cada fila muestra el producto reseñado, la calificación en estrellas, la información del usuario, el comentario y el estado de aprobación.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/160-avaliacoes-en-reviews-list-screen-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"reviews list screen (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/161-avaliacoes-pt-reviews-list-screen-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"reviews list screen (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/162-avaliacoes-es-reviews-list-screen-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"reviews list screen (es)\">\n          <figcaption><span class=\"t-en\">Marketing &gt; Reviews screen, with the search/rating/approval/channel filters and the (empty) review table</span><span class=\"t-pt\">Tela Marketing &gt; Avaliações, com os filtros de busca/avaliação/aprovação/canal e a tabela de avaliações (vazia)</span><span class=\"t-es\">Pantalla Marketing &gt; Reseñas, con los filtros de búsqueda/calificación/aprobación/canal y la tabla de reseñas (vacía)</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">#ID, title, ##SKU or customer name</span><span class=\"t-pt\">#ID, título, ##SKU ou nome do cliente</span><span class=\"t-es\">#ID, título, ##SKU o nombre del cliente</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Searches reviews by order/product ID, title, SKU (prefixed with ##) or the reviewing customer's name.</span><span class=\"t-pt\">Busca avaliações por ID do pedido/produto, título, SKU (prefixado com ##) ou pelo nome do cliente que avaliou.</span><span class=\"t-es\">Busca reseñas por ID de pedido/producto, título, SKU (con prefijo ##) o por el nombre del cliente que reseñó.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Period / Rating / Approval / Channel</span><span class=\"t-pt\">Período / Avaliação / Aprovação / Canal</span><span class=\"t-es\">Período / Calificación / Aprobación / Canal</span></td><td class=\"field-type\"><span class=\"t-en\">Filters</span><span class=\"t-pt\">Filtros</span><span class=\"t-es\">Filtros</span></td><td class=\"field-desc\"><span class=\"t-en\">Narrow the list by date range, star rating, approval status (Approved/Not approved) or sales channel.</span><span class=\"t-pt\">Restringem a lista por período de datas, avaliação em estrelas, status de aprovação (Aprovada/Não aprovada) ou canal de venda.</span><span class=\"t-es\">Acotan la lista por rango de fechas, calificación en estrellas, estado de aprobación (Aprobada/No aprobada) o canal de venta.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">More filters</span><span class=\"t-pt\">Mais filtros</span><span class=\"t-es\">Más filtros</span></td><td class=\"field-type\"><span class=\"t-en\">Panel</span><span class=\"t-pt\">Painel</span><span class=\"t-es\">Panel</span></td><td class=\"field-desc\"><span class=\"t-en\">Opens a side panel with a single extra option: sort order (Most recent).</span><span class=\"t-pt\">Abre um painel lateral com uma única opção extra: ordenação (Mais recente).</span><span class=\"t-es\">Abre un panel lateral con una única opción extra: orden (Más reciente).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">ID / Product / Rating / Information / Comment / Status</span><span class=\"t-pt\">ID / Produto / Avaliação / Informações / Comentário / Status</span><span class=\"t-es\">ID / Producto / Calificación / Información / Comentario / Estado</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">The reviewed product, the star rating given, reviewer details, the written comment and whether the review is currently approved.</span><span class=\"t-pt\">O produto avaliado, a nota em estrelas dada, os dados do avaliador, o comentário escrito e se a avaliação está aprovada no momento.</span><span class=\"t-es\">El producto reseñado, la calificación en estrellas otorgada, los datos del usuario, el comentario escrito y si la reseña está aprobada actualmente.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the review to change its rating, status or comment.</span><span class=\"t-pt\">abre a avaliação para alterar a nota, o status ou o comentário.</span><span class=\"t-es\">abre la reseña para cambiar la calificación, el estado o el comentario.</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">removes the review permanently.</span><span class=\"t-pt\">remove a avaliação permanentemente.</span><span class=\"t-es\">elimina la reseña permanentemente.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"avaliacoes-criar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Marketing &gt; Reviews</span><span class=\"t-pt\">Marketing &gt; Avaliações</span><span class=\"t-es\">Marketing &gt; Reseñas</span></span></h3>\n        <h3><span class=\"t-en\">Add manual review</span><span class=\"t-pt\">Adicionar avaliação manual</span><span class=\"t-es\">Agregar reseña manual</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The \"Add manual review\" button opens a modal for an admin to create a review directly, without waiting for a customer submission &mdash; useful to seed a new product listing with initial reviews.</p></span><span class=\"t-pt\"><p>O botão \"Adicionar avaliação manual\" abre um modal para um admin criar uma avaliação diretamente, sem esperar o envio de um cliente &mdash; útil para dar a um produto novo avaliações iniciais.</p></span><span class=\"t-es\"><p>El botón \"Agregar reseña manual\" abre un modal para que un admin cree una reseña directamente, sin esperar el envío de un cliente &mdash; útil para dar a un producto nuevo reseñas iniciales.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/163-avaliacoes-en-add-manual-review-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add manual review modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/164-avaliacoes-pt-add-manual-review-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add manual review modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/165-avaliacoes-es-add-manual-review-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add manual review modal (es)\">\n          <figcaption><span class=\"t-en\">\"Add manual review\" modal, with the review status dropdown open (Approved / Not approved)</span><span class=\"t-pt\">Modal \"Adicionar avaliação manual\", com o dropdown de status da avaliação aberto (Aprovada / Não aprovada)</span><span class=\"t-es\">Modal \"Agregar reseña manual\", con el menú desplegable de estado de la reseña abierto (Aprobada / No aprobada)</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Products</span><span class=\"t-pt\">Produtos</span><span class=\"t-es\">Productos</span></td><td class=\"field-type\"><span class=\"t-en\">Selector</span><span class=\"t-pt\">Seletor</span><span class=\"t-es\">Selector</span></td><td class=\"field-desc\"><span class=\"t-en\">\"Select products\" opens a picker to choose which product(s) the review applies to.</span><span class=\"t-pt\">\"Selecionar produtos\" abre um seletor para escolher a quais produtos a avaliação se aplica.</span><span class=\"t-es\">\"Seleccionar productos\" abre un selector para elegir a qué productos se aplica la reseña.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Channel</span><span class=\"t-pt\">Canal</span><span class=\"t-es\">Canal</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">The sales channel the review is attributed to.</span><span class=\"t-pt\">O canal de venda ao qual a avaliação é atribuída.</span><span class=\"t-es\">El canal de venta al que se atribuye la reseña.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Rating</span><span class=\"t-pt\">Avaliação</span><span class=\"t-es\">Calificación</span></td><td class=\"field-type\"><span class=\"t-en\">5-star widget</span><span class=\"t-pt\">Widget de 5 estrelas</span><span class=\"t-es\">Widget de 5 estrellas</span></td><td class=\"field-desc\"><span class=\"t-en\">Click a star to set the review's rating from 1 to 5.</span><span class=\"t-pt\">Clique em uma estrela para definir a nota da avaliação de 1 a 5.</span><span class=\"t-es\">Haga clic en una estrella para definir la calificación de la reseña de 1 a 5.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Review status</span><span class=\"t-pt\">Status da avaliação</span><span class=\"t-es\">Estado de la reseña</span></td><td class=\"field-type\"><span class=\"t-en\">Dropdown</span><span class=\"t-pt\">Dropdown</span><span class=\"t-es\">Menú desplegable</span></td><td class=\"field-desc\"><span class=\"t-en\">Approved / Not approved &mdash; controls whether the review is publicly visible on the storefront.</span><span class=\"t-pt\">Aprovada / Não aprovada &mdash; controla se a avaliação fica visível publicamente na loja virtual.</span><span class=\"t-es\">Aprobada / No aprobada &mdash; controla si la reseña queda visible públicamente en la tienda virtual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">User</span><span class=\"t-pt\">Usuário</span><span class=\"t-es\">Usuario</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Type #id, name or email to attribute the review to an existing customer.</span><span class=\"t-pt\">Digite #id, nome ou e-mail para atribuir a avaliação a um cliente existente.</span><span class=\"t-es\">Escriba #id, nombre o correo para atribuir la reseña a un cliente existente.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Comment</span><span class=\"t-pt\">Comentário</span><span class=\"t-es\">Comentario</span></td><td class=\"field-type\"><span class=\"t-en\">Textarea</span><span class=\"t-pt\">Textarea</span><span class=\"t-es\">Textarea</span></td><td class=\"field-desc\"><span class=\"t-en\">The written review text.</span><span class=\"t-pt\">O texto escrito da avaliação.</span><span class=\"t-es\">El texto escrito de la reseña.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=clientes\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Customers and users</span><span class=\"t-pt\">Clientes e usuários</span><span class=\"t-es\">Clientes y usuarios</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=gestao\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Management</span><span class=\"t-pt\">Gestão</span><span class=\"t-es\">Gestión</span></strong></a>\n</nav>\n", "gestao": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Management</span><span class=\"t-pt\">Gestão</span><span class=\"t-es\">Gestión</span></p>\n<section class=\"doc-section\" id=\"carteira\">\n      <h2><span class=\"t-en\">12. Management &gt; Wallet</span><span class=\"t-pt\">12. Gestão &gt; Carteira</span><span class=\"t-es\">12. Gestión &gt; Cartera</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Manages store credit balances applied to customers. This is a store-wide view of every credit/debit entry &mdash; the same underlying wallet shown per-customer under Customers and users &gt; customer detail &gt; Wallet.</span><span class=\"t-pt\">Gerencia os saldos de crédito de loja aplicados aos clientes. Esta é uma visão da loja inteira de todo lançamento de crédito/débito &mdash; a mesma carteira exibida por cliente em Clientes e usuários &gt; detalhe do cliente &gt; Carteira.</span><span class=\"t-es\">Gestiona los saldos de crédito de tienda aplicados a los clientes. Esta es una vista de toda la tienda de cada registro de crédito/débito &mdash; la misma cartera que se muestra por cliente en Clientes y usuarios &gt; detalle del cliente &gt; Cartera.</span>\n      </p>\n      <div class=\"subsection\" id=\"carteira-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Management &gt; Wallet</span><span class=\"t-pt\">Gestão &gt; Carteira</span><span class=\"t-es\">Gestión &gt; Cartera</span></span></h3>\n        <h3><span class=\"t-en\">Wallet list</span><span class=\"t-pt\">Lista da carteira</span><span class=\"t-es\">Lista de la cartera</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists every store-credit transaction across all customers: search by description, by customer #ID/name, by order ID, transfer status, type (credit/debit) and currency. An additional \"More filters\" panel adds a date filter and a sort order. Totals for Credit, Debit and Total balance are shown at the bottom of the table.</p></span><span class=\"t-pt\"><p>Lista todo lançamento de crédito de loja de todos os clientes: busca por descrição, por #ID/nome do cliente, por ID do pedido, status de repasse, tipo (crédito/débito) e moeda. Um painel adicional \"Mais filtros\" acrescenta um filtro de data e uma ordenação. Os totais de Crédito, Débito e Total do saldo aparecem no rodapé da tabela.</p></span><span class=\"t-es\"><p>Lista cada registro de crédito de tienda de todos los clientes: búsqueda por descripción, por #ID/nombre del cliente, por ID de pedido, estado de transferencia, tipo (crédito/débito) y moneda. Un panel adicional \"Más filtros\" agrega un filtro de fecha y un orden. Los totales de Crédito, Débito y Total del saldo aparecen al pie de la tabla.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/166-carteira-en-wallet-list-screen-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"wallet list screen (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/167-carteira-pt-wallet-list-screen-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"wallet list screen (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/168-carteira-es-wallet-list-screen-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"wallet list screen (es)\">\n          <figcaption><span class=\"t-en\">Management &gt; Wallet screen, with the search/status/type/currency filters and the (empty) transaction table</span><span class=\"t-pt\">Tela Gestão &gt; Carteira, com os filtros de busca/status/tipo/moeda e a tabela de lançamentos (vazia)</span><span class=\"t-es\">Pantalla Gestión &gt; Cartera, con los filtros de búsqueda/estado/tipo/moneda y la tabla de registros (vacía)</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search by description</span><span class=\"t-pt\">Buscar por descrição</span><span class=\"t-es\">Buscar por descripción</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters entries by their description text.</span><span class=\"t-pt\">Filtra os lançamentos pelo texto da descrição.</span><span class=\"t-es\">Filtra los registros por el texto de la descripción.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">#ID or user name</span><span class=\"t-pt\">#ID ou nome do usuário</span><span class=\"t-es\">#ID o nombre de usuario</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters entries belonging to a specific customer.</span><span class=\"t-pt\">Filtra lançamentos pertencentes a um cliente específico.</span><span class=\"t-es\">Filtra registros pertenecientes a un cliente específico.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Order ID / Transfer status / Type / Currency</span><span class=\"t-pt\">ID Pedido / Status repasse / Tipo / Moeda</span><span class=\"t-es\">ID de pedido / Estado de transferencia / Tipo / Moneda</span></td><td class=\"field-type\"><span class=\"t-en\">Filters</span><span class=\"t-pt\">Filtros</span><span class=\"t-es\">Filtros</span></td><td class=\"field-desc\"><span class=\"t-en\">Narrow the list by the related order, its payout/transfer status, credit vs. debit, or currency.</span><span class=\"t-pt\">Restringem a lista pelo pedido relacionado, seu status de repasse, crédito vs. débito, ou moeda.</span><span class=\"t-es\">Acotan la lista por el pedido relacionado, su estado de transferencia, crédito vs. débito, o moneda.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Currency / Value / Type / Status / Date / Description / User / Order</span><span class=\"t-pt\">Moeda / Valor / Tipo / Status / Data / Descrição / Usuário / Pedido</span><span class=\"t-es\">Moneda / Valor / Tipo / Estado / Fecha / Descripción / Usuario / Pedido</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">Full detail of each wallet transaction, including which customer and (if applicable) which order it relates to.</span><span class=\"t-pt\">Detalhe completo de cada lançamento da carteira, incluindo a qual cliente e (se aplicável) a qual pedido ele se refere.</span><span class=\"t-es\">Detalle completo de cada registro de la cartera, incluyendo a qué cliente y (si corresponde) a qué pedido se refiere.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Credit / Debit / Total</span><span class=\"t-pt\">Crédito / Débito / Total</span><span class=\"t-es\">Crédito / Débito / Total</span></td><td class=\"field-type\"><span class=\"t-en\">Footer totals</span><span class=\"t-pt\">Totais no rodapé</span><span class=\"t-es\">Totales en el pie</span></td><td class=\"field-desc\"><span class=\"t-en\">Running sums for the currently filtered list.</span><span class=\"t-pt\">Somas para a lista filtrada no momento.</span><span class=\"t-es\">Sumas para la lista actualmente filtrada.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"carteira-gerenciar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Management &gt; Wallet</span><span class=\"t-pt\">Gestão &gt; Carteira</span><span class=\"t-es\">Gestión &gt; Cartera</span></span></h3>\n        <h3><span class=\"t-en\">Manage wallet</span><span class=\"t-pt\">Gerenciar carteira</span><span class=\"t-es\">Administrar cartera</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The \"Manage wallet\" button opens a modal to credit or debit store balance in bulk, applying it either to individually selected customers or to entire customer groups at once.</p></span><span class=\"t-pt\"><p>O botão \"Gerenciar carteira\" abre um modal para creditar ou debitar saldo de loja em lote, aplicando-o a clientes selecionados individualmente ou a grupos de clientes inteiros de uma vez.</p></span><span class=\"t-es\"><p>El botón \"Administrar cartera\" abre un modal para acreditar o debitar saldo de tienda en lote, aplicándolo a clientes seleccionados individualmente o a grupos de clientes completos a la vez.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/169-carteira-en-manage-wallet-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manage wallet modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/170-carteira-pt-manage-wallet-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manage wallet modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/171-carteira-es-manage-wallet-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manage wallet modal (es)\">\n          <figcaption><span class=\"t-en\">\"Manage wallet\" modal, with \"Apply to\" set to Customer groups</span><span class=\"t-pt\">Modal \"Gerenciar carteira\", com \"Aplicar em\" definido como Grupos de clientes</span><span class=\"t-es\">Modal \"Administrar cartera\", con \"Aplicar a\" definido como Grupos de clientes</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Credit adds to the customer's balance; Debit subtracts from it.</span><span class=\"t-pt\">Crédito soma ao saldo do cliente; Débito subtrai dele.</span><span class=\"t-es\">Crédito suma al saldo del cliente; Débito lo resta.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Apply to</span><span class=\"t-pt\">Aplicar em</span><span class=\"t-es\">Aplicar a</span></td><td class=\"field-type\"><span class=\"t-en\">Radio buttons</span><span class=\"t-pt\">Botões de opção</span><span class=\"t-es\">Botones de opción</span></td><td class=\"field-desc\"><span class=\"t-en\">Selected customers (pick individual customers by #ID/name) or Customer groups (apply to every customer in one or more groups at once).</span><span class=\"t-pt\">Clientes selecionados (escolhe clientes individuais por #ID/nome) ou Grupos de clientes (aplica a todos os clientes de um ou mais grupos de uma vez).</span><span class=\"t-es\">Clientes seleccionados (elige clientes individuales por #ID/nombre) o Grupos de clientes (aplica a todos los clientes de uno o más grupos a la vez).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Users / Customer groups</span><span class=\"t-pt\">Usuários / Grupos de clientes</span><span class=\"t-es\">Usuarios / Grupos de clientes</span></td><td class=\"field-type\"><span class=\"t-en\">Selector</span><span class=\"t-pt\">Seletor</span><span class=\"t-es\">Selector</span></td><td class=\"field-desc\"><span class=\"t-en\">Which field appears depends on the \"Apply to\" choice above.</span><span class=\"t-pt\">Qual campo aparece depende da escolha de \"Aplicar em\" acima.</span><span class=\"t-es\">Qué campo aparece depende de la elección de \"Aplicar a\" arriba.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Currency / Value</span><span class=\"t-pt\">Moeda / Valor</span><span class=\"t-es\">Moneda / Valor</span></td><td class=\"field-type\"><span class=\"t-en\">Select / Number</span><span class=\"t-pt\">Seleção / Número</span><span class=\"t-es\">Selección / Número</span></td><td class=\"field-desc\"><span class=\"t-en\">The currency and amount of the credit or debit.</span><span class=\"t-pt\">A moeda e o valor do crédito ou débito.</span><span class=\"t-es\">La moneda y el monto del crédito o débito.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Description</span><span class=\"t-pt\">Descrição</span><span class=\"t-es\">Descripción</span></td><td class=\"field-type\"><span class=\"t-en\">Textarea</span><span class=\"t-pt\">Textarea</span><span class=\"t-es\">Textarea</span></td><td class=\"field-desc\"><span class=\"t-en\">A note explaining the reason for the entry, shown later in the wallet list.</span><span class=\"t-pt\">Uma nota explicando o motivo do lançamento, exibida depois na lista da carteira.</span><span class=\"t-es\">Una nota que explica el motivo del registro, mostrada luego en la lista de la cartera.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n\n    </section>\n\n<section class=\"doc-section\" id=\"movimentacoes\">\n      <h2><span class=\"t-en\">13. Management &gt; Movimentations</span><span class=\"t-pt\">13. Gestão &gt; Movimentações</span><span class=\"t-es\">13. Gestión &gt; Movimientos</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">A financial ledger of every revenue and expense entry generated by the store, in the currency of each transaction. Most entries are created automatically from orders (product cost, shipping cost, order total); additional entries can be added manually to record other income or expenses.</span><span class=\"t-pt\">Um livro-caixa de todo lançamento de receita e despesa gerado pela loja, na moeda de cada transação. A maioria dos lançamentos é criada automaticamente a partir de pedidos (custo do produto, custo do frete, total do pedido); lançamentos adicionais podem ser adicionados manualmente para registrar outras receitas ou despesas.</span><span class=\"t-es\">Un libro contable de cada registro de ingreso y gasto generado por la tienda, en la moneda de cada transacción. La mayoría de los registros se crean automáticamente a partir de pedidos (costo del producto, costo del envío, total del pedido); se pueden añadir registros adicionales manualmente para registrar otros ingresos o gastos.</span>\n      </p>\n      <div class=\"subsection\" id=\"movimentacoes-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Management &gt; Movimentations</span><span class=\"t-pt\">Gestão &gt; Movimentações</span><span class=\"t-es\">Gestión &gt; Movimientos</span></span></h3>\n        <h3><span class=\"t-en\">Movimentation list</span><span class=\"t-pt\">Lista de movimentações</span><span class=\"t-es\">Lista de movimientos</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists every financial entry: search by description, order or amount; filter by situation, sales channel or category. An additional \"More filters\" panel adds a date filter and a sort order. Each row shows the value (in green for revenue, red for expense), its category/name, the related order (if any), a description, channel and date. Totals for Revenue, Expense and net Total appear at the bottom of the table.</p></span><span class=\"t-pt\"><p>Lista todo lançamento financeiro: busca por descrição, pedido ou valor; filtra por situação, canal de venda ou categoria. Um painel adicional \"Mais filtros\" acrescenta um filtro de data e uma ordenação. Cada linha mostra o valor (em verde para receita, vermelho para despesa), sua categoria/nome, o pedido relacionado (se houver), uma descrição, canal e data. Os totais de Receita, Despesa e Total líquido aparecem no rodapé da tabela.</p></span><span class=\"t-es\"><p>Lista cada registro financiero: búsqueda por descripción, pedido o valor; filtra por situación, canal de venta o categoría. Un panel adicional \"Más filtros\" agrega un filtro de fecha y un orden. Cada fila muestra el valor (en verde para ingreso, rojo para gasto), su categoría/nombre, el pedido relacionado (si lo hay), una descripción, canal y fecha. Los totales de Ingreso, Gasto y Total neto aparecen al pie de la tabla.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/172-movimentacoes-en-movimentations-list-screen-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"movimentations list screen (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/173-movimentacoes-pt-movimentations-list-screen-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"movimentations list screen (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/174-movimentacoes-es-movimentations-list-screen-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"movimentations list screen (es)\">\n          <figcaption><span class=\"t-en\">Management &gt; Movimentations screen, populated with the ledger entries auto-generated from recent orders</span><span class=\"t-pt\">Tela Gestão &gt; Movimentações, preenchida com os lançamentos gerados automaticamente a partir de pedidos recentes</span><span class=\"t-es\">Pantalla Gestión &gt; Movimientos, con los registros generados automáticamente a partir de pedidos recientes</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Description, order or amount</span><span class=\"t-pt\">Descrição, pedido ou valor</span><span class=\"t-es\">Descripción, pedido o valor</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Searches entries by any of these three fields at once.</span><span class=\"t-pt\">Busca lançamentos por qualquer um desses três campos ao mesmo tempo.</span><span class=\"t-es\">Busca registros por cualquiera de estos tres campos a la vez.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Situation / Channel / Category</span><span class=\"t-pt\">Situação / Canal / Categoria</span><span class=\"t-es\">Situación / Canal / Categoría</span></td><td class=\"field-type\"><span class=\"t-en\">Filters</span><span class=\"t-pt\">Filtros</span><span class=\"t-es\">Filtros</span></td><td class=\"field-desc\"><span class=\"t-en\">Narrow the list by entry status, sales channel, or the movement category (e.g. product cost, shipping cost, discount).</span><span class=\"t-pt\">Restringem a lista pelo status do lançamento, canal de venda, ou a categoria do movimento (ex.: custo do produto, custo do frete, desconto).</span><span class=\"t-es\">Acotan la lista por el estado del registro, canal de venta, o la categoría del movimiento (ej.: costo del producto, costo del envío, descuento).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Value / Category / Order / Description / Channel / Date</span><span class=\"t-pt\">Valor / Categoria / Pedido / Descrição / Canal / Data</span><span class=\"t-es\">Valor / Categoría / Pedido / Descripción / Canal / Fecha</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">Full detail of each ledger entry; clicking the order number opens that order.</span><span class=\"t-pt\">Detalhe completo de cada lançamento; clicar no número do pedido abre esse pedido.</span><span class=\"t-es\">Detalle completo de cada registro; hacer clic en el número de pedido abre ese pedido.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Revenue / Expense / Total</span><span class=\"t-pt\">Receita / Despesa / Total</span><span class=\"t-es\">Ingreso / Gasto / Total</span></td><td class=\"field-type\"><span class=\"t-en\">Footer totals</span><span class=\"t-pt\">Totais no rodapé</span><span class=\"t-es\">Totales en el pie</span></td><td class=\"field-desc\"><span class=\"t-en\">Running sums for the currently filtered list.</span><span class=\"t-pt\">Somas para a lista filtrada no momento.</span><span class=\"t-es\">Sumas para la lista actualmente filtrada.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"movimentacoes-adicionar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Management &gt; Movimentations</span><span class=\"t-pt\">Gestão &gt; Movimentações</span><span class=\"t-es\">Gestión &gt; Movimientos</span></span></h3>\n        <h3><span class=\"t-en\">Add movimentation</span><span class=\"t-pt\">Adicionar movimentação</span><span class=\"t-es\">Añadir movimiento</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The \"Add\" button opens a simple modal to register a manual revenue or expense entry that did not originate from an order (e.g. a one-off cost or income). Movement category names are defined by the store and are not translated by the language switcher.</p></span><span class=\"t-pt\"><p>O botão \"Adicionar\" abre um modal simples para registrar manualmente um lançamento de receita ou despesa que não teve origem em um pedido (ex.: um custo ou receita avulsa). Os nomes das categorias de movimentação são definidos pela loja e não são traduzidos pelo seletor de idioma.</p></span><span class=\"t-es\"><p>El botón \"Añadir\" abre un modal simple para registrar manualmente un registro de ingreso o gasto que no se originó en un pedido (ej.: un costo o ingreso puntual). Los nombres de las categorías de movimiento son definidos por la tienda y no se traducen con el selector de idioma.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/175-movimentacoes-en-add-movimentation-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add movimentation modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/176-movimentacoes-pt-add-movimentation-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add movimentation modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/177-movimentacoes-es-add-movimentation-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add movimentation modal (es)\">\n          <figcaption><span class=\"t-en\">\"Add\" modal, with the movement category dropdown open</span><span class=\"t-pt\">Modal \"Adicionar\", com o dropdown de categoria da movimentação aberto</span><span class=\"t-es\">Modal \"Añadir\", con el menú desplegable de categoría del movimiento abierto</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Movement category</span><span class=\"t-pt\">Categoria da movimentação</span><span class=\"t-es\">Categoría del movimiento</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">The type of entry, e.g. product cost, shipping cost, discount, uncategorized revenue/expense.</span><span class=\"t-pt\">O tipo de lançamento, ex.: custo do produto, custo do frete, desconto, receita/despesa sem categoria.</span><span class=\"t-es\">El tipo de registro, ej.: costo del producto, costo del envío, descuento, ingreso/gasto sin categoría.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Value</span><span class=\"t-pt\">Valor</span><span class=\"t-es\">Valor</span></td><td class=\"field-type\"><span class=\"t-en\">Number</span><span class=\"t-pt\">Número</span><span class=\"t-es\">Número</span></td><td class=\"field-desc\"><span class=\"t-en\">The monetary amount of the entry.</span><span class=\"t-pt\">O valor monetário do lançamento.</span><span class=\"t-es\">El monto monetario del registro.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Description</span><span class=\"t-pt\">Descrição</span><span class=\"t-es\">Descripción</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">A short note describing the entry.</span><span class=\"t-pt\">Uma nota curta descrevendo o lançamento.</span><span class=\"t-es\">Una nota breve que describe el registro.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Channel</span><span class=\"t-pt\">Canal</span><span class=\"t-es\">Canal</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">The sales channel the entry is attributed to.</span><span class=\"t-pt\">O canal de venda ao qual o lançamento é atribuído.</span><span class=\"t-es\">El canal de venta al que se atribuye el registro.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Date</span><span class=\"t-pt\">Data</span><span class=\"t-es\">Fecha</span></td><td class=\"field-type\"><span class=\"t-en\">Date picker</span><span class=\"t-pt\">Seletor de data</span><span class=\"t-es\">Selector de fecha</span></td><td class=\"field-desc\"><span class=\"t-en\">The date the entry took effect.</span><span class=\"t-pt\">A data em que o lançamento ocorreu.</span><span class=\"t-es\">La fecha en que ocurrió el registro.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n\n    </section>\n\n<section class=\"doc-section\" id=\"relatorios\">\n      <h2><span class=\"t-en\">14. Management &gt; Reports</span><span class=\"t-pt\">14. Gestão &gt; Relatórios</span><span class=\"t-es\">14. Gestión &gt; Informes</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">A generic report builder covering nine data sets: Stock, Movements, Product movements, Orders, Suborders, Sales, Sales by product, Wallet and Products. Each report type has its own filters and columns; results can be printed or exported to CSV, and a filter configuration can be saved for reuse.</span><span class=\"t-pt\">Um construtor genérico de relatórios cobrindo nove conjuntos de dados: Estoques, Movimentações, Movimentações de produto, Pedidos, Subpedidos, Vendas, Vendas por produto, Carteira e Produtos. Cada tipo de relatório tem seus próprios filtros e colunas; os resultados podem ser impressos ou exportados em CSV, e uma configuração de filtros pode ser salva para reutilização.</span><span class=\"t-es\">Un generador genérico de informes que cubre nueve conjuntos de datos: Inventario, Movimientos, Movimientos de producto, Pedidos, Subpedidos, Ventas, Ventas por producto, Cartera y Productos. Cada tipo de informe tiene sus propios filtros y columnas; los resultados se pueden imprimir o exportar a CSV, y una configuración de filtros se puede guardar para reutilizarla.</span>\n      </p>\n      <div class=\"subsection\" id=\"relatorios-gerar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Management &gt; Reports</span><span class=\"t-pt\">Gestão &gt; Relatórios</span><span class=\"t-es\">Gestión &gt; Informes</span></span></h3>\n        <h3><span class=\"t-en\">Generate report</span><span class=\"t-pt\">Gerar relatório</span><span class=\"t-es\">Generar informe</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The \"Report type\" dropdown selects which of the nine data sets to view (Stock, Movements, Product movements, Orders, Suborders, Sales, Sales by product, Wallet, Products). Changing the type replaces the filters and table columns below it with ones specific to that data set &mdash; for example, the Stock report shown here has Product/SKU/title, category and price-table-status filters, while Sales instead offers order/customer search, date, status, payment status and channel. \"Print\" sends the current results to the browser's print dialog, and \"Export CSV\" downloads them as a file.</p></span><span class=\"t-pt\"><p>O dropdown \"Tipo de relatório\" seleciona qual dos nove conjuntos de dados visualizar (Estoques, Movimentações, Movimentações de produto, Pedidos, Subpedidos, Vendas, Vendas por produto, Carteira, Produtos). Trocar o tipo substitui os filtros e as colunas da tabela abaixo por outros específicos daquele conjunto de dados &mdash; por exemplo, o relatório de Estoques mostrado aqui tem filtros de Produto/SKU/título, categoria e status da tabela de preço, enquanto Vendas oferece busca por pedido/cliente, data, status, status de pagamento e canal. \"Imprimir\" envia os resultados atuais para a caixa de diálogo de impressão do navegador, e \"Exportar CSV\" os baixa como um arquivo.</p></span><span class=\"t-es\"><p>El menú desplegable \"Tipo de informe\" selecciona cuál de los nueve conjuntos de datos visualizar (Inventario, Movimientos, Movimientos de producto, Pedidos, Subpedidos, Ventas, Ventas por producto, Cartera, Productos). Cambiar el tipo reemplaza los filtros y las columnas de la tabla de abajo por otros específicos de ese conjunto de datos &mdash; por ejemplo, el informe de Inventario mostrado aquí tiene filtros de Producto/SKU/título, categoría y estado de la tabla de precios, mientras que Ventas ofrece búsqueda por pedido/cliente, fecha, estado, estado de pago y canal. \"Imprimir\" envía los resultados actuales al cuadro de diálogo de impresión del navegador, y \"Exportar CSV\" los descarga como un archivo.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/178-relatorios-en-report-type-dropdown-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"report type dropdown (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/179-relatorios-pt-report-type-dropdown-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"report type dropdown (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/180-relatorios-es-report-type-dropdown-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"report type dropdown (es)\">\n          <figcaption><span class=\"t-en\">The \"Report type\" dropdown, listing all nine available data sets</span><span class=\"t-pt\">O dropdown \"Tipo de relatório\", listando os nove conjuntos de dados disponíveis</span><span class=\"t-es\">El menú desplegable \"Tipo de informe\", con los nueve conjuntos de datos disponibles</span></figcaption>\n        </div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/181-relatorios-en-stock-report-results-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stock report results (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/182-relatorios-pt-stock-report-results-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stock report results (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/183-relatorios-es-stock-report-results-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stock report results (es)\">\n          <figcaption><span class=\"t-en\">Results for the Stock report type, with its specific filters and columns</span><span class=\"t-pt\">Resultados do tipo de relatório Estoques, com seus filtros e colunas específicos</span><span class=\"t-es\">Resultados del tipo de informe Inventario, con sus filtros y columnas específicos</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Report type</span><span class=\"t-pt\">Tipo de relatório</span><span class=\"t-es\">Tipo de informe</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Chooses the data set: Stock, Movements, Product movements, Orders, Suborders, Sales, Sales by product, Wallet or Products.</span><span class=\"t-pt\">Escolhe o conjunto de dados: Estoques, Movimentações, Movimentações de produto, Pedidos, Subpedidos, Vendas, Vendas por produto, Carteira ou Produtos.</span><span class=\"t-es\">Elige el conjunto de datos: Inventario, Movimientos, Movimientos de producto, Pedidos, Subpedidos, Ventas, Ventas por producto, Cartera o Productos.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Filters row(s)</span><span class=\"t-pt\">Linha(s) de filtros</span><span class=\"t-es\">Fila(s) de filtros</span></td><td class=\"field-type\"><span class=\"t-en\">Varies by type</span><span class=\"t-pt\">Varia por tipo</span><span class=\"t-es\">Varía por tipo</span></td><td class=\"field-desc\"><span class=\"t-en\">Search and filter fields specific to the selected report type; an additional \"More filters\" panel may add further options.</span><span class=\"t-pt\">Campos de busca e filtro específicos do tipo de relatório selecionado; um painel adicional \"Mais filtros\" pode acrescentar mais opções.</span><span class=\"t-es\">Campos de búsqueda y filtro específicos del tipo de informe seleccionado; un panel adicional \"Más filtros\" puede agregar más opciones.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Table columns</span><span class=\"t-pt\">Colunas da tabela</span><span class=\"t-es\">Columnas de la tabla</span></td><td class=\"field-type\"><span class=\"t-en\">Varies by type</span><span class=\"t-pt\">Varia por tipo</span><span class=\"t-es\">Varía por tipo</span></td><td class=\"field-desc\"><span class=\"t-en\">Change to match the selected report type &mdash; e.g. stock/cost/price columns for Stock, or gross total/profit columns for Sales.</span><span class=\"t-pt\">Mudam de acordo com o tipo de relatório selecionado &mdash; ex.: colunas de estoque/custo/preço para Estoques, ou total bruto/lucro para Vendas.</span><span class=\"t-es\">Cambian según el tipo de informe seleccionado &mdash; ej.: columnas de existencias/costo/precio para Inventario, o total bruto/ganancia para Ventas.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Print</span><span class=\"t-pt\">Imprimir</span><span class=\"t-es\">Imprimir</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Opens the browser's print dialog with the current report results.</span><span class=\"t-pt\">Abre a caixa de diálogo de impressão do navegador com os resultados atuais do relatório.</span><span class=\"t-es\">Abre el cuadro de diálogo de impresión del navegador con los resultados actuales del informe.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Export CSV</span><span class=\"t-pt\">Exportar CSV</span><span class=\"t-es\">Exportar CSV</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Downloads the current (filtered) report results as a CSV file.</span><span class=\"t-pt\">Baixa os resultados atuais (filtrados) do relatório como um arquivo CSV.</span><span class=\"t-es\">Descarga los resultados actuales (filtrados) del informe como un archivo CSV.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"relatorios-salvos\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Management &gt; Reports</span><span class=\"t-pt\">Gestão &gt; Relatórios</span><span class=\"t-es\">Gestión &gt; Informes</span></span></h3>\n        <h3><span class=\"t-en\">Saved reports</span><span class=\"t-pt\">Relatórios salvos</span><span class=\"t-es\">Informes guardados</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The \"Saved\" tab lists report filter configurations that were previously saved by name, so a frequently used combination of filters can be reopened later without re-entering it. Entries can be searched by name, date or report type.</p></span><span class=\"t-pt\"><p>A aba \"Salvos\" lista configurações de filtros de relatório salvas anteriormente por nome, para que uma combinação de filtros usada com frequência possa ser reaberta depois sem a necessidade de reinseri-la. Os registros podem ser buscados por nome, data ou tipo de relatório.</p></span><span class=\"t-es\"><p>La pestaña \"Guardados\" lista configuraciones de filtros de informe guardadas previamente por nombre, para que una combinación de filtros usada con frecuencia pueda reabrirse después sin volver a introducirla. Los registros se pueden buscar por nombre, fecha o tipo de informe.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/184-relatorios-en-saved-reports-screen-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"saved reports screen (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/185-relatorios-pt-saved-reports-screen-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"saved reports screen (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/186-relatorios-es-saved-reports-screen-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"saved reports screen (es)\">\n          <figcaption><span class=\"t-en\">\"Saved\" tab, filtered by report type (Sales in this example) and showing no saved reports yet</span><span class=\"t-pt\">Aba \"Salvos\", filtrada por tipo de relatório (Vendas neste exemplo) e sem relatórios salvos até o momento</span><span class=\"t-es\">Pestaña \"Guardados\", filtrada por tipo de informe (Ventas en este ejemplo) y sin informes guardados por el momento</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search by name</span><span class=\"t-pt\">Buscar por nome</span><span class=\"t-es\">Buscar por nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Filters saved configurations by the name they were given.</span><span class=\"t-pt\">Filtra as configurações salvas pelo nome dado a elas.</span><span class=\"t-es\">Filtra las configuraciones guardadas por el nombre que se les dio.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Date / Type</span><span class=\"t-pt\">Data / Tipo</span><span class=\"t-es\">Fecha / Tipo</span></td><td class=\"field-type\"><span class=\"t-en\">Filters</span><span class=\"t-pt\">Filtros</span><span class=\"t-es\">Filtros</span></td><td class=\"field-desc\"><span class=\"t-en\">Narrow the list by the date saved or by report type.</span><span class=\"t-pt\">Restringem a lista pela data em que foi salva ou pelo tipo de relatório.</span><span class=\"t-es\">Acotan la lista por la fecha en que se guardó o por el tipo de informe.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name / Type / Date</span><span class=\"t-pt\">Nome / Tipo / Data</span><span class=\"t-es\">Nombre / Tipo / Fecha</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">The saved configuration's name, which report type it applies to, and when it was saved.</span><span class=\"t-pt\">O nome da configuração salva, a qual tipo de relatório ela se aplica e quando foi salva.</span><span class=\"t-es\">El nombre de la configuración guardada, a qué tipo de informe se aplica y cuándo se guardó.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Open</span><span class=\"t-pt\">Abrir</span><span class=\"t-es\">Abrir</span></b> &mdash; <span class=\"t-en\">re-runs the report with the saved filter configuration.</span><span class=\"t-pt\">reexecuta o relatório com a configuração de filtros salva.</span><span class=\"t-es\">vuelve a ejecutar el informe con la configuración de filtros guardada.</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">removes the saved configuration.</span><span class=\"t-pt\">remove a configuração salva.</span><span class=\"t-es\">elimina la configuración guardada.</span></li>\n        </ul>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=marketing\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Marketing</span><span class=\"t-pt\">Marketing</span><span class=\"t-es\">Marketing</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=personalizar\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Customize</span><span class=\"t-pt\">Personalizar</span><span class=\"t-es\">Personalizar</span></strong></a>\n</nav>\n", "personalizar": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Customize</span><span class=\"t-pt\">Personalizar</span><span class=\"t-es\">Personalizar</span></p>\n<section class=\"doc-section\" id=\"temas\">\n      <h2><span class=\"t-en\">15. Customize &gt; Themes</span><span class=\"t-pt\">15. Personalizar &gt; Temas</span><span class=\"t-es\">15. Personalizar &gt; Temas</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Manages the visual themes installed on the store. Each theme is a self-contained template (layout, sections, templates and assets) that can be linked to specific sales channels, edited directly via its underlying code, and exported or imported as a .zip file.</span><span class=\"t-pt\">Gerencia os temas visuais instalados na loja. Cada tema é um modelo autocontido (layout, sections, templates e assets) que pode ser vinculado a canais de venda específicos, editado diretamente pelo código subjacente, e exportado ou importado como um arquivo .zip.</span><span class=\"t-es\">Gestiona los temas visuales instalados en la tienda. Cada tema es una plantilla autocontenida (layout, sections, templates y assets) que se puede vincular a canales de venta específicos, editar directamente mediante su código subyacente, y exportar o importar como un archivo .zip.</span>\n      </p>\n      <div class=\"subsection\" id=\"temas-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Themes</span><span class=\"t-pt\">Personalizar &gt; Temas</span><span class=\"t-es\">Personalizar &gt; Temas</span></span></h3>\n        <h3><span class=\"t-en\">Theme list</span><span class=\"t-pt\">Lista de temas</span><span class=\"t-es\">Lista de temas</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists every theme installed on the store (installed either from the theme gallery or by import), showing which sales channel each one is linked to and its base template and version. A theme not linked to any channel is available but not currently powering a live storefront.</p></span><span class=\"t-pt\"><p>Lista todos os temas instalados na loja (instalados pela galeria de temas ou por importação), mostrando a qual canal de venda cada um está vinculado e seu modelo base e versão. Um tema não vinculado a nenhum canal está disponível, mas não está ativo em nenhuma loja virtual no momento.</p></span><span class=\"t-es\"><p>Lista todos los temas instalados en la tienda (instalados desde la galería de temas o por importación), mostrando a qué canal de venta está vinculado cada uno y su plantilla base y versión. Un tema no vinculado a ningún canal está disponible, pero no está activo en ninguna tienda virtual por el momento.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/187-temas-en-theme-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/188-temas-pt-theme-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/189-temas-es-theme-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme list (es)\">\n          <figcaption><span class=\"t-en\">Customize &gt; Themes screen, listing the 8 themes installed on this store</span><span class=\"t-pt\">Tela Personalizar &gt; Temas, listando os 8 temas instalados nesta loja</span><span class=\"t-es\">Pantalla Personalizar &gt; Temas, con los 8 temas instalados en esta tienda</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">ID / Name</span><span class=\"t-pt\">ID / Nome</span><span class=\"t-es\">ID / Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">The theme's internal id and the custom name given to it in this store (editable, independent of the base template name).</span><span class=\"t-pt\">O id interno do tema e o nome personalizado dado a ele nesta loja (editável, independente do nome do modelo base).</span><span class=\"t-es\">El id interno del tema y el nombre personalizado que se le dio en esta tienda (editable, independiente del nombre de la plantilla base).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Channels</span><span class=\"t-pt\">Canais</span><span class=\"t-es\">Canales</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">Which sales channel(s) currently use this theme; a dash means the theme is not linked to any channel.</span><span class=\"t-pt\">Qual(is) canal(is) de venda usa(m) este tema atualmente; um traço significa que o tema não está vinculado a nenhum canal.</span><span class=\"t-es\">Qué canal(es) de venta usa(n) actualmente este tema; un guion significa que el tema no está vinculado a ningún canal.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Theme / Version</span><span class=\"t-pt\">Tema / Versão</span><span class=\"t-es\">Tema / Versión</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">The base template the theme was created from, and its version number.</span><span class=\"t-pt\">O modelo base a partir do qual o tema foi criado, e seu número de versão.</span><span class=\"t-es\">La plantilla base a partir de la cual se creó el tema, y su número de versión.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the theme editor (General, Code, Import or Export tabs).</span><span class=\"t-pt\">abre o editor do tema (abas Geral, Código, Importar ou Exportar).</span><span class=\"t-es\">abre el editor del tema (pestañas General, Código, Importar o Exportar).</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">removes the theme from the store.</span><span class=\"t-pt\">remove o tema da loja.</span><span class=\"t-es\">elimina el tema de la tienda.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"temas-adicionar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Themes</span><span class=\"t-pt\">Personalizar &gt; Temas</span><span class=\"t-es\">Personalizar &gt; Temas</span></span></h3>\n        <h3><span class=\"t-en\">Add theme</span><span class=\"t-pt\">Adicionar tema</span><span class=\"t-es\">Añadir tema</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The \"Add\" button opens a gallery of ready-made theme templates (13 available in this store's plan, all marked \"Free\" here). Browsing the carousel previews each template's storefront layout before loading a copy of it as a new, independently editable theme.</p></span><span class=\"t-pt\"><p>O botão \"Adicionar\" abre uma galeria de modelos de tema prontos (13 disponíveis no plano desta loja, todos marcados como \"Grátis\" aqui). Navegar pelo carrossel exibe uma prévia do layout de cada modelo antes de carregar uma cópia dele como um novo tema, editável de forma independente.</p></span><span class=\"t-es\"><p>El botón \"Añadir\" abre una galería de plantillas de tema listas para usar (13 disponibles en el plan de esta tienda, todas marcadas como \"Gratis\" aquí). Navegar por el carrusel muestra una vista previa del diseño de cada plantilla antes de cargar una copia de ella como un nuevo tema, editable de forma independiente.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/190-temas-en-add-theme-gallery-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add theme gallery modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/191-temas-pt-add-theme-gallery-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add theme gallery modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/192-temas-es-add-theme-gallery-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add theme gallery modal (es)\">\n          <figcaption><span class=\"t-en\">\"Select a theme template\" gallery, showing the Skate template preview (1 of 13)</span><span class=\"t-pt\">Galeria \"Selecione o modelo do tema\", mostrando a prévia do modelo Skate (1 de 13)</span><span class=\"t-es\">Galería \"Seleccione la plantilla del tema\", con la vista previa de la plantilla Skate (1 de 13)</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Carousel</span><span class=\"t-pt\">Carrossel</span><span class=\"t-es\">Carrusel</span></td><td class=\"field-type\"><span class=\"t-en\">Preview</span><span class=\"t-pt\">Prévia</span><span class=\"t-es\">Vista previa</span></td><td class=\"field-desc\"><span class=\"t-en\">Click through the dots to browse each available theme template's storefront preview, name and version.</span><span class=\"t-pt\">Clique nos pontos para navegar pela prévia da loja virtual, nome e versão de cada modelo de tema disponível.</span><span class=\"t-es\">Haga clic en los puntos para recorrer la vista previa de la tienda virtual, el nombre y la versión de cada plantilla de tema disponible.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Load this theme</span><span class=\"t-pt\">Carregar esse tema</span><span class=\"t-es\">Cargar este tema</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Creates a new, independent theme in this store from the selected template &mdash; it can then be customized without affecting the original template.</span><span class=\"t-pt\">Cria um novo tema, independente, nesta loja a partir do modelo selecionado &mdash; ele pode então ser personalizado sem afetar o modelo original.</span><span class=\"t-es\">Crea un nuevo tema, independiente, en esta tienda a partir de la plantilla seleccionada &mdash; luego se puede personalizar sin afectar la plantilla original.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"temas-editar-geral\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Themes</span><span class=\"t-pt\">Personalizar &gt; Temas</span><span class=\"t-es\">Personalizar &gt; Temas</span></span></h3>\n        <h3><span class=\"t-en\">Edit theme &mdash; General</span><span class=\"t-pt\">Editar tema &mdash; Geral</span><span class=\"t-es\">Editar tema &mdash; General</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The theme editor's \"General\" tab covers the settings a non-developer would typically adjust: the theme's display name, which showcase and menu configuration it uses, whether product variants are grouped together in search results, and the store's logo and favicon images.</p></span><span class=\"t-pt\"><p>A aba \"Geral\" do editor de temas cobre as configurações que um usuário não desenvolvedor normalmente ajustaria: o nome de exibição do tema, qual configuração de vitrine e de menu ele usa, se as variações de produto são agrupadas nos resultados de busca, e as imagens de logo e favicon da loja.</p></span><span class=\"t-es\"><p>La pestaña \"General\" del editor de temas cubre las configuraciones que un usuario no desarrollador normalmente ajustaría: el nombre de visualización del tema, qué configuración de vitrina y de menú usa, si las variantes de producto se agrupan en los resultados de búsqueda, y las imágenes de logo y favicon de la tienda.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/193-temas-en-theme-editor-general-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme editor general tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/194-temas-pt-theme-editor-general-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme editor general tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/195-temas-es-theme-editor-general-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme editor general tab (es)\">\n          <figcaption><span class=\"t-en\">Theme editor, \"General\" tab, showing the Wine theme's name, showcase, menu and logo</span><span class=\"t-pt\">Editor de tema, aba \"Geral\", mostrando o nome, vitrine, menu e logo do tema Wine</span><span class=\"t-es\">Editor de tema, pestaña \"General\", con el nombre, vitrina, menú y logo del tema Wine</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Theme name</span><span class=\"t-pt\">Nome do tema</span><span class=\"t-es\">Nombre del tema</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The display name shown in the theme list; independent of the base template name.</span><span class=\"t-pt\">O nome de exibição mostrado na lista de temas; independente do nome do modelo base.</span><span class=\"t-es\">El nombre de visualización mostrado en la lista de temas; independiente del nombre de la plantilla base.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Showcases</span><span class=\"t-pt\">Vitrines</span><span class=\"t-es\">Vitrinas</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Which showcase (product-highlight) configuration this theme displays.</span><span class=\"t-pt\">Qual configuração de vitrine (destaque de produtos) este tema exibe.</span><span class=\"t-es\">Qué configuración de vitrina (destaque de productos) muestra este tema.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Menus</span><span class=\"t-pt\">Menus</span><span class=\"t-es\">Menús</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Which menu configuration (from Customize &gt; Menus) this theme uses for storefront navigation.</span><span class=\"t-pt\">Qual configuração de menu (de Personalizar &gt; Menus) este tema usa para a navegação da loja virtual.</span><span class=\"t-es\">Qué configuración de menú (de Personalizar &gt; Menús) usa este tema para la navegación de la tienda virtual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Group variants in search</span><span class=\"t-pt\">Agrupar grades na busca</span><span class=\"t-es\">Agrupar variantes en la búsqueda</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">When enabled, product variants (e.g. different colors/sizes of the same item) appear as one grouped result instead of separate listings.</span><span class=\"t-pt\">Quando ativado, as variações de um produto (ex.: cores/tamanhos diferentes do mesmo item) aparecem como um resultado agrupado em vez de listagens separadas.</span><span class=\"t-es\">Cuando está activado, las variantes de un producto (ej.: colores/tallas diferentes del mismo artículo) aparecen como un resultado agrupado en lugar de listados separados.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Logo / Favicon</span><span class=\"t-pt\">Logo / Favicon</span><span class=\"t-es\">Logo / Favicon</span></td><td class=\"field-type\"><span class=\"t-en\">Image upload</span><span class=\"t-pt\">Upload de imagem</span><span class=\"t-es\">Carga de imagen</span></td><td class=\"field-desc\"><span class=\"t-en\">The store logo shown in the theme's header, and the small icon shown in the browser tab.</span><span class=\"t-pt\">O logo da loja exibido no cabeçalho do tema, e o pequeno ícone exibido na aba do navegador.</span><span class=\"t-es\">El logo de la tienda mostrado en el encabezado del tema, y el pequeño ícono mostrado en la pestaña del navegador.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"temas-editar-codigo\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Themes</span><span class=\"t-pt\">Personalizar &gt; Temas</span><span class=\"t-es\">Personalizar &gt; Temas</span></span></h3>\n        <h3><span class=\"t-en\">Edit theme &mdash; Code</span><span class=\"t-pt\">Editar tema &mdash; Código</span><span class=\"t-es\">Editar tema &mdash; Código</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The \"Code\" tab is a developer-level file editor for the theme's raw source: a file tree (assets, layout, sections, templates folders, plus a root config.json) on the left, and a code editor on the right for whichever file is open. This is where deep visual customization happens and is intended for users comfortable editing template code directly.</p></span><span class=\"t-pt\"><p>A aba \"Código\" é um editor de arquivos em nível de desenvolvedor para o código-fonte bruto do tema: uma árvore de arquivos (pastas assets, layout, sections, templates, além de um config.json na raiz) à esquerda, e um editor de código à direita para o arquivo que estiver aberto. É aqui que ocorre a personalização visual profunda, voltada a usuários confortáveis em editar o código do modelo diretamente.</p></span><span class=\"t-es\"><p>La pestaña \"Código\" es un editor de archivos a nivel de desarrollador para el código fuente bruto del tema: un árbol de archivos (carpetas assets, layout, sections, templates, además de un config.json en la raíz) a la izquierda, y un editor de código a la derecha para el archivo que esté abierto. Aquí es donde ocurre la personalización visual profunda, pensada para usuarios cómodos editando el código de la plantilla directamente.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/196-temas-en-theme-code-editor-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme code editor (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/197-temas-pt-theme-code-editor-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme code editor (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/198-temas-es-theme-code-editor-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme code editor (es)\">\n          <figcaption><span class=\"t-en\">\"Code\" tab, with config.json open showing the theme's color and icon definitions</span><span class=\"t-pt\">Aba \"Código\", com o config.json aberto mostrando as definições de cor e ícones do tema</span><span class=\"t-es\">Pestaña \"Código\", con config.json abierto mostrando las definiciones de color e íconos del tema</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Files panel</span><span class=\"t-pt\">Painel Arquivos</span><span class=\"t-es\">Panel Archivos</span></td><td class=\"field-type\"><span class=\"t-en\">File tree</span><span class=\"t-pt\">Árvore de arquivos</span><span class=\"t-es\">Árbol de archivos</span></td><td class=\"field-desc\"><span class=\"t-en\">Browse the theme's folders (assets, layout, sections, templates) and files; the \"+\" icon adds a new file.</span><span class=\"t-pt\">Navega pelas pastas do tema (assets, layout, sections, templates) e arquivos; o ícone \"+\" adiciona um novo arquivo.</span><span class=\"t-es\">Explora las carpetas del tema (assets, layout, sections, templates) y archivos; el ícono \"+\" agrega un nuevo archivo.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Code editor</span><span class=\"t-pt\">Editor de código</span><span class=\"t-es\">Editor de código</span></td><td class=\"field-type\"><span class=\"t-en\">Text editor</span><span class=\"t-pt\">Editor de texto</span><span class=\"t-es\">Editor de texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Shows the contents of the selected file for direct editing (here, config.json defining the theme's color and SVG icon set).</span><span class=\"t-pt\">Mostra o conteúdo do arquivo selecionado para edição direta (aqui, o config.json que define a cor e o conjunto de ícones SVG do tema).</span><span class=\"t-es\">Muestra el contenido del archivo seleccionado para edición directa (aquí, config.json que define el color y el conjunto de íconos SVG del tema).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Delete</span><span class=\"t-pt\">Borrar</span><span class=\"t-es\">Borrar</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Removes the currently open file from the theme.</span><span class=\"t-pt\">Remove o arquivo atualmente aberto do tema.</span><span class=\"t-es\">Elimina el archivo actualmente abierto del tema.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Save file</span><span class=\"t-pt\">Salvar arquivo</span><span class=\"t-es\">Guardar archivo</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Saves changes to the currently open file only (the top-right \"Save\" button saves the whole theme).</span><span class=\"t-pt\">Salva as alterações apenas do arquivo atualmente aberto (o botão \"Salvar\" no canto superior direito salva o tema inteiro).</span><span class=\"t-es\">Guarda los cambios solo del archivo actualmente abierto (el botón \"Guardar\" en la esquina superior derecha guarda todo el tema).</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"temas-editar-importexport\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Themes</span><span class=\"t-pt\">Personalizar &gt; Temas</span><span class=\"t-es\">Personalizar &gt; Temas</span></span></h3>\n        <h3><span class=\"t-en\">Edit theme &mdash; Import or Export</span><span class=\"t-pt\">Editar tema &mdash; Importar ou Exportar</span><span class=\"t-es\">Editar tema &mdash; Importar o Exportar</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The \"Import or Export\" tab moves a theme's entire file set in or out of the store as a single .zip archive &mdash; useful for backing up a theme, editing it in an external code editor, or transferring it between stores. An expandable \"Observations\" panel documents the exact behavior and links to a folder-structure guide and a downloadable theme emulator for local development.</p></span><span class=\"t-pt\"><p>A aba \"Importar ou Exportar\" move todo o conjunto de arquivos de um tema para dentro ou fora da loja como um único arquivo .zip &mdash; útil para fazer backup de um tema, editá-lo em um editor de código externo, ou transferi-lo entre lojas. Um painel expansível \"Observações\" documenta o comportamento exato e traz links para um guia de estrutura de pastas e um emulador de tema para desenvolvimento local.</p></span><span class=\"t-es\"><p>La pestaña \"Importar o Exportar\" mueve todo el conjunto de archivos de un tema hacia dentro o fuera de la tienda como un único archivo .zip &mdash; útil para respaldar un tema, editarlo en un editor de código externo, o transferirlo entre tiendas. Un panel expandible \"Observaciones\" documenta el comportamiento exacto y enlaza a una guía de estructura de carpetas y a un emulador de tema para desarrollo local.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/199-temas-en-theme-import-export-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme import/export tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/200-temas-pt-theme-import-export-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme import/export tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/201-temas-es-theme-import-export-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"theme import/export tab (es)\">\n          <figcaption><span class=\"t-en\">\"Import or Export\" tab, with the \"Observations\" panel expanded</span><span class=\"t-pt\">Aba \"Importar ou Exportar\", com o painel \"Observações\" expandido</span><span class=\"t-es\">Pestaña \"Importar o Exportar\", con el panel \"Observaciones\" expandido</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Observations</span><span class=\"t-pt\">Observações</span><span class=\"t-es\">Observaciones</span></td><td class=\"field-type\"><span class=\"t-en\">Expandable panel</span><span class=\"t-pt\">Painel expansível</span><span class=\"t-es\">Panel expandible</span></td><td class=\"field-desc\"><span class=\"t-en\">Explains that import/export run in the background (tracked under Processes), that export produces a .zip matching the theme's folder structure, that import expects the same structure, and links to a folder-structure guide and a downloadable theme emulator.</span><span class=\"t-pt\">Explica que a importação/exportação rodam em segundo plano (acompanhadas em Processos), que a exportação gera um .zip com a mesma estrutura de pastas do tema, que a importação espera essa mesma estrutura, e traz links para um guia de estrutura de pastas e um emulador de tema para download.</span><span class=\"t-es\">Explica que la importación/exportación se ejecutan en segundo plano (seguidas en Procesos), que la exportación genera un .zip con la misma estructura de carpetas del tema, que la importación espera esa misma estructura, y enlaza a una guía de estructura de carpetas y a un emulador de tema descargable.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Generate download</span><span class=\"t-pt\">Gerar download</span><span class=\"t-es\">Generar descarga</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Starts a background export of the theme as a .zip file.</span><span class=\"t-pt\">Inicia uma exportação em segundo plano do tema como um arquivo .zip.</span><span class=\"t-es\">Inicia una exportación en segundo plano del tema como un archivo .zip.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Import theme</span><span class=\"t-pt\">Importar tema</span><span class=\"t-es\">Importar tema</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Uploads a .zip file (matching the exported structure) to replace this theme's files.</span><span class=\"t-pt\">Envia um arquivo .zip (com a mesma estrutura exportada) para substituir os arquivos deste tema.</span><span class=\"t-es\">Sube un archivo .zip (con la misma estructura exportada) para reemplazar los archivos de este tema.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Download file</span><span class=\"t-pt\">Baixar arquivo</span><span class=\"t-es\">Descargar archivo</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Downloads the most recently generated export .zip.</span><span class=\"t-pt\">Baixa o arquivo .zip da exportação mais recente já gerada.</span><span class=\"t-es\">Descarga el archivo .zip de la exportación más reciente ya generada.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n\n    </section>\n\n<section class=\"doc-section\" id=\"menus\">\n      <h2><span class=\"t-en\">16. Customize &gt; Menus</span><span class=\"t-pt\">16. Personalizar &gt; Menus</span><span class=\"t-es\">16. Personalizar &gt; Menús</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Manages the navigation menus shown on the storefront. Each menu is either built manually (a \"Custom\" type, with hand-entered items and nested submenus) or generated from the store's product categories (a \"Categories\" type). A menu is linked to a theme from that theme's \"General\" tab.</span><span class=\"t-pt\">Gerencia os menus de navegação exibidos na loja virtual. Cada menu é montado manualmente (tipo \"Personalizado\", com itens digitados à mão e submenus aninhados) ou gerado a partir das categorias de produtos da loja (tipo \"Categorias\"). Um menu é vinculado a um tema pela aba \"Geral\" desse tema.</span><span class=\"t-es\">Gestiona los menús de navegación mostrados en la tienda virtual. Cada menú se arma manualmente (tipo \"Personalizado\", con elementos escritos a mano y submenús anidados) o se genera a partir de las categorías de productos de la tienda (tipo \"Categorías\"). Un menú se vincula a un tema desde la pestaña \"General\" de ese tema.</span>\n      </p>\n      <div class=\"subsection\" id=\"menus-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Menus</span><span class=\"t-pt\">Personalizar &gt; Menus</span><span class=\"t-es\">Personalizar &gt; Menús</span></span></h3>\n        <h3><span class=\"t-en\">Menu list</span><span class=\"t-pt\">Lista de menus</span><span class=\"t-es\">Lista de menús</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists every menu created for the store, showing which sales channel(s) each is linked to and its type (Custom or Categories). The \"Add\" button creates a new menu, starting by asking which of the two types it should be.</p></span><span class=\"t-pt\"><p>Lista todos os menus criados para a loja, mostrando a qual(is) canal(is) de venda cada um está vinculado e seu tipo (Personalizado ou Categorias). O botão \"Adicionar\" cria um novo menu, começando por perguntar qual dos dois tipos ele deve ser.</p></span><span class=\"t-es\"><p>Lista todos los menús creados para la tienda, mostrando a qué canal(es) de venta está vinculado cada uno y su tipo (Personalizado o Categorías). El botón \"Añadir\" crea un nuevo menú, comenzando por preguntar cuál de los dos tipos debe ser.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/202-menus-en-menu-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"menu list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/203-menus-pt-menu-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"menu list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/204-menus-es-menu-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"menu list (es)\">\n          <figcaption><span class=\"t-en\">Customize &gt; Menus screen, listing the 3 menus configured on this store</span><span class=\"t-pt\">Tela Personalizar &gt; Menus, listando os 3 menus configurados nesta loja</span><span class=\"t-es\">Pantalla Personalizar &gt; Menús, con los 3 menús configurados en esta tienda</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">ID / Name</span><span class=\"t-pt\">ID / Nome</span><span class=\"t-es\">ID / Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">The menu's internal id and the name given to it.</span><span class=\"t-pt\">O id interno do menu e o nome dado a ele.</span><span class=\"t-es\">El id interno del menú y el nombre que se le dio.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Channels</span><span class=\"t-pt\">Canais</span><span class=\"t-es\">Canales</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">Which sales channel(s) use this menu (via a theme linked to it); a dash means no channel currently uses it.</span><span class=\"t-pt\">Qual(is) canal(is) de venda usa(m) este menu (por meio de um tema vinculado a ele); um traço significa que nenhum canal o utiliza no momento.</span><span class=\"t-es\">Qué canal(es) de venta usa(n) este menú (a través de un tema vinculado a él); un guion significa que ningún canal lo utiliza actualmente.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">\"Custom\" for a manually-built item tree, or \"Categories\" for one generated from the store's product categories.</span><span class=\"t-pt\">\"Personalizado\" para uma árvore de itens montada manualmente, ou \"Categorias\" para um gerado a partir das categorias de produtos da loja.</span><span class=\"t-es\">\"Personalizado\" para un árbol de elementos armado manualmente, o \"Categorías\" para uno generado a partir de las categorías de productos de la tienda.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Add</span><span class=\"t-pt\">Adicionar</span><span class=\"t-es\">Añadir</span></b> &mdash; <span class=\"t-en\">prompts for a Type (Custom or Categories), then opens a new blank menu of that type for editing.</span><span class=\"t-pt\">solicita um Tipo (Personalizado ou Categorias), depois abre um novo menu em branco desse tipo para edição.</span><span class=\"t-es\">solicita un Tipo (Personalizado o Categorías), luego abre un nuevo menú en blanco de ese tipo para edición.</span></li>\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the menu editor, whose layout depends on the menu's type.</span><span class=\"t-pt\">abre o editor do menu, cujo layout depende do tipo do menu.</span><span class=\"t-es\">abre el editor del menú, cuyo diseño depende del tipo del menú.</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">removes the menu from the store.</span><span class=\"t-pt\">remove o menu da loja.</span><span class=\"t-es\">elimina el menú de la tienda.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"menus-personalizado\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Menus</span><span class=\"t-pt\">Personalizar &gt; Menus</span><span class=\"t-es\">Personalizar &gt; Menús</span></span></h3>\n        <h3><span class=\"t-en\">Edit menu &mdash; Custom type</span><span class=\"t-pt\">Editar menu &mdash; Tipo Personalizado</span><span class=\"t-es\">Editar menú &mdash; Tipo Personalizado</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>For a \"Custom\" menu, items are entered by hand: each row has a Name and a Link (the target URL/path), a \"+\" icon that nests a new empty submenu item underneath it, and a trash icon that removes the row. Nesting can go on to build multi-level dropdown menus for the storefront.</p></span><span class=\"t-pt\"><p>Em um menu do tipo \"Personalizado\", os itens são digitados manualmente: cada linha tem um Nome e um Link (a URL/caminho de destino), um ícone \"+\" que aninha um novo item de submenu em branco logo abaixo, e um ícone de lixeira que remove a linha. O aninhamento pode continuar para montar menus suspensos de vários níveis na loja virtual.</p></span><span class=\"t-es\"><p>En un menú de tipo \"Personalizado\", los elementos se escriben a mano: cada fila tiene un Nombre y un Enlace (la URL/ruta de destino), un ícono \"+\" que anida un nuevo elemento de submenú en blanco justo debajo, y un ícono de papelera que elimina la fila. El anidamiento puede continuar para armar menús desplegables de varios niveles en la tienda virtual.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/205-menus-en-custom-menu-editor-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"custom menu editor (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/206-menus-pt-custom-menu-editor-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"custom menu editor (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/207-menus-es-custom-menu-editor-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"custom menu editor (es)\">\n          <figcaption><span class=\"t-en\">Menu editor for a \"Custom\" type menu, showing the Name/Link item list</span><span class=\"t-pt\">Editor de menu de um menu do tipo \"Personalizado\", mostrando a lista de itens Nome/Link</span><span class=\"t-es\">Editor de menú de un menú de tipo \"Personalizado\", con la lista de elementos Nombre/Enlace</span></figcaption>\n        </div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/208-menus-en-custom-menu-nested-submenu-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"custom menu nested submenu (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/209-menus-pt-custom-menu-nested-submenu-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"custom menu nested submenu (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/210-menus-es-custom-menu-nested-submenu-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"custom menu nested submenu (es)\">\n          <figcaption><span class=\"t-en\">Clicking \"+\" on an item reveals a nested, indented submenu row with its own Name/Link</span><span class=\"t-pt\">Clicar em \"+\" em um item revela uma linha de submenu aninhada e recuada, com seu próprio Nome/Link</span><span class=\"t-es\">Al hacer clic en \"+\" en un elemento aparece una fila de submenú anidada y sangrada, con su propio Nombre/Enlace</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The menu's own display name (shown in the menu list, not on the storefront).</span><span class=\"t-pt\">O nome de exibição do próprio menu (mostrado na lista de menus, não na loja virtual).</span><span class=\"t-es\">El nombre de visualización del propio menú (mostrado en la lista de menús, no en la tienda virtual).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Front-end submenus</span><span class=\"t-pt\">Sub-menus no front-end</span><span class=\"t-es\">Submenús en el front-end</span></td><td class=\"field-type\"><span class=\"t-en\">Select: Hide / Show</span><span class=\"t-pt\">Seleção: Ocultar / Exibir</span><span class=\"t-es\">Selección: Ocultar / Mostrar</span></td><td class=\"field-desc\"><span class=\"t-en\">Controls whether nested submenu items are shown as dropdowns on the storefront or hidden.</span><span class=\"t-pt\">Controla se os itens de submenu aninhados são exibidos como menus suspensos na loja virtual ou ocultados.</span><span class=\"t-es\">Controla si los elementos de submenú anidados se muestran como menús desplegables en la tienda virtual u ocultos.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Item Name / Link</span><span class=\"t-pt\">Nome / Link do item</span><span class=\"t-es\">Nombre / Enlace del elemento</span></td><td class=\"field-type\"><span class=\"t-en\">Text fields</span><span class=\"t-pt\">Campos de texto</span><span class=\"t-es\">Campos de texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The label shown in the menu and the URL/path it links to.</span><span class=\"t-pt\">O rótulo exibido no menu e a URL/caminho para o qual ele aponta.</span><span class=\"t-es\">La etiqueta mostrada en el menú y la URL/ruta a la que enlaza.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">+ Add</span><span class=\"t-pt\">+ Adicionar</span><span class=\"t-es\">+ Añadir</span></b> &mdash; <span class=\"t-en\">adds a new top-level item to the menu.</span><span class=\"t-pt\">adiciona um novo item de primeiro nível ao menu.</span><span class=\"t-es\">agrega un nuevo elemento de primer nivel al menú.</span></li>\n          <li><b><span class=\"t-en\">+ (row icon)</span><span class=\"t-pt\">+ (ícone na linha)</span><span class=\"t-es\">+ (ícono en la fila)</span></b> &mdash; <span class=\"t-en\">nests a new empty submenu item underneath that row.</span><span class=\"t-pt\">aninha um novo item de submenu em branco logo abaixo dessa linha.</span><span class=\"t-es\">anida un nuevo elemento de submenú en blanco justo debajo de esa fila.</span></li>\n          <li><b><span class=\"t-en\">Trash icon</span><span class=\"t-pt\">Ícone de lixeira</span><span class=\"t-es\">Ícono de papelera</span></b> &mdash; <span class=\"t-en\">removes that item (and any submenu items nested under it).</span><span class=\"t-pt\">remove esse item (e quaisquer itens de submenu aninhados nele).</span><span class=\"t-es\">elimina ese elemento (y cualquier elemento de submenú anidado en él).</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"menus-categorias\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Menus</span><span class=\"t-pt\">Personalizar &gt; Menus</span><span class=\"t-es\">Personalizar &gt; Menús</span></span></h3>\n        <h3><span class=\"t-en\">Edit menu &mdash; Categories type</span><span class=\"t-pt\">Editar menu &mdash; Tipo Categorias</span><span class=\"t-es\">Editar menú &mdash; Tipo Categorías</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>For a \"Categories\" menu, items are not typed by hand: a search field adds a product category to the menu (typing <code>##</code> between names adds it as a nested level), and every category already on the menu appears in a draggable, reorderable table. Each row can be toggled active/inactive, and can have an icon and a promotional banner (with title and description) attached, all edited via the row's edit action.</p></span><span class=\"t-pt\"><p>Em um menu do tipo \"Categorias\", os itens não são digitados manualmente: um campo de busca adiciona uma categoria de produto ao menu (digitar <code>##</code> entre os nomes a adiciona como um nível aninhado), e cada categoria já presente no menu aparece em uma tabela arrastável e reordenável. Cada linha pode ser ativada/desativada, e pode ter um ícone e um banner promocional (com título e descrição) anexados, tudo editado pela ação de editar da linha.</p></span><span class=\"t-es\"><p>En un menú de tipo \"Categorías\", los elementos no se escriben a mano: un campo de búsqueda agrega una categoría de producto al menú (escribir <code>##</code> entre los nombres la agrega como un nivel anidado), y cada categoría ya presente en el menú aparece en una tabla arrastrable y reordenable. Cada fila se puede activar/desactivar, y puede tener un ícono y un banner promocional (con título y descripción) adjuntos, todo editado mediante la acción de editar de la fila.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/211-menus-en-categories-menu-editor-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"categories menu editor (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/212-menus-pt-categories-menu-editor-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"categories menu editor (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/213-menus-es-categories-menu-editor-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"categories menu editor (es)\">\n          <figcaption><span class=\"t-en\">Menu editor for a \"Categories\" type menu, showing the draggable category table</span><span class=\"t-pt\">Editor de menu de um menu do tipo \"Categorias\", mostrando a tabela arrastável de categorias</span><span class=\"t-es\">Editor de menú de un menú de tipo \"Categorías\", con la tabla arrastrable de categorías</span></figcaption>\n        </div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/214-menus-en-categories-menu-row-edit-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"categories menu row edit (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/215-menus-pt-categories-menu-row-edit-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"categories menu row edit (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/216-menus-es-categories-menu-row-edit-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"categories menu row edit (es)\">\n          <figcaption><span class=\"t-en\">Clicking the edit icon on a category row makes its banner title and description editable inline</span><span class=\"t-pt\">Clicar no ícone de editar em uma linha de categoria torna o título e a descrição do banner editáveis diretamente na linha</span><span class=\"t-es\">Al hacer clic en el ícono de editar en una fila de categoría, el título y la descripción del banner quedan editables directamente en la fila</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search field</span><span class=\"t-pt\">Campo de busca</span><span class=\"t-es\">Campo de búsqueda</span></td><td class=\"field-type\"><span class=\"t-en\">Text input</span><span class=\"t-pt\">Campo de texto</span><span class=\"t-es\">Campo de texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Finds and adds a product category to the menu; separate nested levels with \"##\".</span><span class=\"t-pt\">Localiza e adiciona uma categoria de produto ao menu; separe níveis aninhados com \"##\".</span><span class=\"t-es\">Busca y agrega una categoría de producto al menú; separe niveles anidados con \"##\".</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">The category name; rows can be dragged by the handle to reorder (the \"All categories\" row is fixed at the top).</span><span class=\"t-pt\">O nome da categoria; as linhas podem ser arrastadas pela alça para reordenar (a linha \"Todas as Categorias\" fica fixa no topo).</span><span class=\"t-es\">El nombre de la categoría; las filas se pueden arrastrar por el asa para reordenar (la fila \"Todas las Categorías\" queda fija arriba).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Icon / Banner</span><span class=\"t-pt\">Ícone / Banner</span><span class=\"t-es\">Ícono / Banner</span></td><td class=\"field-type\"><span class=\"t-en\">Image upload</span><span class=\"t-pt\">Upload de imagem</span><span class=\"t-es\">Carga de imagen</span></td><td class=\"field-desc\"><span class=\"t-en\">Optional small icon and promotional banner image for that category in the menu.</span><span class=\"t-pt\">Ícone pequeno e imagem de banner promocional opcionais para essa categoria no menu.</span><span class=\"t-es\">Ícono pequeño e imagen de banner promocional opcionales para esa categoría en el menú.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Banner title / description</span><span class=\"t-pt\">Título / Descrição do banner</span><span class=\"t-es\">Título / Descripción del banner</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Optional headline and text shown over the category's banner; a dash means none is set. Edited inline via the row's edit icon.</span><span class=\"t-pt\">Título e texto opcionais exibidos sobre o banner da categoria; um traço significa que nenhum está definido. Editado diretamente na linha pelo ícone de editar.</span><span class=\"t-es\">Título y texto opcionales mostrados sobre el banner de la categoría; un guion significa que no hay ninguno definido. Se edita directamente en la fila mediante el ícono de editar.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Edit (row icon)</span><span class=\"t-pt\">Editar (ícone na linha)</span><span class=\"t-es\">Editar (ícono en la fila)</span></b> &mdash; <span class=\"t-en\">makes that row's banner title and description editable inline; confirm or cancel with the checkmark/X that appear.</span><span class=\"t-pt\">torna o título e a descrição do banner dessa linha editáveis diretamente; confirme ou cancele com a marca de confirmação/X que aparecem.</span><span class=\"t-es\">hace que el título y la descripción del banner de esa fila sean editables directamente; confirme o cancele con la marca de confirmación/X que aparecen.</span></li>\n        </ul>\n      </div>\n\n    </section>\n\n<section class=\"doc-section\" id=\"vitrines\">\n      <h2><span class=\"t-en\">17. Customize &gt; Showcases</span><span class=\"t-pt\">17. Personalizar &gt; Vitrines</span><span class=\"t-es\">17. Personalizar &gt; Vitrinas</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Manages the \"showcases\" that arrange sections (banners, product carousels, and similar blocks) on the storefront's home page and product pages. A showcase is linked to a theme from that theme's \"General\" tab.</span><span class=\"t-pt\">Gerencia as \"vitrines\" que organizam seções (banners, carrosséis de produtos e blocos semelhantes) na página inicial e nas páginas de produto da loja virtual. Uma vitrine é vinculada a um tema pela aba \"Geral\" desse tema.</span><span class=\"t-es\">Gestiona las \"vitrinas\" que organizan secciones (banners, carruseles de productos y bloques similares) en la página de inicio y en las páginas de producto de la tienda virtual. Una vitrina se vincula a un tema desde la pestaña \"General\" de ese tema.</span>\n      </p>\n      <div class=\"subsection\" id=\"vitrines-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Showcases</span><span class=\"t-pt\">Personalizar &gt; Vitrines</span><span class=\"t-es\">Personalizar &gt; Vitrinas</span></span></h3>\n        <h3><span class=\"t-en\">Showcase list</span><span class=\"t-pt\">Lista de vitrines</span><span class=\"t-es\">Lista de vitrinas</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists every showcase configuration created for the store, showing which sales channel(s) each is linked to.</p></span><span class=\"t-pt\"><p>Lista todas as configurações de vitrine criadas para a loja, mostrando a qual(is) canal(is) de venda cada uma está vinculada.</p></span><span class=\"t-es\"><p>Lista todas las configuraciones de vitrina creadas para la tienda, mostrando a qué canal(es) de venta está vinculada cada una.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/217-vitrines-en-showcase-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"showcase list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/218-vitrines-pt-showcase-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"showcase list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/219-vitrines-es-showcase-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"showcase list (es)\">\n          <figcaption><span class=\"t-en\">Customize &gt; Showcases screen, listing the store's showcase configuration</span><span class=\"t-pt\">Tela Personalizar &gt; Vitrines, listando a configuração de vitrine da loja</span><span class=\"t-es\">Pantalla Personalizar &gt; Vitrinas, con la configuración de vitrina de la tienda</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">ID / Name</span><span class=\"t-pt\">ID / Nome</span><span class=\"t-es\">ID / Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">The showcase's internal id and the name given to it.</span><span class=\"t-pt\">O id interno da vitrine e o nome dado a ela.</span><span class=\"t-es\">El id interno de la vitrina y el nombre que se le dio.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Channels</span><span class=\"t-pt\">Canais</span><span class=\"t-es\">Canales</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">Which sales channel(s) use this showcase (via a theme linked to it).</span><span class=\"t-pt\">Qual(is) canal(is) de venda usa(m) esta vitrine (por meio de um tema vinculado a ela).</span><span class=\"t-es\">Qué canal(es) de venta usa(n) esta vitrina (a través de un tema vinculado a ella).</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the showcase editor.</span><span class=\"t-pt\">abre o editor da vitrine.</span><span class=\"t-es\">abre el editor de la vitrina.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"vitrines-editar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Showcases</span><span class=\"t-pt\">Personalizar &gt; Vitrines</span><span class=\"t-es\">Personalizar &gt; Vitrinas</span></span></h3>\n        <h3><span class=\"t-en\">Edit showcase</span><span class=\"t-pt\">Editar vitrine</span><span class=\"t-es\">Editar vitrina</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The showcase editor has two tabs, \"Home\" and \"Produto\", each holding an independent, draggable list of sections for that storefront page. Each section row shows a template preview, its type, and a \"Display\" selector for whether it appears on Desktop, Mobile, or both.</p></span><span class=\"t-pt\"><p>O editor de vitrine tem duas abas, \"Home\" e \"Produto\", cada uma com uma lista independente e arrastável de seções para aquela página da loja virtual. Cada linha de seção mostra uma prévia do modelo, seu tipo, e um seletor \"Exibição\" para definir se ela aparece no Desktop, Mobile, ou em ambos.</p></span><span class=\"t-es\"><p>El editor de vitrina tiene dos pestañas, \"Home\" y \"Produto\", cada una con una lista independiente y arrastrable de secciones para esa página de la tienda virtual. Cada fila de sección muestra una vista previa de la plantilla, su tipo, y un selector \"Visualización\" para definir si aparece en Desktop, Mobile, o en ambos.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/220-vitrines-en-showcase-editor-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"showcase editor (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/221-vitrines-pt-showcase-editor-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"showcase editor (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/222-vitrines-es-showcase-editor-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"showcase editor (es)\">\n          <figcaption><span class=\"t-en\">Showcase editor, \"Home\" tab, listing the 5 sections configured for the home page</span><span class=\"t-pt\">Editor de vitrine, aba \"Home\", listando as 5 seções configuradas para a página inicial</span><span class=\"t-es\">Editor de vitrina, pestaña \"Home\", con las 5 secciones configuradas para la página de inicio</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Home / Produto tabs</span><span class=\"t-pt\">Abas Home / Produto</span><span class=\"t-es\">Pestañas Home / Produto</span></td><td class=\"field-type\"><span class=\"t-en\">Tabs</span><span class=\"t-pt\">Abas</span><span class=\"t-es\">Pestañas</span></td><td class=\"field-desc\"><span class=\"t-en\">Switch between the section list for the storefront home page and the one for product pages.</span><span class=\"t-pt\">Alterna entre a lista de seções da página inicial da loja virtual e a das páginas de produto.</span><span class=\"t-es\">Cambia entre la lista de secciones de la página de inicio de la tienda virtual y la de las páginas de producto.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Display</span><span class=\"t-pt\">Exibição</span><span class=\"t-es\">Visualización</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Whether that section shows on Desktop, Mobile, or both.</span><span class=\"t-pt\">Se aquela seção aparece no Desktop, Mobile, ou em ambos.</span><span class=\"t-es\">Si esa sección se muestra en Desktop, Mobile, o en ambos.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Drag handle</span><span class=\"t-pt\">Alça de arrastar</span><span class=\"t-es\">Asa de arrastre</span></b> &mdash; <span class=\"t-en\">reorders the sections on the page.</span><span class=\"t-pt\">reordena as seções na página.</span><span class=\"t-es\">reordena las secciones en la página.</span></li>\n          <li><b><span class=\"t-en\">Edit section</span><span class=\"t-pt\">Editar seção</span><span class=\"t-es\">Editar sección</span> (<span class=\"t-en\">pencil icon</span><span class=\"t-pt\">ícone de lápis</span><span class=\"t-es\">ícono de lápiz</span>)</b> &mdash; <span class=\"t-en\">opens that section's settings.</span><span class=\"t-pt\">abre as configurações dessa seção.</span><span class=\"t-es\">abre la configuración de esa sección.</span></li>\n          <li><b><span class=\"t-en\">Remove section</span><span class=\"t-pt\">Remover seção</span><span class=\"t-es\">Eliminar sección</span></b> &mdash; <span class=\"t-en\">deletes the section from the page.</span><span class=\"t-pt\">exclui a seção da página.</span><span class=\"t-es\">elimina la sección de la página.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"vitrines-incluir\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Showcases</span><span class=\"t-pt\">Personalizar &gt; Vitrines</span><span class=\"t-es\">Personalizar &gt; Vitrinas</span></span></h3>\n        <h3><span class=\"t-en\">Add section</span><span class=\"t-pt\">Incluir seção</span><span class=\"t-es\">Agregar sección</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The \"Add section\" button opens a gallery of ready-made section templates (banners, product carousels, and similar layouts) browsable via a carousel; picking one adds a new, empty section of that type to the current tab's list.</p></span><span class=\"t-pt\"><p>O botão \"Incluir seção\" abre uma galeria de modelos de seção prontos (banners, carrosséis de produtos e layouts semelhantes) navegável por um carrossel; escolher um adiciona uma nova seção vazia desse tipo à lista da aba atual.</p></span><span class=\"t-es\"><p>El botón \"Agregar sección\" abre una galería de plantillas de sección listas para usar (banners, carruseles de productos y diseños similares) navegable mediante un carrusel; elegir una agrega una nueva sección vacía de ese tipo a la lista de la pestaña actual.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/223-vitrines-en-add-section-gallery-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add section gallery (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/224-vitrines-pt-add-section-gallery-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add section gallery (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/225-vitrines-es-add-section-gallery-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add section gallery (es)\">\n          <figcaption><span class=\"t-en\">\"Select the section template\" gallery, showing the \"Lançamentos\" template preview</span><span class=\"t-pt\">Galeria \"Selecione o modelo da seção\", mostrando a prévia do modelo \"Lançamentos\"</span><span class=\"t-es\">Galería \"Seleccione el modelo de la sección\", con la vista previa de la plantilla \"Lançamentos\"</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Carousel</span><span class=\"t-pt\">Carrossel</span><span class=\"t-es\">Carrusel</span></td><td class=\"field-type\"><span class=\"t-en\">Preview</span><span class=\"t-pt\">Prévia</span><span class=\"t-es\">Vista previa</span></td><td class=\"field-desc\"><span class=\"t-en\">Click through the dots to browse each available section template's layout preview and name.</span><span class=\"t-pt\">Clique nos pontos para navegar pela prévia de layout e o nome de cada modelo de seção disponível.</span><span class=\"t-es\">Haga clic en los puntos para recorrer la vista previa de diseño y el nombre de cada plantilla de sección disponible.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Select</span><span class=\"t-pt\">Selecionar</span><span class=\"t-es\">Seleccionar</span></b> &mdash; <span class=\"t-en\">adds a new, empty section of the chosen template to the list, ready to be configured.</span><span class=\"t-pt\">adiciona uma nova seção vazia do modelo escolhido à lista, pronta para ser configurada.</span><span class=\"t-es\">agrega una nueva sección vacía de la plantilla elegida a la lista, lista para configurarse.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"vitrines-editar-secao\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Showcases</span><span class=\"t-pt\">Personalizar &gt; Vitrines</span><span class=\"t-es\">Personalizar &gt; Vitrinas</span></span></h3>\n        <h3><span class=\"t-en\">Edit section</span><span class=\"t-pt\">Editar seção</span><span class=\"t-es\">Editar sección</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Editing a section sets its title and, separately for Desktop and Mobile, which images (from the Media bank) fill each of its media slots.</p></span><span class=\"t-pt\"><p>Editar uma seção define seu título e, separadamente para Desktop e Mobile, quais imagens (do Banco de imagens) preenchem cada um dos seus espaços de mídia.</p></span><span class=\"t-es\"><p>Editar una sección define su título y, por separado para Desktop y Mobile, qué imágenes (del Banco de imágenes) llenan cada uno de sus espacios de medios.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/226-vitrines-en-section-settings-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"section settings modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/227-vitrines-pt-section-settings-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"section settings modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/228-vitrines-es-section-settings-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"section settings modal (es)\">\n          <figcaption><span class=\"t-en\">\"Section settings\" modal for the \"Banner Full\" section, with its two desktop media slots filled</span><span class=\"t-pt\">Modal \"Configurações da seção\" da seção \"Banner Full\", com seus dois espaços de mídia desktop preenchidos</span><span class=\"t-es\">Modal \"Configuración de la sección\" de la sección \"Banner Full\", con sus dos espacios de medios de escritorio completados</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Section title</span><span class=\"t-pt\">Título da seção</span><span class=\"t-es\">Título de la sección</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The section's internal label (does not appear on the storefront).</span><span class=\"t-pt\">O rótulo interno da seção (não aparece na loja virtual).</span><span class=\"t-es\">La etiqueta interna de la sección (no aparece en la tienda virtual).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Desktop / Mobile tabs</span><span class=\"t-pt\">Abas Desktop / Mobile</span><span class=\"t-es\">Pestañas Desktop / Mobile</span></td><td class=\"field-type\"><span class=\"t-en\">Tabs</span><span class=\"t-pt\">Abas</span><span class=\"t-es\">Pestañas</span></td><td class=\"field-desc\"><span class=\"t-en\">Set different images for the same section depending on the visitor's device.</span><span class=\"t-pt\">Define imagens diferentes para a mesma seção dependendo do dispositivo do visitante.</span><span class=\"t-es\">Define imágenes distintas para la misma sección según el dispositivo del visitante.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Select images</span><span class=\"t-pt\">Selecionar imagens</span><span class=\"t-es\">Seleccionar imágenes</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Opens the Media bank picker to fill the section's media slots.</span><span class=\"t-pt\">Abre o seletor do Banco de imagens para preencher os espaços de mídia da seção.</span><span class=\"t-es\">Abre el selector del Banco de imágenes para llenar los espacios de medios de la sección.</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"note\"><span class=\"t-en\">&#128161; Within Customize, Showcases is now documented, per the section already authorized.</span><span class=\"t-pt\">&#128161; Dentro de Personalizar, Vitrines já está documentado, conforme a seção já autorizada.</span><span class=\"t-es\">&#128161; Dentro de Personalizar, Vitrinas ya está documentado, según la sección ya autorizada.</span></div>\n      </div>\n\n    </section>\n\n<section class=\"doc-section\" id=\"banco\">\n      <h2><span class=\"t-en\">18. Customize &gt; Media bank</span><span class=\"t-pt\">18. Personalizar &gt; Banco de imagens</span><span class=\"t-es\">18. Personalizar &gt; Banco de imágenes</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">A central media library for the store: every image uploaded here can be reused across showcases, stamp collections, themes and other areas, instead of uploading the same file repeatedly.</span><span class=\"t-pt\">Uma biblioteca de mídia central da loja: toda imagem enviada aqui pode ser reutilizada em vitrines, coleções de selos, temas e outras áreas, em vez de enviar o mesmo arquivo repetidamente.</span><span class=\"t-es\">Una biblioteca de medios central de la tienda: toda imagen subida aquí puede reutilizarse en vitrinas, colecciones de sellos, temas y otras áreas, en lugar de subir el mismo archivo repetidamente.</span>\n      </p>\n      <div class=\"subsection\" id=\"banco-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Media bank</span><span class=\"t-pt\">Personalizar &gt; Banco de imagens</span><span class=\"t-es\">Personalizar &gt; Banco de imágenes</span></span></h3>\n        <h3><span class=\"t-en\">Media list</span><span class=\"t-pt\">Lista de mídias</span><span class=\"t-es\">Lista de medios</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists every image uploaded to the store's media bank, with a search box (matches by title, link or tag) and a table showing each image's thumbnail, name, direct link and search tag(s).</p></span><span class=\"t-pt\"><p>Lista todas as imagens enviadas ao banco de imagens da loja, com uma caixa de busca (procura por título, link ou etiqueta) e uma tabela mostrando a miniatura, o nome, o link direto e a(s) etiqueta(s) de busca de cada imagem.</p></span><span class=\"t-es\"><p>Lista todas las imágenes subidas al banco de imágenes de la tienda, con un cuadro de búsqueda (busca por título, enlace o etiqueta) y una tabla que muestra la miniatura, el nombre, el enlace directo y la(s) etiqueta(s) de búsqueda de cada imagen.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/229-banco-en-media-bank-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"media bank list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/230-banco-pt-media-bank-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"media bank list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/231-banco-es-media-bank-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"media bank list (es)\">\n          <figcaption><span class=\"t-en\">Customize &gt; Media bank screen, listing uploaded images with their search tags</span><span class=\"t-pt\">Tela Personalizar &gt; Banco de imagens, listando as imagens enviadas com suas etiquetas de busca</span><span class=\"t-es\">Pantalla Personalizar &gt; Banco de imágenes, con las imágenes subidas y sus etiquetas de búsqueda</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">The image's thumbnail and given name; a dash means no name was set.</span><span class=\"t-pt\">A miniatura da imagem e o nome dado a ela; um traço significa que nenhum nome foi definido.</span><span class=\"t-es\">La miniatura de la imagen y el nombre que se le dio; un guion significa que no se definió ningún nombre.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Link</span><span class=\"t-pt\">Link</span><span class=\"t-es\">Enlace</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">The image's direct URL, usable outside the admin (e.g. in page content or a custom banner).</span><span class=\"t-pt\">A URL direta da imagem, utilizável fora do admin (ex.: em conteúdo de página ou banner personalizado).</span><span class=\"t-es\">La URL directa de la imagen, utilizable fuera del admin (ej.: en contenido de página o banner personalizado).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search tag</span><span class=\"t-pt\">Tag de busca</span><span class=\"t-es\">Etiqueta para búsqueda</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">One or more labels (e.g. \"logo\", \"banner\", \"Pagamento\") used to filter this image when picking media elsewhere, such as in a stamp collection or showcase section.</span><span class=\"t-pt\">Um ou mais rótulos (ex.: \"logo\", \"banner\", \"Pagamento\") usados para filtrar essa imagem ao selecionar mídia em outras áreas, como em uma coleção de selos ou seção de vitrine.</span><span class=\"t-es\">Una o más etiquetas (ej.: \"logo\", \"banner\", \"Pagamento\") usadas para filtrar esa imagen al seleccionar medios en otras áreas, como en una colección de sellos o sección de vitrina.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Add media</span><span class=\"t-pt\">Adicionar mídia</span><span class=\"t-es\">Agregar medio</span></b> &mdash; <span class=\"t-en\">uploads one or more new image files from the computer.</span><span class=\"t-pt\">envia um ou mais novos arquivos de imagem do computador.</span><span class=\"t-es\">sube uno o más archivos de imagen nuevos desde la computadora.</span></li>\n          <li><b><span class=\"t-en\">More options &gt; Bulk remove</span><span class=\"t-pt\">Mais opções &gt; Remover em massa</span><span class=\"t-es\">Más opciones &gt; Eliminar en masa</span></b> &mdash; <span class=\"t-en\">deletes every checked image at once.</span><span class=\"t-pt\">exclui de uma vez todas as imagens marcadas.</span><span class=\"t-es\">elimina de una vez todas las imágenes marcadas.</span></li>\n          <li><b><span class=\"t-en\">Link icon</span><span class=\"t-pt\">Ícone de link</span><span class=\"t-es\">Ícono de enlace</span></b> &mdash; <span class=\"t-en\">opens the image's direct link.</span><span class=\"t-pt\">abre o link direto da imagem.</span><span class=\"t-es\">abre el enlace directo de la imagen.</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">removes that image from the media bank.</span><span class=\"t-pt\">remove essa imagem do banco de imagens.</span><span class=\"t-es\">elimina esa imagen del banco de imágenes.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"banco-editar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Media bank</span><span class=\"t-pt\">Personalizar &gt; Banco de imagens</span><span class=\"t-es\">Personalizar &gt; Banco de imágenes</span></span></h3>\n        <h3><span class=\"t-en\">Edit media</span><span class=\"t-pt\">Editar mídia</span><span class=\"t-es\">Editar medio</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The edit modal sets the image's Name, Link and one or more Search tags &mdash; the same tags used to filter this image when selecting media from other screens, such as a stamp collection's \"Select media\" picker.</p></span><span class=\"t-pt\"><p>O modal de edição define o Nome, o Link e uma ou mais Tags de busca da imagem &mdash; as mesmas tags usadas para filtrar essa imagem ao selecionar mídia em outras telas, como o seletor \"Selecionar mídia\" de uma coleção de selos.</p></span><span class=\"t-es\"><p>El modal de edición define el Nombre, el Enlace y una o más Etiquetas para búsqueda de la imagen &mdash; las mismas etiquetas usadas para filtrar esa imagen al seleccionar medios desde otras pantallas, como el selector \"Seleccionar medio\" de una colección de sellos.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/232-banco-en-edit-media-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"edit media modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/233-banco-pt-edit-media-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"edit media modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/234-banco-es-edit-media-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"edit media modal (es)\">\n          <figcaption><span class=\"t-en\">\"Edit\" modal for an image, showing its Name, Link and \"logo\" search tag</span><span class=\"t-pt\">Modal \"Editar\" de uma imagem, mostrando seu Nome, Link e a tag de busca \"logo\"</span><span class=\"t-es\">Modal \"Editar\" de una imagen, con su Nombre, Enlace y la etiqueta de búsqueda \"logo\"</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The image's display name in the media bank list.</span><span class=\"t-pt\">O nome de exibição da imagem na lista do banco de imagens.</span><span class=\"t-es\">El nombre de visualización de la imagen en la lista del banco de imágenes.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Link</span><span class=\"t-pt\">Link</span><span class=\"t-es\">Enlace</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">An optional destination URL associated with the image (used when the image itself acts as a clickable banner).</span><span class=\"t-pt\">Uma URL de destino opcional associada à imagem (usada quando a própria imagem funciona como um banner clicável).</span><span class=\"t-es\">Una URL de destino opcional asociada a la imagen (usada cuando la propia imagen funciona como un banner clicable).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search tag</span><span class=\"t-pt\">Tag de busca</span><span class=\"t-es\">Etiqueta para búsqueda</span></td><td class=\"field-type\"><span class=\"t-en\">Multi-tag field</span><span class=\"t-pt\">Campo multi-tag</span><span class=\"t-es\">Campo multietiqueta</span></td><td class=\"field-desc\"><span class=\"t-en\">One or more labels that make this image easy to find and filter when picking media elsewhere.</span><span class=\"t-pt\">Um ou mais rótulos que facilitam encontrar e filtrar essa imagem ao selecionar mídia em outras áreas.</span><span class=\"t-es\">Una o más etiquetas que facilitan encontrar y filtrar esa imagen al seleccionar medios en otras áreas.</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"note\"><span class=\"t-en\">&#128161; Within Customize, Media bank is now documented, per the section already authorized.</span><span class=\"t-pt\">&#128161; Dentro de Personalizar, Banco de imagens já está documentado, conforme a seção já autorizada.</span><span class=\"t-es\">&#128161; Dentro de Personalizar, Banco de imágenes ya está documentado, según la sección ya autorizada.</span></div>\n      </div>\n\n    </section>\n\n<section class=\"doc-section\" id=\"selos\">\n      <h2><span class=\"t-en\">19. Customize &gt; Stamp collection</span><span class=\"t-pt\">19. Personalizar &gt; Coleção de selos</span><span class=\"t-es\">19. Personalizar &gt; Colección de sellos</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Manages named groups of small badge images (\"stamps\") &mdash; payment method logos or social network icons &mdash; typically displayed together, for example in the storefront footer.</span><span class=\"t-pt\">Gerencia grupos nomeados de pequenas imagens de selo (\"stamps\") &mdash; logos de meios de pagamento ou ícones de rede social &mdash; normalmente exibidos juntos, por exemplo no rodapé da loja virtual.</span><span class=\"t-es\">Gestiona grupos con nombre de pequeñas imágenes de sello (\"stamps\") &mdash; logos de métodos de pago o íconos de redes sociales &mdash; normalmente mostrados juntos, por ejemplo en el pie de página de la tienda virtual.</span>\n      </p>\n      <div class=\"subsection\" id=\"selos-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Stamp collection</span><span class=\"t-pt\">Personalizar &gt; Coleção de selos</span><span class=\"t-es\">Personalizar &gt; Colección de sellos</span></span></h3>\n        <h3><span class=\"t-en\">Stamp collection list</span><span class=\"t-pt\">Lista de coleções de selos</span><span class=\"t-es\">Lista de colecciones de sellos</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists every stamp collection created for the store, showing which sales channel(s) each is linked to and its Type (Payment or Social network).</p></span><span class=\"t-pt\"><p>Lista todas as coleções de selos criadas para a loja, mostrando a qual(is) canal(is) de venda cada uma está vinculada e seu Tipo (Pagamento ou Rede social).</p></span><span class=\"t-es\"><p>Lista todas las colecciones de sellos creadas para la tienda, mostrando a qué canal(es) de venta está vinculada cada una y su Tipo (Pago o Red social).</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/235-selos-en-stamp-collection-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stamp collection list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/236-selos-pt-stamp-collection-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stamp collection list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/237-selos-es-stamp-collection-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stamp collection list (es)\">\n          <figcaption><span class=\"t-en\">Customize &gt; Stamp collection screen, listing the store's two collections</span><span class=\"t-pt\">Tela Personalizar &gt; Coleção de selos, listando as duas coleções da loja</span><span class=\"t-es\">Pantalla Personalizar &gt; Colección de sellos, con las dos colecciones de la tienda</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">ID / Name</span><span class=\"t-pt\">ID / Nome</span><span class=\"t-es\">ID / Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Columns</span><span class=\"t-pt\">Colunas</span><span class=\"t-es\">Columnas</span></td><td class=\"field-desc\"><span class=\"t-en\">The collection's internal id and the name given to it.</span><span class=\"t-pt\">O id interno da coleção e o nome dado a ela.</span><span class=\"t-es\">El id interno de la colección y el nombre que se le dio.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Channels</span><span class=\"t-pt\">Canais</span><span class=\"t-es\">Canales</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">Which sales channel(s) use this collection.</span><span class=\"t-pt\">Qual(is) canal(is) de venda usa(m) esta coleção.</span><span class=\"t-es\">Qué canal(es) de venta usa(n) esta colección.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">\"Payment\" for payment-method badges or \"Social network\" for social icons; set when the collection is created and not editable afterward.</span><span class=\"t-pt\">\"Pagamento\" para selos de meios de pagamento ou \"Rede social\" para ícones sociais; definido na criação da coleção e não editável depois.</span><span class=\"t-es\">\"Pago\" para sellos de métodos de pago o \"Red social\" para íconos sociales; se define al crear la colección y no es editable después.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Add</span><span class=\"t-pt\">Adicionar</span><span class=\"t-es\">Añadir</span></b> &mdash; <span class=\"t-en\">creates a new, empty stamp collection.</span><span class=\"t-pt\">cria uma nova coleção de selos vazia.</span><span class=\"t-es\">crea una nueva colección de sellos vacía.</span></li>\n          <li><b><span class=\"t-en\">Edit</span><span class=\"t-pt\">Editar</span><span class=\"t-es\">Editar</span></b> &mdash; <span class=\"t-en\">opens the collection editor.</span><span class=\"t-pt\">abre o editor da coleção.</span><span class=\"t-es\">abre el editor de la colección.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"selos-editar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Stamp collection</span><span class=\"t-pt\">Personalizar &gt; Coleção de selos</span><span class=\"t-es\">Personalizar &gt; Colección de sellos</span></span></h3>\n        <h3><span class=\"t-en\">Edit stamp collection</span><span class=\"t-pt\">Editar coleção de selos</span><span class=\"t-es\">Editar colección de sellos</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The collection editor lists its stamps in order (image, name and optional link), each reorderable with the up/down arrows and editable inline. \"Select media\" opens the Media bank filtered by the collection's own name as a tag, making it quick to add matching images (e.g. every image tagged \"Pagamento\").</p></span><span class=\"t-pt\"><p>O editor da coleção lista seus selos em ordem (imagem, nome e link opcional), cada um reordenável com as setas para cima/baixo e editável diretamente na linha. \"Selecionar mídia\" abre o Banco de imagens filtrado pelo próprio nome da coleção como tag, facilitando adicionar imagens correspondentes (ex.: toda imagem marcada com \"Pagamento\").</p></span><span class=\"t-es\"><p>El editor de la colección lista sus sellos en orden (imagen, nombre y enlace opcional), cada uno reordenable con las flechas arriba/abajo y editable directamente en la fila. \"Seleccionar medio\" abre el Banco de imágenes filtrado por el propio nombre de la colección como etiqueta, facilitando agregar imágenes correspondientes (ej.: toda imagen marcada con \"Pagamento\").</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/238-selos-en-stamp-collection-editor-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stamp collection editor (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/239-selos-pt-stamp-collection-editor-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stamp collection editor (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/240-selos-es-stamp-collection-editor-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"stamp collection editor (es)\">\n          <figcaption><span class=\"t-en\">Editor for the \"Pagamento padrão\" collection, listing its 6 payment-brand stamps</span><span class=\"t-pt\">Editor da coleção \"Pagamento padrão\", listando seus 6 selos de bandeiras de pagamento</span><span class=\"t-es\">Editor de la colección \"Pagamento padrão\", con sus 6 sellos de marcas de pago</span></figcaption>\n        </div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/241-selos-en-select-media-filtered-by-tag-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"select media filtered by tag (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/242-selos-pt-select-media-filtered-by-tag-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"select media filtered by tag (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/243-selos-es-select-media-filtered-by-tag-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"select media filtered by tag (es)\">\n          <figcaption><span class=\"t-en\">\"Select media\" picker, pre-filtered by the \"Pagamento\" tag shared with the collection's name</span><span class=\"t-pt\">Seletor \"Selecionar mídia\", pré-filtrado pela tag \"Pagamento\" compartilhada com o nome da coleção</span><span class=\"t-es\">Selector \"Seleccionar medio\", prefiltrado por la etiqueta \"Pagamento\" compartida con el nombre de la colección</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Image</span><span class=\"t-pt\">Imagem</span><span class=\"t-es\">Imagen</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">The stamp's thumbnail, picked from the Media bank.</span><span class=\"t-pt\">A miniatura do selo, escolhida do Banco de imagens.</span><span class=\"t-es\">La miniatura del sello, elegida del Banco de imágenes.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">The stamp's label (e.g. the payment brand or social network name).</span><span class=\"t-pt\">O rótulo do selo (ex.: o nome da bandeira de pagamento ou rede social).</span><span class=\"t-es\">La etiqueta del sello (ej.: el nombre de la marca de pago o red social).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Link</span><span class=\"t-pt\">Link</span><span class=\"t-es\">Enlace</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">An optional URL the stamp links to when clicked on the storefront.</span><span class=\"t-pt\">Uma URL opcional para a qual o selo aponta quando clicado na loja virtual.</span><span class=\"t-es\">Una URL opcional a la que enlaza el sello al hacer clic en la tienda virtual.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Select media</span><span class=\"t-pt\">Selecionar mídia</span><span class=\"t-es\">Seleccionar medio</span></b> &mdash; <span class=\"t-en\">opens the Media bank, pre-filtered by the collection name as a tag, to add a stamp.</span><span class=\"t-pt\">abre o Banco de imagens, pré-filtrado pelo nome da coleção como tag, para adicionar um selo.</span><span class=\"t-es\">abre el Banco de imágenes, prefiltrado por el nombre de la colección como etiqueta, para agregar un sello.</span></li>\n          <li><b><span class=\"t-en\">Up / down arrows</span><span class=\"t-pt\">Setas para cima/baixo</span><span class=\"t-es\">Flechas arriba/abajo</span></b> &mdash; <span class=\"t-en\">reorder that stamp within the collection.</span><span class=\"t-pt\">reordenam esse selo dentro da coleção.</span><span class=\"t-es\">reordenan ese sello dentro de la colección.</span></li>\n          <li><b><span class=\"t-en\">Edit (row icon)</span><span class=\"t-pt\">Editar (ícone na linha)</span><span class=\"t-es\">Editar (ícono en la fila)</span></b> &mdash; <span class=\"t-en\">makes that stamp's Name and Link editable inline.</span><span class=\"t-pt\">torna o Nome e o Link desse selo editáveis diretamente na linha.</span><span class=\"t-es\">hace que el Nombre y el Enlace de ese sello sean editables directamente en la fila.</span></li>\n          <li><b><span class=\"t-en\">Delete</span><span class=\"t-pt\">Deletar</span><span class=\"t-es\">Borrar</span></b> &mdash; <span class=\"t-en\">removes that stamp from the collection.</span><span class=\"t-pt\">remove esse selo da coleção.</span><span class=\"t-es\">elimina ese sello de la colección.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"selos-adicionar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Stamp collection</span><span class=\"t-pt\">Personalizar &gt; Coleção de selos</span><span class=\"t-es\">Personalizar &gt; Colección de sellos</span></span></h3>\n        <h3><span class=\"t-en\">Add stamp collection</span><span class=\"t-pt\">Adicionar coleção de selos</span><span class=\"t-es\">Agregar colección de sellos</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Creating a new collection just asks for a Name and a Type (Payment or Social network); the Type determines what the collection is meant to display, though it does not restrict which images can be added to it.</p></span><span class=\"t-pt\"><p>Criar uma nova coleção pede apenas um Nome e um Tipo (Pagamento ou Rede social); o Tipo determina o que a coleção deve exibir, embora não restrinja quais imagens podem ser adicionadas a ela.</p></span><span class=\"t-es\"><p>Crear una nueva colección solo pide un Nombre y un Tipo (Pago o Red social); el Tipo determina qué debe mostrar la colección, aunque no restringe qué imágenes se le pueden agregar.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/244-selos-en-add-stamp-collection-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add stamp collection modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/245-selos-pt-add-stamp-collection-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add stamp collection modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/246-selos-es-add-stamp-collection-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add stamp collection modal (es)\">\n          <figcaption><span class=\"t-en\">\"Add stamp collection\" modal, with Type defaulted to \"Social network\"</span><span class=\"t-pt\">Modal \"Adicionar coleção de selos\", com o Tipo padrão em \"Rede social\"</span><span class=\"t-es\">Modal \"Agregar colección de sellos\", con el Tipo predeterminado en \"Red social\"</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The collection's display name.</span><span class=\"t-pt\">O nome de exibição da coleção.</span><span class=\"t-es\">El nombre de visualización de la colección.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></td><td class=\"field-type\"><span class=\"t-en\">Select: Payment / Social network</span><span class=\"t-pt\">Seleção: Pagamento / Rede social</span><span class=\"t-es\">Selección: Pago / Red social</span></td><td class=\"field-desc\"><span class=\"t-en\">Sets the collection's Type, shown in the list column.</span><span class=\"t-pt\">Define o Tipo da coleção, exibido na coluna da lista.</span><span class=\"t-es\">Define el Tipo de la colección, mostrado en la columna de la lista.</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"note\"><span class=\"t-en\">&#128161; Within Customize, Stamp collection is now documented, per the section already authorized.</span><span class=\"t-pt\">&#128161; Dentro de Personalizar, Coleção de selos já está documentado, conforme a seção já autorizada.</span><span class=\"t-es\">&#128161; Dentro de Personalizar, Colección de sellos ya está documentado, según la sección ya autorizada.</span></div>\n      </div>\n\n    </section>\n\n<section class=\"doc-section\" id=\"paginas\">\n      <h2><span class=\"t-en\">20. Customize &gt; Additional pages</span><span class=\"t-pt\">20. Personalizar &gt; Páginas adicionais</span><span class=\"t-es\">20. Personalizar &gt; Páginas adicionales</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Manages custom static pages (e.g. \"About us\", \"Contact\", \"Privacy policy\") that appear on the storefront outside the regular product/category structure, organized under named groupers for the site's help/institutional menus.</span><span class=\"t-pt\">Gerencia páginas estáticas personalizadas (ex.: \"Quem somos\", \"Fale conosco\", \"Política de privacidade\") que aparecem na loja virtual fora da estrutura regular de produtos/categorias, organizadas sob agrupadores nomeados para os menus de ajuda/institucional do site.</span><span class=\"t-es\">Gestiona páginas estáticas personalizadas (ej.: \"Quiénes somos\", \"Contacto\", \"Política de privacidad\") que aparecen en la tienda virtual fuera de la estructura regular de productos/categorías, organizadas bajo agrupadores con nombre para los menús de ayuda/institucional del sitio.</span>\n      </p>\n      <div class=\"subsection\" id=\"paginas-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Additional pages</span><span class=\"t-pt\">Personalizar &gt; Páginas adicionais</span><span class=\"t-es\">Personalizar &gt; Páginas adicionales</span></span></h3>\n        <h3><span class=\"t-en\">Page list</span><span class=\"t-pt\">Lista de páginas</span><span class=\"t-es\">Lista de páginas</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists every additional page created for the store, with filters by Status and by Grouper, showing each page's sales channel(s), Grouper and publish status (a green check for published, an empty circle for a draft not yet visible on the storefront).</p></span><span class=\"t-pt\"><p>Lista todas as páginas adicionais criadas para a loja, com filtros por Status e por Agrupador, mostrando o(s) canal(is) de venda, o Agrupador e o status de publicação de cada página (um check verde para publicada, um círculo vazio para um rascunho ainda não visível na loja virtual).</p></span><span class=\"t-es\"><p>Lista todas las páginas adicionales creadas para la tienda, con filtros por Estado y por Agrupador, mostrando el/los canal(es) de venta, el Agrupador y el estado de publicación de cada página (una marca verde para publicada, un círculo vacío para un borrador aún no visible en la tienda virtual).</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/247-paginas-en-additional-pages-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"additional pages list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/248-paginas-pt-additional-pages-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"additional pages list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/249-paginas-es-additional-pages-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"additional pages list (es)\">\n          <figcaption><span class=\"t-en\">Customize &gt; Additional pages screen, listing the 6 pages grouped under \"Help and support\" and \"Institutional\"</span><span class=\"t-pt\">Tela Personalizar &gt; Páginas adicionais, listando as 6 páginas agrupadas em \"Ajuda e Suporte\" e \"Institucional\"</span><span class=\"t-es\">Pantalla Personalizar &gt; Páginas adicionales, con las 6 páginas agrupadas en \"Ayuda y soporte\" e \"Institucional\"</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">The page's title and, below it, a status dot (green check = published, empty circle = draft).</span><span class=\"t-pt\">O título da página e, abaixo, um indicador de status (check verde = publicada, círculo vazio = rascunho).</span><span class=\"t-es\">El título de la página y, debajo, un indicador de estado (marca verde = publicada, círculo vacío = borrador).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Grouper</span><span class=\"t-pt\">Agrupador</span><span class=\"t-es\">Agrupador</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">The named group this page belongs to, used to organize pages in the storefront's side menu.</span><span class=\"t-pt\">O grupo nomeado ao qual essa página pertence, usado para organizar páginas no menu lateral da loja virtual.</span><span class=\"t-es\">El grupo con nombre al que pertenece esa página, usado para organizar páginas en el menú lateral de la tienda virtual.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Add</span><span class=\"t-pt\">Adicionar</span><span class=\"t-es\">Añadir</span></b> &mdash; <span class=\"t-en\">opens a blank page form.</span><span class=\"t-pt\">abre um formulário de página em branco.</span><span class=\"t-es\">abre un formulario de página en blanco.</span></li>\n          <li><b><span class=\"t-en\">Edit (row / ID link)</span><span class=\"t-pt\">Editar (linha / link do ID)</span><span class=\"t-es\">Editar (fila / enlace del ID)</span></b> &mdash; <span class=\"t-en\">opens that page's form for editing.</span><span class=\"t-pt\">abre o formulário dessa página para edição.</span><span class=\"t-es\">abre el formulario de esa página para edición.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"paginas-form\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Customize &gt; Additional pages</span><span class=\"t-pt\">Personalizar &gt; Páginas adicionais</span><span class=\"t-es\">Personalizar &gt; Páginas adicionales</span></span></h3>\n        <h3><span class=\"t-en\">Create / edit page</span><span class=\"t-pt\">Criar/editar página</span><span class=\"t-es\">Crear/editar página</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Creating and editing a page use the same form: metadata fields at the top (name, title, grouper, SEO fields, URL and side-menu visibility) followed by a full rich-text editor for the page's Content, with formatting, alignment, lists, tables, links, images and embedded video.</p></span><span class=\"t-pt\"><p>Criar e editar uma página usam o mesmo formulário: campos de metadados no topo (nome, título, agrupador, campos de SEO, URL e visibilidade no menu lateral) seguidos de um editor de texto rico completo para o Conteúdo da página, com formatação, alinhamento, listas, tabelas, links, imagens e vídeo incorporado.</p></span><span class=\"t-es\"><p>Crear y editar una página usan el mismo formulario: campos de metadatos arriba (nombre, título, agrupador, campos de SEO, URL y visibilidad en el menú lateral) seguidos de un editor de texto enriquecido completo para el Contenido de la página, con formato, alineación, listas, tablas, enlaces, imágenes y video incrustado.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/250-paginas-en-page-form-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"page form (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/251-paginas-pt-page-form-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"page form (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/252-paginas-es-page-form-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"page form (es)\">\n          <figcaption><span class=\"t-en\">Page form for \"Fale conosco\", showing the metadata fields and the rich-text Content editor toolbar</span><span class=\"t-pt\">Formulário de página \"Fale conosco\", mostrando os campos de metadados e a barra do editor de texto rico do Conteúdo</span><span class=\"t-es\">Formulario de página \"Fale conosco\", con los campos de metadatos y la barra del editor de texto enriquecido del Contenido</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name / Title</span><span class=\"t-pt\">Nome / Título</span><span class=\"t-es\">Nombre / Título</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Name is the internal label; Title is shown on the storefront page.</span><span class=\"t-pt\">Nome é o rótulo interno; Título é exibido na página da loja virtual.</span><span class=\"t-es\">Nombre es la etiqueta interna; Título se muestra en la página de la tienda virtual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Grouper</span><span class=\"t-pt\">Agrupador</span><span class=\"t-es\">Agrupador</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The named group this page is filed under in the storefront's side menu.</span><span class=\"t-pt\">O grupo nomeado sob o qual essa página é organizada no menu lateral da loja virtual.</span><span class=\"t-es\">El grupo con nombre bajo el cual se organiza esa página en el menú lateral de la tienda virtual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Search tags</span><span class=\"t-pt\">Tags para pesquisa</span><span class=\"t-es\">Etiquetas de búsqueda</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Optional keywords that help this page surface in the storefront's internal search/help widgets.</span><span class=\"t-pt\">Palavras-chave opcionais que ajudam essa página a aparecer nas buscas/widgets de ajuda internos da loja virtual.</span><span class=\"t-es\">Palabras clave opcionales que ayudan a que esta página aparezca en las búsquedas/widgets de ayuda internos de la tienda virtual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Meta tag title / description</span><span class=\"t-pt\">Título / Descrição da meta tag</span><span class=\"t-es\">Título / Descripción de la meta tag</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">SEO fields used by search engines when indexing the page.</span><span class=\"t-pt\">Campos de SEO usados por mecanismos de busca ao indexar a página.</span><span class=\"t-es\">Campos de SEO usados por los motores de búsqueda al indexar la página.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Page URL</span><span class=\"t-pt\">URL da página</span><span class=\"t-es\">URL de la página</span></td><td class=\"field-type\"><span class=\"t-en\">Text (auto)</span><span class=\"t-pt\">Texto (automático)</span><span class=\"t-es\">Texto (automático)</span></td><td class=\"field-desc\"><span class=\"t-en\">The page's slug, generated from its Title and shown greyed out here.</span><span class=\"t-pt\">O slug da página, gerado a partir do Título e exibido em cinza aqui.</span><span class=\"t-es\">El slug de la página, generado a partir del Título y mostrado en gris aquí.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Groupers visible in side menu</span><span class=\"t-pt\">Agrupadores visíveis no menu lateral</span><span class=\"t-es\">Agrupadores visibles en el menú lateral</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Which groupers' pages are listed in the storefront side menu alongside this one.</span><span class=\"t-pt\">Quais páginas de agrupadores são listadas no menu lateral da loja virtual junto com esta.</span><span class=\"t-es\">Qué páginas de agrupadores se listan en el menú lateral de la tienda virtual junto con esta.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Side menu active</span><span class=\"t-pt\">Menu lateral ativo</span><span class=\"t-es\">Menú lateral activo</span></td><td class=\"field-type\"><span class=\"t-en\">Toggle</span><span class=\"t-pt\">Alternância</span><span class=\"t-es\">Interruptor</span></td><td class=\"field-desc\"><span class=\"t-en\">Shows or hides the side menu when this page is open on the storefront.</span><span class=\"t-pt\">Exibe ou oculta o menu lateral quando essa página está aberta na loja virtual.</span><span class=\"t-es\">Muestra u oculta el menú lateral cuando esta página está abierta en la tienda virtual.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Content</span><span class=\"t-pt\">Conteúdo</span><span class=\"t-es\">Contenido</span></td><td class=\"field-type\"><span class=\"t-en\">Rich-text editor</span><span class=\"t-pt\">Editor de texto rico</span><span class=\"t-es\">Editor de texto enriquecido</span></td><td class=\"field-desc\"><span class=\"t-en\">The page's body, with formatting, tables, links, images and embedded video, editable via the toolbar.</span><span class=\"t-pt\">O corpo da página, com formatação, tabelas, links, imagens e vídeo incorporado, editável pela barra de ferramentas.</span><span class=\"t-es\">El cuerpo de la página, con formato, tablas, enlaces, imágenes y video incrustado, editable mediante la barra de herramientas.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=gestao\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Management</span><span class=\"t-pt\">Gestão</span><span class=\"t-es\">Gestión</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=canais\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Channels</span><span class=\"t-pt\">Canais</span><span class=\"t-es\">Canales</span></strong></a>\n</nav>\n", "canais": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Channels</span><span class=\"t-pt\">Canais</span><span class=\"t-es\">Canales</span></p>\n<section class=\"doc-section\" id=\"canais\">\n      <h2><span class=\"t-en\">21. Channels</span><span class=\"t-pt\">21. Canais</span><span class=\"t-es\">21. Canales</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Manages the sales channels connected to the store: the storefront itself, marketplaces (e.g. Mercado Livre), ERPs (e.g. Bling) and generic API/test channels. Each channel has its own price table, product mapping and order flow.</span><span class=\"t-pt\">Gerencia os canais de venda conectados à loja: a própria loja virtual, marketplaces (ex.: Mercado Livre), ERPs (ex.: Bling) e canais genéricos de API/teste. Cada canal tem sua própria tabela de preço, mapeamento de produtos e fluxo de pedidos.</span><span class=\"t-es\">Gestiona los canales de venta conectados a la tienda: la propia tienda virtual, marketplaces (ej.: Mercado Livre), ERPs (ej.: Bling) y canales genéricos de API/prueba. Cada canal tiene su propia tabla de precios, mapeo de productos y flujo de pedidos.</span>\n      </p>\n      <div class=\"subsection\" id=\"canais-lista\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Channels</span><span class=\"t-pt\">Canais</span><span class=\"t-es\">Canales</span></span></h3>\n        <h3><span class=\"t-en\">Channel list</span><span class=\"t-pt\">Lista de canais</span><span class=\"t-es\">Lista de canales</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists every channel already connected to the store, with search by name and a filter by Type, showing each channel's Type and Status (Active/Inactive).</p></span><span class=\"t-pt\"><p>Lista todos os canais já conectados à loja, com busca por nome e filtro por Tipo, mostrando o Tipo e o Status (Ativo/Inativo) de cada canal.</p></span><span class=\"t-es\"><p>Lista todos los canales ya conectados a la tienda, con búsqueda por nombre y filtro por Tipo, mostrando el Tipo y el Estado (Activo/Inactivo) de cada canal.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/253-canais-en-channel-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"channel list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/254-canais-pt-channel-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"channel list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/255-canais-es-channel-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"channel list (es)\">\n          <figcaption><span class=\"t-en\">Channels screen, listing channels such as Bling, Mercado Livre and the store's own virtual store</span><span class=\"t-pt\">Tela Canais, listando canais como Bling, Mercado Livre e a própria loja virtual</span><span class=\"t-es\">Pantalla Canales, con canales como Bling, Mercado Livre y la propia tienda virtual</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></td><td class=\"field-type\"><span class=\"t-en\">Column</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-desc\"><span class=\"t-en\">The kind of channel (marketplace, ERP, generic API, virtual store, etc.).</span><span class=\"t-pt\">O tipo do canal (marketplace, ERP, API genérica, loja virtual etc.).</span><span class=\"t-es\">El tipo de canal (marketplace, ERP, API genérica, tienda virtual, etc.).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Status</span><span class=\"t-pt\">Coluna</span><span class=\"t-es\">Columna</span></td><td class=\"field-type\"><span class=\"t-en\">Active / Inactive</span><span class=\"t-pt\">Ativo / Inativo</span><span class=\"t-es\">Activo / Inactivo</span></td><td class=\"field-desc\"><span class=\"t-en\">Whether the channel is currently synchronizing orders/products.</span><span class=\"t-pt\">Se o canal está atualmente sincronizando pedidos/produtos.</span><span class=\"t-es\">Si el canal está actualmente sincronizando pedidos/productos.</span></td></tr>\n          </tbody>\n        </table>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Add</span><span class=\"t-pt\">Adicionar</span><span class=\"t-es\">Añadir</span></b> &mdash; <span class=\"t-en\">opens the \"Add channel\" modal to connect a new channel.</span><span class=\"t-pt\">abre o modal \"Adicionar canal\" para conectar um novo canal.</span><span class=\"t-es\">abre el modal \"Agregar canal\" para conectar un nuevo canal.</span></li>\n          <li><b><span class=\"t-en\">Edit (row / ID link)</span><span class=\"t-pt\">Editar (linha / link do ID)</span><span class=\"t-es\">Editar (fila / enlace del ID)</span></b> &mdash; <span class=\"t-en\">opens that channel's configuration screen.</span><span class=\"t-pt\">abre a tela de configuração desse canal.</span><span class=\"t-es\">abre la pantalla de configuración de ese canal.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"canais-adicionar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Channels</span><span class=\"t-pt\">Canais</span><span class=\"t-es\">Canales</span></span></h3>\n        <h3><span class=\"t-en\">Add channel</span><span class=\"t-pt\">Adicionar canal</span><span class=\"t-es\">Añadir canal</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Adding a channel only asks for its Type at first (e.g. Loja virtual, Mercado Livre, Bling, Api, Grid2b, Agendamento de exportação, among others); after choosing the Type and confirming, the platform opens that channel's own configuration screen.</p></span><span class=\"t-pt\"><p>Adicionar um canal pede apenas o Tipo no primeiro passo (ex.: Loja virtual, Mercado Livre, Bling, Api, Grid2b, Agendamento de exportação, entre outros); depois de escolher o Tipo e confirmar, a plataforma abre a tela de configuração própria desse canal.</p></span><span class=\"t-es\"><p>Agregar un canal solo pide el Tipo en el primer paso (ej.: Loja virtual, Mercado Livre, Bling, Api, Grid2b, Agendamento de exportação, entre otros); después de elegir el Tipo y confirmar, la plataforma abre la pantalla de configuración propia de ese canal.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/256-canais-en-add-channel-modal-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add channel modal (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/257-canais-pt-add-channel-modal-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add channel modal (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/258-canais-es-add-channel-modal-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"add channel modal (es)\">\n          <figcaption><span class=\"t-en\">\"Add channel\" modal, with the Type dropdown defaulted to \"Loja virtual\"</span><span class=\"t-pt\">Modal \"Adicionar canal\", com o dropdown de Tipo padrão em \"Loja virtual\"</span><span class=\"t-es\">Modal \"Agregar canal\", con el desplegable de Tipo predeterminado en \"Loja virtual\"</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Which kind of channel to connect; determines the fields shown on the next screen (API credentials, marketplace app keys, etc.).</span><span class=\"t-pt\">Qual tipo de canal conectar; determina os campos mostrados na tela seguinte (credenciais de API, chaves de aplicativo do marketplace etc.).</span><span class=\"t-es\">Qué tipo de canal conectar; determina los campos mostrados en la pantalla siguiente (credenciales de API, claves de aplicación del marketplace, etc.).</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"canais-editar\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Channels</span><span class=\"t-pt\">Canais</span><span class=\"t-es\">Canales</span></span></h3>\n        <h3><span class=\"t-en\">Configure channel</span><span class=\"t-pt\">Configurar canal</span><span class=\"t-es\">Configurar canal</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Each channel opens its own configuration screen, specific to its Type. A marketplace channel like Mercado Livre, for example, shows tabs for General data (name, price table, app credentials and access token, with a button to renew authorization), Mappings, Products, Stock, Orders, Listings, Management, Questions/Chat and Contact/Notifications &mdash; other channel types show a different, shorter set of tabs matching what that integration supports.</p></span><span class=\"t-pt\"><p>Cada canal abre sua própria tela de configuração, específica do seu Tipo. Um canal de marketplace como o Mercado Livre, por exemplo, mostra abas de Dados gerais (nome, tabela de preço, credenciais do aplicativo e token de acesso, com um botão para renovar a autorização), Mapeamentos, Produtos, Estoque, Pedidos, Anúncios, Gestão, Perguntas/Chat e Contato/Notificações &mdash; outros tipos de canal mostram um conjunto de abas diferente e mais enxuto, de acordo com o que essa integração suporta.</p></span><span class=\"t-es\"><p>Cada canal abre su propia pantalla de configuración, específica de su Tipo. Un canal de marketplace como Mercado Livre, por ejemplo, muestra pestañas de Datos generales (nombre, tabla de precios, credenciales de la aplicación y token de acceso, con un botón para renovar la autorización), Mapeos, Productos, Stock, Pedidos, Anuncios, Gestión, Preguntas/Chat y Contacto/Notificaciones &mdash; otros tipos de canal muestran un conjunto de pestañas diferente y más reducido, según lo que esa integración soporte.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/259-canais-en-channel-configuration-screen-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"channel configuration screen (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/260-canais-pt-channel-configuration-screen-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"channel configuration screen (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/261-canais-es-channel-configuration-screen-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"channel configuration screen (es)\">\n          <figcaption><span class=\"t-en\">Configuration screen for the Mercado Livre channel, showing the General data tab with app credentials and the full set of marketplace-specific tabs</span><span class=\"t-pt\">Tela de configuração do canal Mercado Livre, mostrando a aba Dados gerais com as credenciais do aplicativo e o conjunto completo de abas específicas do marketplace</span><span class=\"t-es\">Pantalla de configuración del canal Mercado Livre, con la pestaña Datos generales con las credenciales de la aplicación y el conjunto completo de pestañas específicas del marketplace</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The channel's display name in the list and throughout the admin.</span><span class=\"t-pt\">O nome de exibição do canal na lista e no restante do admin.</span><span class=\"t-es\">El nombre de visualización del canal en la lista y en el resto del admin.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Price table</span><span class=\"t-pt\">Tabela de preço</span><span class=\"t-es\">Tabla de precios</span></td><td class=\"field-type\"><span class=\"t-en\">Select</span><span class=\"t-pt\">Seleção</span><span class=\"t-es\">Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">Which price table this channel's products/orders use.</span><span class=\"t-pt\">Qual tabela de preço os produtos/pedidos desse canal usam.</span><span class=\"t-es\">Qué tabla de precios usan los productos/pedidos de ese canal.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">App id / Client secret / Access token</span><span class=\"t-pt\">ID do aplicativo / Client Secret / Token de acesso</span><span class=\"t-es\">ID de la aplicación / Client Secret / Token de acceso</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Credentials issued by the external platform (marketplace, ERP, etc.) that authenticate this connection; \"Renew authorization\" refreshes an expired token.</span><span class=\"t-pt\">Credenciais emitidas pela plataforma externa (marketplace, ERP etc.) que autenticam essa conexão; \"Renovar autorização\" atualiza um token expirado.</span><span class=\"t-es\">Credenciales emitidas por la plataforma externa (marketplace, ERP, etc.) que autentican esta conexión; \"Renovar autorización\" actualiza un token vencido.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"canais-loja-geral\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Channels &gt; Virtual store</span><span class=\"t-pt\">Canais &gt; Loja virtual</span><span class=\"t-es\">Canales &gt; Tienda virtual</span></span></h3>\n        <h3><span class=\"t-en\">Virtual store channel &mdash; General data</span><span class=\"t-pt\">Canal Loja virtual &mdash; Dados gerais</span><span class=\"t-es\">Canal Tienda virtual &mdash; Datos generales</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The \"Loja virtual\" (virtual store) channel type represents the store's own storefront. Its \"General data\" tab holds the channel-wide defaults: theme, display mode, default price table/stock/shipping/payment, stamps, currency display, domains, accepted documents, invoice issuer and checkout rules.</p></span><span class=\"t-pt\"><p>O canal do tipo \"Loja virtual\" representa a própria vitrine da loja. A aba \"Dados gerais\" concentra os padrões do canal como um todo: tema, modo de exibição, tabela de preço/estoque/frete/pagamento padrão, selos, exibição de moeda, domínios, documentos aceitos, emissor de nota fiscal e regras de checkout.</p></span><span class=\"t-es\"><p>El canal del tipo \"Loja virtual\" (tienda virtual) representa el propio escaparate de la tienda. La pestaña \"Datos generales\" reúne los valores predeterminados del canal como un todo: tema, modo de visualización, tabla de precios/stock/envío/pago predeterminados, sellos, visualización de moneda, dominios, documentos aceptados, emisor de factura y reglas de checkout.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/262-canais-en-virtual-store-channel-general-data-top-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store channel general data top (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/263-canais-pt-virtual-store-channel-general-data-top-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store channel general data top (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/264-canais-es-virtual-store-channel-general-data-top-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store channel general data top (es)\">\n          <figcaption><span class=\"t-en\">\"Loja virtual\" channel &mdash; General data tab, top half: name, theme, display mode and channel defaults</span><span class=\"t-pt\">Canal \"Loja virtual\" &mdash; aba Dados gerais, metade superior: nome, tema, modo de exibição e padrões do canal</span><span class=\"t-es\">Canal \"Loja virtual\" &mdash; pestaña Datos generales, mitad superior: nombre, tema, modo de visualización y valores predeterminados del canal</span></figcaption>\n        </div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/265-canais-en-virtual-store-channel-general-data-bottom-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store channel general data bottom (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/266-canais-pt-virtual-store-channel-general-data-bottom-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store channel general data bottom (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/267-canais-es-virtual-store-channel-general-data-bottom-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store channel general data bottom (es)\">\n          <figcaption><span class=\"t-en\">\"Loja virtual\" channel &mdash; General data tab, bottom half: featured prices, domains, documents, NFe and checkout</span><span class=\"t-pt\">Canal \"Loja virtual\" &mdash; aba Dados gerais, metade inferior: valores em destaque, domínios, documentos, NFe e checkout</span><span class=\"t-es\">Canal \"Loja virtual\" &mdash; pestaña Datos generales, mitad inferior: precios destacados, dominios, documentos, NFe y checkout</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name / Theme</span><span class=\"t-pt\">Nome / Tema</span><span class=\"t-es\">Nombre / Tema</span></td><td class=\"field-type\"><span class=\"t-en\">Text / Select</span><span class=\"t-pt\">Texto / Seleção</span><span class=\"t-es\">Texto / Selección</span></td><td class=\"field-desc\"><span class=\"t-en\">The channel's display name and which storefront theme it uses.</span><span class=\"t-pt\">O nome de exibição do canal e qual tema de vitrine ele usa.</span><span class=\"t-es\">El nombre de visualización del canal y qué tema de escaparate usa.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Display mode</span><span class=\"t-pt\">Modo de exibição</span><span class=\"t-es\">Modo de visualización</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">B2C or B2B &mdash; changes catalog/checkout behavior for consumer vs. business buyers.</span><span class=\"t-pt\">B2C ou B2B &mdash; muda o comportamento de catálogo/checkout para compradores consumidores ou empresas.</span><span class=\"t-es\">B2C o B2B &mdash; cambia el comportamiento de catálogo/checkout para compradores consumidores o empresas.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Channel defaults</span><span class=\"t-pt\">Padrões do canal</span><span class=\"t-es\">Valores predeterminados del canal</span></td><td class=\"field-type\"><span class=\"t-en\">Price table, Stock, Shipping, Payment, Additional pages, Embed codes, Plugins</span><span class=\"t-pt\">Tabela de preço, Estoque, Frete, Pagamento, Páginas adicionais, Códigos incorporados, Plugins</span><span class=\"t-es\">Tabla de precios, Stock, Envío, Pago, Páginas adicionales, Códigos incrustados, Plugins</span></td><td class=\"field-desc\"><span class=\"t-en\">Default resources applied across the channel unless overridden elsewhere.</span><span class=\"t-pt\">Recursos padrão aplicados no canal como um todo, salvo substituição em outro ponto.</span><span class=\"t-es\">Recursos predeterminados aplicados en todo el canal, salvo que se sustituyan en otro punto.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Stamps</span><span class=\"t-pt\">Selos</span><span class=\"t-es\">Sellos</span></td><td class=\"field-type\"><span class=\"t-en\">Social network / Payment / Others</span><span class=\"t-pt\">Rede social / Pagamento / Outros</span><span class=\"t-es\">Red social / Pago / Otros</span></td><td class=\"field-desc\"><span class=\"t-en\">Which badge sets (from Customize &gt; Stamp collection) show on the storefront for social, payment and other trust seals.</span><span class=\"t-pt\">Quais conjuntos de selos (de Personalizar &gt; Coleção de selos) aparecem na vitrine para redes sociais, pagamento e outros selos de confiança.</span><span class=\"t-es\">Qué conjuntos de sellos (de Personalizar &gt; Colección de sellos) se muestran en el escaparate para redes sociales, pago y otros sellos de confianza.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Featured prices</span><span class=\"t-pt\">Valores em destaque</span><span class=\"t-es\">Precios destacados</span></td><td class=\"field-type\"><span class=\"t-en\">Currency symbol / Primary / Secondary highlight</span><span class=\"t-pt\">Símbolo de moeda / Destaque primário / secundário</span><span class=\"t-es\">Símbolo de moneda / Destacado primario / secundario</span></td><td class=\"field-desc\"><span class=\"t-en\">Currency symbol shown on prices, and which price fields (e.g. installment, PIX discount) are emphasized on the product page.</span><span class=\"t-pt\">Símbolo de moeda exibido nos preços, e quais campos de preço (ex.: parcelamento, desconto PIX) são destacados na página do produto.</span><span class=\"t-es\">Símbolo de moneda mostrado en los precios, y qué campos de precio (ej.: cuotas, descuento PIX) se destacan en la página del producto.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Domains</span><span class=\"t-pt\">Domínios</span><span class=\"t-es\">Dominios</span></td><td class=\"field-type\"><span class=\"t-en\">List</span><span class=\"t-pt\">Lista</span><span class=\"t-es\">Lista</span></td><td class=\"field-desc\"><span class=\"t-en\">Custom domains pointed at this channel; one is marked as default.</span><span class=\"t-pt\">Domínios personalizados apontados para este canal; um é marcado como padrão.</span><span class=\"t-es\">Dominios personalizados que apuntan a este canal; uno se marca como predeterminado.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Accepted documents and activation</span><span class=\"t-pt\">Documentos aceitos e ativação</span><span class=\"t-es\">Documentos aceptados y activación</span></td><td class=\"field-type\"><span class=\"t-en\">CPF/CNPJ + toggle</span><span class=\"t-pt\">CPF/CNPJ + interruptor</span><span class=\"t-es\">CPF/CNPJ + interruptor</span></td><td class=\"field-desc\"><span class=\"t-en\">Which ID document types customers can register with, and whether new accounts activate automatically.</span><span class=\"t-pt\">Quais tipos de documento os clientes podem usar no cadastro, e se novas contas são ativadas automaticamente.</span><span class=\"t-es\">Qué tipos de documento pueden usar los clientes al registrarse, y si las cuentas nuevas se activan automáticamente.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">NFe</span><span class=\"t-pt\">NFe</span><span class=\"t-es\">NFe</span></td><td class=\"field-type\"><span class=\"t-en\">Issuer / auto-issue toggle</span><span class=\"t-pt\">Emissor / interruptor de emissão automática</span><span class=\"t-es\">Emisor / interruptor de emisión automática</span></td><td class=\"field-desc\"><span class=\"t-en\">Which invoice issuer integration is used and whether invoices are issued automatically per order.</span><span class=\"t-pt\">Qual integração de emissão de nota fiscal é usada e se as notas são emitidas automaticamente por pedido.</span><span class=\"t-es\">Qué integración de emisión de factura se usa y si las facturas se emiten automáticamente por pedido.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Checkout</span><span class=\"t-pt\">Checkout</span><span class=\"t-es\">Checkout</span></td><td class=\"field-type\"><span class=\"t-en\">Min. product qty, seller selection, document/password rules</span><span class=\"t-pt\">Qtd. mín. de produtos, seleção de vendedor, regras de documento/senha</span><span class=\"t-es\">Cant. mín. de productos, selección de vendedor, reglas de documento/contraseña</span></td><td class=\"field-desc\"><span class=\"t-en\">Minimum cart size, whether the customer picks a seller/marketplace vendor, whether accepted documents are required at checkout, and whether a password is auto-created on signup.</span><span class=\"t-pt\">Tamanho mínimo do carrinho, se o cliente escolhe um vendedor, se documentos aceitos são exigidos no checkout, e se uma senha é criada automaticamente no cadastro.</span><span class=\"t-es\">Tamaño mínimo del carrito, si el cliente elige un vendedor, si se exigen documentos aceptados en el checkout, y si se crea una contraseña automáticamente al registrarse.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"canais-loja-seo\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Channels &gt; Virtual store</span><span class=\"t-pt\">Canais &gt; Loja virtual</span><span class=\"t-es\">Canales &gt; Tienda virtual</span></span></h3>\n        <h3><span class=\"t-en\">Virtual store channel &mdash; SEO</span><span class=\"t-pt\">Canal Loja virtual &mdash; SEO</span><span class=\"t-es\">Canal Tienda virtual &mdash; SEO</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Search-engine settings for the storefront: page title, search tags, meta description, robots.txt content and sitemap.</p></span><span class=\"t-pt\"><p>Configurações de mecanismo de busca da vitrine: título da página, tags de pesquisa, meta description, conteúdo do robots.txt e sitemap.</p></span><span class=\"t-es\"><p>Configuraciones de motor de búsqueda del escaparate: título de la página, tags de búsqueda, meta description, contenido del robots.txt y sitemap.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/268-canais-en-virtual-store-channel-seo-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store channel SEO tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/269-canais-pt-virtual-store-channel-seo-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store channel SEO tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/270-canais-es-virtual-store-channel-seo-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store channel SEO tab (es)\">\n          <figcaption><span class=\"t-en\">\"Loja virtual\" channel &mdash; SEO tab: title, search tags, meta description, robots.txt and sitemap</span><span class=\"t-pt\">Canal \"Loja virtual\" &mdash; aba SEO: título, tags de pesquisa, meta description, robots.txt e sitemap</span><span class=\"t-es\">Canal \"Loja virtual\" &mdash; pestaña SEO: título, tags de búsqueda, meta description, robots.txt y sitemap</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Title / Search tags</span><span class=\"t-pt\">Título / Tags para pesquisa</span><span class=\"t-es\">Título / Tags de búsqueda</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The storefront's page title and the keywords search engines associate with it.</span><span class=\"t-pt\">O título de página da vitrine e as palavras-chave que os buscadores associam a ela.</span><span class=\"t-es\">El título de página del escaparate y las palabras clave que los buscadores le asocian.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Meta description</span><span class=\"t-pt\">Meta description</span><span class=\"t-es\">Meta description</span></td><td class=\"field-type\"><span class=\"t-en\">Text area</span><span class=\"t-pt\">Área de texto</span><span class=\"t-es\">Área de texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The snippet shown under the title in search results.</span><span class=\"t-pt\">O trecho exibido abaixo do título nos resultados de busca.</span><span class=\"t-es\">El fragmento mostrado debajo del título en los resultados de búsqueda.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">robots.txt file</span><span class=\"t-pt\">Arquivo robots.txt</span><span class=\"t-es\">Archivo robots.txt</span></td><td class=\"field-type\"><span class=\"t-en\">Text area</span><span class=\"t-pt\">Área de texto</span><span class=\"t-es\">Área de texto</span></td><td class=\"field-desc\"><span class=\"t-en\">Rules telling search engine crawlers what they may index.</span><span class=\"t-pt\">Regras que dizem aos robôs de busca o que eles podem indexar.</span><span class=\"t-es\">Reglas que indican a los robots de búsqueda qué pueden indexar.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Sitemap</span><span class=\"t-pt\">Sitemap</span><span class=\"t-es\">Sitemap</span></td><td class=\"field-type\"><span class=\"t-en\">Automatic toggle + link</span><span class=\"t-pt\">Interruptor automático + link</span><span class=\"t-es\">Interruptor automático + enlace</span></td><td class=\"field-desc\"><span class=\"t-en\">When Automatic is on, the sitemap is generated and kept in sync by the platform; clicking the link notifies Google of updates.</span><span class=\"t-pt\">Com Automático ativado, o sitemap é gerado e mantido pela plataforma; clicar no link notifica o Google sobre atualizações.</span><span class=\"t-es\">Con Automático activado, el sitemap se genera y mantiene actualizado por la plataforma; hacer clic en el enlace notifica a Google sobre actualizaciones.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"canais-loja-contato\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Channels &gt; Virtual store</span><span class=\"t-pt\">Canais &gt; Loja virtual</span><span class=\"t-es\">Canales &gt; Tienda virtual</span></span></h3>\n        <h3><span class=\"t-en\">Virtual store channel &mdash; Contact/Notifications</span><span class=\"t-pt\">Canal Loja virtual &mdash; Contato/Notificações</span><span class=\"t-es\">Canal Tienda virtual &mdash; Contacto/Notificaciones</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The store's own contact/address details and the full set of transactional e-mail templates sent to customers, sellers and the channel itself.</p></span><span class=\"t-pt\"><p>Os dados de contato/endereço da própria loja e o conjunto completo de modelos de e-mail transacionais enviados a clientes, vendedores e ao próprio canal.</p></span><span class=\"t-es\"><p>Los datos de contacto/dirección de la propia tienda y el conjunto completo de plantillas de correo transaccionales enviadas a clientes, vendedores y al propio canal.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/271-canais-en-virtual-store-contact-tab-top-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store contact tab top (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/272-canais-pt-virtual-store-contact-tab-top-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store contact tab top (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/273-canais-es-virtual-store-contact-tab-top-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store contact tab top (es)\">\n          <figcaption><span class=\"t-en\">Contact/Notifications tab, top: phone, e-mail, address and notification copy e-mail</span><span class=\"t-pt\">Aba Contato/Notificações, topo: telefone, e-mail, endereço e e-mail para cópia de notificações</span><span class=\"t-es\">Pestaña Contacto/Notificaciones, arriba: teléfono, correo, dirección y correo para copia de notificaciones</span></figcaption>\n        </div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/274-canais-en-virtual-store-contact-tab-email-templates-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store contact tab email templates (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/275-canais-pt-virtual-store-contact-tab-email-templates-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store contact tab email templates (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/276-canais-es-virtual-store-contact-tab-email-templates-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store contact tab email templates (es)\">\n          <figcaption><span class=\"t-en\">Contact/Notifications tab: full e-mail templates table (header/footer, body and BCC/CC rules per event)</span><span class=\"t-pt\">Aba Contato/Notificações: tabela completa de modelos de e-mail (cabeçalho/rodapé, corpo e regras de CCO/CC por evento)</span><span class=\"t-es\">Pestaña Contacto/Notificaciones: tabla completa de plantillas de correo (encabezado/pie, cuerpo y reglas de CCO/CC por evento)</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Phone / E-mail / Address</span><span class=\"t-pt\">Telefone / E-mail / Endereço</span><span class=\"t-es\">Teléfono / Correo / Dirección</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The store's own contact details, shown in e-mails and, where applicable, on the storefront.</span><span class=\"t-pt\">Os dados de contato da própria loja, exibidos em e-mails e, quando aplicável, na vitrine.</span><span class=\"t-es\">Los datos de contacto de la propia tienda, mostrados en correos y, cuando corresponda, en el escaparate.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Notification copy e-mail</span><span class=\"t-pt\">E-mail para cópia de notificações</span><span class=\"t-es\">Correo para copia de notificaciones</span></td><td class=\"field-type\"><span class=\"t-en\">Text (multiple)</span><span class=\"t-pt\">Texto (múltiplos)</span><span class=\"t-es\">Texto (múltiples)</span></td><td class=\"field-desc\"><span class=\"t-en\">Extra addresses that receive a copy of every notification e-mail.</span><span class=\"t-pt\">Endereços extras que recebem cópia de todo e-mail de notificação.</span><span class=\"t-es\">Direcciones adicionales que reciben copia de cada correo de notificación.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">E-mail templates table</span><span class=\"t-pt\">Tabela de modelos de e-mail</span><span class=\"t-es\">Tabla de plantillas de correo</span></td><td class=\"field-type\"><span class=\"t-en\">List</span><span class=\"t-pt\">Lista</span><span class=\"t-es\">Lista</span></td><td class=\"field-desc\"><span class=\"t-en\">One row per system event (order placed, password reset, status change, shipping, invoice, cancellation, quotation, product review, etc.); for each, pick the header/footer and body template and toggle whether the channel (BCC), the seller (BCC) and/or the customer (CC) receive it.</span><span class=\"t-pt\">Uma linha por evento do sistema (pedido inserido, redefinição de senha, mudança de status, envio, nota fiscal, cancelamento, orçamento, avaliação de produto etc.); em cada uma, escolha o modelo de cabeçalho/rodapé e de corpo e marque se o canal (CCO), o vendedor (CCO) e/ou o cliente (CC) recebem o e-mail.</span><span class=\"t-es\">Una fila por evento del sistema (pedido insertado, restablecimiento de contraseña, cambio de estado, envío, factura, cancelación, presupuesto, evaluación de producto, etc.); en cada una, elija la plantilla de encabezado/pie y de cuerpo y marque si el canal (CCO), el vendedor (CCO) y/o el cliente (CC) lo reciben.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"canais-loja-cotacao\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Channels &gt; Virtual store</span><span class=\"t-pt\">Canais &gt; Loja virtual</span><span class=\"t-es\">Canales &gt; Tienda virtual</span></span></h3>\n        <h3><span class=\"t-en\">Virtual store channel &mdash; Quotation</span><span class=\"t-pt\">Canal Loja virtual &mdash; Cotação</span><span class=\"t-es\">Canal Tienda virtual &mdash; Cotización</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Registers one or more currency quotations used to convert and display prices in a second currency on the storefront and at checkout.</p></span><span class=\"t-pt\"><p>Cadastra uma ou mais cotações de moeda usadas para converter e exibir preços em uma segunda moeda na vitrine e no checkout.</p></span><span class=\"t-es\"><p>Registra una o más cotizaciones de moneda usadas para convertir y mostrar precios en una segunda moneda en el escaparate y en el checkout.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/277-canais-en-virtual-store-quotation-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store quotation tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/278-canais-pt-virtual-store-quotation-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store quotation tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/279-canais-es-virtual-store-quotation-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store quotation tab (es)\">\n          <figcaption><span class=\"t-en\">\"Loja virtual\" channel &mdash; Quotation tab, expanded, showing the empty quotation table and \"Add quotation\"</span><span class=\"t-pt\">Canal \"Loja virtual\" &mdash; aba Cotação, expandida, mostrando a tabela de cotações vazia e \"Adicionar cotação\"</span><span class=\"t-es\">Canal \"Loja virtual\" &mdash; pestaña Cotización, expandida, con la tabla de cotizaciones vacía y \"Agregar cotización\"</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">+ Add quotation</span><span class=\"t-pt\">+ Adicionar cotação</span><span class=\"t-es\">+ Agregar cotización</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Registers a new currency quotation (symbol and value).</span><span class=\"t-pt\">Cadastra uma nova cotação de moeda (símbolo e valor).</span><span class=\"t-es\">Registra una nueva cotización de moneda (símbolo y valor).</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Quotation table</span><span class=\"t-pt\">Tabela de cotações</span><span class=\"t-es\">Tabla de cotizaciones</span></td><td class=\"field-type\"><span class=\"t-en\">Symbol / Value / Default</span><span class=\"t-pt\">Símbolo / Valor / Padrão</span><span class=\"t-es\">Símbolo / Valor / Predeterminado</span></td><td class=\"field-desc\"><span class=\"t-en\">One row per registered quotation; mark one as default for the initial display, and use the row arrows to reorder them.</span><span class=\"t-pt\">Uma linha por cotação cadastrada; marque uma como padrão para a exibição inicial, e use as setas da linha para reordenar.</span><span class=\"t-es\">Una fila por cotización registrada; marque una como predeterminada para la visualización inicial, y use las flechas de la fila para reordenarlas.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"canais-loja-horarios\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Channels &gt; Virtual store</span><span class=\"t-pt\">Canais &gt; Loja virtual</span><span class=\"t-es\">Canales &gt; Tienda virtual</span></span></h3>\n        <h3><span class=\"t-en\">Virtual store channel &mdash; Opening hours</span><span class=\"t-pt\">Canal Loja virtual &mdash; Horários</span><span class=\"t-es\">Canal Tienda virtual &mdash; Horarios</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Weekly business-hours schedule used to show the store as open/closed and, when enabled, to constrain delivery scheduling.</p></span><span class=\"t-pt\"><p>Grade de horário de funcionamento semanal usada para mostrar a loja como aberta/fechada e, quando ativado, para limitar o agendamento de entregas.</p></span><span class=\"t-es\"><p>Cuadro de horario de funcionamiento semanal usado para mostrar la tienda como abierta/cerrada y, cuando está activado, para limitar la programación de entregas.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/280-canais-en-virtual-store-opening-hours-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store opening hours tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/281-canais-pt-virtual-store-opening-hours-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store opening hours tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/282-canais-es-virtual-store-opening-hours-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"virtual store opening hours tab (es)\">\n          <figcaption><span class=\"t-en\">\"Loja virtual\" channel &mdash; Opening hours tab: weekday schedule and options</span><span class=\"t-pt\">Canal \"Loja virtual\" &mdash; aba Horários: grade por dia da semana e opções</span><span class=\"t-es\">Canal \"Loja virtual\" &mdash; pestaña Horarios: cuadro por día de la semana y opciones</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Weekday rows</span><span class=\"t-pt\">Linhas de dia da semana</span><span class=\"t-es\">Filas de día de la semana</span></td><td class=\"field-type\"><span class=\"t-en\">Checkbox + time fields</span><span class=\"t-pt\">Caixa de seleção + campos de hora</span><span class=\"t-es\">Casilla + campos de hora</span></td><td class=\"field-desc\"><span class=\"t-en\">For each day: enable/disable it and set Opens, Break start, Break end and Closes times.</span><span class=\"t-pt\">Para cada dia: habilitar/desabilitar e definir os horários de Abertura, Início do intervalo, Final do intervalo e Fechamento.</span><span class=\"t-es\">Para cada día: habilitar/deshabilitar y definir los horarios de Apertura, Inicio de descanso, Fin de descanso y Cierre.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Show as closed</span><span class=\"t-pt\">Exibir como fechado</span><span class=\"t-es\">Mostrar como cerrado</span></td><td class=\"field-type\">Select</td><td class=\"field-desc\"><span class=\"t-en\">How the storefront signals it's outside business hours.</span><span class=\"t-pt\">Como a vitrine sinaliza que está fora do horário de funcionamento.</span><span class=\"t-es\">Cómo el escaparate indica que está fuera del horario de funcionamiento.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Schedule deliveries / Scheduling margin</span><span class=\"t-pt\">Agendar entregas / Margem de horas para agendar</span><span class=\"t-es\">Programar entregas / Margen de horas para programar</span></td><td class=\"field-type\"><span class=\"t-en\">Select / Number</span><span class=\"t-pt\">Seleção / Número</span><span class=\"t-es\">Selección / Número</span></td><td class=\"field-desc\"><span class=\"t-en\">Whether customers can pick a delivery time slot at checkout, and the minimum lead time (in hours) required to book one.</span><span class=\"t-pt\">Se os clientes podem escolher uma janela de horário de entrega no checkout, e a antecedência mínima (em horas) exigida para agendar.</span><span class=\"t-es\">Si los clientes pueden elegir una franja horaria de entrega en el checkout, y la antelación mínima (en horas) requerida para programarla.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"canais-api\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Channels &gt; API</span><span class=\"t-pt\">Canais &gt; Api</span><span class=\"t-es\">Canales &gt; Api</span></span></h3>\n        <h3><span class=\"t-en\">API channel</span><span class=\"t-pt\">Canal Api</span><span class=\"t-es\">Canal Api</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>A generic channel type for connecting external systems directly through WDNA's own API, using OAuth2 client credentials instead of a ready-made marketplace/ERP integration. Useful for custom integrations or testing.</p></span><span class=\"t-pt\"><p>Um tipo de canal genérico para conectar sistemas externos diretamente pela API própria da WDNA, usando credenciais OAuth2 (client credentials) em vez de uma integração pronta de marketplace/ERP. Útil para integrações sob medida ou testes.</p></span><span class=\"t-es\"><p>Un tipo de canal genérico para conectar sistemas externos directamente a través de la API propia de WDNA, usando credenciales OAuth2 (client credentials) en lugar de una integración lista de marketplace/ERP. Útil para integraciones a medida o pruebas.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/283-canais-en-api-channel-configuration-screen-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"API channel configuration screen (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/284-canais-pt-api-channel-configuration-screen-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"API channel configuration screen (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/285-canais-es-api-channel-configuration-screen-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"API channel configuration screen (es)\">\n          <figcaption><span class=\"t-en\">Api channel configuration screen: Client ID and Client Secret (masked here), with a link to the WDNA API documentation</span><span class=\"t-pt\">Tela de configuração do canal Api: Client ID e Client Secret (mascarados aqui), com link para a documentação da API WDNA</span><span class=\"t-es\">Pantalla de configuración del canal Api: Client ID y Client Secret (enmascarados aquí), con enlace a la documentación de la API WDNA</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Observations</span><span class=\"t-pt\">Observações</span><span class=\"t-es\">Observaciones</span></td><td class=\"field-type\"><span class=\"t-en\">Info panel</span><span class=\"t-pt\">Painel de informação</span><span class=\"t-es\">Panel de información</span></td><td class=\"field-desc\"><span class=\"t-en\">Links out to the external WDNA API documentation for building the integration.</span><span class=\"t-pt\">Link para a documentação externa da API WDNA, para quem vai construir a integração.</span><span class=\"t-es\">Enlace a la documentación externa de la API WDNA, para quien vaya a construir la integración.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name</span><span class=\"t-pt\">Nome</span><span class=\"t-es\">Nombre</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The channel's display name.</span><span class=\"t-pt\">O nome de exibição do canal.</span><span class=\"t-es\">El nombre de visualización del canal.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Client ID / Client Secret</span><span class=\"t-pt\">Client ID / Client Secret</span><span class=\"t-es\">Client ID / Client Secret</span></td><td class=\"field-type\"><span class=\"t-en\">Text (read-only)</span><span class=\"t-pt\">Texto (somente leitura)</span><span class=\"t-es\">Texto (solo lectura)</span></td><td class=\"field-desc\"><span class=\"t-en\">The OAuth2 credentials issued for this channel, used to authenticate API requests.</span><span class=\"t-pt\">As credenciais OAuth2 emitidas para este canal, usadas para autenticar as requisições à API.</span><span class=\"t-es\">Las credenciales OAuth2 emitidas para este canal, usadas para autenticar las solicitudes a la API.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Refresh credentials</span><span class=\"t-pt\">Renovar credenciais</span><span class=\"t-es\">Renovar credenciales</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Revokes the current Client Secret and issues a new one &mdash; any integration using the old value stops working immediately.</span><span class=\"t-pt\">Revoga o Client Secret atual e emite um novo &mdash; qualquer integração usando o valor antigo para de funcionar imediatamente.</span><span class=\"t-es\">Revoca el Client Secret actual y emite uno nuevo &mdash; cualquier integración que use el valor anterior deja de funcionar de inmediato.</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"note\"><span class=\"t-en\">&#128161; The platform's own English/Spanish translation for this screen falls back to raw, untranslated field keys (e.g. \"Channel api client id\") &mdash; that's a quirk of the live platform, not a documentation gap.</span><span class=\"t-pt\">&#128161; A própria tradução da plataforma para inglês/espanhol nesta tela cai para chaves de campo não traduzidas (ex.: \"Channel api client id\") &mdash; isso é uma característica da plataforma ao vivo, não uma lacuna da documentação.</span><span class=\"t-es\">&#128161; La propia traducción de la plataforma al inglés/español en esta pantalla recae en claves de campo sin traducir (ej.: \"Channel api client id\") &mdash; eso es una particularidad de la plataforma en vivo, no un vacío de la documentación.</span></div>\n      </div>\n      <div class=\"subsection\" id=\"canais-bling-geral\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Channels &gt; Bling</span><span class=\"t-pt\">Canais &gt; Bling</span><span class=\"t-es\">Canales &gt; Bling</span></span></h3>\n        <h3><span class=\"t-en\">Bling channel &mdash; General data & authorization</span><span class=\"t-pt\">Canal Bling &mdash; Dados gerais e autorização</span><span class=\"t-es\">Canal Bling &mdash; Datos generales y autorización</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>The Bling channel connects the store to the Bling ERP. The \"General data\" tab holds the OAuth2 app credentials and the button that starts Bling's authorization flow; the banner at the top links to Bling's own setup instructions.</p></span><span class=\"t-pt\"><p>O canal Bling conecta a loja ao ERP Bling. A aba \"Dados gerais\" concentra as credenciais do aplicativo OAuth2 e o botão que inicia o fluxo de autorização do Bling; o banner no topo leva às instruções de configuração do próprio Bling.</p></span><span class=\"t-es\"><p>El canal Bling conecta la tienda con el ERP Bling. La pestaña \"Datos generales\" reúne las credenciales de la aplicación OAuth2 y el botón que inicia el flujo de autorización de Bling; el banner superior lleva a las instrucciones de configuración del propio Bling.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/286-canais-en-bling-channel-general-data-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel general data tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/287-canais-pt-bling-channel-general-data-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel general data tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/288-canais-es-bling-channel-general-data-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel general data tab (es)\">\n          <figcaption><span class=\"t-en\">Bling channel &mdash; General data tab: API key, Client ID/Secret, \"Authorize application\" and the OAuth redirect URL</span><span class=\"t-pt\">Canal Bling &mdash; aba Dados gerais: API key, Client ID/Secret, \"Autorizar aplicação\" e a URL de redirecionamento OAuth</span><span class=\"t-es\">Canal Bling &mdash; pestaña Datos generales: API key, Client ID/Secret, \"Autorizar aplicación\" y la URL de redirección OAuth</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Info banner</span><span class=\"t-pt\">Banner de informação</span><span class=\"t-es\">Banner de información</span></td><td class=\"field-type\"><span class=\"t-en\">Link</span><span class=\"t-pt\">Link</span><span class=\"t-es\">Enlace</span></td><td class=\"field-desc\"><span class=\"t-en\">\"To configure the integration click here\" &mdash; opens Bling's own app-registration screen in a new tab.</span><span class=\"t-pt\">\"Para configurar a integração clique aqui\" &mdash; abre a tela de cadastro de aplicativo do próprio Bling em uma nova aba.</span><span class=\"t-es\">\"Para configurar la integración haga clic aquí\" &mdash; abre la pantalla de registro de aplicación del propio Bling en una nueva pestaña.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Name / API key</span><span class=\"t-pt\">Nome / API key</span><span class=\"t-es\">Nombre / API key</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The channel's display name and the API key generated on the Bling side.</span><span class=\"t-pt\">O nome de exibição do canal e a API key gerada do lado do Bling.</span><span class=\"t-es\">El nombre de visualización del canal y la API key generada del lado de Bling.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Client ID / Client Secret</span><span class=\"t-pt\">Client ID / Client Secret</span><span class=\"t-es\">Client ID / Client Secret</span></td><td class=\"field-type\"><span class=\"t-en\">Text</span><span class=\"t-pt\">Texto</span><span class=\"t-es\">Texto</span></td><td class=\"field-desc\"><span class=\"t-en\">The OAuth2 app credentials created in Bling's developer panel for this integration.</span><span class=\"t-pt\">As credenciais do aplicativo OAuth2 criadas no painel de desenvolvedor do Bling para esta integração.</span><span class=\"t-es\">Las credenciales de la aplicación OAuth2 creadas en el panel de desarrollador de Bling para esta integración.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Authorize application</span><span class=\"t-pt\">Autorizar aplicação</span><span class=\"t-es\">Autorizar aplicación</span></td><td class=\"field-type\"><span class=\"t-en\">Button</span><span class=\"t-pt\">Botão</span><span class=\"t-es\">Botón</span></td><td class=\"field-desc\"><span class=\"t-en\">Starts the OAuth2 consent flow on Bling's side to link the two accounts.</span><span class=\"t-pt\">Inicia o fluxo de consentimento OAuth2 do lado do Bling para vincular as duas contas.</span><span class=\"t-es\">Inicia el flujo de consentimiento OAuth2 del lado de Bling para vincular las dos cuentas.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">OAuth redirect URL</span><span class=\"t-pt\">URL de redirecionamento OAuth</span><span class=\"t-es\">URL de redirección OAuth</span></td><td class=\"field-type\"><span class=\"t-en\">Text (copy)</span><span class=\"t-pt\">Texto (copiar)</span><span class=\"t-es\">Texto (copiar)</span></td><td class=\"field-desc\"><span class=\"t-en\">The callback URL to paste into Bling's app registration so it can hand control back after authorization.</span><span class=\"t-pt\">A URL de callback para colar no cadastro do aplicativo no Bling, para que ele devolva o controle após a autorização.</span><span class=\"t-es\">La URL de callback para pegar en el registro de la aplicación en Bling, para que este devuelva el control tras la autorización.</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"subsection\" id=\"canais-bling-modulos\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Channels &gt; Bling</span><span class=\"t-pt\">Canais &gt; Bling</span><span class=\"t-es\">Canales &gt; Bling</span></span></h3>\n        <h3><span class=\"t-en\">Bling channel &mdash; Sync modules</span><span class=\"t-pt\">Canal Bling &mdash; Módulos de sincronização</span><span class=\"t-es\">Canal Bling &mdash; Módulos de sincronización</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Besides General data, the Bling channel has five sync-module tabs (Products, Stock, Orders, Categories, Customers) plus a Contact/Notifications tab identical to the virtual store channel's. Each sync module follows the same pattern: a Status switch (Enabled/Disabled) and, for Stock and Orders, a callback URL that must be registered on Bling's side for that data to flow back into the store.</p></span><span class=\"t-pt\"><p>Além de Dados gerais, o canal Bling tem cinco abas de módulo de sincronização (Produtos, Estoque, Pedidos, Categorias, Clientes) mais uma aba Contato/Notificações idêntica à do canal loja virtual. Cada módulo de sincronização segue o mesmo padrão: um interruptor de Status (Habilitado/Desabilitado) e, no caso de Estoque e Pedidos, uma URL de retorno que precisa ser cadastrada do lado do Bling para que esses dados voltem para a loja.</p></span><span class=\"t-es\"><p>Además de Datos generales, el canal Bling tiene cinco pestañas de módulo de sincronización (Productos, Stock, Pedidos, Categorías, Clientes) más una pestaña Contacto/Notificaciones idéntica a la del canal tienda virtual. Cada módulo de sincronización sigue el mismo patrón: un interruptor de Estado (Habilitado/Deshabilitado) y, en el caso de Stock y Pedidos, una URL de retorno que debe registrarse del lado de Bling para que esos datos vuelvan a la tienda.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/289-canais-en-bling-channel-products-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel products tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/290-canais-pt-bling-channel-products-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel products tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/291-canais-es-bling-channel-products-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel products tab (es)\">\n          <figcaption><span class=\"t-en\">Products tab: Status, product identifier (SKU/GTIN) and the synchronized products list</span><span class=\"t-pt\">Aba Produtos: Status, identificador do produto (SKU/GTIN) e a lista de produtos sincronizados</span><span class=\"t-es\">Pestaña Productos: Estado, identificador del producto (SKU/GTIN) y la lista de productos sincronizados</span></figcaption>\n        </div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/292-canais-en-bling-channel-stock-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel stock tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/293-canais-pt-bling-channel-stock-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel stock tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/294-canais-es-bling-channel-stock-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel stock tab (es)\">\n          <figcaption><span class=\"t-en\">Stock tab: callback-URL notice, Status, stock balance and the negative-stock/mapping checkboxes</span><span class=\"t-pt\">Aba Estoque: aviso de URL de retorno, Status, saldo de estoque e as caixas de mapear estoques/estoque negativo</span><span class=\"t-es\">Pestaña Stock: aviso de URL de retorno, Estado, saldo de stock y las casillas de mapear stocks/stock negativo</span></figcaption>\n        </div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/295-canais-en-bling-channel-orders-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel orders tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/296-canais-pt-bling-channel-orders-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel orders tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/297-canais-es-bling-channel-orders-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"Bling channel orders tab (es)\">\n          <figcaption><span class=\"t-en\">Orders tab: callback-URL notice (JSON urlencoded), Status and the synchronized orders list</span><span class=\"t-pt\">Aba Pedidos: aviso de URL de retorno (JSON urlencoded), Status e a lista de pedidos sincronizados</span><span class=\"t-es\">Pestaña Pedidos: aviso de URL de retorno (JSON urlencoded), Estado y la lista de pedidos sincronizados</span></figcaption>\n        </div>\n        <table class=\"fields\">\n          <thead><tr>\n            <th style=\"width:22%\"><span class=\"t-en\">Element</span><span class=\"t-pt\">Elemento</span><span class=\"t-es\">Elemento</span></th>\n            <th style=\"width:16%\"><span class=\"t-en\">Type</span><span class=\"t-pt\">Tipo</span><span class=\"t-es\">Tipo</span></th>\n            <th><span class=\"t-en\">Function</span><span class=\"t-pt\">Função</span><span class=\"t-es\">Función</span></th>\n          </tr></thead>\n          <tbody>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Products</span><span class=\"t-pt\">Produtos</span><span class=\"t-es\">Productos</span></td><td class=\"field-type\"><span class=\"t-en\">Status + Product identifier</span><span class=\"t-pt\">Status + Identificador do produto</span><span class=\"t-es\">Estado + Identificador del producto</span></td><td class=\"field-desc\"><span class=\"t-en\">Enables product sync and sets whether products are matched by SKU or another identifier; shows the synchronized products list.</span><span class=\"t-pt\">Habilita a sincronização de produtos e define se o casamento é feito por SKU ou outro identificador; mostra a lista de produtos sincronizados.</span><span class=\"t-es\">Habilita la sincronización de productos y define si la coincidencia se hace por SKU u otro identificador; muestra la lista de productos sincronizados.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Stock</span><span class=\"t-pt\">Estoque</span><span class=\"t-es\">Stock</span></td><td class=\"field-type\"><span class=\"t-en\">Status + Stock balance</span><span class=\"t-pt\">Status + Saldo de estoque</span><span class=\"t-es\">Estado + Saldo de stock</span></td><td class=\"field-desc\"><span class=\"t-en\">Enables stock sync; \"Map stocks\" links specific warehouses, and \"Allow negative stock\" lets the balance go below zero.</span><span class=\"t-pt\">Habilita a sincronização de estoque; \"Mapear estoques\" vincula depósitos específicos, e \"Permitir estoque negativo\" deixa o saldo ficar abaixo de zero.</span><span class=\"t-es\">Habilita la sincronización de stock; \"Mapear stocks\" vincula almacenes específicos, y \"Permitir stock negativo\" deja que el saldo quede por debajo de cero.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Orders</span><span class=\"t-pt\">Pedidos</span><span class=\"t-es\">Pedidos</span></td><td class=\"field-type\"><span class=\"t-en\">Status</span><span class=\"t-pt\">Status</span><span class=\"t-es\">Estado</span></td><td class=\"field-desc\"><span class=\"t-en\">Enables order sync to Bling; requires the callback URL to be registered on Bling's side with the \"JSON (urlencoded)\" callback type.</span><span class=\"t-pt\">Habilita a sincronização de pedidos com o Bling; exige que a URL de retorno seja cadastrada do lado do Bling com o tipo de callback \"JSON (urlencoded)\".</span><span class=\"t-es\">Habilita la sincronización de pedidos con Bling; requiere que la URL de retorno se registre del lado de Bling con el tipo de callback \"JSON (urlencoded)\".</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Categories</span><span class=\"t-pt\">Categorias</span><span class=\"t-es\">Categorías</span></td><td class=\"field-type\"><span class=\"t-en\">Status</span><span class=\"t-pt\">Status</span><span class=\"t-es\">Estado</span></td><td class=\"field-desc\"><span class=\"t-en\">Enables category sync between the store and Bling.</span><span class=\"t-pt\">Habilita a sincronização de categorias entre a loja e o Bling.</span><span class=\"t-es\">Habilita la sincronización de categorías entre la tienda y Bling.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Customers</span><span class=\"t-pt\">Clientes</span><span class=\"t-es\">Clientes</span></td><td class=\"field-type\"><span class=\"t-en\">Status</span><span class=\"t-pt\">Status</span><span class=\"t-es\">Estado</span></td><td class=\"field-desc\"><span class=\"t-en\">Enables customer sync between the store and Bling.</span><span class=\"t-pt\">Habilita a sincronização de clientes entre a loja e o Bling.</span><span class=\"t-es\">Habilita la sincronización de clientes entre la tienda y Bling.</span></td></tr>\n            <tr><td class=\"field-name\"><span class=\"t-en\">Contact/Notifications</span><span class=\"t-pt\">Contato/Notificações</span><span class=\"t-es\">Contacto/Notificaciones</span></td><td class=\"field-type\"><span class=\"t-en\">Same as virtual store</span><span class=\"t-pt\">Igual ao da loja virtual</span><span class=\"t-es\">Igual al de la tienda virtual</span></td><td class=\"field-desc\"><span class=\"t-en\">Identical form to the virtual store channel's Contact/Notifications tab (see above): address, notification copy e-mail and the e-mail templates table.</span><span class=\"t-pt\">Formulário idêntico ao da aba Contato/Notificações do canal loja virtual (ver acima): endereço, e-mail para cópia de notificações e a tabela de modelos de e-mail.</span><span class=\"t-es\">Formulario idéntico al de la pestaña Contacto/Notificaciones del canal tienda virtual (ver arriba): dirección, correo para copia de notificaciones y la tabla de plantillas de correo.</span></td></tr>\n          </tbody>\n        </table>\n        <div class=\"note\"><span class=\"t-en\">&#128161; Channels is now documented, per the section already authorized.</span><span class=\"t-pt\">&#128161; Canais já está documentado, conforme a seção já autorizada.</span><span class=\"t-es\">&#128161; Canales ya está documentado, según la sección ya autorizada.</span></div>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=personalizar\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Customize</span><span class=\"t-pt\">Personalizar</span><span class=\"t-es\">Personalizar</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=integracoes\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Integrations</span><span class=\"t-pt\">Integrações</span><span class=\"t-es\">Integraciones</span></strong></a>\n</nav>\n", "integracoes": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Integrations</span><span class=\"t-pt\">Integrações</span><span class=\"t-es\">Integraciones</span></p>\n<section class=\"doc-section\" id=\"integracoes\">\n      <h2><span class=\"t-en\">22. Integrations</span><span class=\"t-pt\">22. Integrações</span><span class=\"t-es\">22. Integraciones</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">Central hub for connecting the store to external tools and services. Split into five tabs; this screen is documented at the tab level only.</span><span class=\"t-pt\">Central para conectar a loja a ferramentas e serviços externos. Dividida em cinco abas; esta tela é documentada apenas no nível das abas.</span><span class=\"t-es\">Centro para conectar la tienda a herramientas y servicios externos. Dividida en cinco pestañas; esta pantalla se documenta solo a nivel de pestañas.</span>\n      </p>\n      <div class=\"subsection\" id=\"integracoes-integracoes\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Integrations</span><span class=\"t-pt\">Integrações</span><span class=\"t-es\">Integraciones</span></span></h3>\n        <h3><span class=\"t-en\">Integrations tab</span><span class=\"t-pt\">Aba Integrações</span><span class=\"t-es\">Pestaña Integraciones</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Shows every integration available on the platform (payment gateways, ERPs, delivery/logistics services, chat/reviews tools, security, marketplaces and more) as a gallery of logos, browsable by category (All, Payments, Stock, Shipping, Chat, ERP, Analytics, Security, Marketplace, Data feed, Tax data).</p></span><span class=\"t-pt\"><p>Mostra todas as integrações disponíveis na plataforma (gateways de pagamento, ERPs, serviços de entrega/logística, ferramentas de chat/avaliações, segurança, marketplaces e outras) como uma galeria de logos, navegável por categoria (Todos, Pagamentos, Estoques, Fretes, Chat, ERP, Análise, Segurança, Marketplace, Data feed, Dados fiscais).</p></span><span class=\"t-es\"><p>Muestra todas las integraciones disponibles en la plataforma (pasarelas de pago, ERPs, servicios de entrega/logística, herramientas de chat/reseñas, seguridad, marketplaces y otras) como una galería de logos, navegable por categoría (Todos, Pagos, Estoques, Fretes, Chat, ERP, Análisis, Seguridad, Marketplace, Data feed, Datos fiscales).</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/298-integracoes-en-integrations-gallery-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"integrations gallery (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/299-integracoes-pt-integrations-gallery-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"integrations gallery (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/300-integracoes-es-integrations-gallery-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"integrations gallery (es)\">\n          <figcaption><span class=\"t-en\">Integrations tab, showing the gallery of available integrations and the category filter row</span><span class=\"t-pt\">Aba Integrações, mostrando a galeria de integrações disponíveis e a linha de filtro por categoria</span><span class=\"t-es\">Pestaña Integraciones, con la galería de integraciones disponibles y la fila de filtro por categoría</span></figcaption>\n        </div>\n      </div>\n      <div class=\"subsection\" id=\"integracoes-codigos\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Integrations</span><span class=\"t-pt\">Integrações</span><span class=\"t-es\">Integraciones</span></span></h3>\n        <h3><span class=\"t-en\">Embed codes tab</span><span class=\"t-pt\">Aba Incorporar códigos</span><span class=\"t-es\">Pestaña Incrustar códigos</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Embed codes are scripts that can be added to specific pages of the platform (e.g. a tracking pixel or a custom widget), listed here with the script's Name and Location.</p></span><span class=\"t-pt\"><p>Incorporar códigos são scripts que podem ser adicionados em determinadas páginas da plataforma (ex.: um pixel de rastreamento ou um widget personalizado), listados aqui com o Nome e o Local do script.</p></span><span class=\"t-es\"><p>Incrustar códigos son scripts que se pueden agregar en determinadas páginas de la plataforma (ej.: un píxel de seguimiento o un widget personalizado), listados aquí con el Nombre y el Lugar del script.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/301-integracoes-en-embed-codes-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"embed codes tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/302-integracoes-pt-embed-codes-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"embed codes tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/303-integracoes-es-embed-codes-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"embed codes tab (es)\">\n          <figcaption><span class=\"t-en\">Embed codes tab, empty in this store, with the ID / Name / Location / Actions columns</span><span class=\"t-pt\">Aba Incorporar códigos, vazia nesta loja, com as colunas ID / Nome / Local / Ações</span><span class=\"t-es\">Pestaña Incrustar códigos, vacía en esta tienda, con las columnas ID / Nombre / Lugar / Acciones</span></figcaption>\n        </div>\n      </div>\n      <div class=\"subsection\" id=\"integracoes-plugins\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Integrations</span><span class=\"t-pt\">Integrações</span><span class=\"t-es\">Integraciones</span></span></h3>\n        <h3><span class=\"t-en\">Plugins tab</span><span class=\"t-pt\">Aba Plugins</span><span class=\"t-es\">Pestaña Plugins</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Plugins are practically the same as embed codes, but pre-formatted: ready-made widgets tied to a specific integration and type (e.g. a WhatsApp chat plugin) that only need to be enabled, without writing any code.</p></span><span class=\"t-pt\"><p>Plugins são praticamente o mesmo que Incorporar códigos, mas aqui já vêm pré-formatados: widgets prontos, vinculados a uma integração e um tipo específicos (ex.: um plugin de chat do WhatsApp), que só precisam ser ativados, sem escrever nenhum código.</p></span><span class=\"t-es\"><p>Los Plugins son prácticamente lo mismo que Incrustar códigos, pero aquí ya vienen preformateados: widgets listos, vinculados a una integración y un tipo específicos (ej.: un plugin de chat de WhatsApp), que solo necesitan activarse, sin escribir ningún código.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/304-integracoes-en-plugins-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"plugins tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/305-integracoes-pt-plugins-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"plugins tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/306-integracoes-es-plugins-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"plugins tab (es)\">\n          <figcaption><span class=\"t-en\">Plugins tab, showing the default WhatsApp Chat plugin</span><span class=\"t-pt\">Aba Plugins, mostrando o plugin padrão de Chat do WhatsApp</span><span class=\"t-es\">Pestaña Plugins, con el plugin predeterminado de Chat de WhatsApp</span></figcaption>\n        </div>\n      </div>\n      <div class=\"subsection\" id=\"integracoes-datafeed\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Integrations</span><span class=\"t-pt\">Integrações</span><span class=\"t-es\">Integraciones</span></span></h3>\n        <h3><span class=\"t-en\">Datafeed tab</span><span class=\"t-pt\">Aba Datafeed</span><span class=\"t-es\">Pestaña Datafeed</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Datafeed manages product feed integrations that export the store's catalog to external services (e.g. Google Merchant), listed with the feed's Name and the integration it belongs to.</p></span><span class=\"t-pt\"><p>Datafeed gerencia integrações de feed de produtos que exportam o catálogo da loja para serviços externos (ex.: Google Merchant), listadas com o Nome do feed e a integração à qual pertence.</p></span><span class=\"t-es\"><p>Datafeed gestiona integraciones de feed de productos que exportan el catálogo de la tienda a servicios externos (ej.: Google Merchant), listadas con el Nombre del feed y la integración a la que pertenece.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/307-integracoes-en-datafeed-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"datafeed tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/308-integracoes-pt-datafeed-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"datafeed tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/309-integracoes-es-datafeed-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"datafeed tab (es)\">\n          <figcaption><span class=\"t-en\">Datafeed tab, showing a Google Merchant feed already configured</span><span class=\"t-pt\">Aba Datafeed, mostrando um feed do Google Merchant já configurado</span><span class=\"t-es\">Pestaña Datafeed, con un feed de Google Merchant ya configurado</span></figcaption>\n        </div>\n      </div>\n      <div class=\"subsection\" id=\"integracoes-fiscais\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Integrations</span><span class=\"t-pt\">Integrações</span><span class=\"t-es\">Integraciones</span></span></h3>\n        <h3><span class=\"t-en\">Tax data tab</span><span class=\"t-pt\">Aba Dados fiscais</span><span class=\"t-es\">Pestaña Datos fiscales</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Tax data manages integrations with invoicing/tax services used to issue fiscal documents for orders, listed with the integration's ID and Name.</p></span><span class=\"t-pt\"><p>Dados fiscais gerencia integrações com serviços de nota fiscal/fiscais usados para emitir documentos fiscais dos pedidos, listadas com o ID e o Nome da integração.</p></span><span class=\"t-es\"><p>Datos fiscales gestiona integraciones con servicios de factura/fiscales usados para emitir documentos fiscales de los pedidos, listadas con el ID y el Nombre de la integración.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/310-integracoes-en-tax-data-tab-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"tax data tab (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/311-integracoes-pt-tax-data-tab-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"tax data tab (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/312-integracoes-es-tax-data-tab-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"tax data tab (es)\">\n          <figcaption><span class=\"t-en\">Tax data tab, empty in this store, with the ID / Name / Actions columns</span><span class=\"t-pt\">Aba Dados fiscais, vazia nesta loja, com as colunas ID / Nome / Ações</span><span class=\"t-es\">Pestaña Datos fiscales, vacía en esta tienda, con las columnas ID / Nombre / Acciones</span></figcaption>\n        </div>\n        <div class=\"note\"><span class=\"t-en\">&#128161; Integrations is now documented at the tab level, per the section already authorized.</span><span class=\"t-pt\">&#128161; Integrações já está documentado no nível das abas, conforme a seção já autorizada.</span><span class=\"t-es\">&#128161; Integraciones ya está documentado a nivel de pestañas, según la sección ya autorizada.</span></div>\n      </div>\n\n    </section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=canais\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Channels</span><span class=\"t-pt\">Canais</span><span class=\"t-es\">Canales</span></strong></a>\n<a class=\"docs-pager__link docs-pager__link--next\" href=\"/pagina/documentacao-da-admin?modulo=configuracoes\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Next</span><span class=\"t-pt\">Próximo</span><span class=\"t-es\">Siguiente</span></span><strong><span class=\"t-en\">Settings</span><span class=\"t-pt\">Configurações</span><span class=\"t-es\">Configuraciones</span></strong></a>\n</nav>\n", "configuracoes": "<p class=\"docs-crumb\"><a href=\"/pagina/documentacao-da-admin\"><span class=\"t-en\">Documentation</span><span class=\"t-pt\">Documentação</span><span class=\"t-es\">Documentación</span></a> <span aria-hidden=\"true\">/</span> <span class=\"t-en\">Settings</span><span class=\"t-pt\">Configurações</span><span class=\"t-es\">Configuraciones</span></p>\n<section class=\"doc-section\" id=\"config\">\n      <h2><span class=\"t-en\">23. Settings</span><span class=\"t-pt\">23. Configurações</span><span class=\"t-es\">23. Configuraciones</span></h2>\n      <p class=\"section-desc\">\n        <span class=\"t-en\">General administrative settings for the platform, grouped into eight areas: order/product/dashboard defaults, payment methods, shipping options, shared catalog data (groups, descriptions, brands...), email templates, print templates, and manual import/export.</span><span class=\"t-pt\">Configurações administrativas gerais da plataforma, agrupadas em oito áreas: padrões de pedido/produto/painel, formas de pagamento, opções de frete, dados de catálogo compartilhados (grupos, descrições, marcas...), templates de e-mail, templates de impressão e importação/exportação manual.</span><span class=\"t-es\">Configuraciones administrativas generales de la plataforma, agrupadas en ocho áreas: valores predeterminados de pedido/producto/panel, formas de pago, opciones de envío, datos de catálogo compartidos (grupos, descripciones, marcas...), plantillas de email, plantillas de impresión e importación/exportación manual.</span>\n      </p>\n      <div class=\"subsection\" id=\"config-geral\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Settings</span><span class=\"t-pt\">Configurações</span><span class=\"t-es\">Configuraciones</span></span></h3>\n        <h3><span class=\"t-en\">General settings</span><span class=\"t-pt\">Configuração geral</span><span class=\"t-es\">Configuración general</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>General data for configuring the main admin dashboard, grouped into Order settings (whether manual orders can change sales channel, whether shipping/payment are required, whether sellers only manage their own orders, and the next order number), Product settings (default status filter, whether kits are flagged in listings, cost price/margin management) and Dashboard settings (default currency, panel theme and the dashboard's dark/light logos and icons).</p></span><span class=\"t-pt\"><p>Dados gerais para configuração do painel principal do admin, agrupados em Configurações de pedidos (se pedidos manuais podem mudar de canal de venda, se frete/pagamento são obrigatórios, se vendedores só gerenciam seus próprios pedidos e o próximo número de pedido), Configuração de produto (filtro de status padrão na listagem, se kits são sinalizados na listagem, gestão de preço de custo/margem) e Configuração de dashboard (moeda padrão, tema do painel e os logos/ícones claro e escuro do painel).</p></span><span class=\"t-es\"><p>Datos generales para la configuración del panel principal del admin, agrupados en Configuración de pedidos (si los pedidos manuales pueden cambiar de canal de venta, si el envío/pago son obligatorios, si los vendedores solo gestionan sus propios pedidos y el próximo número de pedido), Configuración de producto (filtro de estado predeterminado en el listado, si los kits se señalan en el listado, gestión de precio de costo/margen) y Configuración del panel (moneda predeterminada, tema del panel y los logos/íconos claro y oscuro del panel).</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/313-config-en-general-settings-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"general settings (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/314-config-pt-general-settings-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"general settings (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/315-config-es-general-settings-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"general settings (es)\">\n          <figcaption><span class=\"t-en\">General settings screen, showing the Order settings and the start of Product settings</span><span class=\"t-pt\">Tela Configuração geral, mostrando Configurações de pedidos e o início de Configuração de produto</span><span class=\"t-es\">Pantalla Configuración general, con Configuración de pedidos y el inicio de Configuración de producto</span></figcaption>\n        </div>\n      </div>\n      <div class=\"subsection\" id=\"config-pagamentos\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Settings</span><span class=\"t-pt\">Configurações</span><span class=\"t-es\">Configuraciones</span></span></h3>\n        <h3><span class=\"t-en\">Payments</span><span class=\"t-pt\">Pagamentos</span><span class=\"t-es\">Pagos</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists the payment methods accepted by the store (e.g. a Mercado Pago gateway plus custom methods such as Card, PIX and Cash on pickup), with search by name and filters by Status and Type.</p></span><span class=\"t-pt\"><p>Lista as formas de pagamento aceitas pela loja (ex.: um gateway Mercado Pago mais métodos personalizados como Cartão, PIX e Pagamento na retirada), com busca por nome e filtros por Status e Tipo.</p></span><span class=\"t-es\"><p>Lista las formas de pago aceptadas por la tienda (ej.: una pasarela Mercado Pago más métodos personalizados como Tarjeta, PIX y Pago en retiro), con búsqueda por nombre y filtros por Estado y Tipo.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/316-config-en-payments-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"payments list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/317-config-pt-payments-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"payments list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/318-config-es-payments-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"payments list (es)\">\n          <figcaption><span class=\"t-en\">Payments screen, listing a Mercado Pago gateway and three custom payment methods</span><span class=\"t-pt\">Tela Pagamentos, listando um gateway Mercado Pago e três formas de pagamento personalizadas</span><span class=\"t-es\">Pantalla Pagos, con una pasarela Mercado Pago y tres formas de pago personalizadas</span></figcaption>\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Add</span><span class=\"t-pt\">Adicionar</span><span class=\"t-es\">Añadir</span></b> &mdash; <span class=\"t-en\">creates a new payment method (gateway or custom).</span><span class=\"t-pt\">cria uma nova forma de pagamento (gateway ou personalizada).</span><span class=\"t-es\">crea una nueva forma de pago (pasarela o personalizada).</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"config-frete\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Settings</span><span class=\"t-pt\">Configurações</span><span class=\"t-es\">Configuraciones</span></span></h3>\n        <h3><span class=\"t-en\">Shipping</span><span class=\"t-pt\">Frete</span><span class=\"t-es\">Envío</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists the store's delivery/shipping options (custom options, in-store pickup, motoboy delivery, or gateways such as Melhor Envio), with the same search/filter/bulk-action pattern as Payments, plus a \"More options\" menu for bulk actions.</p></span><span class=\"t-pt\"><p>Lista as opções de entrega/frete da loja (opções personalizadas, retirada na loja, entrega via motoboy ou gateways como o Melhor Envio), com o mesmo padrão de busca/filtro/ações em massa de Pagamentos, além de um menu \"Mais opções\" para ações em massa.</p></span><span class=\"t-es\"><p>Lista las opciones de entrega/envío de la tienda (opciones personalizadas, retiro en la tienda, entrega vía motoboy o pasarelas como Melhor Envio), con el mismo patrón de búsqueda/filtro/acciones masivas de Pagos, además de un menú \"Más opciones\" para acciones masivas.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/319-config-en-shipping-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"shipping list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/320-config-pt-shipping-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"shipping list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/321-config-es-shipping-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"shipping list (es)\">\n          <figcaption><span class=\"t-en\">Shipping screen, listing custom delivery options, store pickup and a Melhor Envio gateway</span><span class=\"t-pt\">Tela Frete, listando opções de entrega personalizadas, retirada na loja e um gateway Melhor Envio</span><span class=\"t-es\">Pantalla Envío, con opciones de entrega personalizadas, retiro en tienda y una pasarela Melhor Envio</span></figcaption>\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Add</span><span class=\"t-pt\">Adicionar</span><span class=\"t-es\">Añadir</span></b> &mdash; <span class=\"t-en\">creates a new shipping option or gateway.</span><span class=\"t-pt\">cria uma nova opção de entrega ou gateway.</span><span class=\"t-es\">crea una nueva opción de envío o pasarela.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"config-grupos\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Settings</span><span class=\"t-pt\">Configurações</span><span class=\"t-es\">Configuraciones</span></span></h3>\n        <h3><span class=\"t-en\">Groups, descriptions, brands...</span><span class=\"t-pt\">Grupos, descrições, marcas...</span><span class=\"t-es\">Grupos, descripciones, marcas...</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>A multi-tab screen for creating and editing dynamic system-wide data, used throughout the rest of the admin. The tabs are: Users (customer/staff access groups &mdash; Administrator, Clientes, Vendedor, Vendedor Marketplace &mdash; with Admin/Dashboard access toggles, seller flag and detailed permissions), Contacts, Addresses, Descriptions, Brands, Grids (size/attribute grids used by product variations), Order status (custom stages beyond the default ones), Movement categories (used to classify Wallet movimentations) and Attributes (custom product attributes).</p></span><span class=\"t-pt\"><p>Uma tela com múltiplas abas para criar e editar dados dinâmicos usados em todo o restante do admin. As abas são: Usuários (grupos de acesso de clientes/equipe &mdash; Administrador, Clientes, Vendedor, Vendedor Marketplace &mdash; com alternâncias de Acesso ao admin/dashboard, indicador de vendedor e permissões detalhadas), Contatos, Endereços, Descrições, Marcas, Grades (grades de tamanho/atributo usadas nas variações de produto), Status de pedido (etapas personalizadas além das padrão), Categorias de movimentação (usadas para classificar movimentações da Carteira) e Atributos (atributos de produto personalizados).</p></span><span class=\"t-es\"><p>Una pantalla con múltiples pestañas para crear y editar datos dinámicos usados en el resto del admin. Las pestañas son: Usuarios (grupos de acceso de clientes/equipo &mdash; Administrador, Clientes, Vendedor, Vendedor Marketplace &mdash; con interruptores de Acceso al admin/dashboard, indicador de vendedor y permisos detallados), Contactos, Direcciones, Descripciones, Marcas, Cuadrículas (cuadrículas de talla/atributo usadas en las variaciones de producto), Estado del pedido (etapas personalizadas además de las predeterminadas), Categorías de movimiento (usadas para clasificar movimientos de la Cartera) y Atributos (atributos de producto personalizados).</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/322-config-en-groups-screen-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"groups screen (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/323-config-pt-groups-screen-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"groups screen (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/324-config-es-groups-screen-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"groups screen (es)\">\n          <figcaption><span class=\"t-en\">Groups, descriptions, brands... screen on the Users tab, showing the four access groups and their Admin/Dashboard access toggles</span><span class=\"t-pt\">Tela Grupos, descrições, marcas... na aba Usuários, mostrando os quatro grupos de acesso e suas alternâncias de Acesso ao admin/dashboard</span><span class=\"t-es\">Pantalla Grupos, descripciones, marcas... en la pestaña Usuarios, con los cuatro grupos de acceso y sus interruptores de Acceso al admin/dashboard</span></figcaption>\n        </div>\n      </div>\n      <div class=\"subsection\" id=\"config-emails\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Settings</span><span class=\"t-pt\">Configurações</span><span class=\"t-es\">Configuraciones</span></span></h3>\n        <h3><span class=\"t-en\">Email templates</span><span class=\"t-pt\">Templates de emails</span><span class=\"t-es\">Plantillas de email</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists the dynamic transactional email templates used by the system (order tracking, registration confirmation, cancellation request, product review request, invoice notification, and a shared Header/Footer template), which can be edited to customize the wording and layout of each automatic email.</p></span><span class=\"t-pt\"><p>Lista os templates de e-mail transacional dinâmicos usados pelo sistema (rastreamento de pedido, confirmação de cadastro, solicitação de cancelamento, solicitação de avaliação de produto, notificação de nota fiscal e um template compartilhado de Cabeçalho/Rodapé), que podem ser editados para personalizar o texto e o layout de cada e-mail automático.</p></span><span class=\"t-es\"><p>Lista las plantillas de email transaccional dinámicas usadas por el sistema (seguimiento de pedido, confirmación de registro, solicitud de cancelación, solicitud de reseña de producto, notificación de factura y una plantilla compartida de Encabezado/Pie), que se pueden editar para personalizar el texto y el diseño de cada email automático.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/325-config-en-email-templates-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"email templates list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/326-config-pt-email-templates-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"email templates list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/327-config-es-email-templates-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"email templates list (es)\">\n          <figcaption><span class=\"t-en\">Email templates screen, listing 14 templates such as Product review and Order inserted via integration</span><span class=\"t-pt\">Tela Templates de emails, listando 14 templates como Avaliação de produto e Pedido inserido via integração</span><span class=\"t-es\">Pantalla Plantillas de email, con 14 plantillas como Reseña de producto y Pedido insertado vía integración</span></figcaption>\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Add</span><span class=\"t-pt\">Adicionar</span><span class=\"t-es\">Añadir</span></b> &mdash; <span class=\"t-en\">creates a new email template.</span><span class=\"t-pt\">cria um novo template de e-mail.</span><span class=\"t-es\">crea una nueva plantilla de email.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"config-impressao\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Settings</span><span class=\"t-pt\">Configurações</span><span class=\"t-es\">Configuraciones</span></span></h3>\n        <h3><span class=\"t-en\">Print templates</span><span class=\"t-pt\">Templates de impressão</span><span class=\"t-es\">Plantillas de impresión</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists the system's print templates (quotation, shipping label, coupon, order, plus a shared Header and Footer), edited to customize what is printed for each document type.</p></span><span class=\"t-pt\"><p>Lista os templates de impressão do sistema (orçamento, etiqueta de envio, cupom, pedido, além de um Cabeçalho e um Rodapé compartilhados), editados para personalizar o que é impresso em cada tipo de documento.</p></span><span class=\"t-es\"><p>Lista las plantillas de impresión del sistema (presupuesto, etiqueta de envío, cupón, pedido, además de un Encabezado y un Pie compartidos), editadas para personalizar lo que se imprime en cada tipo de documento.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/328-config-en-print-templates-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"print templates list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/329-config-pt-print-templates-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"print templates list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/330-config-es-print-templates-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"print templates list (es)\">\n          <figcaption><span class=\"t-en\">Print templates screen, listing Quotation, Jadlog label, Coupon, Label, Order, Footer and Header</span><span class=\"t-pt\">Tela Templates de impressão, listando Orçamento, Etiqueta Jadlog, Cupom, Etiqueta, Pedido, Rodapé e Topo</span><span class=\"t-es\">Pantalla Plantillas de impresión, con Presupuesto, Etiqueta Jadlog, Cupón, Etiqueta, Pedido, Pie y Encabezado</span></figcaption>\n        </div>\n      </div>\n      <div class=\"subsection\" id=\"config-importacoes\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Settings</span><span class=\"t-pt\">Configurações</span><span class=\"t-es\">Configuraciones</span></span></h3>\n        <h3><span class=\"t-en\">Manual imports</span><span class=\"t-pt\">Importações manual</span><span class=\"t-es\">Importaciones manual</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists manual product/order import jobs, with search and filters by Format and Type; a new import is started from here by uploading a file in the expected format.</p></span><span class=\"t-pt\"><p>Lista as importações manuais de produtos ou pedidos já realizadas, com busca e filtros por Formato e Tipo; uma nova importação é iniciada por aqui, enviando um arquivo no formato esperado.</p></span><span class=\"t-es\"><p>Lista las importaciones manuales de productos o pedidos ya realizadas, con búsqueda y filtros por Formato y Tipo; una nueva importación se inicia desde aquí, subiendo un archivo en el formato esperado.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/331-config-en-manual-imports-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manual imports list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/332-config-pt-manual-imports-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manual imports list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/333-config-es-manual-imports-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manual imports list (es)\">\n          <figcaption><span class=\"t-en\">Manual imports screen, empty in this store, with the Format and Type filters</span><span class=\"t-pt\">Tela Importações manual, vazia nesta loja, com os filtros de Formato e Tipo</span><span class=\"t-es\">Pantalla Importaciones manual, vacía en esta tienda, con los filtros de Formato y Tipo</span></figcaption>\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Add</span><span class=\"t-pt\">Adicionar</span><span class=\"t-es\">Añadir</span></b> &mdash; <span class=\"t-en\">starts a new manual import.</span><span class=\"t-pt\">inicia uma nova importação manual.</span><span class=\"t-es\">inicia una nueva importación manual.</span></li>\n        </ul>\n      </div>\n      <div class=\"subsection\" id=\"config-exportacoes\">\n        <h3><span class=\"badge\"><span class=\"t-en\">Settings</span><span class=\"t-pt\">Configurações</span><span class=\"t-es\">Configuraciones</span></span></h3>\n        <h3><span class=\"t-en\">Manual exports</span><span class=\"t-pt\">Exportações manual</span><span class=\"t-es\">Exportaciones manual</span></h3>\n        <div class=\"desc\"><span class=\"t-en\"><p>Lists manual product/order export jobs, with the same search and Format/Type filters as Manual imports, plus an Export date column; a new export is generated from here for download.</p></span><span class=\"t-pt\"><p>Lista as exportações manuais de produtos ou pedidos já geradas, com a mesma busca e filtros de Formato/Tipo das Importações manual, além de uma coluna de Data de exportação; uma nova exportação é gerada por aqui para download.</p></span><span class=\"t-es\"><p>Lista las exportaciones manuales de productos o pedidos ya generadas, con la misma búsqueda y filtros de Formato/Tipo que Importaciones manual, además de una columna de Fecha de exportación; una nueva exportación se genera desde aquí para descargar.</p></span></div>\n        <div class=\"shot\">\n<img class=\"shot-img shot-en\" src=\"https://salescdn.net/static/documentation/images/334-config-en-manual-exports-list-en.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manual exports list (en)\">\n<img class=\"shot-img shot-pt\" src=\"https://salescdn.net/static/documentation/images/335-config-pt-manual-exports-list-pt.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manual exports list (pt)\">\n<img class=\"shot-img shot-es\" src=\"https://salescdn.net/static/documentation/images/336-config-es-manual-exports-list-es.jpg\" loading=\"lazy\" decoding=\"async\" alt=\"manual exports list (es)\">\n          <figcaption><span class=\"t-en\">Manual exports screen, empty in this store, with the Format, Type and Export date columns</span><span class=\"t-pt\">Tela Exportações manual, vazia nesta loja, com as colunas Formato, Tipo e Data de exportação</span><span class=\"t-es\">Pantalla Exportaciones manual, vacía en esta tienda, con las columnas Formato, Tipo y Fecha de exportación</span></figcaption>\n        </div>\n        <ul class=\"action-list\">\n          <li><b><span class=\"t-en\">Add</span><span class=\"t-pt\">Adicionar</span><span class=\"t-es\">Añadir</span></b> &mdash; <span class=\"t-en\">generates a new manual export.</span><span class=\"t-pt\">gera uma nova exportação manual.</span><span class=\"t-es\">genera una nueva exportación manual.</span></li>\n        </ul>\n        <div class=\"note\"><span class=\"t-en\">&#128161; This completes the batch of sections authorized for this update (Customize sub-sections, Channels, Integrations and Settings).</span><span class=\"t-pt\">&#128161; Este é o fim do lote de seções autorizado para esta atualização (subseções de Personalizar, Canais, Integrações e Configurações).</span><span class=\"t-es\">&#128161; Este es el fin del lote de secciones autorizado para esta actualización (subsecciones de Personalizar, Canales, Integraciones y Configuraciones).</span></div>\n      </div>\n</section>\n\n<nav class=\"docs-pager\" aria-label=\"Paginação da documentação\">\n<a class=\"docs-pager__link docs-pager__link--prev\" href=\"/pagina/documentacao-da-admin?modulo=integracoes\"><span class=\"docs-pager__dir\"><span class=\"t-en\">Previous</span><span class=\"t-pt\">Anterior</span><span class=\"t-es\">Anterior</span></span><strong><span class=\"t-en\">Integrations</span><span class=\"t-pt\">Integrações</span><span class=\"t-es\">Integraciones</span></strong></a>\n<span class=\"docs-pager__link docs-pager__link--next is-empty\"></span>\n</nav>\n"};

